@dataclass(slots=True)
class RoundInspectionContext:
    """Ephemeral caches for one exact all-round read phase.

    This is deliberately neither persisted nor authoritative.  It only keeps
    repeated validation work inside one command from reconstructing the same
    immutable project-wide inputs once per task card or round.
    """

    owner_project_root: str = ""
    runtime_validation_cache: set[tuple[bool, str]] = field(default_factory=set)
    paper_logic_cache: dict[tuple[Any, ...], Any] = field(default_factory=dict)
    paper_logic_store: Any | None = None
    paper_continuation_manager: Any | None = None
    release_records: dict[tuple[str, bool, bool], dict[str, Any]] = field(
        default_factory=dict
    )
    verifier_capsules: dict[str, dict[str, Any]] = field(default_factory=dict)
    decision_records: dict[tuple[str, bool], dict[str, Any]] = field(
        default_factory=dict
    )
    admission_records: dict[
        tuple[str, bool],
        tuple[dict[str, Any], dict[str, Path]],
    ] = field(default_factory=dict)
    lineage_snapshots: dict[
        tuple[str, tuple[str, ...]],
        tuple[dict[str, Fact], dict[str, Path]],
    ] = field(default_factory=dict)
    research_records: dict[str, dict[str, Any]] = field(default_factory=dict)
    all_research_records: list[dict[str, Any]] | None = None
    all_research_envelopes: list[dict[str, Any]] | None = None
    research_envelopes_by_id: dict[str, dict[str, Any]] | None = None
    # A command-local index of worker-produced Research products.  This is a
    # read optimization and recovery projection only; it is never persisted
    # and never replaces the immutable Research records or their hashes.
    research_products_by_assignment: dict[
        tuple[str, str], list[dict[str, Any]]
    ] | None = None
    research_product_bindings: dict[
        tuple[str, str, str],
        tuple[dict[str, Any], dict[str, Any] | None],
    ] = field(default_factory=dict)
    ordinary_capability_bytes: dict[tuple[str, str, bool], bytes] = field(
        default_factory=dict
    )
    ordinary_capability_digests_by_path: dict[str, str] = field(
        default_factory=dict
    )
    repair_capability_bytes: dict[tuple[str, str], bytes] = field(
        default_factory=dict
    )
    repair_capability_digests_by_path: dict[str, str] = field(default_factory=dict)
    repair_capability_total_bytes: int = 0
    research_supervision_validation_stack: set[
        tuple[str, str, str, str, str, str]
    ] = field(default_factory=set)
    paper_continuation_scopes: dict[str, dict[str, Any] | None] = field(
        default_factory=dict
    )
    paper_continuation_plans: dict[str, dict[str, Any]] = field(
        default_factory=dict
    )
    authority_snapshots: dict[tuple[str, str], dict[str, Any]] = field(
        default_factory=dict
    )
    active_fact_paths: dict[str, Path] | None = None
    active_facts: dict[str, Fact] | None = None
    active_fact_validation_in_progress: bool = False
    # Ordinary Research consumes admitted Facts by exact graph identity.  Keep
    # those local admission bindings for this command only instead of turning
    # one premise read into a reconstruction of every historical admission.
    direct_active_fact_bindings: dict[str, dict[str, Any]] = field(
        default_factory=dict
    )
    revoked_fact_ids: set[str] | None = None
    quarantine_records: list[dict[str, Any]] | None = None
    adverse_cases: dict[str, dict[str, Any]] | None = None
    adverse_proposals: dict[str, dict[str, Any]] | None = None
    adverse_rules: dict[str, dict[str, Any]] | None = None
    campaign_statuses: dict[str, dict[str, Any]] = field(default_factory=dict)
    campaign_scopes: dict[str, dict[str, Any]] = field(default_factory=dict)
    # Main's goal-coverage view and ordinary workflow queue share this exact
    # command-local projection.  It is neither persisted nor authoritative.
    frontier_structural_state: tuple[Any, ...] | None = None
    frontier_group_completions: dict[
        str, tuple[str, str | None, int, str]
    ] = field(default_factory=dict)
    # COW succession is derived from the same complete structural Research
    # snapshot for every requested workgroup.  Build its global adjacency once
    # per command and cache only exact seed projections below it.
    frontier_cow_repair_children: dict[str, tuple[str, ...]] | None = None
    frontier_cow_terminal_members: dict[
        tuple[str, ...], dict[str, str | None]
    ] = field(default_factory=dict)
    # A missing key has not been inspected; a present ``None`` is an exactly
    # validated pending obligation.  This prevents later goal/queue subqueries
    # from replaying the same round and receipt closure.
    frontier_completion_statuses: dict[str, str | None] = field(
        default_factory=dict
    )
    frontier_group_actions: dict[str, dict[str, Any]] = field(
        default_factory=dict
    )
    round_completed: dict[str, bool] = field(default_factory=dict)
    round_aborts: dict[str, dict[str, Any] | None] = field(default_factory=dict)
    round_statuses: dict[str, dict[str, Any]] = field(default_factory=dict)
    round_manifests: dict[str, tuple[Path, dict[str, Any]]] = field(
        default_factory=dict
    )
    supervision_manifests_by_production_round: dict[
        str, list[tuple[Path, dict[str, Any]]]
    ] = field(default_factory=dict)
    completion_obligation_rounds: dict[
        str, list[tuple[str, str]]
    ] | None = None
    supervision_round_ids_by_production_round: dict[
        str, list[str]
    ] | None = None

    def bind_project(self, root: Path | str) -> None:
        canonical = str(Path(root).resolve())
        if not self.owner_project_root:
            self.owner_project_root = canonical
            return
        if self.owner_project_root != canonical:
            raise ValueError(
                "V5 inspection context belongs to a different project root"
            )


@dataclass(frozen=True, slots=True)
class TerminalArtifactSnapshot:
    source_relpath: str
    sha256: str
    role: str | None
    raw: bytes


@dataclass(frozen=True, slots=True)
class TerminalIngestSnapshot:
    return_path: Path
    return_relpath: str
    return_sha256: str
    return_bytes: bytes
    payload: dict[str, Any]
    artifacts: tuple[TerminalArtifactSnapshot, ...]


class _WorkerFinalHashMismatch(ValueError):
    """A caller hash mismatch is not authenticated failure evidence."""


class _CanonicalSourceNotVisible(ValueError):
    """A canonical worker source was not stably visible for one snapshot.

    This is an ephemeral read classification, not a weaker validator or a
    persistent workflow state.  Unsafe file types, symlinks, malformed bytes,
    and content/hash failures continue through the ordinary quarantine path.
    """


@dataclass(slots=True)
class V5AuditReport:
    facts: int = 0
    edges: int = 0
    targets: int = 0
    target_closure: int = 0
    max_depth: int = 0
    candidates: int = 0
    memory_entries: int = 0
    novelty_entries: int = 0
    research_entries: int = 0
    candidate_releases: int = 0
    certification_decisions: int = 0
    quarantined_contributions: int = 0
    round_states: dict[str, str] = field(default_factory=dict)
    graph_errors: list[str] = field(default_factory=list)
    workflow_errors: list[str] = field(default_factory=list)
    blackboard_graph_errors: list[str] = field(default_factory=list)
    blackboard_graph_warnings: list[str] = field(default_factory=list)
    paper_logic_errors: list[str] = field(default_factory=list)
    paper_logic_warnings: list[str] = field(default_factory=list)
    paper_source_nodes: int = 0
    paper_reconstruction_nodes: int = 0
    paper_audit_nodes: int = 0
    paper_continuation_plans: int = 0
    paper_continuation_complete_plans: int = 0
    paper_continuation_targets: int = 0
    paper_continuation_researched: int = 0
    paper_continuation_dispositioned: int = 0
    paper_continuation_unresolved: int = 0
    paper_continuation_successor_mapped: int = 0
    paper_continuation_revised_manuscript_covered: int = 0
    paper_continuation_adequacy_complete: bool | None = None
    historical_workflow_warnings: list[str] = field(default_factory=list)
    trust_debt: list[str] = field(default_factory=list)
    errors: list[str] = field(default_factory=list)
    warnings: list[str] = field(default_factory=list)

    @property
    def ok(self) -> bool:
        return not self.errors

    @property
    def current_ok(self) -> bool:
        return self.ok

    @property
    def history_clean(self) -> bool:
        return not self.historical_workflow_warnings and not self.trust_debt

    def as_dict(self) -> dict[str, Any]:
        return {
            "ok": self.ok,
            "current_ok": self.current_ok,
            "history_clean": self.history_clean,
            "workflow_evidence_version": V5_WORKFLOW_EVIDENCE_VERSION,
            "facts": self.facts,
            "edges": self.edges,
            "targets": self.targets,
            "target_closure": self.target_closure,
            "max_depth": self.max_depth,
            "candidates": self.candidates,
            "memory_entries": self.memory_entries,
            "novelty_entries": self.novelty_entries,
            "research_entries": self.research_entries,
            "candidate_releases": self.candidate_releases,
            "certification_decisions": self.certification_decisions,
            "quarantined_contributions": self.quarantined_contributions,
            "round_states": dict(sorted(self.round_states.items())),
            "graph_errors": self.graph_errors,
            "workflow_errors": self.workflow_errors,
            "current_workflow_errors": self.workflow_errors,
            "blackboard_graph_errors": self.blackboard_graph_errors,
            "blackboard_graph_warnings": self.blackboard_graph_warnings,
            "paper_logic_errors": self.paper_logic_errors,
            "paper_logic_warnings": self.paper_logic_warnings,
            "paper_source_nodes": self.paper_source_nodes,
            "paper_reconstruction_nodes": self.paper_reconstruction_nodes,
            "paper_audit_nodes": self.paper_audit_nodes,
            "paper_continuation": {
                "plans": self.paper_continuation_plans,
                "complete_plans": self.paper_continuation_complete_plans,
                "targets": self.paper_continuation_targets,
                "researched": self.paper_continuation_researched,
                "dispositioned": self.paper_continuation_dispositioned,
                "unresolved": self.paper_continuation_unresolved,
                "successor_mapped": self.paper_continuation_successor_mapped,
                "revised_manuscript_covered": (
                    self.paper_continuation_revised_manuscript_covered
                ),
                "adequacy_complete": (
                    self.paper_continuation_adequacy_complete
                ),
                "authority_effect": "none",
            },
            "historical_workflow_warnings": self.historical_workflow_warnings,
            "trust_debt": self.trust_debt,
            "errors": self.errors,
            "warnings": self.warnings,
        }


def _is_research_draft_assurance_revision(value: Any) -> bool:
    """Recognize exact historical/current strict-draft assurance revisions."""

    return value in {
        LEGACY_RESEARCH_DRAFT_ASSURANCE_REVISION,
        RESEARCH_DRAFT_ASSURANCE_REVISION,
    }


class V5LifecycleManager:
    """Own the V5 authority boundary without importing a retired runtime."""

    def __init__(self, store: Any) -> None:
        self.store = store
        self.root = store.root / "governance" / "v5"
        self.contract_path = self.root / "lifecycle-contract.json"
        self.research_root = store.root / "research"
        self.research_entries_dir = self.research_root / "entries" / "by-id"
        self.quarantine_dir = self.research_root / "quarantine" / "by-id"
        self.candidate_releases_dir = (
            store.root / "candidate_releases" / "by-id"
        )
        self.candidate_artifacts_dir = (
            store.root / "candidate_releases" / "artifacts" / "by-hash"
        )
        self.certification_decisions_dir = (
            store.root / "certification" / "decisions" / "by-id"
        )
        self.certification_repair_outbox_dir = (
            store.root / "certification" / "repair-outbox" / "by-decision"
        )
        self.certification_repair_effects_dir = (
            store.root / "certification" / "repair-effects" / "by-decision"
        )
        self.fact_admission_checkpoints_dir = (
            self.root / "fact-admission-checkpoints" / "by-id"
        )
        self.admissions_dir = (
            store.fact_graph_dir / "v5_admissions" / "by-release"
        )
        self.revocations_dir = (
            store.fact_graph_dir / "v5_revocations" / "by-fact"
        )

    def _bind_inspection_context(
        self,
        context: RoundInspectionContext | None,
        *,
        create: bool = False,
    ) -> RoundInspectionContext | None:
        if context is None:
            if not create:
                return None
            context = RoundInspectionContext()
        context.bind_project(self.store.root)
        return context

    def initialize(self) -> None:
        for path in (
            self.root,
            self.research_entries_dir,
            self.quarantine_dir,
            self.candidate_releases_dir,
            self.candidate_artifacts_dir,
            self.certification_decisions_dir,
            self.certification_repair_outbox_dir,
            self.certification_repair_effects_dir,
            self.fact_admission_checkpoints_dir,
            self.admissions_dir,
            self.revocations_dir,
        ):
            path.mkdir(parents=True, exist_ok=True)
        payload = {
            **V5_LIFECYCLE_CONTRACT,
            "contract_sha256": V5_LIFECYCLE_CONTRACT_SHA256,
        }
        self.store._write_json_once(self.contract_path, payload)
        self.paper_continuation().initialize()
        self.research_draft().initialize()
        self.parallel_verification().initialize()

    def _inspection_paper_logic(
        self,
        context: RoundInspectionContext | None,
    ) -> Any:
        context = self._bind_inspection_context(context)
        if context is None:
            return self.store.paper_logic()
        if context.paper_logic_store is None:
            context.paper_logic_store = self.store.paper_logic(
                _inspection_cache=context.paper_logic_cache
            )
        return context.paper_logic_store

    def paper_continuation(
        self,
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> Any:
        from .paper_continuation import PaperContinuationManager

        _inspection_context = self._bind_inspection_context(
            _inspection_context
        )
        if _inspection_context is None:
            return PaperContinuationManager(self)
        if _inspection_context.paper_continuation_manager is None:
            _inspection_context.paper_continuation_manager = (
                PaperContinuationManager(
                    self,
                    _inspection_context=_inspection_context,
                )
            )
        return _inspection_context.paper_continuation_manager

    def research_draft(self) -> Any:
        from .research_draft import ResearchDraftManager

        return ResearchDraftManager(self)

    def parallel_verification(self) -> Any:
        from .parallel_verification_lifecycle import (
            ParallelVerificationLifecycleManager,
        )

        return ParallelVerificationLifecycleManager(self)

    def _research_path(self, research_id: str) -> Path:
        return self.research_entries_dir / f"{validate_memory_id(research_id)}.json"

    def _research_record(
        self,
        research_id: str,
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any]:
        path = self._research_path(research_id)
        if path.is_symlink() or not path.is_file():
            raise KeyError(f"unknown V5 research entry: {research_id}")
        record = self.store._read_json(path)
        self._validate_research_record(
            record,
            path=path,
            _inspection_context=_inspection_context,
        )
        return record

    def _research_record_envelope(
        self,
        research_id: str,
    ) -> dict[str, Any]:
        """Validate immutable identity and connectivity without artifact replay.

        This projection is intentionally nonauthoritative.  It is suitable only
        for connecting an explicitly selected Research record to its ancestry;
        any selected or otherwise authority-bearing record still uses the full
        validator.
        """

        path = self._research_path(research_id)
        if path.is_symlink() or not path.is_file():
            raise KeyError(f"unknown V5 research entry: {research_id}")
        record = self.store._read_json(path)
        required = {
            "schema_version",
            "policy_revision",
            "project_id",
            "research_id",
            "kind",
            "status",
            "claim",
            "content",
            "rationale",
            "dependencies",
            "source",
            "relation",
            "related_research_ids",
            "metadata",
            "actor",
            "created_at",
            "semantic_sha256",
            "record_sha256",
        }
        if not isinstance(record, dict) or set(record) != required:
            raise ValueError("research envelope fields are not exact")
        resolved_id = validate_memory_id(
            _require_nonempty_text(record.get("research_id"), "research id")
        )
        if path.stem != resolved_id:
            raise ValueError("research envelope path/id mismatch")
        if (
            record.get("schema_version") != 5
            or record.get("policy_revision") != V5_POLICY_REVISION
            or record.get("project_id") != self.store.project_id()
            or record.get("kind") not in V5_RESEARCH_KINDS
            or record.get("status") not in MEMORY_STATUSES
        ):
            raise ValueError("research envelope identity is invalid")
        _require_nonempty_text(record.get("claim"), "research claim")
        for field_name in ("content", "rationale", "source", "actor", "created_at"):
            if not isinstance(record.get(field_name), str):
                raise ValueError(f"research {field_name} must be a string")
        for fact_id in _require_string_list(
            record.get("dependencies"), "research dependencies"
        ):
            validate_fact_id(fact_id)
        for related_id in _require_string_list(
            record.get("related_research_ids"), "related research ids"
        ):
            validate_memory_id(related_id)
        relation = record.get("relation")
        if relation is not None and not isinstance(relation, str):
            raise ValueError("research relation must be a string or null")
        if not isinstance(record.get("metadata"), dict):
            raise ValueError("research metadata must be an object")
        semantic = {
            key: record[key]
            for key in required.difference(
                {"research_id", "created_at", "semantic_sha256", "record_sha256"}
            )
        }
        semantic_sha = sha256_json(semantic)
        if (
            record.get("semantic_sha256") != semantic_sha
            or resolved_id != semantic_sha[:12]
        ):
            raise ValueError("research envelope content identity drifted")
        record_without_hash = {
            key: value for key, value in record.items() if key != "record_sha256"
        }
        if record.get("record_sha256") != sha256_json(record_without_hash):
            raise ValueError("research envelope record hash mismatch")
        return record

    def research_envelopes(
        self,
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> list[dict[str, Any]]:
        """Return the complete structural Research collection without artifacts."""

        _inspection_context = self._bind_inspection_context(_inspection_context)
        if (
            _inspection_context is not None
            and _inspection_context.all_research_envelopes is not None
        ):
            if _inspection_context.research_envelopes_by_id is None:
                _inspection_context.research_envelopes_by_id = {
                    item["research_id"]: item
                    for item in _inspection_context.all_research_envelopes
                }
            return _inspection_context.all_research_envelopes
        if not self.research_entries_dir.exists():
            return []
        records: list[dict[str, Any]] = []
        for path in sorted(self.research_entries_dir.glob("*.json")):
            if path.is_symlink() or not path.is_file():
                raise ValueError("research ledger contains an unsafe entry")
            records.append(self._research_record_envelope(path.stem))
        if _inspection_context is not None:
            _inspection_context.all_research_envelopes = records
            _inspection_context.research_envelopes_by_id = {
                item["research_id"]: item for item in records
            }
        return records

    def _validate_research_record(
        self,
        record: Any,
        *,
        path: Path,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any]:
        if not isinstance(record, dict):
            raise ValueError("research record must be one object")
        required = {
            "schema_version",
            "policy_revision",
            "project_id",
            "research_id",
            "kind",
            "status",
            "claim",
            "content",
            "rationale",
            "dependencies",
            "source",
            "relation",
            "related_research_ids",
            "metadata",
            "actor",
            "created_at",
            "semantic_sha256",
            "record_sha256",
        }
        if set(record) != required:
            raise ValueError("research record fields are not exact")
        research_id = validate_memory_id(
            _require_nonempty_text(record.get("research_id"), "research id")
        )
        if path.stem != research_id:
            raise ValueError("research path/id mismatch")
        if (
            record.get("schema_version") != 5
            or record.get("policy_revision") != V5_POLICY_REVISION
            or record.get("project_id") != self.store.project_id()
        ):
            raise ValueError("research schema/policy/project mismatch")
        if record.get("kind") not in V5_RESEARCH_KINDS:
            raise ValueError("research kind is invalid")
        if record.get("status") not in MEMORY_STATUSES:
            raise ValueError("research status is invalid")
        _require_nonempty_text(record.get("claim"), "research claim")
        for field_name in ("content", "rationale", "source", "actor", "created_at"):
            if not isinstance(record.get(field_name), str):
                raise ValueError(f"research {field_name} must be a string")
        dependencies = _require_string_list(
            record.get("dependencies"), "research dependencies"
        )
        for fact_id in dependencies:
            validate_fact_id(fact_id)
        related = _require_string_list(
            record.get("related_research_ids"), "related research ids"
        )
        for related_id in related:
            validate_memory_id(related_id)
        relation = record.get("relation")
        if relation is not None and not isinstance(relation, str):
            raise ValueError("research relation must be a string or null")
        if not isinstance(record.get("metadata"), dict):
            raise ValueError("research metadata must be an object")
        metadata = record["metadata"]
        # Retired goal-intake metadata is inert historical provenance.  The
        # ordinary Campaign id is the only current planning association.
        _research_decision_profile(metadata)
        validate_adverse_domain_profile(metadata.get("adverse_domain_profile"))
        independent_adverse_required(record)
        self._research_is_adverse_assignment(record)
        if "workload_profile" in metadata:
            validate_workload_profile(metadata["workload_profile"])
        self._validate_exact_repair_spec_metadata(
            kind=record["kind"],
            metadata=metadata,
        )
        repair_manifest = self._validate_repair_input_capability_metadata(
            kind=record["kind"],
            metadata=metadata,
            _inspection_context=_inspection_context,
        )
        self._validate_schema_v2_repair_lineage(
            kind=record["kind"],
            relation=record["relation"],
            related_research_ids=record["related_research_ids"],
            metadata=metadata,
            _inspection_context=_inspection_context,
        )
        self._validate_supervised_production_authority_metadata(
            metadata,
            dependencies=record["dependencies"],
        )
        assurance_revision = metadata.get(
            "assurance_contract_revision",
            V5_LEGACY_ASSURANCE_CONTRACT_REVISION,
        )
        if assurance_revision not in {
            V5_ASSURANCE_CONTRACT_REVISION,
            V5_LEGACY_ASSURANCE_CONTRACT_REVISION,
        }:
            raise ValueError("research assurance contract revision is invalid")
        if repair_manifest is not None and assurance_revision != V5_ASSURANCE_CONTRACT_REVISION:
            raise ValueError(
                "repair input capability manifest requires current assurance"
            )
        if assurance_revision == V5_ASSURANCE_CONTRACT_REVISION:
            artifacts = metadata.get("artifacts", [])
            if not isinstance(artifacts, list) or any(
                not isinstance(item, dict)
                or set(item) != {"path", "sha256", "role"}
                for item in artifacts
            ):
                raise ValueError(
                    "current Research artifacts must be exact path/hash/role objects"
                )
            seen_artifact_roles: set[str] = set()
            for item in artifacts:
                relpath = _require_nonempty_text(
                    item["path"], "Research artifact path"
                )
                digest = _require_nonempty_text(
                    item["sha256"], "Research artifact SHA-256"
                )
                role = _require_nonempty_text(
                    item["role"], "Research artifact role"
                )
                if SHA256_RE.fullmatch(digest) is None:
                    raise ValueError("Research artifact SHA-256 is invalid")
                if role in seen_artifact_roles:
                    raise ValueError("Research artifact roles must be unique")
                seen_artifact_roles.add(role)
                artifact_path = self._lexical_contained_path(
                    relpath, "Research artifact path"
                )
                try:
                    self._ordinary_capability_bytes(
                        artifact_path,
                        digest,
                        label="Research artifact",
                        _inspection_context=_inspection_context,
                    )
                except ValueError:
                    raise ValueError("Research artifact is missing, unsafe, or drifted")
            invalidations = metadata.get("route_invalidations", [])
            if not isinstance(invalidations, list) or any(
                not isinstance(item, str) or MEMORY_ID_RE.fullmatch(item) is None
                for item in invalidations
            ):
                raise ValueError("Research route_invalidations must be V5 Research ids")
            if len(invalidations) != len(set(invalidations)):
                raise ValueError("Research route_invalidations must be unique")
        self._validate_research_supervision_record_fields(
            kind=record["kind"],
            status=record["status"],
            relation=record["relation"],
            related_research_ids=record["related_research_ids"],
            metadata=metadata,
            _inspection_context=_inspection_context,
        )
        self._validate_approved_computation_record_fields(
            kind=record["kind"],
            status=record["status"],
            relation=record["relation"],
            related_research_ids=record["related_research_ids"],
            metadata=metadata,
            _inspection_context=_inspection_context,
        )
        semantic = {
            key: record[key]
            for key in required.difference(
                {"research_id", "created_at", "semantic_sha256", "record_sha256"}
            )
        }
        semantic_sha = sha256_json(semantic)
        if record.get("semantic_sha256") != semantic_sha:
            raise ValueError("research semantic hash mismatch")
        if research_id != semantic_sha[:12]:
            raise ValueError("research content id mismatch")
        record_without_hash = {
            key: value for key, value in record.items() if key != "record_sha256"
        }
        if record.get("record_sha256") != sha256_json(record_without_hash):
            raise ValueError("research record hash mismatch")
        return record

    @staticmethod
    def _research_assurance_revision(record: dict[str, Any]) -> str:
        metadata = record.get("metadata", {})
        if not isinstance(metadata, dict):
            return V5_LEGACY_ASSURANCE_CONTRACT_REVISION
        value = metadata.get(
            "assurance_contract_revision",
            V5_LEGACY_ASSURANCE_CONTRACT_REVISION,
        )
        return str(value)

    @staticmethod
    def production_research_cycle_binding() -> dict[str, Any]:
        """Return the prospective first-subround contract used by public planning."""

        return {
            "revision": V5_RESEARCH_CYCLE_REVISION,
            "subround": "production",
            "source_round_id": None,
            "source_round_manifest_sha256": None,
            "source_receipts_sha256": None,
            "source_component_id": None,
            "source_component_sha256": None,
            "supervisor_scopes": [],
            "computation_policy": "core_code_review_before_formal_execution",
            "repair_policy": "copy_on_write_next_research_cycle",
            "pulse_policy": "not_used",
            "truth_effect": "none",
        }

    @staticmethod
    def _validate_research_cycle_binding(payload: Any) -> dict[str, Any]:
        legacy_required = {
            "revision",
            "subround",
            "source_round_id",
            "source_round_manifest_sha256",
            "source_receipts_sha256",
            "supervisor_scopes",
            "computation_policy",
            "repair_policy",
            "pulse_policy",
            "truth_effect",
        }
        current_required = legacy_required.union(
            {"source_component_id", "source_component_sha256"}
        )
        if not isinstance(payload, dict):
            raise ValueError("V5 Research-cycle binding fields are not exact")
        revision = payload.get("revision")
        required = (
            legacy_required
            if revision == V5_LEGACY_RESEARCH_CYCLE_REVISION
            else current_required
        )
        if set(payload) != required:
            raise ValueError("V5 Research-cycle binding fields are not exact")
        if (
            revision
            not in {
                V5_LEGACY_RESEARCH_CYCLE_REVISION,
                V5_RESEARCH_CYCLE_REVISION,
            }
            or payload["subround"] not in {"production", "supervision"}
            or payload["computation_policy"]
            != "core_code_review_before_formal_execution"
            or payload["repair_policy"]
            != "copy_on_write_next_research_cycle"
            or payload["pulse_policy"] != "not_used"
            or payload["truth_effect"] != "none"
        ):
            raise ValueError("V5 Research-cycle policy is invalid")
        scopes = _require_string_list(
            payload["supervisor_scopes"], "V5 Research supervisor scopes"
        )
        if scopes != sorted(set(scopes)) or any(
            scope not in V5_RESEARCH_SUPERVISOR_SCOPES for scope in scopes
        ):
            raise ValueError("V5 Research supervisor scopes are invalid")
        if payload["subround"] == "production":
            if (
                payload["source_round_id"] is not None
                or payload["source_round_manifest_sha256"] is not None
                or payload["source_receipts_sha256"] is not None
                or scopes
            ):
                raise ValueError("V5 production subround has source supervision state")
            if revision == V5_RESEARCH_CYCLE_REVISION and (
                payload["source_component_id"] is not None
                or payload["source_component_sha256"] is not None
            ):
                raise ValueError(
                    "V5 production subround has source component state"
                )
        else:
            validate_round_id(
                _require_nonempty_text(
                    payload["source_round_id"],
                    "V5 supervision source round id",
                )
            )
            for key in (
                "source_round_manifest_sha256",
                "source_receipts_sha256",
            ):
                value = payload[key]
                if not isinstance(value, str) or SHA256_RE.fullmatch(value) is None:
                    raise ValueError(f"V5 supervision {key} is invalid")
            if revision == V5_RESEARCH_CYCLE_REVISION:
                component_id = _require_nonempty_text(
                    payload["source_component_id"],
                    "V5 supervision source component id",
                )
                if not component_id.startswith("component-"):
                    raise ValueError(
                        "V5 supervision source component id is invalid"
                    )
                component_sha = payload["source_component_sha256"]
                if (
                    not isinstance(component_sha, str)
                    or SHA256_RE.fullmatch(component_sha) is None
                    or component_id != "component-" + component_sha[:16]
                ):
                    raise ValueError(
                        "V5 supervision source component hash is invalid"
                    )
            if not scopes or len(scopes) > V5_RESEARCH_SUPERVISOR_LIMIT:
                raise ValueError("V5 supervision must contain one to three scopes")
        return payload

    @classmethod
    def _computation_design_only(
        cls,
        *,
        entry: dict[str, Any],
        work_mode: str,
        research_cycle: dict[str, Any] | None,
    ) -> bool:
        if work_mode != "compute" or research_cycle is None:
            return False
        cycle = cls._validate_research_cycle_binding(research_cycle)
        metadata = entry.get("metadata", {})
        return (
            cycle["subround"] == "production"
            and isinstance(metadata, dict)
            and "approved_computation_execution" not in metadata
        )

    @staticmethod
    def _research_is_adverse_assignment(record: dict[str, Any]) -> bool:
        metadata = record.get("metadata", {})
        if not isinstance(metadata, dict):
            return False
        provenance = metadata.get("assignment_provenance")
        if provenance is None:
            return False
        required = {
            "schema_version",
            "round_id",
            "assignment_id",
            "worker_id",
            "task_card_sha256",
            "work_mode",
            "adverse_assignment",
        }
        if not isinstance(provenance, dict):
            raise ValueError("Research assignment provenance fields are not exact")
        schema_version = provenance.get("schema_version")
        if schema_version == 1:
            expected_fields = required
        elif schema_version == 2:
            expected_fields = {*required, "writer_lease_id"}
        else:
            raise ValueError("Research assignment provenance schema is unsupported")
        if set(provenance) != expected_fields:
            raise ValueError("Research assignment provenance fields are not exact")
        validate_round_id(
            _require_nonempty_text(provenance.get("round_id"), "provenance round id")
        )
        validate_assignment_id(
            _require_nonempty_text(
                provenance.get("assignment_id"), "provenance assignment id"
            )
        )
        worker_id = _require_nonempty_text(
            provenance.get("worker_id"), "provenance worker id"
        )
        if worker_id != record.get("actor"):
            raise ValueError("Research assignment provenance worker/actor mismatch")
        task_card_sha = _require_nonempty_text(
            provenance.get("task_card_sha256"), "provenance task-card hash"
        )
        if SHA256_RE.fullmatch(task_card_sha) is None:
            raise ValueError("Research assignment provenance task-card hash is invalid")
        work_mode = provenance.get("work_mode")
        if work_mode not in WORK_MODES:
            raise ValueError("Research assignment provenance work mode is invalid")
        adverse = provenance.get("adverse_assignment")
        if not isinstance(adverse, bool) or adverse != (work_mode == "refute"):
            raise ValueError("Research adverse-assignment provenance is inconsistent")
        if schema_version == 2:
            writer_lease_id = provenance.get("writer_lease_id")
            if (
                not isinstance(writer_lease_id, str)
                or not writer_lease_id.startswith("writer-lease-")
                or SHA256_RE.fullmatch(
                    writer_lease_id.removeprefix("writer-lease-")
                )
                is None
            ):
                raise ValueError("Research writer-lease provenance is invalid")
        task_binding = metadata.get("task_binding")
        if isinstance(task_binding, dict):
            for key in ("round_id", "assignment_id", "task_card_sha256"):
                if task_binding.get(key) != provenance[key]:
                    raise ValueError(
                        "Research assignment provenance/task binding mismatch"
                    )
            if schema_version == 2 and task_binding.get(
                "writer_lease_id"
            ) != provenance.get("writer_lease_id"):
                raise ValueError(
                    "Research writer-lease provenance/task binding mismatch"
                )
        return adverse

    @staticmethod
    def _writer_lease_id(
        *,
        round_id: str,
        assignment_id: str,
        task_card_sha256: str,
        worker_context_id: str,
        host_task_scope_id: str,
    ) -> str:
        """Derive the assignment/host-scoped writer lease identity.

        The lease is an immutable identity binding, not a permission bit.  A
        terminal seal records it so a retry or a stale worker can never be
        mistaken for a different assignment merely because it writes to the
        same legacy return path.
        """

        semantic = {
            "revision": V5_WRITER_LEASE_REVISION,
            "round_id": round_id,
            "assignment_id": assignment_id,
            "task_card_sha256": task_card_sha256,
            "worker_context_id": worker_context_id,
            "host_task_scope_id": host_task_scope_id,
        }
        return "writer-lease-" + sha256_json(semantic)

    @classmethod
    def _validate_writer_lease_id(
        cls,
        value: Any,
        *,
        round_id: str,
        assignment_id: str,
        task_card_sha256: str,
        worker_context_id: str,
        host_task_scope_id: str,
    ) -> str:
        if (
            not isinstance(value, str)
            or not value.startswith("writer-lease-")
            or SHA256_RE.fullmatch(value.removeprefix("writer-lease-")) is None
        ):
            raise ValueError("V5 writer lease id is invalid")
        expected = cls._writer_lease_id(
            round_id=round_id,
            assignment_id=assignment_id,
            task_card_sha256=task_card_sha256,
            worker_context_id=worker_context_id,
            host_task_scope_id=host_task_scope_id,
        )
        if value != expected:
            raise ValueError("V5 writer lease binding is invalid")
        return value

    def _repair_capability_bytes(
        self,
        path: Path,
        digest: str,
        *,
        label: str,
        _inspection_context: RoundInspectionContext | None = None,
        require_single_link: bool = False,
    ) -> bytes:
        """Read one repair capability once inside a command-local snapshot.

        The snapshot is deliberately keyed by the lexical project-relative
        path and its declared digest.  It is discarded with the inspection
        context and is never used across a mutation boundary; callers that
        cross that boundary invoke this helper without a context for a fresh
        no-follow read.
        """

        context = self._bind_inspection_context(_inspection_context)
        if context is None:
            raw = self._read_regular_bytes_once(
                path,
                label=label,
                containment_root=self.store.root,
                require_single_link=require_single_link,
            )
            if sha256_bytes(raw) != digest:
                raise ValueError(f"{label} bytes/hash mismatch")
            return raw
        try:
            relative = path.relative_to(self.store.root).as_posix()
        except ValueError as exc:
            raise ValueError(f"{label} escapes its project root") from exc
        previous_digest = context.repair_capability_digests_by_path.get(relative)
        if previous_digest is not None and previous_digest != digest:
            raise ValueError(f"{label} path has conflicting declared bytes")
        key = (relative, digest)
        cached = context.repair_capability_bytes.get(key)
        if cached is not None:
            return cached
        raw = self._read_regular_bytes_once(
            path,
            label=label,
            containment_root=self.store.root,
            require_single_link=require_single_link,
        )
        if sha256_bytes(raw) != digest:
            raise ValueError(f"{label} bytes/hash mismatch")
        projected_total = context.repair_capability_total_bytes + len(raw)
        if projected_total > V5_MAX_REPAIR_INPUT_CAPABILITY_BYTES:
            raise ValueError(
                "repair input capability bytes exceed the 64 MiB aggregate cap"
            )
        context.repair_capability_digests_by_path[relative] = digest
        context.repair_capability_bytes[key] = raw
        context.repair_capability_total_bytes = projected_total
        return raw

    def _ordinary_capability_bytes(
        self,
        path: Path,
        digest: str,
        *,
        label: str,
        _inspection_context: RoundInspectionContext | None = None,
        require_single_link: bool = False,
    ) -> bytes:
        """Validate one non-Repair capability without charging Repair budget.

        Ordinary Research, task-card, source, and Fact capabilities retain the
        same lexical containment, no-follow regular-file read, and SHA-256
        checks as a schema-v2 Repair input.  Their command-local cache is kept
        separate so a large valid project cannot consume the bounded Repair
        closure budget.  A fresh context or no context always re-reads bytes.
        """

        context = self._bind_inspection_context(_inspection_context)
        if context is None:
            raw = self._read_regular_bytes_once(
                path,
                label=label,
                containment_root=self.store.root,
                require_single_link=require_single_link,
            )
            if sha256_bytes(raw) != digest:
                raise ValueError(f"{label} bytes/hash mismatch")
            return raw
        try:
            relative = path.relative_to(self.store.root).as_posix()
        except ValueError as exc:
            raise ValueError(f"{label} escapes its project root") from exc
        previous_digest = context.ordinary_capability_digests_by_path.get(
            relative
        )
        if previous_digest is not None and previous_digest != digest:
            raise ValueError(f"{label} path has conflicting declared bytes")
        key = (relative, digest, require_single_link)
        cached = context.ordinary_capability_bytes.get(key)
        if cached is not None:
            return cached
        raw = self._read_regular_bytes_once(
            path,
            label=label,
            containment_root=self.store.root,
            require_single_link=require_single_link,
        )
        if sha256_bytes(raw) != digest:
            raise ValueError(f"{label} bytes/hash mismatch")
        context.ordinary_capability_digests_by_path[relative] = digest
        context.ordinary_capability_bytes[key] = raw
        return raw

    def _schema_v2_repair_capability_manifest(
        self,
        record: dict[str, Any],
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any] | None:
        """Return the validated manifest only for an explicit schema-v2 Repair."""

        metadata = record.get("metadata")
        if not isinstance(metadata, dict):
            return None
        spec = metadata.get("repair_spec")
        if not isinstance(spec, dict) or spec.get("schema_version") != 2:
            return None
        if record.get("kind") != "repair":
            raise ValueError("schema-v2 repair capability scope requires repair kind")
        if record.get("relation") != "repairs":
            raise ValueError(
                "schema-v2 repair capability scope requires repairs relation"
            )
        manifest = self._validate_repair_input_capability_metadata(
            kind="repair",
            metadata=metadata,
            _inspection_context=_inspection_context,
        )
        if not isinstance(manifest, dict):
            raise ValueError("schema-v2 repair capability scope lacks its manifest")
        return manifest

    def _typed_research_artifacts(
        self,
        record: dict[str, Any],
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> list[dict[str, str]]:
        metadata = record.get("metadata", {})
        if not isinstance(metadata, dict):
            return []
        artifacts = metadata.get("artifacts", [])
        # Capability is a property of the declared path/SHA-256/role graph,
        # not of the historical assurance label on the Research record. Old
        # records that already carry exact capabilities remain directly usable;
        # malformed declarations still fail when the capability is selected.
        if not isinstance(artifacts, list) or any(
            not isinstance(item, dict)
            or set(item) != {"path", "sha256", "role"}
            or not isinstance(item["path"], str)
            or not item["path"]
            or not isinstance(item["sha256"], str)
            or SHA256_RE.fullmatch(item["sha256"]) is None
            or not isinstance(item["role"], str)
            or not item["role"]
            for item in artifacts
        ):
            return []
        # CHX-038 bounds the declared byte closure of a schema-v2 Repair.
        # Ordinary current-assurance Research artifacts are historical/source
        # evidence and may legitimately exceed that one-Repair budget when a
        # project-wide audit reads many records.  Keep their no-follow/hash
        # validation, but do not charge them against the Repair snapshot.
        repair_capability_scope = (
            self._schema_v2_repair_capability_manifest(
                record,
                _inspection_context=_inspection_context,
            )
            is not None
        )
        result: list[dict[str, str]] = []
        for item in artifacts:
            path = self._lexical_contained_path(
                item["path"], "Research capability artifact"
            )
            try:
                if repair_capability_scope:
                    self._repair_capability_bytes(
                        path,
                        item["sha256"],
                        label="Research capability artifact",
                        _inspection_context=_inspection_context,
                    )
                else:
                    self._ordinary_capability_bytes(
                        path,
                        item["sha256"],
                        label="Research capability artifact",
                        _inspection_context=_inspection_context,
                    )
            except ValueError as exc:
                # Preserve the historical Research-record interface while
                # allowing the shared CHX-016 reader to expose precise errors
                # to the newer repair-capability callers.
                raise ValueError("Research capability artifact drifted") from exc
            result.append(
                {
                    "path": item["path"],
                    "sha256": item["sha256"],
                    "role": f"{record['research_id']}:{item['role']}",
                    "source_research_id": record["research_id"],
                }
            )
        return result

    @staticmethod
    def _literal_research_reference_tokens(
        record: dict[str, Any],
    ) -> list[str]:
        """Return exact 12-hex Research tokens literally named in prose.

        This is intentionally lexical rather than semantic.  It lets Main
        make a predecessor operable by naming its exact Research id, without
        introducing fuzzy relevance inference, a compatibility layer, or a
        planning gate.
        """

        tokens: set[str] = set()
        for field in ("claim", "content", "rationale", "source"):
            value = record.get(field)
            if not isinstance(value, str):
                continue
            tokens.update(_EXACT_RESEARCH_REFERENCE_RE.findall(value))
        tokens.discard(str(record.get("research_id") or ""))
        return sorted(tokens)

    def _resolvable_literal_research_reference_ids(
        self,
        record: dict[str, Any],
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> list[str]:
        """Resolve only literal tokens that are existing valid Research ids."""

        explicit = set(record.get("related_research_ids", []))
        resolved: list[str] = []
        for research_id in self._literal_research_reference_tokens(record):
            if research_id in explicit:
                continue
            try:
                self._inspection_research_record(
                    research_id,
                    _inspection_context,
                )
            except KeyError:
                continue
            resolved.append(research_id)
        return resolved

    @staticmethod
    def _normalize_repair_input_capabilities(
        value: Any,
    ) -> list[dict[str, str]]:
        if not isinstance(value, list):
            raise ValueError("repair input capabilities must be a list")
        if len(value) > V5_MAX_REPAIR_INPUT_CAPABILITIES:
            raise ValueError("repair input capabilities exceed the 256-item cap")
        by_role: dict[str, dict[str, str]] = {}
        by_path: dict[str, str] = {}
        candidates: list[dict[str, str]] = []
        for raw in value:
            if not isinstance(raw, dict) or set(raw) != {
                "path",
                "sha256",
                "role",
            }:
                raise ValueError(
                    "repair input capability fields must be exact path/sha256/role"
                )
            path = _require_nonempty_text(
                raw["path"], "repair input capability path"
            )
            digest = _require_nonempty_text(
                raw["sha256"], "repair input capability SHA-256"
            )
            role = _require_nonempty_text(
                raw["role"], "repair input capability role"
            )
            if len(path) > 4_096 or len(role) > 1_024:
                raise ValueError("repair input capability path or role exceeds its cap")
            if SHA256_RE.fullmatch(digest) is None:
                raise ValueError("repair input capability SHA-256 is invalid")
            item = {"path": path, "sha256": digest, "role": role}
            previous_role = by_role.get(role)
            if previous_role is not None and previous_role != item:
                raise ValueError("repair input capability role has conflicting bytes")
            previous_digest = by_path.get(path)
            if previous_digest is not None and previous_digest != digest:
                raise ValueError("repair input capability path has conflicting bytes")
            by_role[role] = item
            by_path[path] = digest
            candidates.append(item)

        # One byte capability is sufficient even if several inherited cards
        # named it under different local roles.  Retain the lexicographically
        # first role so the union is deterministic and bounded.
        by_binding: dict[tuple[str, str], dict[str, str]] = {}
        for item in sorted(
            candidates,
            key=lambda current: (
                current["path"],
                current["sha256"],
                current["role"],
            ),
        ):
            by_binding.setdefault((item["path"], item["sha256"]), item)
        normalized = sorted(
            by_binding.values(),
            key=lambda item: (item["role"], item["path"], item["sha256"]),
        )
        if len(normalized) > V5_MAX_REPAIR_INPUT_CAPABILITIES:
            raise ValueError("repair input capabilities exceed the 256-item cap")
        return normalized

    def _validate_repair_input_capability_files(
        self,
        capabilities: list[dict[str, str]],
        *,
        bounded_repair: bool = True,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> None:
        for item in capabilities:
            try:
                path = self._lexical_contained_path(
                    item["path"], "repair input capability path"
                )
                if bounded_repair:
                    self._repair_capability_bytes(
                        path,
                        item["sha256"],
                        label="repair input capability",
                        _inspection_context=_inspection_context,
                    )
                else:
                    self._ordinary_capability_bytes(
                        path,
                        item["sha256"],
                        label="repair input capability",
                        _inspection_context=_inspection_context,
                    )
            except ValueError as exc:
                # Keep the schema-1/2 Research capability interface stable;
                # direct CHX-016 callers still receive the detailed helper
                # error when they need to distinguish missing, drifted, or
                # over-capability inputs.
                raise ValueError("Research capability artifact drifted") from exc

    def _repair_capabilities_from_frozen_card(
        self,
        *,
        assignment: dict[str, Any],
        card: dict[str, Any],
        origin: str,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> list[dict[str, str]]:
        capabilities: list[dict[str, str]] = [
            {
                "path": assignment["task_card_relpath"],
                "sha256": assignment["task_card_sha256"],
                "role": (
                    f"{origin}:task_card:{assignment['assignment_id']}"
                ),
            }
        ]
        mathematical_state = card.get("mathematical_state")
        if not isinstance(mathematical_state, dict):
            raise ValueError("repair source task card lacks mathematical state")
        raw_capabilities = [
            *mathematical_state.get("related_artifacts", []),
            *mathematical_state.get("authority_snapshot", {}).get(
                "capabilities", []
            ),
        ]
        for index, item in enumerate(raw_capabilities, 1):
            if (
                not isinstance(item, dict)
                or not isinstance(item.get("path"), str)
                or not isinstance(item.get("sha256"), str)
                or not isinstance(item.get("role"), str)
            ):
                raise ValueError("repair source task-card capability is invalid")
            capabilities.append(
                {
                    "path": item["path"],
                    "sha256": item["sha256"],
                    "role": f"{origin}:input_{index:03d}:{item['role']}",
                }
            )
        fact_bindings = mathematical_state.get("authority_snapshot", {}).get(
            "fact_bindings", []
        )
        if not isinstance(fact_bindings, list):
            raise ValueError("repair source task-card Fact bindings are invalid")
        for binding in fact_bindings:
            if not isinstance(binding, dict) or binding.get("status") != "active":
                continue
            fact_id = validate_fact_id(binding.get("fact_id"))
            expected_sha = binding.get("fact_sha256")
            if not isinstance(expected_sha, str) or SHA256_RE.fullmatch(expected_sha) is None:
                raise ValueError("repair source active Fact binding is invalid")
            fact_path = self.store.active_fact_path(fact_id)
            fact_raw = self._repair_capability_bytes(
                fact_path,
                expected_sha,
                label="repair source active Fact",
                require_single_link=True,
                _inspection_context=_inspection_context,
            )
            capabilities.append(
                {
                    "path": fact_path.relative_to(self.store.root).as_posix(),
                    "sha256": expected_sha,
                    "role": f"{origin}:active_fact:{fact_id}",
                }
            )
        return capabilities

    def _repair_capabilities_from_assignment_provenance(
        self,
        record: dict[str, Any],
        *,
        origin: str,
        _inspection_context: RoundInspectionContext,
    ) -> list[dict[str, str]]:
        metadata = record.get("metadata", {})
        provenance = metadata.get("assignment_provenance")
        if provenance is None:
            return []
        self._research_is_adverse_assignment(record)
        round_dir, manifest = self._round_manifest(
            provenance["round_id"],
            _inspection_context=_inspection_context,
        )
        assignment = self._assignment(manifest, provenance["assignment_id"])
        product, receipt = self._research_product_for_assignment(
            round_dir=round_dir,
            manifest=manifest,
            assignment=assignment,
            _inspection_context=_inspection_context,
        )
        task_binding = metadata.get("task_binding")
        product_binding = product.get("metadata", {}).get("task_binding", {})
        product_return_sha = (
            receipt["return_sha256"]
            if receipt is not None
            else product_binding.get("return_sha256")
        )
        if (
            assignment["task_card_sha256"] != provenance["task_card_sha256"]
            or assignment["worker_id"] != record["actor"]
            or product["research_id"] != record["research_id"]
            or not isinstance(task_binding, dict)
            or product_return_sha != task_binding.get("return_sha256")
        ):
            raise ValueError("repair source assignment provenance drifted")
        card_path = self._lexical_contained_path(
            assignment["task_card_relpath"], "repair source task card"
        )
        raw_card = self._repair_capability_bytes(
            card_path,
            assignment["task_card_sha256"],
            label="repair source task card",
            _inspection_context=_inspection_context,
        )
        try:
            card = json.loads(raw_card.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise ValueError("repair source task card is not valid JSON") from exc
        capabilities = self._repair_capabilities_from_frozen_card(
            assignment=assignment,
            card=card,
            origin=f"{origin}:{record['research_id']}",
            _inspection_context=_inspection_context,
        )

        # A pre-0.7.14 supervisor card may not itself contain the attacked
        # production inputs.  Follow only its exact, validated source receipt
        # binding; never infer a production card from prose or recurse through
        # arbitrary Research relations.
        source_dossier = card.get("mathematical_state", {}).get(
            "source_research_dossier", {}
        )
        source_metadata = (
            source_dossier.get("metadata", {})
            if isinstance(source_dossier, dict)
            else {}
        )
        supervision = source_metadata.get("research_supervision")
        if supervision is not None:
            binding = self._validate_research_supervision_binding(
                supervision,
                _inspection_context=_inspection_context,
            )
            component_id = (
                binding.get("source_component_id")
                if binding["revision"] == V5_RESEARCH_SUPERVISION_REVISION
                else None
            )
            source_manifest, descriptors = self._source_round_receipt_descriptors(
                binding["source_round_id"],
                source_component_id=component_id,
                _inspection_context=_inspection_context,
            )
            if (
                source_manifest["manifest_sha256"]
                != binding["source_round_manifest_sha256"]
            ):
                raise ValueError("repair supervision source manifest drifted")
            descriptor_by_assignment = {
                item["assignment_id"]: item for item in descriptors
            }
            source_assignment_by_id = {
                item["assignment_id"]: item
                for item in source_manifest["assignments"]
            }
            for descriptor in binding["source_receipts"]:
                current = descriptor_by_assignment.get(
                    descriptor["assignment_id"]
                )
                if current != descriptor:
                    raise ValueError("repair supervision source receipt drifted")
                source_assignment = source_assignment_by_id[
                    descriptor["assignment_id"]
                ]
                source_card_path = self._lexical_contained_path(
                    source_assignment["task_card_relpath"],
                    "repair supervised production task card",
                )
                source_card_raw = self._repair_capability_bytes(
                    source_card_path,
                    source_assignment["task_card_sha256"],
                    label="repair supervised production task card",
                    _inspection_context=_inspection_context,
                )
                source_card = json.loads(source_card_raw.decode("utf-8"))
                capabilities.extend(
                    self._repair_capabilities_from_frozen_card(
                        assignment=source_assignment,
                        card=source_card,
                        origin=(
                            f"{origin}:{record['research_id']}:"
                            f"source_receipt:{descriptor['assignment_id']}"
                        ),
                        _inspection_context=_inspection_context,
                    )
                )
        return capabilities

    def _repair_input_capability_manifest(
        self,
        *,
        source: dict[str, Any],
        trigger: dict[str, Any] | None,
        explicit_capabilities: list[dict[str, str]],
        _inspection_context: RoundInspectionContext,
    ) -> dict[str, Any]:
        capabilities: list[dict[str, str]] = list(explicit_capabilities)
        for origin, record in (
            ("source", source),
            ("trigger", trigger),
        ):
            if record is None:
                continue
            # Preserve the source record's declared artifact role in the
            # repair capability closure.  The role is part of the frozen
            # source contract; prefixing it with an actor/research id here
            # changes an otherwise byte-identical repair artifact projection
            # and breaks compatibility with existing source-bound repairs.
            for item in record.get("metadata", {}).get("artifacts", []):
                if (
                    not isinstance(item, dict)
                    or set(item) != {"path", "sha256", "role"}
                ):
                    raise ValueError("repair source artifact binding is invalid")
                path = self._lexical_contained_path(
                    item["path"], "repair source artifact path"
                )
                raw = self._repair_capability_bytes(
                    path,
                    item["sha256"],
                    label="repair source artifact",
                    _inspection_context=_inspection_context,
                )
                capabilities.append(
                    {
                        "path": item["path"],
                        "sha256": item["sha256"],
                        "role": item["role"],
                    }
                )
            capabilities.extend(
                self._repair_capabilities_from_assignment_provenance(
                    record,
                    origin=origin,
                    _inspection_context=_inspection_context,
                )
            )
        normalized = self._normalize_repair_input_capabilities(capabilities)
        self._validate_repair_input_capability_files(
            normalized,
            _inspection_context=_inspection_context,
        )
        semantic = {
            "revision": V5_REPAIR_INPUT_CAPABILITY_REVISION,
            "source_research_id": source["research_id"],
            "trigger_research_id": (
                trigger["research_id"] if trigger is not None else None
            ),
            "input_capabilities": normalized,
            "selection_policy": (
                "direct_research_plus_one_verified_assignment_or_source_receipt_hop"
            ),
            "max_capabilities": V5_MAX_REPAIR_INPUT_CAPABILITIES,
            "truth_effect": "none",
        }
        return {
            **semantic,
            "manifest_sha256": sha256_json(semantic),
        }

    def _structured_source_evidence_capabilities_from_card(
        self,
        *,
        card: dict[str, Any],
        origin: str,
    ) -> list[dict[str, str]]:
        """Expand explicitly declared source-evidence bytes for review cards.

        A source-evidence JSON artifact may name rendered-primary files that
        are not themselves direct Research artifacts.  Those names are a
        capability declaration only when they are present in the frozen card's
        related-artifact set and the JSON has the structured
        ``source_artifacts`` shape.  Free prose, filenames, and arbitrary
        metadata never grant a worker read access.
        """

        mathematical_state = card.get("mathematical_state")
        if not isinstance(mathematical_state, dict):
            raise ValueError("source-evidence task card lacks mathematical state")
        related = mathematical_state.get("related_artifacts", [])
        if not isinstance(related, list):
            raise ValueError("source-evidence related artifacts are invalid")
        expanded: list[dict[str, str]] = []
        seen: set[tuple[str, str]] = set()
        for related_item in related:
            if not isinstance(related_item, dict):
                raise ValueError("source-evidence related artifact is invalid")
            path_value = related_item.get("path")
            digest_value = related_item.get("sha256")
            if not isinstance(path_value, str) or not path_value:
                raise ValueError("source-evidence related artifact path is invalid")
            if not isinstance(digest_value, str) or SHA256_RE.fullmatch(digest_value) is None:
                raise ValueError("source-evidence related artifact SHA-256 is invalid")
            path = self._lexical_contained_path(
                path_value, "source-evidence related artifact"
            )
            raw = self._read_regular_bytes_once(
                path,
                label="source-evidence related artifact",
                containment_root=self.store.root,
            )
            if sha256_bytes(raw) != digest_value:
                raise ValueError("source-evidence related artifact bytes/hash mismatch")
            if path.suffix.lower() != ".json":
                continue
            try:
                payload = json.loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError):
                continue
            source_artifacts = (
                payload.get("source_artifacts")
                if isinstance(payload, dict)
                else None
            )
            if source_artifacts is None:
                continue
            if not isinstance(source_artifacts, list):
                raise ValueError("structured source-evidence source_artifacts must be a list")
            for index, source_item in enumerate(source_artifacts, 1):
                if not isinstance(source_item, dict):
                    raise ValueError(
                        f"structured source-evidence item {index} is invalid"
                    )
                source_key = source_item.get("source_key")
                if not isinstance(source_key, str) or not source_key:
                    raise ValueError(
                        f"structured source-evidence item {index} lacks exact source key/path/hash"
                    )

                # Older frozen cards use ``path``/``sha256`` or the explicit
                # ``card_authorized_path``/``returned_copy_path`` pair.  These
                # spellings carry the same capability when their bytes agree;
                # normalize them at the read boundary instead of forcing a
                # historical-card rewrite.  A locator without a concrete file
                # remains deliberately non-authorizing.
                hash_values: list[tuple[str, str]] = []
                for hash_field in ("artifact_sha256", "sha256"):
                    hash_value = source_item.get(hash_field)
                    if hash_value is None:
                        continue
                    if (
                        not isinstance(hash_value, str)
                        or SHA256_RE.fullmatch(hash_value) is None
                    ):
                        raise ValueError(
                            f"structured source-evidence item {index} has invalid source hash"
                        )
                    hash_values.append((hash_field, hash_value))
                if not hash_values:
                    # A locator-only entry is navigation metadata, not a
                    # capability.  It must not block concrete bytes declared
                    # elsewhere on the frozen card.
                    continue
                if len({value for _, value in hash_values}) != 1:
                    raise ValueError(
                        f"structured source-evidence item {index} lacks exact source key/path/hash"
                    )
                source_sha = hash_values[0][1]

                path_fields = (
                    "returned_copy_path",
                    "artifact_path",
                    "path",
                    "card_authorized_path",
                )
                declared_paths: list[tuple[str, str]] = []
                for path_field in path_fields:
                    path_value = source_item.get(path_field)
                    if path_value is None:
                        continue
                    if not isinstance(path_value, str) or not path_value:
                        raise ValueError(
                            f"structured source-evidence item {index} has invalid source path"
                        )
                    declared_paths.append((path_field, path_value))
                if not declared_paths:
                    # A valid digest paired only with a locator is still
                    # non-authorizing metadata; concrete card artifacts remain
                    # the authority for worker reads.
                    continue

                # Validate every declared spelling.  This prevents a stale
                # returned copy or card path from silently shadowing the
                # selected deterministic path.
                for _, source_path_value in declared_paths:
                    source_file = self._lexical_contained_path(
                        source_path_value,
                        "structured source-evidence source artifact",
                    )
                    source_raw = self._read_regular_bytes_once(
                        source_file,
                        label="structured source-evidence source artifact",
                        containment_root=self.store.root,
                    )
                    if sha256_bytes(source_raw) != source_sha:
                        raise ValueError(
                            "structured source-evidence source artifact bytes/hash mismatch"
                        )

                source_path = next(
                    path_value
                    for field in path_fields
                    for declared_field, path_value in declared_paths
                    if declared_field == field
                )
                if not source_path:
                    raise ValueError(
                        f"structured source-evidence item {index} lacks exact source key/path/hash"
                    )
                key = (source_path, source_sha)
                if key in seen:
                    continue
                seen.add(key)
                expanded.append(
                    {
                        "path": source_path,
                        "sha256": source_sha,
                        # ``source_artifacts`` is the structured declaration of
                        # concrete primary bytes.  Preserve that semantic role
                        # when the capability is projected into a supervisor
                        # card; otherwise the later source-use validator sees
                        # the same path/hash but loses the direct-primary
                        # authority that the frozen evidence already granted.
                        "role": f"{origin}:primary_source:{source_key}",
                    }
                )
        return sorted(
            expanded,
            key=lambda item: (item["role"], item["path"], item["sha256"]),
        )

    def _validate_repair_input_capability_manifest(
        self,
        value: Any,
        *,
        bounded_repair: bool = True,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any]:
        required = {
            "revision",
            "source_research_id",
            "trigger_research_id",
            "input_capabilities",
            "selection_policy",
            "max_capabilities",
            "truth_effect",
            "manifest_sha256",
        }
        if not isinstance(value, dict) or set(value) != required:
            raise ValueError("repair input capability manifest fields are not exact")
        capabilities = self._normalize_repair_input_capabilities(
            value["input_capabilities"]
        )
        semantic = {key: item for key, item in value.items() if key != "manifest_sha256"}
        if (
            value["revision"] != V5_REPAIR_INPUT_CAPABILITY_REVISION
            or validate_memory_id(value["source_research_id"])
            != value["source_research_id"]
            or (
                value["trigger_research_id"] is not None
                and validate_memory_id(value["trigger_research_id"])
                != value["trigger_research_id"]
            )
            or value["input_capabilities"] != capabilities
            or value["selection_policy"]
            != "direct_research_plus_one_verified_assignment_or_source_receipt_hop"
            or value["max_capabilities"] != V5_MAX_REPAIR_INPUT_CAPABILITIES
            or value["truth_effect"] != "none"
            or value["manifest_sha256"] != sha256_json(semantic)
        ):
            raise ValueError("repair input capability manifest is invalid")
        self._validate_repair_input_capability_files(
            capabilities,
            bounded_repair=bounded_repair,
            _inspection_context=_inspection_context,
        )
        return value

    def _validate_repair_input_capability_metadata(
        self,
        *,
        kind: str,
        metadata: dict[str, Any],
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any] | None:
        manifest = metadata.get("repair_input_capability_manifest")
        if manifest is None:
            return None
        if kind != "repair":
            raise ValueError(
                "repair input capability manifest requires one repair record"
            )
        spec = metadata.get("repair_spec")
        bounded_repair = (
            isinstance(spec, dict) and spec.get("schema_version") == 2
        )
        manifest = self._validate_repair_input_capability_manifest(
            manifest,
            bounded_repair=bounded_repair,
            _inspection_context=_inspection_context,
        )
        capabilities = manifest["input_capabilities"]
        raw_artifacts = metadata.get("artifacts", [])
        artifacts = self._normalize_repair_input_capabilities(raw_artifacts)
        if raw_artifacts != artifacts:
            raise ValueError(
                "repair Research artifacts must be the canonical capability list"
            )
        if artifacts != capabilities:
            raise ValueError(
                "repair input capability manifest and Research artifacts disagree"
            )
        source_dependent = metadata.get("source_dependent")
        if not isinstance(source_dependent, bool):
            raise ValueError("repair source_dependent must be boolean")
        # A schema-1 repair with no frozen input bytes is a valid non-source
        # repair.  The capability manifest is still recorded as an explicit
        # empty closure, but it must not manufacture a source dependency (or
        # reject the repair merely because the closure is empty).  Once any
        # capability is present, the repair is necessarily source-dependent.
        if capabilities and source_dependent is not True:
            raise ValueError(
                "repair input capability manifest requires source_dependent=true"
            )
        if isinstance(spec, dict) and spec.get("schema_version") == 2:
            if spec.get("input_capabilities") != capabilities:
                raise ValueError(
                    "schema-v2 repair specification and capability manifest disagree"
                )
        return manifest

    def _validate_schema_v2_repair_lineage(
        self,
        *,
        kind: str,
        relation: str | None,
        related_research_ids: list[str],
        metadata: dict[str, Any],
        require_existing: bool = False,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> None:
        spec = metadata.get("repair_spec")
        if not isinstance(spec, dict) or spec.get("schema_version") != 2:
            return
        if kind != "repair":
            raise ValueError("schema-v2 repair lineage requires one repair record")
        if relation != "repairs":
            raise ValueError("schema-v2 repair relation must be repairs")

        manifest = metadata.get("repair_input_capability_manifest")
        if not isinstance(manifest, dict):
            raise ValueError("schema-v2 repair lineage lacks its capability manifest")
        source_research_id = validate_memory_id(
            _require_nonempty_text(
                metadata.get("repair_of_research_id"),
                "schema-v2 repair source Research id",
            )
        )
        trigger_research_id = metadata.get("trigger_research_id")
        if trigger_research_id is not None:
            trigger_research_id = validate_memory_id(
                _require_nonempty_text(
                    trigger_research_id,
                    "schema-v2 repair trigger Research id",
                )
            )
        if manifest.get("source_research_id") != source_research_id:
            raise ValueError(
                "schema-v2 repair source lineage disagrees with capability manifest"
            )
        if manifest.get("trigger_research_id") != trigger_research_id:
            raise ValueError(
                "schema-v2 repair trigger lineage disagrees with capability manifest"
            )
        expected_related = sorted(
            dict.fromkeys(
                [
                    source_research_id,
                    *(
                        [trigger_research_id]
                        if trigger_research_id is not None
                        else []
                    ),
                ]
            )
        )
        if related_research_ids != expected_related:
            raise ValueError(
                "schema-v2 repair related Research lineage is not exact"
            )
        if require_existing:
            inspection = self._bind_inspection_context(
                _inspection_context,
                create=True,
            )
            assert inspection is not None
            self._inspection_research_record(source_research_id, inspection)
            if trigger_research_id is not None:
                self._inspection_research_record(
                    trigger_research_id,
                    inspection,
                )

    def _expected_repair_task_capabilities(
        self,
        record: dict[str, Any],
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> list[dict[str, str]] | None:
        """Project one repair manifest into its exact task-card capability shape.

        Repair input capabilities and obligation output roles are deliberately
        different namespaces.  Only the manifest's path/SHA/role triples are
        projected here; ``required_artifact_roles`` describes future return
        artifacts and must never grant an input read capability.
        """

        manifest = self._validate_repair_input_capability_metadata(
            kind=record["kind"],
            metadata=record["metadata"],
            _inspection_context=_inspection_context,
        )
        if manifest is None:
            return None
        research_id = record["research_id"]
        return sorted(
            [
                {
                    "path": item["path"],
                    "sha256": item["sha256"],
                    "role": f"{research_id}:{item['role']}",
                    "source_research_id": research_id,
                }
                for item in manifest["input_capabilities"]
            ],
            key=lambda item: (
                item["source_research_id"],
                item["role"],
                item["path"],
                item["sha256"],
            ),
        )

    def _validate_repair_task_capability_closure(
        self,
        *,
        record: dict[str, Any],
        related_artifacts: list[dict[str, str]],
        _inspection_context: RoundInspectionContext | None = None,
    ) -> None:
        expected = self._expected_repair_task_capabilities(
            record,
            _inspection_context=_inspection_context,
        )
        if expected is None:
            return
        research_id = record["research_id"]
        actual = sorted(
            [
                item
                for item in related_artifacts
                if item.get("source_research_id") == research_id
            ],
            key=lambda item: (
                item.get("source_research_id", ""),
                item.get("role", ""),
                item.get("path", ""),
                item.get("sha256", ""),
            ),
        )
        if actual != expected:
            raise ValueError(
                "repair task-card input capability closure drifted"
            )

    @staticmethod
    def _research_is_source_dependent(record: dict[str, Any]) -> bool:
        metadata = record.get("metadata", {})
        explicit = metadata.get("source_dependent", False)
        if not isinstance(explicit, bool):
            raise ValueError("Research source_dependent must be boolean")
        source_text = "\n".join(
            str(record.get(field, ""))
            for field in ("claim", "content", "rationale", "source")
        )
        return explicit or _LOCAL_SOURCE_PATH_RE.search(source_text) is not None

    @staticmethod
    def _research_artifact_bindings(record: dict[str, Any]) -> list[dict[str, str]]:
        artifacts = record.get("metadata", {}).get("artifacts", [])
        if not isinstance(artifacts, list):
            raise ValueError("Research artifact bindings must be a list")
        return sorted(
            [
                {"role": item["role"], "sha256": item["sha256"]}
                for item in artifacts
            ],
            key=lambda item: (item["role"], item["sha256"]),
        )

    @staticmethod
    def _validate_logical_supervision_component_structure(
        payload: Any,
        *,
        assignments: list[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        """Validate one immutable partition of production assignments.

        Components are frozen before dispatch.  They are not a projection of
        whichever workers happened to return first, so an identical planning
        retry cannot silently widen or shrink the object under supervision.
        """

        if not isinstance(payload, list) or not payload:
            raise ValueError(
                "logical supervision components must be a nonempty list"
            )
        assignment_by_id = {
            item["assignment_id"]: item for item in assignments
        }
        if len(assignment_by_id) != len(assignments):
            raise ValueError(
                "logical supervision components require unique assignments"
            )
        expected_assignment_ids = sorted(assignment_by_id)
        covered_assignment_ids: list[str] = []
        seen_component_ids: set[str] = set()
        validated: list[dict[str, Any]] = []
        required = {
            "revision",
            "component_id",
            "component_sha256",
            "assignment_ids",
            "research_ids",
            "relation_policy",
            "truth_effect",
        }
        for component in payload:
            if not isinstance(component, dict) or set(component) != required:
                raise ValueError(
                    "logical supervision component fields are not exact"
                )
            assignment_ids = _require_string_list(
                component["assignment_ids"],
                "logical supervision component assignment ids",
            )
            research_ids = _require_string_list(
                component["research_ids"],
                "logical supervision component Research ids",
            )
            if (
                component["revision"]
                != V5_LOGICAL_SUPERVISION_COMPONENT_REVISION
                or component["relation_policy"]
                != "selected_research_ancestry_connected_components"
                or component["truth_effect"] != "none"
                or not assignment_ids
                or assignment_ids != sorted(set(assignment_ids))
                or research_ids != sorted(set(research_ids))
                or len(assignment_ids) != len(research_ids)
            ):
                raise ValueError("logical supervision component is invalid")
            try:
                component_assignments = [
                    assignment_by_id[assignment_id]
                    for assignment_id in assignment_ids
                ]
            except KeyError as exc:
                raise ValueError(
                    "logical supervision component names an unknown assignment"
                ) from exc
            if sorted(
                item["research_id"] for item in component_assignments
            ) != research_ids:
                raise ValueError(
                    "logical supervision component Research projection drifted"
                )
            semantic = {
                "revision": component["revision"],
                "assignment_ids": assignment_ids,
                "research_ids": research_ids,
                "relation_policy": component["relation_policy"],
                "truth_effect": component["truth_effect"],
            }
            component_sha = sha256_json(semantic)
            component_id = "component-" + component_sha[:16]
            if (
                component["component_sha256"] != component_sha
                or component["component_id"] != component_id
                or component_id in seen_component_ids
            ):
                raise ValueError(
                    "logical supervision component identity is invalid"
                )
            seen_component_ids.add(component_id)
            covered_assignment_ids.extend(assignment_ids)
            validated.append(component)
        if (
            len(covered_assignment_ids) != len(set(covered_assignment_ids))
            or sorted(covered_assignment_ids) != expected_assignment_ids
        ):
            raise ValueError(
                "logical supervision components must partition assignments exactly"
            )
        if validated != sorted(
            validated, key=lambda item: item["component_id"]
        ):
            raise ValueError(
                "logical supervision components are not canonical"
            )
        return validated

    def _validate_logical_supervision_components(
        self,
        payload: Any,
        *,
        assignments: list[dict[str, Any]],
        _inspection_context: RoundInspectionContext | None = None,
    ) -> list[dict[str, Any]]:
        """Validate structure and rederive the partition from Research ancestry.

        Component hashes authenticate the declared partition, but a caller can
        also rehash a different self-consistent partition.  Authority therefore
        comes from rederiving the connected components from the exact selected
        Research records, not from trusting the manifest's own grouping.
        """

        validated = self._validate_logical_supervision_component_structure(
            payload,
            assignments=assignments,
        )
        inspection = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert inspection is not None
        source_records = {
            assignment["research_id"]: self._inspection_research_record(
                assignment["research_id"], inspection
            )
            for assignment in assignments
        }
        derived = self._build_logical_supervision_components(
            assignments=assignments,
            source_records=source_records,
            _inspection_context=inspection,
            validate_result=False,
        )
        if validated != derived:
            raise ValueError(
                "logical supervision component partition drifted from "
                "Research ancestry"
            )
        return validated

    def _build_logical_supervision_components(
        self,
        *,
        assignments: list[dict[str, Any]],
        source_records: dict[str, dict[str, Any]],
        _inspection_context: RoundInspectionContext | None = None,
        validate_result: bool = True,
    ) -> list[dict[str, Any]]:
        """Freeze dependency components from selected Research ancestry.

        Two assignments share a component exactly when one selected Research
        entry is in the ancestry of the other, transitively.  Sharing an
        admitted Fact or an older common Research premise does not serialize
        otherwise independent outputs.  A logical relation that matters for
        supervision must therefore be represented in ``related_research_ids``.
        """

        assignment_by_research: dict[str, str] = {}
        for assignment in assignments:
            research_id = assignment["research_id"]
            if research_id in assignment_by_research:
                raise ValueError(
                    "logical supervision cannot duplicate one Research assignment"
                )
            assignment_by_research[research_id] = assignment["assignment_id"]
        selected_ids = set(assignment_by_research)
        if selected_ids != set(source_records):
            raise ValueError(
                "logical supervision source records do not match assignments"
            )

        parent = {research_id: research_id for research_id in selected_ids}

        def find(research_id: str) -> str:
            while parent[research_id] != research_id:
                parent[research_id] = parent[parent[research_id]]
                research_id = parent[research_id]
            return research_id

        def union(left: str, right: str) -> None:
            left_root = find(left)
            right_root = find(right)
            if left_root != right_root:
                parent[max(left_root, right_root)] = min(left_root, right_root)

        inspection = self._bind_inspection_context(_inspection_context)
        if (
            inspection is not None
            and inspection.research_envelopes_by_id is not None
        ):
            record_cache = dict(inspection.research_envelopes_by_id)
            record_cache.update(source_records)
        else:
            record_cache = dict(source_records)
        for root_id in sorted(selected_ids):
            seen: set[str] = set()
            pending = list(source_records[root_id]["related_research_ids"])
            while pending:
                related_id = pending.pop()
                if related_id == root_id:
                    raise ValueError(
                        "logical supervision Research ancestry is cyclic"
                    )
                if related_id in seen:
                    continue
                seen.add(related_id)
                if related_id in selected_ids:
                    union(root_id, related_id)
                record = record_cache.get(related_id)
                if record is None:
                    # Component construction needs only immutable identity and
                    # direct Research connectivity for unselected ancestors.
                    # Full artifact, supervision, runtime, and Fact replay is
                    # reserved for the selected authority-bearing records.
                    # This structural envelope is hash-checked and never
                    # supplies a premise or artifact capability.
                    record = self._research_record_envelope(related_id)
                    record_cache[related_id] = record
                pending.extend(record["related_research_ids"])

        grouped: dict[str, list[str]] = {}
        for research_id in sorted(selected_ids):
            grouped.setdefault(find(research_id), []).append(research_id)
        components: list[dict[str, Any]] = []
        for research_ids in grouped.values():
            research_ids = sorted(research_ids)
            assignment_ids = sorted(
                assignment_by_research[research_id]
                for research_id in research_ids
            )
            semantic = {
                "revision": V5_LOGICAL_SUPERVISION_COMPONENT_REVISION,
                "assignment_ids": assignment_ids,
                "research_ids": research_ids,
                "relation_policy": (
                    "selected_research_ancestry_connected_components"
                ),
                "truth_effect": "none",
            }
            component_sha = sha256_json(semantic)
            components.append(
                {
                    **semantic,
                    "component_id": "component-" + component_sha[:16],
                    "component_sha256": component_sha,
                }
            )
        components.sort(key=lambda item: item["component_id"])
        if not validate_result:
            return components
        return self._validate_logical_supervision_component_structure(
            components,
            assignments=assignments,
        )

    def _source_supervision_component(
        self,
        manifest: dict[str, Any],
        source_component_id: str | None,
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any] | None:
        components = manifest.get("supervision_components")
        if components is None:
            if source_component_id is not None:
                raise ValueError(
                    "historical production rounds have no logical component ids"
                )
            return None
        components = self._validate_logical_supervision_components(
            components,
            assignments=manifest["assignments"],
            _inspection_context=_inspection_context,
        )
        if source_component_id is None:
            if len(components) != 1:
                raise ValueError(
                    "source component id is required for multi-component production"
                )
            return components[0]
        source_component_id = _require_nonempty_text(
            source_component_id,
            "source component id",
        )
        matches = [
            component
            for component in components
            if component["component_id"] == source_component_id
        ]
        if len(matches) != 1:
            raise ValueError("unknown logical supervision component")
        return matches[0]

    def _source_component_id_for_assignment(
        self,
        manifest: dict[str, Any],
        assignment_id: str,
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> str | None:
        assignment_id = validate_assignment_id(assignment_id)
        components = manifest.get("supervision_components")
        if components is None:
            return None
        components = self._validate_logical_supervision_components(
            components,
            assignments=manifest["assignments"],
            _inspection_context=_inspection_context,
        )
        matches = [
            component["component_id"]
            for component in components
            if assignment_id in component["assignment_ids"]
        ]
        if len(matches) != 1:
            raise ValueError(
                "assignment does not belong to exactly one logical component"
            )
        return matches[0]

    def _research_product_for_assignment(
        self,
        *,
        round_dir: Path,
        manifest: dict[str, Any],
        assignment: dict[str, Any],
        _inspection_context: RoundInspectionContext | None = None,
    ) -> tuple[dict[str, Any], dict[str, Any] | None]:
        """Return the immutable worker product without requiring its receipt.

        ``ingest_return`` publishes the Research record before it writes the
        derived ``*.receipt.json`` file.  The Research record carries the
        assignment provenance, task-card hash, return hash, owner, stage, and
        worker outcome, so a downstream logical component can safely consume
        that product during the narrow recovery interval in which the receipt
        is absent.  A receipt that is present is still checked as optional
        provenance; it is never the capability that authorizes the read.

        Historical records without assignment provenance retain the old
        receipt fallback so legacy graph data stays directly readable.
        """

        inspection = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert inspection is not None
        round_id = validate_round_id(
            _require_nonempty_text(manifest.get("round_id"), "product round id")
        )
        assignment_id = validate_assignment_id(
            _require_nonempty_text(
                assignment.get("assignment_id"), "product assignment id"
            )
        )
        if manifest.get("round_id") != round_dir.name or round_id != round_dir.name:
            raise ValueError("worker product round identity drifted")
        product_cache_key = (
            round_id,
            assignment_id,
            str(assignment.get("task_card_sha256") or ""),
        )
        cached_product = inspection.research_product_bindings.get(
            product_cache_key
        )
        if cached_product is not None:
            return cached_product

        if inspection.research_products_by_assignment is None:
            index: dict[tuple[str, str], list[dict[str, Any]]] = {}
            for envelope in self.research_envelopes(
                _inspection_context=inspection,
            ):
                metadata = envelope.get("metadata", {})
                provenance = (
                    metadata.get("assignment_provenance")
                    if isinstance(metadata, dict)
                    else None
                )
                if not isinstance(provenance, dict):
                    continue
                key = (
                    str(provenance.get("round_id") or ""),
                    str(provenance.get("assignment_id") or ""),
                )
                if not key[0] or not key[1]:
                    continue
                index.setdefault(key, []).append(envelope)
            for values in index.values():
                values.sort(key=lambda item: item["research_id"])
            inspection.research_products_by_assignment = index

        candidates = inspection.research_products_by_assignment.get(
            (round_id, assignment_id), []
        )
        matching: list[dict[str, Any]] = []
        for envelope in candidates:
            metadata = envelope.get("metadata", {})
            provenance = (
                metadata.get("assignment_provenance")
                if isinstance(metadata, dict)
                else None
            )
            task_binding = (
                metadata.get("task_binding") if isinstance(metadata, dict) else None
            )
            if not isinstance(provenance, dict) or not isinstance(task_binding, dict):
                continue
            if (
                provenance.get("task_card_sha256")
                != assignment.get("task_card_sha256")
                or provenance.get("worker_id") != assignment.get("worker_id")
                or provenance.get("work_mode") != assignment.get("work_mode")
                or task_binding.get("assignment_id") != assignment_id
                or task_binding.get("round_id") != round_id
                or task_binding.get("task_card_sha256")
                != assignment.get("task_card_sha256")
                or envelope.get("related_research_ids")
                != [assignment.get("research_id")]
            ):
                continue
            return_sha = task_binding.get("return_sha256")
            if not isinstance(return_sha, str) or SHA256_RE.fullmatch(return_sha) is None:
                continue
            outcome = metadata.get("worker_outcome")
            if outcome not in V5_RETURN_OUTCOMES:
                continue
            matching.append(envelope)

        if len(matching) > 1:
            raise ValueError(
                "multiple Research products are bound to one worker assignment"
            )

        optional_receipt: dict[str, Any] | None = None
        receipt_path = round_dir / "returns" / f"{assignment_id}.receipt.json"
        if receipt_path.exists() and not receipt_path.is_symlink():
            # The receipt is a derived diagnostic/provenance object.  A stale
            # or partially written copy must not hide a valid hash-bound
            # Research product; the product itself remains the owning record.
            try:
                optional_receipt = self._validated_ingest_receipt(
                    round_dir=round_dir,
                    assignment=assignment,
                    _inspection_context=inspection,
                )
            except (KeyError, OSError, ValueError):
                optional_receipt = None

        if matching:
            result = self._inspection_research_record(
                matching[0]["research_id"],
                inspection,
            )
            metadata = result["metadata"]
            provenance = metadata["assignment_provenance"]
            task_binding = metadata["task_binding"]
            if (
                optional_receipt is not None
                and (
                    optional_receipt.get("research_id") != result["research_id"]
                    or optional_receipt.get("return_sha256")
                    != task_binding.get("return_sha256")
                )
            ):
                # Keep the product authoritative.  The mismatch is useful
                # diagnostic evidence but is not a start-up capability gate.
                optional_receipt = None
            # Reassert the owner/stage binding after the full Research
            # validation, rather than trusting the structural envelope.
            if (
                provenance.get("round_id") != round_id
                or provenance.get("assignment_id") != assignment_id
                or provenance.get("task_card_sha256")
                != assignment.get("task_card_sha256")
                or provenance.get("worker_id") != assignment.get("worker_id")
                or provenance.get("work_mode") != assignment.get("work_mode")
                or not isinstance(task_binding.get("return_sha256"), str)
                or SHA256_RE.fullmatch(task_binding["return_sha256"]) is None
            ):
                raise ValueError("worker Research product provenance drifted")
            binding = (result, optional_receipt)
            inspection.research_product_bindings[product_cache_key] = binding
            return binding

        # Legacy single-wave records may not carry assignment provenance.  A
        # valid receipt remains a compatibility fallback, but a current result
        # with provenance never depends on this branch.
        if optional_receipt is not None:
            result = self._inspection_research_record(
                optional_receipt["research_id"],
                inspection,
            )
            binding = (result, optional_receipt)
            inspection.research_product_bindings[product_cache_key] = binding
            return binding
        raise ValueError(
            "worker Research product is missing for "
            f"{round_id}/{assignment_id}"
        )

    def _source_round_receipt_descriptors(
        self,
        round_id: str,
        *,
        source_component_id: str | None = None,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> tuple[dict[str, Any], list[dict[str, Any]]]:
        inspection = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert inspection is not None
        round_dir, manifest = self._round_manifest(
            round_id,
            _inspection_context=inspection,
        )
        cycle = manifest.get("research_cycle")
        if cycle is None or self._validate_research_cycle_binding(cycle)[
            "subround"
        ] != "production":
            raise ValueError(
                "Research supervision requires a prospective production subround; "
                "historical single-wave rounds are not backfilled"
            )
        if self.store.reasoning_modes().work_unit_abort(round_id) is not None:
            raise ValueError("aborted Research production cannot be supervised")
        component = self._source_supervision_component(
            manifest,
            source_component_id,
            _inspection_context=inspection,
        )
        if component is None:
            selected_assignments = manifest["assignments"]
        else:
            assignment_ids = set(component["assignment_ids"])
            selected_assignments = [
                assignment
                for assignment in manifest["assignments"]
                if assignment["assignment_id"] in assignment_ids
            ]
        descriptors: list[dict[str, Any]] = []
        for assignment in selected_assignments:
            result, receipt = self._research_product_for_assignment(
                round_dir=round_dir,
                manifest=manifest,
                assignment=assignment,
                _inspection_context=inspection,
            )
            card = self.store._read_json(
                self.store.root / assignment["task_card_relpath"]
            )
            source_metadata = card["mathematical_state"][
                "source_research_dossier"
            ]["metadata"]
            computation_phase = "none"
            if assignment["work_mode"] == "compute":
                computation_phase = (
                    "approved_execution"
                    if "approved_computation_execution" in source_metadata
                    else "core_code_design"
                )
            result_metadata = result.get("metadata", {})
            result_binding = (
                result_metadata.get("task_binding")
                if isinstance(result_metadata, dict)
                else None
            )
            result_outcome = (
                result_metadata.get("worker_outcome")
                if isinstance(result_metadata, dict)
                else None
            )
            return_sha = (
                result_binding.get("return_sha256")
                if isinstance(result_binding, dict)
                else None
            )
            if receipt is not None:
                return_sha = receipt["return_sha256"]
                result_outcome = receipt["outcome"]
            if (
                not isinstance(return_sha, str)
                or SHA256_RE.fullmatch(return_sha) is None
                or result_outcome not in V5_RETURN_OUTCOMES
            ):
                raise ValueError(
                    "worker Research product lacks an exact return binding"
                )
            source_uses = result_metadata.get("source_uses", [])
            descriptors.append(
                {
                    "assignment_id": assignment["assignment_id"],
                    "assignment_role": assignment.get(
                        "assignment_role", "legacy_primary"
                    ),
                    "source_research_id": assignment["research_id"],
                    "work_mode": assignment["work_mode"],
                    "task_card_sha256": assignment["task_card_sha256"],
                    "return_sha256": return_sha,
                    "outcome": result_outcome,
                    "result_research_id": result["research_id"],
                    "result_record_sha256": result["record_sha256"],
                    "artifact_bindings": self._research_artifact_bindings(result),
                    "has_source_uses": bool(source_uses),
                    "computation_phase": computation_phase,
                }
            )
        descriptors.sort(key=lambda item: item["assignment_id"])
        return manifest, descriptors

    def _source_round_selection_logic_signals(
        self,
        manifest: dict[str, Any],
        descriptors: list[dict[str, Any]],
    ) -> dict[str, frozenset[str]]:
        """Read prospective selection signals without changing receipt bytes.

        Source-receipt descriptors are a frozen hash contract and cannot gain
        fields retroactively.  Current component-aware production cards may,
        however, carry explicit failure-family signals that guide whether a
        supervisor is needed.  Keep those signals in this planning-only side
        channel so historical descriptor hashes and legacy cycle semantics
        remain byte-exact.
        """

        cycle = manifest.get("research_cycle")
        if (
            not isinstance(cycle, dict)
            or cycle.get("revision") != V5_RESEARCH_CYCLE_REVISION
        ):
            return {}
        assignment_by_id = {
            assignment["assignment_id"]: assignment
            for assignment in manifest["assignments"]
        }
        selected: dict[str, frozenset[str]] = {}
        for descriptor in descriptors:
            assignment_id = descriptor["assignment_id"]
            assignment = assignment_by_id.get(assignment_id)
            if assignment is None:
                raise ValueError(
                    "Research supervision descriptor assignment is missing"
                )
            card = self.store._read_json(
                self.store.root / assignment["task_card_relpath"]
            )
            raw = card["mathematical_state"]["source_research_dossier"][
                "metadata"
            ].get("logic_signals", [])
            signals = _require_string_list(
                raw,
                "Research supervision selection logic signals",
            )
            selected[assignment_id] = frozenset(signals)
        return selected

    @staticmethod
    def _supervisor_scope_applies(
        scope: str,
        descriptor: dict[str, Any],
    ) -> bool:
        """Return the immutable receipt-coverage rule for one supervisor.

        Scope selection and receipt coverage are deliberately separate.  The
        0.7 selector may omit an unnecessary supervisor, but a supervisor that
        does exist still receives the complete historical scope it is expected
        to review.  Keeping this rule stable also preserves validation of
        already-frozen Research supervision records.
        """

        roles = {item["role"] for item in descriptor["artifact_bindings"]}
        if scope == "proof_logic":
            return descriptor["work_mode"] in {
                "prove",
                "refute",
                "interpret",
            } or descriptor["outcome"] in {
                "proof",
                "counterexample",
                "challenge",
            }
        if scope == "program_math":
            return descriptor["work_mode"] == "compute" or bool(
                {"computation_source", "computation_output"}.intersection(roles)
            )
        if scope == "source_scope":
            return descriptor["work_mode"] == "literature" or descriptor[
                "has_source_uses"
            ]
        if scope == "integration":
            return True
        raise ValueError("unsupported Research supervisor scope")

    @classmethod
    def _research_supervision_scope_receipts(
        cls,
        scope: str,
        descriptors: list[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        """Bind one selected scope to exact frozen production products.

        The sparse automatic selector may use work mode, outcome, artifact
        roles, and frozen logic signals to omit unnecessary supervisors.  Once
        Main explicitly selects a registered primary scope, however, a work
        mode classification must not make that scope targetless.  Preserve the
        historical narrow receipt subset when it is nonempty; otherwise bind
        the complete frozen component.  Integration keeps its separate
        cross-primary applicability rule at planning time.
        """

        scoped = [
            descriptor
            for descriptor in descriptors
            if cls._supervisor_scope_applies(scope, descriptor)
        ]
        if scoped:
            return scoped
        if scope in {"proof_logic", "program_math", "source_scope"}:
            return list(descriptors)
        return []

    @staticmethod
    def _failure_informed_scope_applies(
        scope: str,
        descriptor: dict[str, Any],
        *,
        logic_signals: frozenset[str] = frozenset(),
    ) -> bool:
        """Return the narrow prospective 0.7 supervisor-selection rule."""

        roles = {item["role"] for item in descriptor["artifact_bindings"]}
        if scope == "proof_logic":
            proof_artifact = any(
                role.startswith("proof")
                or role in {"counterexample", "derivation"}
                for role in roles
            )
            return (
                descriptor["work_mode"] == "prove"
                or descriptor["outcome"]
                in {"proof", "counterexample", "challenge"}
                or proof_artifact
                or bool(V5_PROOF_LOGIC_SELECTION_SIGNALS & logic_signals)
            )
        if scope == "program_math":
            return descriptor["work_mode"] == "compute" or bool(
                {"computation_source", "computation_output"}.intersection(roles)
            )
        if scope == "source_scope":
            return descriptor["work_mode"] == "literature" or descriptor[
                "has_source_uses"
            ]
        if scope == "integration":
            return True
        raise ValueError("unsupported Research supervisor scope")

    @classmethod
    def _applicable_research_supervisor_scopes(
        cls,
        descriptors: list[dict[str, Any]],
        *,
        selection_logic_signals: dict[str, frozenset[str]] | None = None,
    ) -> list[str]:
        """Select narrow assurance scopes from static reproduced failure families.

        Integration replaces the former blanket multi-return check.  It is
        useful only when one logical component crosses at least two primary
        assurance scopes; same-scope consistency remains owned by that primary
        supervisor.
        """

        primary = [
            scope
            for scope in ("program_math", "proof_logic", "source_scope")
            if any(
                cls._failure_informed_scope_applies(
                    scope,
                    descriptor,
                    logic_signals=(selection_logic_signals or {}).get(
                        descriptor.get("assignment_id", ""), frozenset()
                    ),
                )
                for descriptor in descriptors
            )
        ]
        applicable = list(primary)
        if len(descriptors) >= 2 and len(primary) >= 2:
            applicable.append("integration")
        return applicable

    @staticmethod
    def _research_supervision_focus(scope: str) -> tuple[list[str], str]:
        selected = [
            (family_id, focus)
            for family_id, family_scope, focus in V5_RESEARCH_FAILURE_FAMILIES
            if family_scope == scope
        ]
        if not selected:
            raise ValueError("Research supervisor scope has no failure-family focus")
        return [family_id for family_id, _ in selected], "; ".join(
            focus for _, focus in selected
        )

    @classmethod
    def _validate_failure_informed_assurance(
        cls,
        payload: Any,
        *,
        supervisor_scope: str,
    ) -> dict[str, Any]:
        binding = _require_exact_object_fields(
            payload,
            {
                "revision",
                "registry_sha256",
                "family_ids",
                "supervisor_scope",
                "selection_policy",
                "truth_effect",
            },
            label="failure-informed Research assurance",
            pointer="/failure_informed_assurance",
        )
        expected_ids, _ = cls._research_supervision_focus(supervisor_scope)
        family_ids = _require_string_list(
            binding["family_ids"],
            "failure-informed Research assurance family ids",
        )
        if (
            binding["revision"]
            != V5_RESEARCH_ASSURANCE_SELECTION_REVISION
            or binding["registry_sha256"]
            != V5_RESEARCH_FAILURE_FAMILY_REGISTRY_SHA256
            or family_ids != expected_ids
            or binding["supervisor_scope"] != supervisor_scope
            or binding["selection_policy"]
            not in {
                V5_LEGACY_RESEARCH_ASSURANCE_SELECTION_POLICY,
                V5_RESEARCH_ASSURANCE_SELECTION_POLICY,
            }
            or binding["truth_effect"] != "none"
        ):
            raise ValueError("failure-informed Research assurance binding drifted")
        return binding

    def _default_research_supervisor_scopes(
        self,
        descriptors: list[dict[str, Any]],
        *,
        selection_logic_signals: dict[str, frozenset[str]] | None = None,
    ) -> list[str]:
        applicable = self._applicable_research_supervisor_scopes(
            descriptors,
            selection_logic_signals=selection_logic_signals,
        )
        return applicable[:V5_RESEARCH_SUPERVISOR_LIMIT]

    def _validate_research_supervision_binding(
        self,
        payload: Any,
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any]:
        legacy_required = {
            "revision",
            "supervisor_scope",
            "source_round_id",
            "source_round_manifest_sha256",
            "source_receipts",
            "source_receipts_sha256",
            "review_policy",
            "repair_policy",
            "pulse_policy",
            "truth_effect",
        }
        current_required = legacy_required.union(
            {"source_component_id", "source_component_sha256"}
        )
        if not isinstance(payload, dict):
            raise ValueError("Research supervision binding fields are not exact")
        revision = payload.get("revision")
        required = (
            legacy_required
            if revision == V5_LEGACY_RESEARCH_SUPERVISION_REVISION
            else current_required
        )
        if set(payload) != required:
            raise ValueError("Research supervision binding fields are not exact")
        scope = payload["supervisor_scope"]
        if (
            revision
            not in {
                V5_LEGACY_RESEARCH_SUPERVISION_REVISION,
                V5_RESEARCH_SUPERVISION_REVISION,
            }
            or scope not in V5_RESEARCH_SUPERVISOR_SCOPES
            or payload["review_policy"] != "attack_exact_production_outputs"
            or payload["repair_policy"]
            != "copy_on_write_next_research_cycle"
            or payload["pulse_policy"] != "not_used"
            or payload["truth_effect"] != "none"
        ):
            raise ValueError("Research supervision policy is invalid")
        source_component_id: str | None = None
        if revision == V5_RESEARCH_SUPERVISION_REVISION:
            source_component_id = _require_nonempty_text(
                payload["source_component_id"],
                "Research supervision source component id",
            )
            component_sha = payload["source_component_sha256"]
            if (
                not source_component_id.startswith("component-")
                or not isinstance(component_sha, str)
                or SHA256_RE.fullmatch(component_sha) is None
                or source_component_id != "component-" + component_sha[:16]
            ):
                raise ValueError(
                    "Research supervision source component identity is invalid"
                )
        round_id = validate_round_id(
            _require_nonempty_text(
                payload["source_round_id"], "Research supervision source round"
            )
        )
        for key in (
            "source_round_manifest_sha256",
            "source_receipts_sha256",
        ):
            value = payload[key]
            if not isinstance(value, str) or SHA256_RE.fullmatch(value) is None:
                raise ValueError(f"Research supervision {key} is invalid")
        receipts = payload["source_receipts"]
        descriptor_fields = {
            "assignment_id",
            "assignment_role",
            "source_research_id",
            "work_mode",
            "task_card_sha256",
            "return_sha256",
            "outcome",
            "result_research_id",
            "result_record_sha256",
            "artifact_bindings",
            "has_source_uses",
            "computation_phase",
        }
        if not isinstance(receipts, list) or not receipts:
            raise ValueError("Research supervision source receipts must be nonempty")
        for descriptor in receipts:
            if not isinstance(descriptor, dict) or set(descriptor) != descriptor_fields:
                raise ValueError("Research supervision receipt fields are not exact")
            validate_assignment_id(descriptor["assignment_id"])
            validate_memory_id(descriptor["source_research_id"])
            validate_memory_id(descriptor["result_research_id"])
            if descriptor["work_mode"] not in WORK_MODES:
                raise ValueError("Research supervision work mode is invalid")
            if descriptor["outcome"] not in V5_RETURN_OUTCOMES:
                raise ValueError("Research supervision outcome is invalid")
            if descriptor["computation_phase"] not in {
                "none",
                "core_code_design",
                "approved_execution",
            }:
                raise ValueError("Research supervision computation phase is invalid")
            if not isinstance(descriptor["has_source_uses"], bool):
                raise ValueError("Research supervision source-use flag is invalid")
            for key in (
                "task_card_sha256",
                "return_sha256",
                "result_record_sha256",
            ):
                if (
                    not isinstance(descriptor[key], str)
                    or SHA256_RE.fullmatch(descriptor[key]) is None
                ):
                    raise ValueError("Research supervision receipt hash is invalid")
            artifacts = descriptor["artifact_bindings"]
            if not isinstance(artifacts, list) or any(
                not isinstance(item, dict)
                or set(item) != {"role", "sha256"}
                or not isinstance(item["role"], str)
                or not item["role"].strip()
                or SHA256_RE.fullmatch(item["sha256"]) is None
                for item in artifacts
            ):
                raise ValueError("Research supervision artifact bindings are invalid")
            if artifacts != sorted(
                artifacts, key=lambda item: (item["role"], item["sha256"])
            ):
                raise ValueError("Research supervision artifact bindings are not canonical")
        if receipts != sorted(receipts, key=lambda item: item["assignment_id"]):
            raise ValueError("Research supervision source receipts are not canonical")
        if payload["source_receipts_sha256"] != sha256_json(receipts):
            raise ValueError("Research supervision receipt-set hash drifted")
        inspection = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert inspection is not None
        validation_key = (
            round_id,
            scope,
            payload["source_round_manifest_sha256"],
            payload["source_receipts_sha256"],
            source_component_id or "",
            (
                payload.get("source_component_sha256")
                if revision == V5_RESEARCH_SUPERVISION_REVISION
                else ""
            ),
        )
        if validation_key in inspection.research_supervision_validation_stack:
            # A source task card can legitimately reconstruct admitted-Fact
            # authority, whose sealed release in turn scans Research ancestry.
            # If that ancestry reaches this same supervisor, the outer frame
            # remains responsible for the exact source comparison.  The inner
            # frame validates the complete local/hash schema and then stops at
            # this explicit cycle boundary; it does not create an authority
            # cache or accept a binding without one full outer validation.
            return payload
        inspection.research_supervision_validation_stack.add(validation_key)
        try:
            source_manifest, all_descriptors = (
                self._source_round_receipt_descriptors(
                    round_id,
                    source_component_id=source_component_id,
                    _inspection_context=inspection,
                )
            )
            if payload["source_round_manifest_sha256"] != source_manifest[
                "manifest_sha256"
            ]:
                raise ValueError("Research supervision source manifest drifted")
            source_component = self._source_supervision_component(
                source_manifest,
                source_component_id,
                _inspection_context=inspection,
            )
            if revision == V5_LEGACY_RESEARCH_SUPERVISION_REVISION:
                if source_component is not None:
                    raise ValueError(
                        "legacy supervision cannot target component-aware production"
                    )
            elif (
                source_component is None
                or payload["source_component_sha256"]
                != source_component["component_sha256"]
            ):
                raise ValueError(
                    "Research supervision source component drifted"
                )
            expected = self._research_supervision_scope_receipts(
                scope,
                all_descriptors,
            )
            # Frozen pre-0.7 integration records covered every multi-return
            # component.  The 0.7 selector no longer creates same-scope
            # integration supervisors, but validation must not reinterpret
            # immutable historical records with the new prospective policy.
            if scope == "integration" and len(all_descriptors) < 2:
                expected = []
            if not expected or receipts != expected:
                raise ValueError(
                    "Research supervision scope/receipt coverage drifted"
                )
        finally:
            inspection.research_supervision_validation_stack.remove(
                validation_key
            )
        return payload

    def _validate_research_supervision_record_fields(
        self,
        *,
        kind: str,
        status: str,
        relation: str | None,
        related_research_ids: list[str],
        metadata: dict[str, Any],
        _inspection_context: RoundInspectionContext | None = None,
    ) -> None:
        raw = metadata.get("research_supervision")
        if raw is None:
            return
        inspection = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert inspection is not None
        raw_key: tuple[str, str, str, str, str, str] | None = None
        if isinstance(raw, dict) and all(
            isinstance(raw.get(key), str)
            for key in (
                "source_round_id",
                "supervisor_scope",
                "source_round_manifest_sha256",
                "source_receipts_sha256",
            )
        ):
            raw_key = (
                raw["source_round_id"],
                raw["supervisor_scope"],
                raw["source_round_manifest_sha256"],
                raw["source_receipts_sha256"],
                str(raw.get("source_component_id") or ""),
                str(raw.get("source_component_sha256") or ""),
            )
        reentrant_source_validation = (
            raw_key is not None
            and raw_key in inspection.research_supervision_validation_stack
        )
        binding = self._validate_research_supervision_binding(
            raw,
            _inspection_context=inspection,
        )
        failure_assurance = metadata.get("failure_informed_assurance")
        if (
            binding["revision"] == V5_RESEARCH_SUPERVISION_REVISION
            and failure_assurance is not None
        ):
            self._validate_failure_informed_assurance(
                failure_assurance,
                supervisor_scope=binding["supervisor_scope"],
            )
        elif failure_assurance is not None:
            raise ValueError(
                "legacy Research supervision cannot claim failure-informed assurance"
            )
        if kind != "challenge" or status != "open" or relation != "challenges":
            raise ValueError(
                "Research supervision must be an open challenge relation"
            )
        target_ids = {
            item["result_research_id"]
            for item in binding["source_receipts"]
        }
        if (
            not reentrant_source_validation
            and binding["supervisor_scope"] == "program_math"
            and any(
            item["computation_phase"] == "approved_execution"
            for item in binding["source_receipts"]
            )
        ):
            _, source_manifest = self._round_manifest(
                binding["source_round_id"],
                _inspection_context=inspection,
            )
            assignment_by_id = {
                item["assignment_id"]: item
                for item in source_manifest["assignments"]
            }
            for descriptor in binding["source_receipts"]:
                if descriptor["computation_phase"] != "approved_execution":
                    continue
                assignment = assignment_by_id[descriptor["assignment_id"]]
                card = self.store._read_json(
                    self.store.root / assignment["task_card_relpath"]
                )
                approved = card["mathematical_state"][
                    "source_research_dossier"
                ]["metadata"].get("approved_computation_execution")
                approved = self._validate_approved_computation_execution_binding(
                    approved,
                    _inspection_context=inspection,
                )
                target_ids.add(approved["design_research_id"])
        if not target_ids.issubset(set(related_research_ids)):
            raise ValueError(
                "Research supervision links omit exact production results"
            )
        required_roles = metadata.get("required_related_artifact_roles", [])
        if not isinstance(required_roles, list) or any(
            not isinstance(item, str) for item in required_roles
        ):
            raise ValueError(
                "Research supervision required artifact roles are invalid"
            )
        if required_roles != sorted(set(required_roles)):
            raise ValueError(
                "Research supervision required artifact roles are not canonical"
            )
        if binding["supervisor_scope"] == "program_math":
            expected_roles: set[str] = set()
            for descriptor in binding["source_receipts"]:
                roles = {
                    item["role"] for item in descriptor["artifact_bindings"]
                }
                if descriptor["computation_phase"] == "core_code_design":
                    expected_roles.update(V5_COMPUTATION_DESIGN_ARTIFACT_ROLES)
                elif descriptor["computation_phase"] == "approved_execution":
                    expected_roles.update(
                        {
                            "computation_dependencies",
                            "computation_design",
                            "computation_log",
                            "computation_output",
                            "computation_source",
                        }
                    )
                else:
                    expected_roles.update(
                        roles.intersection(
                            {"computation_output", "computation_source"}
                        )
                    )
            if not expected_roles.issubset(set(required_roles)):
                raise ValueError(
                    "program-math supervision lacks required exact artifacts"
                )

    def _validate_supervision_round_selection(
        self,
        *,
        research_cycle: dict[str, Any],
        selected: list[dict[str, Any]],
        _inspection_context: RoundInspectionContext | None = None,
    ) -> None:
        inspection = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert inspection is not None
        cycle = self._validate_research_cycle_binding(research_cycle)
        if cycle["subround"] != "supervision":
            return
        source_component_id = (
            cycle["source_component_id"]
            if cycle["revision"] == V5_RESEARCH_CYCLE_REVISION
            else None
        )
        source_manifest, descriptors = self._source_round_receipt_descriptors(
            cycle["source_round_id"],
            source_component_id=source_component_id,
            _inspection_context=inspection,
        )
        if (
            cycle["source_round_manifest_sha256"]
            != source_manifest["manifest_sha256"]
            or cycle["source_receipts_sha256"] != sha256_json(descriptors)
        ):
            raise ValueError("V5 supervision round source binding drifted")
        scopes: list[str] = []
        for entry in selected:
            binding = self._validate_research_supervision_binding(
                entry.get("metadata", {}).get("research_supervision"),
                _inspection_context=inspection,
            )
            if (
                binding["source_round_id"] != cycle["source_round_id"]
                or binding["source_round_manifest_sha256"]
                != cycle["source_round_manifest_sha256"]
            ):
                raise ValueError(
                    "V5 supervision Research and round source bindings disagree"
                )
            if cycle["revision"] == V5_RESEARCH_CYCLE_REVISION and (
                binding["revision"] != V5_RESEARCH_SUPERVISION_REVISION
                or binding["source_component_id"]
                != cycle["source_component_id"]
                or binding["source_component_sha256"]
                != cycle["source_component_sha256"]
            ):
                raise ValueError(
                    "V5 supervision Research and round component bindings disagree"
                )
            if (
                cycle["revision"] == V5_LEGACY_RESEARCH_CYCLE_REVISION
                and binding["revision"]
                != V5_LEGACY_RESEARCH_SUPERVISION_REVISION
            ):
                raise ValueError(
                    "V5 legacy supervision binding revision drifted"
                )
            scopes.append(binding["supervisor_scope"])
        if sorted(scopes) != cycle["supervisor_scopes"] or len(scopes) != len(
            set(scopes)
        ):
            raise ValueError("V5 supervision round scope coverage drifted")

    def _supervision_review_lane_allows_stale_projection(
        self,
        *,
        projection: dict[str, Any],
        research_cycle: dict[str, Any],
    ) -> bool:
        """Keep exact invalidator review schedulable without reviving its route.

        A production result may itself invalidate an earlier Research route.
        The supervisor entry that reviews that exact result then inherits the
        invalidated target through the result's immutable lineage and is
        correctly absent from the ordinary frontier.  It is nevertheless a
        required review object.  This command-local exception admits only the
        exact supervision binding whose frozen source result is every cause of
        the projected staleness.  The projection remains stale everywhere
        else, including ordinary planning and Candidate release.
        """

        cycle = self._validate_research_cycle_binding(research_cycle)
        if (
            cycle["subround"] != "supervision"
            or projection.get("status") not in ACTIVE_MEMORY_STATUSES
            or projection.get("route_status")
            != "stale_pending_copy_on_write_repair"
        ):
            return False
        invalidators = projection.get("route_invalidated_by")
        if (
            not isinstance(invalidators, list)
            or not invalidators
            or any(not isinstance(item, str) for item in invalidators)
        ):
            return False
        # ``projection`` came from ``frontier(include_history=True)``, whose
        # Research loader already validated this record and its binding.  Use
        # that command-local projection here; the complete selection validator
        # below reconstructs the exact source-round authority once more before
        # any round bytes are written.
        binding = projection.get("metadata", {}).get("research_supervision")
        if not isinstance(binding, dict):
            return False
        if (
            binding.get("source_round_id") != cycle["source_round_id"]
            or binding.get("source_round_manifest_sha256")
            != cycle["source_round_manifest_sha256"]
            or binding.get("supervisor_scope") not in cycle["supervisor_scopes"]
        ):
            return False
        if cycle["revision"] == V5_RESEARCH_CYCLE_REVISION and (
            binding.get("revision") != V5_RESEARCH_SUPERVISION_REVISION
            or binding.get("source_component_id")
            != cycle["source_component_id"]
            or binding.get("source_component_sha256")
            != cycle["source_component_sha256"]
        ):
            return False
        source_receipts = binding.get("source_receipts")
        if not isinstance(source_receipts, list):
            return False
        reviewed_result_ids = {
            item["result_research_id"]
            for item in source_receipts
            if isinstance(item, dict)
            and isinstance(item.get("result_research_id"), str)
        }
        return set(invalidators).issubset(reviewed_result_ids)

    @staticmethod
    def _canonical_design_artifacts(
        record: dict[str, Any],
    ) -> list[dict[str, str]]:
        artifacts = record.get("metadata", {}).get("artifacts", [])
        if not isinstance(artifacts, list):
            raise ValueError("computation design artifacts must be a list")
        canonical = sorted(
            [
                {
                    "path": item["path"],
                    "sha256": item["sha256"],
                    "role": item["role"],
                }
                for item in artifacts
            ],
            key=lambda item: item["role"],
        )
        if {item["role"] for item in canonical} != set(
            V5_COMPUTATION_DESIGN_ARTIFACT_ROLES
        ):
            raise ValueError(
                "approved computation requires exactly the frozen core source, "
                "mathematical design, and dependency manifest"
            )
        return canonical

    def _validate_approved_computation_execution_binding(
        self,
        payload: Any,
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any]:
        inspection = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert inspection is not None
        required = {
            "revision",
            "design_round_id",
            "design_round_manifest_sha256",
            "design_assignment_id",
            "design_task_card_sha256",
            "design_return_sha256",
            "design_research_id",
            "design_record_sha256",
            "design_artifacts",
            "supervision_round_id",
            "supervision_round_manifest_sha256",
            "supervision_assignment_id",
            "supervision_task_card_sha256",
            "supervision_return_sha256",
            "supervision_research_id",
            "supervision_record_sha256",
            "disposition_research_id",
            "disposition_record_sha256",
            "disposition_status",
            "execution_policy",
            "repair_policy",
            "pulse_policy",
            "truth_effect",
        }
        if not isinstance(payload, dict) or set(payload) != required:
            raise ValueError(
                "approved computation execution binding fields are not exact"
            )
        if (
            payload["revision"] != V5_APPROVED_COMPUTATION_EXECUTION_REVISION
            or payload["execution_policy"]
            != "execute_exact_supervised_source_and_dependencies"
            or payload["repair_policy"]
            != "changed_code_requires_new_production_and_supervision"
            or payload["pulse_policy"] != "not_used"
            or payload["truth_effect"] != "none"
            or not isinstance(payload["disposition_status"], str)
            or payload["disposition_status"] not in V5_SAFE_SUPERVISION_DISPOSITIONS
        ):
            raise ValueError("approved computation execution policy is invalid")
        for key in ("design_round_id", "supervision_round_id"):
            validate_round_id(_require_nonempty_text(payload[key], key))
        for key in (
            "design_assignment_id",
            "supervision_assignment_id",
        ):
            validate_assignment_id(_require_nonempty_text(payload[key], key))
        for key in (
            "design_research_id",
            "supervision_research_id",
            "disposition_research_id",
        ):
            validate_memory_id(_require_nonempty_text(payload[key], key))
        for key in (
            "design_round_manifest_sha256",
            "design_task_card_sha256",
            "design_return_sha256",
            "design_record_sha256",
            "supervision_round_manifest_sha256",
            "supervision_task_card_sha256",
            "supervision_return_sha256",
            "supervision_record_sha256",
            "disposition_record_sha256",
        ):
            value = payload[key]
            if not isinstance(value, str) or SHA256_RE.fullmatch(value) is None:
                raise ValueError(f"approved computation {key} is invalid")

        _, design_manifest_preview = self._round_manifest(
            payload["design_round_id"],
            _inspection_context=inspection,
        )
        design_component_id = self._source_component_id_for_assignment(
            design_manifest_preview,
            payload["design_assignment_id"],
            _inspection_context=inspection,
        )
        design_manifest, design_descriptors = self._source_round_receipt_descriptors(
            payload["design_round_id"],
            source_component_id=design_component_id,
            _inspection_context=inspection,
        )
        design_matches = [
            item
            for item in design_descriptors
            if item["assignment_id"] == payload["design_assignment_id"]
        ]
        if len(design_matches) != 1:
            raise ValueError("approved computation design assignment is missing")
        design_descriptor = design_matches[0]
        if (
            design_manifest["manifest_sha256"]
            != payload["design_round_manifest_sha256"]
            or design_descriptor["work_mode"] != "compute"
            or design_descriptor["computation_phase"] != "core_code_design"
            or design_descriptor["task_card_sha256"]
            != payload["design_task_card_sha256"]
            or design_descriptor["return_sha256"]
            != payload["design_return_sha256"]
            or design_descriptor["result_research_id"]
            != payload["design_research_id"]
            or design_descriptor["result_record_sha256"]
            != payload["design_record_sha256"]
        ):
            raise ValueError("approved computation design binding drifted")
        design_record = self._inspection_research_record(
            payload["design_research_id"],
            inspection,
        )
        if payload["design_artifacts"] != self._canonical_design_artifacts(
            design_record
        ):
            raise ValueError("approved computation design artifacts drifted")

        supervision_dir, supervision_manifest = self._round_manifest(
            payload["supervision_round_id"],
            _inspection_context=inspection,
        )
        supervision_cycle = supervision_manifest.get("research_cycle")
        if (
            supervision_cycle is None
            or self._validate_research_cycle_binding(supervision_cycle)[
                "subround"
            ]
            != "supervision"
            or supervision_cycle["source_round_id"] != payload["design_round_id"]
            or "program_math" not in supervision_cycle["supervisor_scopes"]
            or supervision_manifest["manifest_sha256"]
            != payload["supervision_round_manifest_sha256"]
            or self.store.reasoning_modes().work_unit_abort(
                supervision_manifest["round_id"]
            )
            is not None
            or not self._round_is_completed(
                supervision_dir,
                supervision_manifest,
                _inspection_context=inspection,
            )
        ):
            raise ValueError("approved computation supervision round drifted")
        supervision_assignment = self._assignment(
            supervision_manifest, payload["supervision_assignment_id"]
        )
        supervision_result, _supervision_receipt = (
            self._research_product_for_assignment(
                round_dir=supervision_dir,
                manifest=supervision_manifest,
                assignment=supervision_assignment,
                _inspection_context=inspection,
            )
        )
        supervision_binding_metadata = supervision_result.get("metadata", {})
        supervision_task_binding = (
            supervision_binding_metadata.get("task_binding")
            if isinstance(supervision_binding_metadata, dict)
            else None
        )
        if not isinstance(supervision_task_binding, dict):
            raise ValueError("approved computation supervision product lacks return binding")
        supervision_return_sha256 = supervision_task_binding.get("return_sha256")
        if (
            not isinstance(supervision_return_sha256, str)
            or SHA256_RE.fullmatch(supervision_return_sha256) is None
        ):
            raise ValueError("approved computation supervision return binding is invalid")
        supervision_source = self._inspection_research_record(
            supervision_assignment["research_id"],
            inspection,
        )
        supervision_binding = self._validate_research_supervision_binding(
            supervision_source.get("metadata", {}).get("research_supervision"),
            _inspection_context=inspection,
        )
        if (
            supervision_binding["supervisor_scope"] != "program_math"
            or payload["design_assignment_id"]
            not in {
                item["assignment_id"]
                for item in supervision_binding["source_receipts"]
            }
            or supervision_assignment["task_card_sha256"]
            != payload["supervision_task_card_sha256"]
            or supervision_return_sha256 != payload["supervision_return_sha256"]
            or supervision_result["research_id"]
            != payload["supervision_research_id"]
        ):
            raise ValueError("approved computation supervision binding drifted")
        supervision_record = self._inspection_research_record(
            payload["supervision_research_id"],
            inspection,
        )
        if (
            supervision_record["record_sha256"]
            != payload["supervision_record_sha256"]
        ):
            raise ValueError("approved computation supervision record drifted")

        disposition = self._inspection_research_record(
            payload["disposition_research_id"],
            inspection,
        )
        if (
            disposition["kind"] != "disposition"
            or disposition["record_sha256"]
            != payload["disposition_record_sha256"]
            or disposition["metadata"].get("target_research_id")
            != payload["supervision_research_id"]
            or disposition["metadata"].get("disposition_status")
            != payload["disposition_status"]
            or disposition["status"] != payload["disposition_status"]
        ):
            raise ValueError("approved computation supervision disposition drifted")
        return payload

    def _validate_selected_execution_authority_liveness(
        self,
        selected: list[dict[str, Any]],
    ) -> None:
        """Recheck approved computation authority under the round-write lock."""

        for entry in selected:
            raw = entry.get("metadata", {}).get(
                "approved_computation_execution"
            )
            if raw is None:
                continue
            try:
                current = self._research_record(entry["research_id"])
                if current["record_sha256"] != entry["record_sha256"]:
                    raise ValueError(
                        "approved computation Research changed before round creation"
                    )
                binding = self._validate_approved_computation_execution_binding(
                    raw
                )
                latest_disposition = self._latest_supervision_disposition(
                    binding["supervision_research_id"]
                )
                if (
                    latest_disposition["research_id"]
                    != binding["disposition_research_id"]
                    or latest_disposition["record_sha256"]
                    != binding["disposition_record_sha256"]
                    or latest_disposition["metadata"].get(
                        "disposition_status"
                    )
                    != binding["disposition_status"]
                ):
                    raise ValueError(
                        "approved computation supervision disposition changed "
                        "before round creation"
                    )
            except ValueError as exc:
                raise ValueError(
                    "approved computation execution authority changed before "
                    "round creation"
                ) from exc

    def _validate_approved_computation_record_fields(
        self,
        *,
        kind: str,
        status: str,
        relation: str | None,
        related_research_ids: list[str],
        metadata: dict[str, Any],
        _inspection_context: RoundInspectionContext | None = None,
    ) -> None:
        raw = metadata.get("approved_computation_execution")
        if raw is None:
            return
        binding = self._validate_approved_computation_execution_binding(
            raw,
            _inspection_context=_inspection_context,
        )
        if kind != "computation" or status != "open" or relation != "executes":
            raise ValueError(
                "approved computation execution must be an open computation relation"
            )
        expected_related = {
            binding["design_research_id"],
            binding["supervision_research_id"],
            binding["disposition_research_id"],
        }
        if not expected_related.issubset(set(related_research_ids)):
            raise ValueError(
                "approved computation execution omits design, supervision, or disposition lineage"
            )
        required_roles = metadata.get("required_related_artifact_roles", [])
        if (
            not isinstance(required_roles, list)
            or any(not isinstance(item, str) for item in required_roles)
            or sorted(set(required_roles))
            != sorted(V5_COMPUTATION_DESIGN_ARTIFACT_ROLES)
        ):
            raise ValueError(
                "approved computation execution lacks exact design artifact capabilities"
            )

    def add_research(
        self,
        payload: dict[str, Any],
        *,
        actor: str,
        task_binding: dict[str, str] | None = None,
        campaign_id: str | None = None,
        assurance_contract_revision: str = V5_LEGACY_ASSURANCE_CONTRACT_REVISION,
        reuse_unbound_main_semantics: bool = False,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any]:
        inspection = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert inspection is not None
        if not isinstance(payload, dict):
            raise ValueError("research input must be one object")
        if not isinstance(reuse_unbound_main_semantics, bool):
            raise ValueError("Main Research semantic reuse flag must be boolean")
        if reuse_unbound_main_semantics and task_binding is not None:
            raise ValueError(
                "Main Research semantic reuse requires an unbound Research write"
            )
        if "id" in payload or "research_id" in payload:
            raise ValueError("research ids are generated internally")
        actor = _require_nonempty_text(actor, "research actor")
        kind = payload.get("kind", "direction")
        if not isinstance(kind, str) or kind not in V5_RESEARCH_KINDS:
            raise ValueError(f"unsupported V5 research kind: {kind!r}")
        status = payload.get("status", "open")
        if not isinstance(status, str) or status not in MEMORY_STATUSES:
            raise ValueError(f"unsupported V5 research status: {status!r}")
        claim = _require_nonempty_text(payload.get("claim"), "research claim")
        content = payload.get("content", payload.get("body", ""))
        rationale = payload.get("rationale", "")
        source = payload.get("source", "")
        for label, value in (
            ("content", content),
            ("rationale", rationale),
            ("source", source),
        ):
            if not isinstance(value, str):
                raise ValueError(f"research {label} must be a string")
        dependencies = _require_string_list(
            payload.get("dependencies", []), "research dependencies"
        )
        dependencies = sorted(dict.fromkeys(validate_fact_id(item) for item in dependencies))
        # Applicability comes before authority expansion.  An independent
        # nontruth Research append has no Fact premise to validate, so opening
        # the complete active-Fact lineage would let unrelated historical
        # Research and artifact closure veto this write.  Nonempty dependency
        # sets validate their exact admitted Fact graph bindings below.
        if dependencies:
            self._active_fact_premise_bindings(
                dependencies,
                _inspection_context=inspection,
            )
        related = _require_string_list(
            payload.get("related_research_ids", []), "related research ids"
        )
        related = sorted(dict.fromkeys(validate_memory_id(item) for item in related))
        for related_id in related:
            self._inspection_research_record(related_id, inspection)
        relation = payload.get("relation")
        if relation is not None:
            relation = _require_nonempty_text(relation, "research relation")
        if bool(related) != bool(relation):
            raise ValueError(
                "research relation and related_research_ids must be supplied together"
            )
        reserved = {
            "kind",
            "status",
            "claim",
            "content",
            "body",
            "rationale",
            "dependencies",
            "source",
            "relation",
            "related_research_ids",
            "assurance_contract_revision",
        }
        metadata = {
            key: value for key, value in payload.items() if key not in reserved
        }
        if "goal_intake_binding" in metadata or "goal_intake_token" in metadata:
            raise ValueError(
                "retired goal-intake metadata cannot be added to new Research"
            )
        payload_campaign = metadata.get("campaign_id")
        if payload_campaign is not None:
            payload_campaign = validate_campaign_id(payload_campaign)
        if campaign_id is not None:
            campaign_id = validate_campaign_id(campaign_id)
            if payload_campaign is not None and payload_campaign != campaign_id:
                raise ValueError(
                    "Research payload and --campaign identify different Campaigns"
                )
        bound_campaign_id = campaign_id or payload_campaign
        if bound_campaign_id is not None:
            self.store.campaigns().status(bound_campaign_id)
            metadata["campaign_id"] = bound_campaign_id
        decision_profile = _research_decision_profile(metadata)
        validate_adverse_domain_profile(metadata.get("adverse_domain_profile"))
        independent_adverse_required({"metadata": metadata})
        if "decision_profile" in metadata:
            metadata["decision_profile"] = decision_profile
            metadata["score_model"] = COMPACT_SCORE_MODEL
        if "workload_profile" in metadata:
            metadata["workload_profile"] = validate_workload_profile(
                metadata["workload_profile"]
            )
        self._validate_exact_repair_spec_metadata(
            kind=kind,
            metadata=metadata,
        )
        repair_manifest = self._validate_repair_input_capability_metadata(
            kind=kind,
            metadata=metadata,
            _inspection_context=inspection,
        )
        self._validate_schema_v2_repair_lineage(
            kind=kind,
            relation=relation,
            related_research_ids=related,
            metadata=metadata,
            require_existing=True,
            _inspection_context=inspection,
        )
        self._validate_supervised_production_authority_metadata(
            metadata,
            dependencies=dependencies,
        )
        if assurance_contract_revision not in {
            V5_ASSURANCE_CONTRACT_REVISION,
            V5_LEGACY_ASSURANCE_CONTRACT_REVISION,
        }:
            raise ValueError("research assurance contract revision is invalid")
        if (
            repair_manifest is not None
            and assurance_contract_revision != V5_ASSURANCE_CONTRACT_REVISION
        ):
            raise ValueError(
                "repair input capability manifest requires current assurance"
            )
        metadata["assurance_contract_revision"] = assurance_contract_revision
        if assurance_contract_revision == V5_ASSURANCE_CONTRACT_REVISION:
            artifacts = metadata.get("artifacts", [])
            if not isinstance(artifacts, list) or any(
                not isinstance(item, dict)
                or set(item) != {"path", "sha256", "role"}
                for item in artifacts
            ):
                raise ValueError(
                    "current Research artifacts must be exact path/hash/role objects"
                )
            seen_roles: set[str] = set()
            for item in artifacts:
                relpath = _require_nonempty_text(
                    item["path"], "Research artifact path"
                )
                digest = _require_nonempty_text(
                    item["sha256"], "Research artifact SHA-256"
                )
                role = _require_nonempty_text(
                    item["role"], "Research artifact role"
                )
                if SHA256_RE.fullmatch(digest) is None:
                    raise ValueError("Research artifact SHA-256 is invalid")
                if role in seen_roles:
                    raise ValueError("Research artifact roles must be unique")
                seen_roles.add(role)
                artifact_path = contained_path(
                    self.store.root, relpath, "Research artifact path"
                )
                if (
                    artifact_path.is_symlink()
                    or not artifact_path.is_file()
                    or sha256_bytes(artifact_path.read_bytes()) != digest
                ):
                    raise ValueError(
                        "Research artifact is missing, unsafe, or hash-mismatched"
                    )
            source_dependent = metadata.get("source_dependent", False)
            if not isinstance(source_dependent, bool):
                raise ValueError("Research source_dependent must be boolean")
            prospective_record = {
                "claim": claim,
                "content": content,
                "rationale": rationale,
                "source": source,
                "metadata": metadata,
            }
            if self._research_is_source_dependent(prospective_record) and not artifacts:
                raise ValueError(
                    "source-dependent current Research requires at least one exact "
                    "project-relative path/SHA-256/role artifact capability"
                )
            invalidations = metadata.get("route_invalidations", [])
            if not isinstance(invalidations, list) or any(
                not isinstance(item, str) or MEMORY_ID_RE.fullmatch(item) is None
                for item in invalidations
            ):
                raise ValueError("Research route_invalidations must be V5 Research ids")
            if len(invalidations) != len(set(invalidations)):
                raise ValueError("Research route_invalidations must be unique")
            if invalidations and kind not in {
                "challenge",
                "counterexample",
                "obstacle",
                "dead_end",
            }:
                raise ValueError(
                    "only adverse or dead-end Research may invalidate a route"
                )
            for target_id in invalidations:
                self._inspection_research_record(target_id, inspection)
        self._validate_research_supervision_record_fields(
            kind=kind,
            status=status,
            relation=relation,
            related_research_ids=related,
            metadata=metadata,
            _inspection_context=inspection,
        )
        self._validate_approved_computation_record_fields(
            kind=kind,
            status=status,
            relation=relation,
            related_research_ids=related,
            metadata=metadata,
        )
        if task_binding is not None:
            if not isinstance(task_binding, dict) or any(
                not isinstance(key, str) or not isinstance(value, str)
                for key, value in task_binding.items()
            ):
                raise ValueError("research task binding must map strings to strings")
            metadata["task_binding"] = dict(sorted(task_binding.items()))
        if reuse_unbound_main_semantics and (
            "task_binding" in metadata or "assignment_provenance" in metadata
        ):
            raise ValueError(
                "Main Research semantic reuse cannot consume task- or assignment-bound Research"
            )
        semantic_without_actor = {
            "schema_version": 5,
            "policy_revision": V5_POLICY_REVISION,
            "project_id": self.store.project_id(),
            "kind": kind,
            "status": status,
            "claim": claim,
            "content": content,
            "rationale": rationale,
            "dependencies": dependencies,
            "source": source,
            "relation": relation,
            "related_research_ids": related,
            "metadata": metadata,
        }
        semantic = {
            **semantic_without_actor,
            "actor": actor,
        }
        self._research_is_adverse_assignment(semantic)
        semantic_sha = sha256_json(semantic)
        research_id = semantic_sha[:12]
        created_at = _utc_now()
        record_without_hash = {
            **semantic,
            "research_id": research_id,
            "created_at": created_at,
            "semantic_sha256": semantic_sha,
        }
        record = {
            **record_without_hash,
            "record_sha256": sha256_json(record_without_hash),
        }
        path = self._research_path(research_id)
        with self.store.v5_mutation_lock(command="research-add"):
            if bound_campaign_id is not None:
                # Campaign binding and immutable Research publication are one
                # transaction.  Revalidate under the existing write boundary
                # before reuse checks or any derived index preparation.
                self.store.campaigns().status(bound_campaign_id)
            # The command-local capability snapshot is only a read-phase
            # optimization.  Recheck the exact bytes after entering the
            # mutation boundary so a concurrent source replacement cannot be
            # published from a stale snapshot.
            if repair_manifest is not None:
                self._validate_repair_input_capability_files(
                    repair_manifest["input_capabilities"]
                )
            if reuse_unbound_main_semantics:
                reusable: list[dict[str, Any]] = []
                for envelope in self.research_envelopes():
                    envelope_metadata = envelope["metadata"]
                    if (
                        "task_binding" in envelope_metadata
                        or "assignment_provenance" in envelope_metadata
                    ):
                        continue
                    existing_semantic = {
                        key: envelope[key]
                        for key in semantic_without_actor
                    }
                    if existing_semantic == semantic_without_actor:
                        reusable.append(envelope)
                if reusable:
                    selected = min(
                        reusable,
                        key=lambda item: (item["created_at"], item["research_id"]),
                    )
                    existing = self._inspection_research_record(
                        selected["research_id"],
                        inspection,
                    )
                    self.paper_continuation(
                        _inspection_context=inspection
                    )._status_index.reconcile_research(existing)
                    return existing
            if path.exists():
                existing = self._inspection_research_record(
                    research_id,
                    inspection,
                )
                if existing["semantic_sha256"] != semantic_sha:
                    raise ValueError(f"research id collision at {path}")
                # The immutable Research object is published before the
                # derived Paper-continuation status update.  A process stop in
                # that narrow interval must be recoverable by retrying the
                # same write command; ordinary status/read paths never invoke
                # this reconciliation.
                self.paper_continuation(
                    _inspection_context=inspection
                )._status_index.reconcile_research(existing)
                return existing
            continuation = self.paper_continuation(
                _inspection_context=inspection
            )
            prepared_status_index = continuation._status_index.prepare_research(
                record
            )
            self.store._write_json_once(path, record)
            continuation._status_index.commit_research(prepared_status_index)
            inspection.research_records[research_id] = record
            # A command-local product index is only a read optimization.  Any
            # immutable Research write invalidates it so a later lookup in the
            # same command cannot miss a just-published worker product.
            inspection.research_products_by_assignment = None
            inspection.research_product_bindings.clear()
            if inspection.all_research_records is not None:
                inspection.all_research_records.append(record)
            if inspection.all_research_envelopes is not None:
                inspection.all_research_envelopes.append(record)
            if inspection.research_envelopes_by_id is not None:
                inspection.research_envelopes_by_id[research_id] = record
            inspection.frontier_structural_state = None
            inspection.frontier_group_completions.clear()
            inspection.frontier_group_actions.clear()
            inspection.frontier_cow_repair_children = None
            inspection.frontier_cow_terminal_members.clear()
            inspection.frontier_completion_statuses.clear()
            inspection.round_completed.clear()
            inspection.round_statuses.clear()
            inspection.round_manifests.clear()
            inspection.supervision_manifests_by_production_round.clear()
            inspection.completion_obligation_rounds = None
            inspection.supervision_round_ids_by_production_round = None
        return record

    def update_research(
        self,
        research_id: str,
        *,
        status: str,
        actor: str,
        note: str = "",
        resolution_fact_id: str | None = None,
        claim_relation: str | None = None,
        related_fact_id: str | None = None,
        attention_basis_research_ids: list[str] | None = None,
    ) -> dict[str, Any]:
        target = self._research_record(research_id)
        if status not in MEMORY_STATUSES:
            raise ValueError(f"unsupported V5 research status: {status}")
        if not isinstance(note, str):
            raise ValueError("research disposition note must be a string")
        if resolution_fact_id is not None:
            resolution_fact_id = validate_fact_id(resolution_fact_id)
            self.store.get_fact(resolution_fact_id)
        if claim_relation is not None:
            if claim_relation not in CLAIM_RELATIONS or related_fact_id is None:
                raise ValueError(
                    "research disposition claim relation requires a related Fact"
                )
            related_fact_id = validate_fact_id(related_fact_id)
            self.store.get_fact(related_fact_id)
        elif related_fact_id is not None:
            raise ValueError("related Fact requires a claim relation")
        attention_basis = sorted(
            dict.fromkeys(
                validate_memory_id(item)
                for item in (attention_basis_research_ids or [])
            )
        )
        attention_disposition = (
            status
            if status in {"superseded", "equivalent_review_accepted"}
            else None
        )
        if attention_disposition is not None:
            if not note.strip() or not attention_basis:
                raise ValueError(
                    "semantic attention disposition requires a reason and exact basis Research ids"
                )
            for basis_id in attention_basis:
                self._research_record(basis_id)
        elif attention_basis:
            raise ValueError(
                "attention basis Research ids require superseded or equivalent_review_accepted status"
            )
        metadata: dict[str, Any] = {
            "target_research_id": research_id,
            "disposition_status": status,
            "resolution_fact_id": resolution_fact_id,
            "claim_relation": claim_relation,
            "related_fact_id": related_fact_id,
        }
        if attention_disposition is not None:
            metadata["attention_disposition"] = attention_disposition
            metadata["attention_basis_research_ids"] = attention_basis
        return self.add_research(
            {
                "kind": "disposition",
                "status": status,
                "claim": f"Disposition of {research_id}: {target['claim']}",
                "content": note,
                "relation": "disposes",
                "related_research_ids": [research_id, *attention_basis],
                **metadata,
            },
            actor=actor,
        )

    def create_repair_round(
        self,
        research_id: str,
        *,
        trigger_research_id: str | None = None,
        repair_spec: dict[str, Any] | None = None,
        actor: str = "v5-orchestrator",
        host_task_scope_id: str | None = None,
        frontier_target_id: str | None = None,
    ) -> dict[str, Any]:
        """Append one repair branch and plan exactly one bounded work unit."""

        inspection = self._bind_inspection_context(
            RoundInspectionContext(),
            create=True,
        )
        assert inspection is not None
        source = self._inspection_research_record(research_id, inspection)
        related_ids = [source["research_id"]]
        trigger: dict[str, Any] | None = None
        if trigger_research_id is not None:
            trigger = self._inspection_research_record(
                trigger_research_id,
                inspection,
            )
            related_ids.append(trigger["research_id"])
        related_ids = sorted(dict.fromkeys(related_ids))
        source_provenance = source.get("metadata", {}).get(
            "assignment_provenance"
        )
        inherited_repair_mode = source.get("metadata", {}).get(
            "repair_work_mode"
        )
        repair_mode: str = (
            source_provenance.get("work_mode")
            if isinstance(source_provenance, dict)
            and source_provenance.get("work_mode") in WORK_MODES
            else (
                inherited_repair_mode
                if inherited_repair_mode in WORK_MODES
                else "auto"
            )
        )
        normalized_repair_spec = (
            None
            if repair_spec is None
            else self._normalize_exact_repair_spec(repair_spec)
        )
        if (
            normalized_repair_spec is not None
            and normalized_repair_spec["work_mode"] != "auto"
        ):
            repair_mode = normalized_repair_spec["work_mode"]
        explicit_input_capabilities = (
            normalized_repair_spec.get("input_capabilities", [])
            if normalized_repair_spec is not None
            else []
        )
        repair_input_manifest = self._repair_input_capability_manifest(
            source=source,
            trigger=trigger,
            explicit_capabilities=explicit_input_capabilities,
            _inspection_context=inspection,
        )
        if (
            normalized_repair_spec is not None
            and normalized_repair_spec["schema_version"] == 2
            and not repair_input_manifest["input_capabilities"]
        ):
            raise ValueError(
                "schema-v2 repair specification requires at least one verified "
                "input capability"
            )
        if normalized_repair_spec is not None and normalized_repair_spec["schema_version"] == 2:
            normalized_repair_spec = {
                **normalized_repair_spec,
                "input_capabilities": repair_input_manifest[
                    "input_capabilities"
                ],
            }
            normalized_repair_spec = self._normalize_exact_repair_spec(
                normalized_repair_spec
            )
        copied_metadata = {
            key: source["metadata"][key]
            for key in (
                "source_claim_id",
                "convention_profile_ids",
                "campaign_id",
                "blackboard_write_space_ids",
                "obligations",
                "stop_conditions",
                "goal_relation",
                "independent_adverse_required",
            )
            if key in source["metadata"]
        }
        repair_campaign_id = copied_metadata.get("campaign_id")
        if frontier_target_id is not None:
            if repair_campaign_id is None:
                raise ValueError(
                    "--frontier-target requires repair Research bound to a Campaign"
                )
            repair_campaign_id = validate_campaign_id(repair_campaign_id)
            repair_campaign_snapshot, _ = self._campaign_snapshot_for_planning(
                repair_campaign_id,
                _inspection_context=inspection,
            )
            frontier_target_id = (
                self._validate_frontier_target_in_campaign_snapshot(
                    repair_campaign_snapshot,
                    frontier_target_id,
                )
            )
        # A repair may need the same exact source bytes or other artifacts that
        # carried the challenged claim.  Preserve that minimum capability
        # closure directly; do not force Main to synthesize a second Research
        # head merely to recover bytes already frozen by the source result.
        copied_metadata["artifacts"] = json.loads(
            json.dumps(
                repair_input_manifest["input_capabilities"],
                ensure_ascii=False,
                sort_keys=True,
            )
        )
        copied_metadata["source_dependent"] = bool(
            repair_input_manifest["input_capabilities"]
        )
        copied_metadata["repair_input_capability_manifest"] = (
            repair_input_manifest
        )
        if normalized_repair_spec is not None:
            copied_metadata["obligations"] = normalized_repair_spec[
                "obligations"
            ]
            copied_metadata["stop_conditions"] = normalized_repair_spec[
                "stop_conditions"
            ]
            copied_metadata["repair_spec"] = normalized_repair_spec
            copied_metadata["repair_spec_sha256"] = sha256_json(
                normalized_repair_spec
            )
        trigger_note = (
            f" Triggered by Research {trigger['research_id']}: {trigger['claim']}"
            if trigger is not None
            else ""
        )
        repair = self.add_research(
            {
                "kind": "repair",
                "status": "open",
                "claim": (
                    normalized_repair_spec["claim"]
                    if normalized_repair_spec is not None
                    else f"Repair branch for: {source['claim']}"
                ),
                "content": (
                    normalized_repair_spec["content"]
                    if normalized_repair_spec is not None
                    else (
                        "Re-examine the bounded claim while preserving prior "
                        "counterexamples, challenges, and evidence."
                        + trigger_note
                    )
                ),
                "rationale": (
                    normalized_repair_spec["rationale"]
                    if normalized_repair_spec is not None
                    else (
                        "A new cumulative branch is required; the source Research "
                        "record remains immutable and readable."
                    )
                ),
                "dependencies": source["dependencies"],
                "source": f"research:{source['research_id']}",
                "relation": "repairs",
                "related_research_ids": related_ids,
                "repair_of_research_id": source["research_id"],
                "repair_work_mode": repair_mode,
                "trigger_research_id": (
                    trigger["research_id"] if trigger is not None else None
                ),
                **copied_metadata,
            },
            actor=actor,
            assurance_contract_revision=V5_ASSURANCE_CONTRACT_REVISION,
            _inspection_context=inspection,
        )
        planned = self.create_production_round(
            workers=1,
            mode=repair_mode,
            research_ids=[repair["research_id"]],
            campaign_id=(
                validate_campaign_id(repair_campaign_id)
                if repair_campaign_id is not None
                else None
            ),
            host_task_scope_id=host_task_scope_id,
            frontier_target_id=frontier_target_id,
            _inspection_context=inspection,
        )
        return {
            **planned,
            "memory_id": repair["research_id"],
            "research_id": repair["research_id"],
            "repair_of_research_id": source["research_id"],
            "trigger_research_id": (
                trigger["research_id"] if trigger is not None else None
            ),
            "repair_spec_sha256": repair["metadata"].get(
                "repair_spec_sha256"
            ),
            "repair_input_capability_manifest_sha256": repair["metadata"][
                "repair_input_capability_manifest"
            ]["manifest_sha256"],
        }

    @staticmethod
    def _normalize_exact_repair_spec(value: Any) -> dict[str, Any]:
        base_required = {
            "schema_version",
            "claim",
            "content",
            "rationale",
            "work_mode",
            "obligations",
            "stop_conditions",
        }
        if not isinstance(value, dict) or not base_required.issubset(value):
            raise ValueError("exact repair specification fields are not exact")
        schema_version = value.get("schema_version")
        if schema_version == 1:
            required = base_required
        elif schema_version == 2:
            required = {*base_required, "input_capabilities"}
        else:
            raise ValueError("exact repair specification schema_version is invalid")
        if set(value) != required:
            raise ValueError("exact repair specification fields are not exact")
        claim = _require_nonempty_text(value.get("claim"), "repair spec claim")
        content = _require_nonempty_text(
            value.get("content"), "repair spec content"
        )
        rationale = _require_nonempty_text(
            value.get("rationale"), "repair spec rationale"
        )
        if len(claim) > 4_096 or len(rationale) > 4_096 or len(content) > 32_768:
            raise ValueError("exact repair specification prose exceeds its cap")
        work_mode = value.get("work_mode")
        if work_mode != "auto" and work_mode not in WORK_MODES:
            raise ValueError("exact repair specification work_mode is invalid")
        obligations = value.get("obligations")
        normalize_obligations(obligations)
        stop_conditions = _require_string_list(
            value.get("stop_conditions"), "repair spec stop conditions"
        )
        if (
            len(stop_conditions) > 32
            or len(stop_conditions) != len(set(stop_conditions))
            or any(not item.strip() or len(item) > 2_048 for item in stop_conditions)
        ):
            raise ValueError("exact repair specification stop conditions are invalid")
        normalized = {
            "schema_version": schema_version,
            "claim": claim,
            "content": content,
            "rationale": rationale,
            "work_mode": work_mode,
            "obligations": json.loads(
                json.dumps(obligations, ensure_ascii=False, sort_keys=True)
            ),
            "stop_conditions": list(stop_conditions),
        }
        if schema_version == 2:
            normalized["input_capabilities"] = (
                V5LifecycleManager._normalize_repair_input_capabilities(
                    value.get("input_capabilities")
                )
            )
        raw = json.dumps(
            normalized,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
        if len(raw) > 256 * 1_024:
            raise ValueError("exact repair specification exceeds 256 KiB")
        return normalized

    @classmethod
    def _validate_exact_repair_spec_metadata(
        cls,
        *,
        kind: str,
        metadata: dict[str, Any],
    ) -> None:
        spec = metadata.get("repair_spec")
        digest = metadata.get("repair_spec_sha256")
        if spec is None and digest is None:
            return
        if kind != "repair" or spec is None or digest is None:
            raise ValueError(
                "exact repair specification metadata requires one repair record"
            )
        normalized = cls._normalize_exact_repair_spec(spec)
        if normalized != spec or digest != sha256_json(normalized):
            raise ValueError("exact repair specification metadata drifted")
        if normalized["schema_version"] == 2:
            if not normalized["input_capabilities"]:
                raise ValueError(
                    "schema-v2 repair specification requires at least one verified "
                    "input capability"
                )
            manifest = metadata.get("repair_input_capability_manifest")
            if (
                not isinstance(manifest, dict)
                or manifest.get("input_capabilities")
                != normalized["input_capabilities"]
            ):
                raise ValueError(
                    "schema-v2 repair specification is not bound to its capability manifest"
                )

    @staticmethod
    def _validate_supervised_production_authority_metadata(
        metadata: dict[str, Any],
        *,
        dependencies: list[str],
    ) -> None:
        payload = metadata.get("supervised_production_authority")
        if payload is None:
            return
        if not isinstance(payload, list) or not payload:
            raise ValueError(
                "supervised production authority must be a nonempty list"
            )
        seen_assignments: set[str] = set()
        projected_fact_ids: set[str] = set()
        for item in payload:
            semantic_fields = {
                "revision",
                "assignment_id",
                "task_card_path",
                "task_card_sha256",
                "active_fact_ids",
                "capabilities",
                "truth_effect",
            }
            if not isinstance(item, dict) or set(item) != {
                *semantic_fields,
                "receipt_sha256",
            }:
                raise ValueError(
                    "supervised production authority fields are not exact"
                )
            if (
                item["revision"] != V5_SUPERVISED_AUTHORITY_CLOSURE_REVISION
                or item["truth_effect"] != "none"
            ):
                raise ValueError("supervised production authority policy is invalid")
            assignment_id = validate_assignment_id(item["assignment_id"])
            if assignment_id in seen_assignments:
                raise ValueError(
                    "supervised production authority assignments are duplicated"
                )
            seen_assignments.add(assignment_id)
            task_card_path = _require_nonempty_text(
                item["task_card_path"],
                "supervised production task-card path",
            )
            task_card_sha = _require_nonempty_text(
                item["task_card_sha256"],
                "supervised production task-card SHA-256",
            )
            if SHA256_RE.fullmatch(task_card_sha) is None or not task_card_path.endswith(
                f"/{assignment_id}.json"
            ):
                raise ValueError(
                    "supervised production task-card binding is invalid"
                )
            fact_ids = _require_string_list(
                item["active_fact_ids"],
                "supervised production active Fact ids",
            )
            if fact_ids != sorted(set(fact_ids)):
                raise ValueError(
                    "supervised production active Fact ids are not canonical"
                )
            projected_fact_ids.update(validate_fact_id(value) for value in fact_ids)
            capabilities = item["capabilities"]
            if not isinstance(capabilities, list) or any(
                not isinstance(capability, dict)
                or set(capability) != {"path", "sha256", "source_role"}
                or not isinstance(capability["path"], str)
                or not capability["path"]
                or not isinstance(capability["source_role"], str)
                or not capability["source_role"]
                or not isinstance(capability["sha256"], str)
                or SHA256_RE.fullmatch(capability["sha256"]) is None
                for capability in capabilities
            ):
                raise ValueError(
                    "supervised production capabilities are invalid"
                )
            semantic = {key: item[key] for key in semantic_fields}
            if item["receipt_sha256"] != sha256_json(semantic):
                raise ValueError(
                    "supervised production authority receipt hash drifted"
                )
        if projected_fact_ids != set(dependencies):
            raise ValueError(
                "supervisor dependencies do not exactly preserve production Fact premises"
            )

    def research_records(
        self,
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> list[dict[str, Any]]:
        _inspection_context = self._bind_inspection_context(
            _inspection_context
        )
        if (
            _inspection_context is not None
            and _inspection_context.all_research_records is not None
        ):
            return _inspection_context.all_research_records
        records: list[dict[str, Any]] = []
        if not self.research_entries_dir.exists():
            return records
        for path in sorted(self.research_entries_dir.glob("*.json")):
            if path.is_symlink() or not path.is_file():
                raise ValueError("research ledger contains an unsafe entry")
            records.append(
                self._inspection_research_record(
                    path.stem,
                    _inspection_context,
                )
            )
        if _inspection_context is not None:
            _inspection_context.all_research_records = records
        return records

    @staticmethod
    def _checkpoint_reason_items(
        value: Any,
        *,
        label: str,
        id_field: str,
        maximum: int,
    ) -> list[dict[str, str]]:
        if not isinstance(value, list) or len(value) > maximum:
            raise ValueError(f"{label} must be a list of at most {maximum} items")
        normalized: list[dict[str, str]] = []
        seen: set[str] = set()
        for index, item in enumerate(value, 1):
            if not isinstance(item, dict) or set(item) != {id_field, "reason"}:
                raise ValueError(f"{label} item {index} fields are not exact")
            research_id = validate_memory_id(
                _require_nonempty_text(item.get(id_field), f"{label} research id")
            )
            if research_id in seen:
                raise ValueError(f"{label} research ids must be unique")
            reason = _require_nonempty_text(item.get("reason"), f"{label} reason")
            if len(reason) > 1_024:
                raise ValueError(f"{label} reason exceeds 1024 code points")
            normalized.append({id_field: research_id, "reason": reason})
            seen.add(research_id)
        return normalized

    @staticmethod
    def _selected_dependency_edges(
        *,
        target_ids: list[str],
        structural: dict[str, dict[str, Any]],
    ) -> list[list[str]]:
        """Return exact positive-dependency reachability inside a selection.

        Research ancestry also carries attacks, repairs, dispositions, and
        investigations. Those relations preserve lineage but do not make two
        Candidate claims one mathematical atom. Unknown relation names remain
        conservative dependency edges; only the explicit nondependency
        boundary below is excluded.
        """

        selected_ids = set(target_ids)
        nondependency_relations = {
            "challenges",
            "copy_on_write_repair",
            "corrects",
            "disposes",
            "investigates",
            "repairs",
            "repairs_assurance_of",
            "responds_to",
        }
        edges: set[tuple[str, str]] = set()
        for target_id in target_ids:
            pending = [target_id]
            seen: set[str] = set()
            while pending:
                research_id = pending.pop()
                if research_id in seen:
                    continue
                seen.add(research_id)
                record = structural[research_id]
                if record.get("relation") in nondependency_relations:
                    continue
                for ancestor_id in record["related_research_ids"]:
                    if ancestor_id in selected_ids and ancestor_id != target_id:
                        edges.add((ancestor_id, target_id))
                    pending.append(ancestor_id)
        return [list(item) for item in sorted(edges)]

    def selective_fact_checkpoint(
        self,
        payload: dict[str, Any],
        *,
        actor: str,
    ) -> dict[str, Any]:
        """Freeze one Main-owned, nontruth selective-admission checkpoint.

        The command validates the explicit targets completely, uses structural
        envelopes only for unselected topology, and reports facts rather than a
        score.  It never constructs or authorizes a Candidate Release.
        """

        inspection = self._bind_inspection_context(
            RoundInspectionContext(),
            create=True,
        )
        assert inspection is not None
        required = {
            "schema_version",
            "objective",
            "target_rationales",
            "excluded_research",
        }
        if not isinstance(payload, dict) or set(payload) != required:
            raise ValueError("selective Fact checkpoint input fields are not exact")
        if payload.get("schema_version") != 1:
            raise ValueError("selective Fact checkpoint schema_version must be 1")
        objective = _require_nonempty_text(
            payload.get("objective"), "selective Fact checkpoint objective"
        )
        if len(objective) > 4_096:
            raise ValueError("selective Fact checkpoint objective exceeds 4096 code points")
        actor = _require_nonempty_text(actor, "selective Fact checkpoint actor")
        targets = self._checkpoint_reason_items(
            payload.get("target_rationales"),
            label="selective Fact checkpoint target_rationales",
            id_field="research_id",
            maximum=V5_MAX_SELECTIVE_FACT_TARGETS,
        )
        if not targets:
            raise ValueError("selective Fact checkpoint requires at least one target")
        exclusions = self._checkpoint_reason_items(
            payload.get("excluded_research"),
            label="selective Fact checkpoint excluded_research",
            id_field="research_id",
            maximum=V5_MAX_SELECTIVE_FACT_EXCLUSIONS,
        )
        target_ids = [item["research_id"] for item in targets]
        excluded_ids = {item["research_id"] for item in exclusions}
        overlap = sorted(set(target_ids).intersection(excluded_ids))
        if overlap:
            raise ValueError(
                "selective Fact checkpoint targets cannot also be excluded: "
                + ", ".join(overlap)
            )

        envelopes = self.research_envelopes()
        if len(envelopes) > V5_MAX_SELECTIVE_FACT_GRAPH_RECORDS:
            raise ValueError(
                "selective Fact checkpoint structural Research graph exceeds "
                f"{V5_MAX_SELECTIVE_FACT_GRAPH_RECORDS} records"
            )
        structural = {item["research_id"]: item for item in envelopes}
        structural_graph_binding = [
            {
                "research_id": item["research_id"],
                "record_sha256": item["record_sha256"],
                "related_research_ids": item["related_research_ids"],
            }
            for item in sorted(envelopes, key=lambda entry: entry["research_id"])
        ]
        structural_graph_sha256 = sha256_json(structural_graph_binding)
        missing = sorted((set(target_ids) | excluded_ids).difference(structural))
        if missing:
            raise ValueError(
                "selective Fact checkpoint names unknown Research: "
                + ", ".join(missing)
            )
        explicit_records = [
            self._research_record(
                item,
                _inspection_context=inspection,
            )
            for item in target_ids
        ]
        all_records = dict(structural)
        all_records.update(
            {item["research_id"]: item for item in explicit_records}
        )
        stale_routes = self._route_staleness(all_records)

        ancestors_by_target: dict[str, list[str]] = {}
        closure: set[str] = set()
        for target_id in target_ids:
            ancestors: set[str] = set()
            pending = list(structural[target_id]["related_research_ids"])
            while pending:
                research_id = pending.pop()
                if research_id in ancestors:
                    continue
                if research_id not in structural:
                    raise ValueError(
                        "selective Fact checkpoint Research ancestry is incomplete: "
                        + research_id
                    )
                ancestors.add(research_id)
                pending.extend(structural[research_id]["related_research_ids"])
            ancestors_by_target[target_id] = sorted(ancestors)
            closure.add(target_id)
            closure.update(ancestors)

        descendants_by_parent: dict[str, set[str]] = {
            research_id: set() for research_id in structural
        }
        for child_id, record in structural.items():
            for parent_id in record["related_research_ids"]:
                if parent_id not in descendants_by_parent:
                    raise ValueError(
                        "selective Fact checkpoint Research parent is missing: "
                        + parent_id
                    )
                descendants_by_parent[parent_id].add(child_id)

        projections: list[dict[str, Any]] = []
        for target, record in zip(targets, explicit_records, strict=True):
            target_id = target["research_id"]
            descendants: set[str] = set()
            pending = list(descendants_by_parent[target_id])
            while pending:
                research_id = pending.pop()
                if research_id in descendants:
                    continue
                descendants.add(research_id)
                pending.extend(descendants_by_parent[research_id])
            blockers: list[dict[str, Any]] = []
            if record["status"] not in ACTIVE_MEMORY_STATUSES:
                blockers.append(
                    {
                        "kind": "research_not_active",
                        "details": [record["status"]],
                    }
                )
            if target_id in stale_routes:
                blockers.append(
                    {
                        "kind": "route_invalidated",
                        "details": stale_routes[target_id],
                    }
                )
            if self._research_is_adverse_assignment(record) or isinstance(
                record.get("metadata", {}).get("research_supervision"), dict
            ):
                blockers.append(
                    {"kind": "review_only_target", "details": [target_id]}
                )
            required_supervision: list[str] = []
            try:
                required_supervision = sorted(
                    self._required_supervision_results_for_candidate(
                        [record],
                        _inspection_context=inspection,
                    )
                )
            except Exception as exc:
                blockers.append(
                    {
                        "kind": "candidate_supervision_not_ready",
                        "details": [str(exc)],
                    }
                )
            metadata = record.get("metadata", {})
            artifacts = metadata.get("artifacts", [])
            source_uses = metadata.get("source_uses", [])
            dispositions = metadata.get("obligation_dispositions", [])
            disposition_counts: dict[str, int] = {}
            if isinstance(dispositions, list):
                for disposition in dispositions:
                    if not isinstance(disposition, dict):
                        continue
                    status = disposition.get("status")
                    if isinstance(status, str):
                        disposition_counts[status] = disposition_counts.get(status, 0) + 1
            projections.append(
                {
                    "research_id": target_id,
                    "record_sha256": record["record_sha256"],
                    "kind": record["kind"],
                    "status": record["status"],
                    "selection_reason": target["reason"],
                    "ancestor_ids": ancestors_by_target[target_id],
                    "downstream_reuse_count": len(descendants),
                    "downstream_reuse_ids_sha256": sha256_json(sorted(descendants)),
                    "artifact_count": len(artifacts) if isinstance(artifacts, list) else 0,
                    "source_use_count": len(source_uses) if isinstance(source_uses, list) else 0,
                    "assurance_contract_revision": metadata.get("assurance_contract_revision"),
                    "obligation_disposition_counts": disposition_counts,
                    "computation_manifest_present": metadata.get("computation_manifest") is not None,
                    "required_supervision_result_ids": required_supervision,
                    "checkpoint_status": (
                        "no_checkpoint_blocker" if not blockers else "blocked"
                    ),
                    "blockers": blockers,
                }
            )

        structural_binding = [
            {
                "research_id": research_id,
                "record_sha256": structural[research_id]["record_sha256"],
                "related_research_ids": structural[research_id]["related_research_ids"],
            }
            for research_id in sorted(closure)
        ]

        # Automatic atomization is safe only after the explicitly selected
        # targets are closed under their own dependency relation. Unselected
        # background Research remains structural context, but selected targets
        # joined by ancestry belong to one atomic Candidate unit. A blocked
        # selected premise also blocks every selected dependent.
        selected_dependency_edges = self._selected_dependency_edges(
            target_ids=target_ids,
            structural=structural,
        )
        blockers_by_target = {
            item["research_id"]: item["blockers"] for item in projections
        }
        blocked_selected = {
            research_id
            for research_id, blockers in blockers_by_target.items()
            if blockers
        }
        changed = True
        while changed:
            changed = False
            for ancestor_id, target_id in selected_dependency_edges:
                if ancestor_id not in blocked_selected or target_id in blocked_selected:
                    continue
                blockers_by_target[target_id].append(
                    {
                        "kind": "selected_dependency_blocked",
                        "details": [ancestor_id],
                    }
                )
                blocked_selected.add(target_id)
                changed = True
        for projection in projections:
            projection["checkpoint_status"] = (
                "no_checkpoint_blocker"
                if not projection["blockers"]
                else "blocked"
            )

        ready_ids = sorted(
            item["research_id"]
            for item in projections
            if item["checkpoint_status"] == "no_checkpoint_blocker"
        )
        blocked_ids = sorted(
            item["research_id"]
            for item in projections
            if item["checkpoint_status"] == "blocked"
        )
        ready_set = set(ready_ids)
        adjacency: dict[str, set[str]] = {
            research_id: set() for research_id in ready_ids
        }
        for ancestor_id, target_id in selected_dependency_edges:
            if ancestor_id in ready_set and target_id in ready_set:
                adjacency[ancestor_id].add(target_id)
                adjacency[target_id].add(ancestor_id)
        components: list[list[str]] = []
        unseen = set(ready_ids)
        while unseen:
            root = min(unseen)
            component: set[str] = set()
            pending = [root]
            while pending:
                research_id = pending.pop()
                if research_id in component:
                    continue
                component.add(research_id)
                pending.extend(sorted(adjacency[research_id], reverse=True))
            unseen.difference_update(component)
            components.append(sorted(component))
        components.sort(key=lambda item: tuple(item))
        checkpoint_input = {
            "schema_version": 1,
            "objective": objective,
            "target_rationales": targets,
            "excluded_research": exclusions,
        }
        semantic = {
            "schema_version": 1,
            "contract_revision": V5_SELECTIVE_FACT_CHECKPOINT_REVISION,
            "project_id": self.store.project_id(),
            "input": checkpoint_input,
            "selected": projections,
            "selected_ancestry": structural_binding,
            "research_graph_record_count": len(structural_graph_binding),
            "research_graph_envelope_sha256": structural_graph_sha256,
            "candidate_batch_seed": {
                "contract_revision": "chalxius-v5-candidate-batch-seed-3",
                "ready_research_ids": ready_ids,
                "blocked_research_ids": blocked_ids,
                "selected_dependency_edges": selected_dependency_edges,
                "atomization_policy": (
                    "explicit_one_claim_fact_authoring_with_exact_candidate_dependency_closure"
                ),
                "partition_semantics": (
                    "dependency_closed_authoring_batches_not_fact_atoms"
                ),
                "candidate_fact_atomicity_contract": (
                    "exactly_one_semantic_conclusion_atom_per_fact"
                ),
                "automatic_atomization": False,
                "candidate_dag_closure_required": True,
                "default_partition": [
                    {"unit": index, "research_entry_ids": component}
                    for index, component in enumerate(components, 1)
                ],
                "main_approval_required": True,
                "candidate_fact_authoring_required": True,
                "candidate_effect": "none",
            },
            "selection_authority": "main_explicit_only",
            "automatic_ranking": False,
            "candidate_release_preflight_required": True,
            "candidate_effect": "none",
            "certification_effect": "none",
            "fact_effect": "none",
            "truth_effect": "none",
            "actor": actor,
        }
        semantic_bytes = json.dumps(
            semantic,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
        if len(semantic_bytes) > V5_MAX_SELECTIVE_FACT_CHECKPOINT_BYTES:
            raise ValueError(
                "selective Fact checkpoint exceeds the 512 KiB semantic limit; "
                "split the explicit target set"
            )
        checkpoint_id = "fact-checkpoint-" + sha256_json(semantic)
        path = self.fact_admission_checkpoints_dir / f"{checkpoint_id}.json"
        with self.store.v5_mutation_lock(command="selective-fact-checkpoint"):
            if path.exists():
                if path.is_symlink() or not path.is_file():
                    raise ValueError("selective Fact checkpoint path is unsafe")
                record = self.store._read_json(path)
            else:
                record = {
                    **semantic,
                    "checkpoint_id": checkpoint_id,
                    "created_at": _utc_now(),
                }
                record["record_sha256"] = sha256_json(record)
                self.store._write_json_once(path, record)
            self._validate_selective_fact_checkpoint_record(
                record,
                expected_semantic=semantic,
                expected_checkpoint_id=checkpoint_id,
            )
        return {
            "checkpoint_id": checkpoint_id,
            "checkpoint_path": str(path),
            "record_sha256": record["record_sha256"],
            "selected": projections,
            "candidate_batch_seed": record["candidate_batch_seed"],
            "selection_authority": record["selection_authority"],
            "truth_effect": "none",
        }

    @staticmethod
    def _validate_selective_fact_checkpoint_record(
        record: Any,
        *,
        expected_semantic: dict[str, Any],
        expected_checkpoint_id: str,
    ) -> None:
        if not isinstance(record, dict):
            raise ValueError("selective Fact checkpoint record is invalid")
        existing_semantic = {
            key: value
            for key, value in record.items()
            if key not in {"checkpoint_id", "created_at", "record_sha256"}
        }
        existing_without_hash = {
            key: value for key, value in record.items() if key != "record_sha256"
        }
        if (
            existing_semantic != expected_semantic
            or record.get("checkpoint_id") != expected_checkpoint_id
            or record.get("record_sha256") != sha256_json(existing_without_hash)
        ):
            raise ValueError("selective Fact checkpoint immutable record drifted")

    def novelty_record(
        self,
        payload: dict[str, Any],
        *,
        actor: str,
    ) -> str:
        """Append query-bounded novelty evidence for V5 Research or Fact.

        Novelty remains nontruth evidence.  The adapter deliberately reuses the
        compact 0.3.6 ledger instead of creating a second novelty subsystem.
        """

        if not isinstance(payload, dict):
            raise ValueError("novelty record must be one object")
        required = {
            "subject_kind",
            "subject_id",
            "corpus",
            "query",
            "status",
            "hits",
        }
        if set(payload).difference(required | {"notes"}) or not required.issubset(
            payload
        ):
            raise ValueError("novelty record fields are not exact")
        subject_kind = _require_nonempty_text(
            payload.get("subject_kind"), "novelty subject kind"
        )
        subject_id = _require_nonempty_text(
            payload.get("subject_id"), "novelty subject id"
        )
        if subject_kind in {"research", "memory"}:
            subject_kind = "research"
            subject_id = validate_memory_id(subject_id)
            self._research_record(subject_id)
        elif subject_kind == "fact":
            subject_id = validate_fact_id(subject_id)
            if subject_id not in set(self.store.fact_ids()).union(
                self.revoked_fact_ids()
            ):
                raise ValueError("novelty subject is not a known V5 Fact")
        else:
            raise ValueError(
                "V5 novelty subject_kind must be research, memory, or fact"
            )
        corpus = _require_nonempty_text(payload.get("corpus"), "novelty corpus")
        query = _require_nonempty_text(payload.get("query"), "novelty query")
        status = _require_nonempty_text(payload.get("status"), "novelty status")
        if status not in NOVELTY_STATUSES:
            raise ValueError(
                "novelty status must be one of: "
                + ", ".join(sorted(NOVELTY_STATUSES))
            )
        hits = payload.get("hits")
        if not isinstance(hits, list):
            raise ValueError("novelty hits must be a list")
        normalized_hits: list[dict[str, str]] = []
        for index, hit in enumerate(hits, 1):
            if not isinstance(hit, dict) or set(hit) != {
                "title",
                "locator",
                "relation",
            }:
                raise ValueError(
                    f"novelty hits[{index}] fields are not exact"
                )
            relation = _require_nonempty_text(
                hit.get("relation"), f"novelty hits[{index}] relation"
            )
            if relation not in {"exact", "partial", "background"}:
                raise ValueError(
                    f"novelty hits[{index}] relation must be exact, partial, "
                    "or background"
                )
            normalized_hits.append(
                {
                    "title": _require_nonempty_text(
                        hit.get("title"), f"novelty hits[{index}] title"
                    ),
                    "locator": _require_nonempty_text(
                        hit.get("locator"), f"novelty hits[{index}] locator"
                    ),
                    "relation": relation,
                }
            )
        if status == "known" and not any(
            hit["relation"] == "exact" for hit in normalized_hits
        ):
            raise ValueError("novelty status known requires an exact hit")
        if status == "no_exact_match_found" and any(
            hit["relation"] == "exact" for hit in normalized_hits
        ):
            raise ValueError("no_exact_match_found conflicts with an exact hit")
        notes = payload.get("notes", "")
        if not isinstance(notes, str):
            raise ValueError("novelty notes must be a string")
        semantic = {
            "subject_kind": subject_kind,
            "subject_id": subject_id,
            "corpus": corpus,
            "query": query,
            "status": status,
            "hits": normalized_hits,
            "notes": notes,
            "actor": _require_nonempty_text(actor, "novelty actor"),
        }
        event_id = sha256_json(semantic)
        event = {
            **semantic,
            "event": "novelty-query",
            "event_id": event_id,
            "searched_at": _utc_now(),
        }
        with self.store.v5_mutation_lock(command="novelty-record"):
            self.store._append_jsonl_once(
                self.store.novelty_log,
                event,
                event_id=event_id,
            )
        return event_id

    def novelty_status(self, subject_id: str) -> list[dict[str, Any]]:
        if FACT_ID_RE.fullmatch(subject_id):
            subject_kind = "fact"
        elif MEMORY_ID_RE.fullmatch(subject_id):
            subject_kind = "research"
        else:
            raise ValueError("novelty subject id must be a Fact or Research id")
        return [
            event
            for event in self.store._read_jsonl(self.store.novelty_log)
            if event.get("subject_kind") == subject_kind
            and event.get("subject_id") == subject_id
        ]

    def _audit_novelty(
        self,
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> list[str]:
        _inspection_context = self._bind_inspection_context(
            _inspection_context
        )
        errors: list[str] = []
        events = self.store._read_jsonl(self.store.novelty_log)
        known_facts = set(
            self.store.fact_ids(_inspection_context=_inspection_context)
        ).union(
            self.revoked_fact_ids(_inspection_context=_inspection_context)
        )
        known_research = {
            record["research_id"]
            for record in self.research_records(
                _inspection_context=_inspection_context
            )
        }
        for index, event in enumerate(events, 1):
            try:
                if event.get("event") != "novelty-query":
                    raise ValueError("invalid event kind")
                subject_kind = event.get("subject_kind")
                subject_id = event.get("subject_id")
                if subject_kind == "fact":
                    validate_fact_id(subject_id)
                    if subject_id not in known_facts:
                        raise ValueError("unknown Fact subject")
                elif subject_kind == "research":
                    validate_memory_id(subject_id)
                    if subject_id not in known_research:
                        raise ValueError("unknown Research subject")
                else:
                    raise ValueError("invalid V5 subject_kind")
                if event.get("status") not in NOVELTY_STATUSES:
                    raise ValueError("invalid novelty status")
                for field_name in (
                    "corpus",
                    "query",
                    "notes",
                    "actor",
                    "searched_at",
                ):
                    if not isinstance(event.get(field_name), str):
                        raise ValueError(f"invalid {field_name}")
                hits = event.get("hits")
                if not isinstance(hits, list):
                    raise ValueError("hits is not a list")
                for hit in hits:
                    if not isinstance(hit, dict) or set(hit) != {
                        "title",
                        "locator",
                        "relation",
                    }:
                        raise ValueError("invalid novelty hit")
                    if hit["relation"] not in {"exact", "partial", "background"}:
                        raise ValueError("invalid novelty hit relation")
                    _require_nonempty_text(hit["title"], "novelty hit title")
                    _require_nonempty_text(hit["locator"], "novelty hit locator")
                semantic = {
                    key: event.get(key)
                    for key in (
                        "subject_kind",
                        "subject_id",
                        "corpus",
                        "query",
                        "status",
                        "hits",
                        "notes",
                        "actor",
                    )
                }
                if event.get("event_id") != sha256_json(semantic):
                    raise ValueError("event_id mismatch")
            except Exception as exc:
                errors.append(f"event {index}: {exc}")
        return errors

    def _release_research_records(
        self,
        explicit_records: list[dict[str, Any]],
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> list[dict[str, Any]]:
        """Include linked adverse work without creating another review layer.

        A release author chooses its constructive Research anchors.  Every
        adverse record that directly targets an anchor, or an already-bound
        adverse record, is then bound automatically, so an existing challenge
        cannot be hidden by omitting its id from the input.

        Generic ``related_research_ids`` on a constructive result are not an
        ancestry relation.  They may point to planning, repair, or source-
        capability records whose own related ids span old project history.
        Walking those edges backwards would turn a local Candidate into a
        project-wide administrative closure.  Mathematical provenance remains
        available through the selected Research artifacts and metadata.
        """

        inspection = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert inspection is not None
        selected_records = {
            item["research_id"]: item for item in explicit_records
        }
        branch = set(selected_records)
        raw_inventory: list[tuple[Path, bytes]] = []
        if self.research_entries_dir.exists():
            for path in sorted(self.research_entries_dir.glob("*.json")):
                if path.is_symlink() or not path.is_file():
                    raise ValueError("research ledger contains an unsafe entry")
                if path.stem in selected_records:
                    continue
                raw_inventory.append(
                    (
                        path,
                        self._read_regular_bytes_once(
                            path,
                            label="Candidate Research ledger entry",
                        ),
                    )
                )
        loaded: dict[str, dict[str, Any]] = {}

        adverse_kinds = {"challenge", "counterexample", "obstacle"}
        changed = True
        while changed:
            changed = False
            branch_tokens = [item.encode("ascii") for item in branch]
            for path, raw in raw_inventory:
                research_id = path.stem
                if research_id in branch or not any(
                    token in raw for token in branch_tokens
                ):
                    continue
                record = loaded.get(research_id)
                if record is None:
                    record = self._inspection_research_record(
                        research_id,
                        inspection,
                    )
                    loaded[research_id] = record
                if (
                    record["kind"] not in adverse_kinds
                    and not self._research_is_adverse_assignment(record)
                ):
                    continue
                if not set(record["related_research_ids"]).intersection(branch):
                    continue
                # The planner's challenge is an administrative bridge to the
                # actual supervisor return, not adverse mathematical work.
                # Keep its id as a transient link so the return can be found,
                # but do not make the planner task itself (or its historical
                # input package) part of the release.
                if (
                    record.get("actor") == "v5-research-supervisor-planner"
                    and not self._research_is_adverse_assignment(record)
                ):
                    branch.add(research_id)
                    changed = True
                    continue
                selected_records[research_id] = record
                branch.add(research_id)
                changed = True
        return [
            selected_records[research_id]
            for research_id in sorted(selected_records)
        ]

    def _supervision_manifests_for_production_round(
        self,
        production_round_id: str,
        inspection: RoundInspectionContext,
    ) -> list[tuple[Path, dict[str, Any]]]:
        """Return live supervision rounds for one exact production round.

        The index is command-local.  It avoids repeating a whole rounds scan
        when Candidate projection, frontier inspection, and source-review
        continuity ask about the same immutable production round.
        """

        production_round_id = validate_round_id(production_round_id)
        cached = inspection.supervision_manifests_by_production_round.get(
            production_round_id
        )
        if cached is not None:
            return cached
        matching_manifests: list[tuple[Path, dict[str, Any]]] = []
        if self.store.rounds_dir.exists():
            for candidate_dir in sorted(self.store.rounds_dir.glob("round-*")):
                if candidate_dir.is_symlink() or not candidate_dir.is_dir():
                    continue
                manifest_path = candidate_dir / "round.json"
                if manifest_path.is_symlink() or not manifest_path.is_file():
                    raise ValueError("round ledger contains an unsafe manifest")
                raw_manifest = self._read_regular_bytes_once(
                    manifest_path,
                    label="Research supervision round manifest",
                )
                if production_round_id.encode("ascii") not in raw_manifest:
                    continue
                round_dir, manifest = self._round_manifest(
                    candidate_dir.name,
                    _inspection_context=inspection,
                )
                cycle = manifest.get("research_cycle")
                if (
                    isinstance(cycle, dict)
                    and cycle.get("subround") == "supervision"
                    and cycle.get("source_round_id") == production_round_id
                    and self.store.reasoning_modes().work_unit_abort(
                        manifest["round_id"]
                    )
                    is None
                ):
                    matching_manifests.append((round_dir, manifest))
        inspection.supervision_manifests_by_production_round[
            production_round_id
        ] = matching_manifests
        return matching_manifests

    def _production_component_for_exact_research_input(
        self,
        record: dict[str, Any],
        inspection: RoundInspectionContext,
    ) -> tuple[str, str | None] | None:
        """Resolve explicit Research provenance to its production component.

        This follows only immutable workflow identities.  It deliberately does
        not infer mathematical relevance from prose or search the wider graph.
        """

        metadata = record.get("metadata", {})
        if not isinstance(metadata, dict):
            return None
        direct_supervision = metadata.get("research_supervision")
        if isinstance(direct_supervision, dict):
            binding = self._validate_research_supervision_binding(
                direct_supervision,
                _inspection_context=inspection,
            )
            return (
                binding["source_round_id"],
                binding.get("source_component_id"),
            )
        provenance = metadata.get("assignment_provenance")
        if not isinstance(provenance, dict):
            return None
        round_dir, manifest = self._round_manifest(
            provenance["round_id"],
            _inspection_context=inspection,
        )
        assignments = [
            item
            for item in manifest["assignments"]
            if item["assignment_id"] == provenance["assignment_id"]
        ]
        if len(assignments) != 1:
            raise ValueError("exact Research input assignment is missing")
        assignment = assignments[0]
        product, _receipt = self._research_product_for_assignment(
            round_dir=round_dir,
            manifest=manifest,
            assignment=assignment,
            _inspection_context=inspection,
        )
        if product["research_id"] != record["research_id"]:
            raise ValueError("exact Research input product/result drifted")
        cycle = manifest.get("research_cycle")
        if not isinstance(cycle, dict):
            return None
        cycle = self._validate_research_cycle_binding(cycle)
        if cycle["subround"] == "production":
            if self._research_is_adverse_assignment(record):
                return None
            return (
                manifest["round_id"],
                self._source_component_id_for_assignment(
                    manifest,
                    assignment["assignment_id"],
                    _inspection_context=inspection,
                ),
            )
        if cycle["subround"] != "supervision":
            return None
        supervisor_task = self._inspection_research_record(
            assignment["research_id"],
            inspection,
        )
        binding = supervisor_task.get("metadata", {}).get(
            "research_supervision"
        )
        if not isinstance(binding, dict):
            return None
        binding = self._validate_research_supervision_binding(
            binding,
            _inspection_context=inspection,
        )
        return (
            binding["source_round_id"],
            binding.get("source_component_id"),
        )

    def _completed_scope_reviews_for_component(
        self,
        *,
        production_round_id: str,
        source_component_id: str | None,
        scope: str,
        inspection: RoundInspectionContext,
    ) -> list[tuple[dict[str, Any], dict[str, Any]]]:
        """Return completed review products and their exact frozen task cards."""

        matches: dict[str, tuple[dict[str, Any], dict[str, Any]]] = {}
        for round_dir, manifest in self._supervision_manifests_for_production_round(
            production_round_id,
            inspection,
        ):
            cycle = manifest["research_cycle"]
            if (
                cycle.get("source_component_id") != source_component_id
                or scope not in cycle.get("supervisor_scopes", [])
            ):
                continue
            for assignment in manifest["assignments"]:
                supervisor_task = self._inspection_research_record(
                    assignment["research_id"],
                    inspection,
                )
                binding = supervisor_task.get("metadata", {}).get(
                    "research_supervision"
                )
                if not isinstance(binding, dict):
                    continue
                binding = self._validate_research_supervision_binding(
                    binding,
                    _inspection_context=inspection,
                )
                if (
                    binding["supervisor_scope"] != scope
                    or binding["source_round_id"] != production_round_id
                    or binding.get("source_component_id") != source_component_id
                ):
                    continue
                try:
                    product, _receipt = self._research_product_for_assignment(
                        round_dir=round_dir,
                        manifest=manifest,
                        assignment=assignment,
                        _inspection_context=inspection,
                    )
                except ValueError as exc:
                    if "worker Research product is missing" in str(exc):
                        continue
                    raise
                task_card_path = contained_path(
                    self.store.root,
                    assignment["task_card_relpath"],
                    "completed Research supervisor task card",
                )
                raw = self._read_regular_bytes_once(
                    task_card_path,
                    label="completed Research supervisor task card",
                )
                if sha256_bytes(raw) != assignment["task_card_sha256"]:
                    raise ValueError("completed supervisor task-card hash drifted")
                matches[product["research_id"]] = (
                    product,
                    self.store._read_json(task_card_path),
                )
        return [matches[key] for key in sorted(matches)]

    def _source_scope_continuity_for_card(
        self,
        source_card: dict[str, Any],
        inspection: RoundInspectionContext,
    ) -> tuple[set[str], list[dict[str, str]]]:
        """Carry exact prior source review context into a downstream review.

        The route is intentionally narrow: direct Research input, its exact
        production component, the completed source-scope sibling, and only
        primary bytes that sibling actually cited in ``source_uses``.
        """

        dossier = source_card["mathematical_state"]["source_research_dossier"]
        origins: set[tuple[str, str | None]] = set()
        for research_id in dossier.get("related_research_ids", []):
            record = self._inspection_research_record(research_id, inspection)
            origin = self._production_component_for_exact_research_input(
                record,
                inspection,
            )
            if origin is not None:
                origins.add(origin)

        review_ids: set[str] = set()
        capabilities: dict[tuple[str, str], dict[str, str]] = {}
        for production_round_id, source_component_id in sorted(
            origins,
            key=lambda item: (item[0], item[1] or ""),
        ):
            reviews = self._completed_scope_reviews_for_component(
                production_round_id=production_round_id,
                source_component_id=source_component_id,
                scope="source_scope",
                inspection=inspection,
            )
            for review, review_card in reviews:
                review_id = review["research_id"]
                review_ids.add(review_id)
                source_hashes = {
                    item["source_artifact_sha256"]
                    for item in review.get("metadata", {}).get(
                        "source_uses", []
                    )
                    if isinstance(item, dict)
                    and isinstance(item.get("source_artifact_sha256"), str)
                }
                state = review_card["mathematical_state"]
                available = [
                    *state.get("related_artifacts", []),
                    *state.get("authority_snapshot", {}).get(
                        "capabilities", []
                    ),
                    *state.get("source_research_dossier", {})
                    .get("metadata", {})
                    .get("artifacts", []),
                ]
                for capability in available:
                    if capability.get("sha256") not in source_hashes:
                        continue
                    key = (capability["path"], capability["sha256"])
                    if key in capabilities:
                        continue
                    capabilities[key] = {
                        "path": capability["path"],
                        "sha256": capability["sha256"],
                        "source_role": (
                            f"prior_source_review:{review_id}:"
                            f"{capability.get('role', 'primary_source')}"
                        ),
                    }
        return review_ids, list(capabilities.values())

    def _required_supervision_results_for_candidate(
        self,
        explicit_records: list[dict[str, Any]],
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> set[str]:
        """Require completed, ingested subround-2 review before Candidate work.

        The gate applies prospectively to constructive results ingested from a
        two-subround production round.  Manual and historical single-wave
        Research remain readable compatibility inputs.  For each production
        component, the same deterministic default scope policy used by the
        planner must have exactly one live, completed supervision return.
        """

        required_result_ids: set[str] = set()
        inspection = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert inspection is not None
        supervision_manifests = (
            inspection.supervision_manifests_by_production_round
        )

        checked_components: set[tuple[str, str | None]] = set()
        for record in explicit_records:
            provenance = record.get("metadata", {}).get(
                "assignment_provenance"
            )
            if not isinstance(provenance, dict):
                continue
            if self._research_is_adverse_assignment(record):
                continue
            production_round_id = provenance["round_id"]
            production_round_dir, production_manifest = self._round_manifest(
                production_round_id,
                _inspection_context=inspection,
            )
            production_cycle = production_manifest.get("research_cycle")
            if (
                not isinstance(production_cycle, dict)
                or self._validate_research_cycle_binding(production_cycle)[
                    "subround"
                ]
                != "production"
            ):
                continue
            if production_round_id not in supervision_manifests:
                self._supervision_manifests_for_production_round(
                    production_round_id,
                    inspection,
                )
            assignment_matches = [
                assignment
                for assignment in production_manifest["assignments"]
                if assignment["assignment_id"]
                == provenance["assignment_id"]
            ]
            if len(assignment_matches) != 1:
                raise ValueError(
                    "Candidate Research production assignment is missing"
                )
            production_assignment = assignment_matches[0]
            production_product, _production_receipt = (
                self._research_product_for_assignment(
                    round_dir=production_round_dir,
                    manifest=production_manifest,
                    assignment=production_assignment,
                    _inspection_context=inspection,
                )
            )
            if production_product["research_id"] != record["research_id"]:
                raise ValueError(
                    "Candidate Research production product/result drifted"
                )
            source_component_id = self._source_component_id_for_assignment(
                production_manifest,
                production_assignment["assignment_id"],
                _inspection_context=inspection,
            )
            component_key = (production_round_id, source_component_id)
            if component_key in checked_components:
                continue
            checked_components.add(component_key)
            source_manifest, descriptors = self._source_round_receipt_descriptors(
                production_round_id,
                source_component_id=source_component_id,
                _inspection_context=inspection,
            )
            selection_logic_signals = (
                self._source_round_selection_logic_signals(
                    source_manifest,
                    descriptors,
                )
            )
            required_scopes = self._default_research_supervisor_scopes(
                descriptors,
                selection_logic_signals=selection_logic_signals,
            )
            if not required_scopes:
                raise ValueError(
                    "Candidate Research component has no applicable supervision scope"
                )
            for scope in required_scopes:
                matching_results: list[str] = []
                pending_rounds: list[str] = []
                for supervision_round_dir, supervision_manifest in (
                    supervision_manifests.get(production_round_id, [])
                ):
                    cycle = supervision_manifest["research_cycle"]
                    if (
                        cycle.get("source_round_id") != production_round_id
                        or cycle.get("source_component_id")
                        != source_component_id
                        or scope not in cycle.get("supervisor_scopes", [])
                    ):
                        continue
                    for assignment in supervision_manifest["assignments"]:
                        supervisor_task = self._inspection_research_record(
                            assignment["research_id"], inspection
                        )
                        binding = supervisor_task.get("metadata", {}).get(
                            "research_supervision"
                        )
                        if not isinstance(binding, dict):
                            continue
                        binding = self._validate_research_supervision_binding(
                            binding,
                            _inspection_context=inspection,
                        )
                        if (
                            binding["supervisor_scope"] != scope
                            or binding["source_round_id"]
                            != production_round_id
                            or binding.get("source_component_id")
                            != source_component_id
                        ):
                            continue
                        try:
                            product, _receipt = self._research_product_for_assignment(
                                round_dir=supervision_round_dir,
                                manifest=supervision_manifest,
                                assignment=assignment,
                                _inspection_context=inspection,
                            )
                        except ValueError as exc:
                            if "worker Research product is missing" in str(exc):
                                pending_rounds.append(
                                    supervision_manifest["round_id"]
                                )
                                continue
                            raise
                        matching_results.append(product["research_id"])
                if pending_rounds:
                    raise ValueError(
                        "Candidate construction is blocked by pending Research "
                        f"supervision ({scope}): "
                        + ", ".join(sorted(pending_rounds))
                    )
                if len(matching_results) != 1:
                    raise ValueError(
                        "Candidate construction requires exactly one completed "
                        f"and ingested Research supervision result ({scope}) for "
                        f"{production_round_id}/{source_component_id or 'legacy'}"
                    )
                required_result_ids.add(matching_results[0])
        return required_result_ids

    def _route_staleness(
        self,
        records: dict[str, dict[str, Any]],
    ) -> dict[str, list[str]]:
        """Project explicit route invalidations without rewriting Research.

        A current-contract adverse/dead-end Research entry may invalidate exact
        earlier Research ids.  The field is an explicit invalidation list, not
        a dependency edge.  In particular, ``related_research_ids`` is a
        general provenance/context relation and must never make a later route
        stale by transitive inference.  A future semantic invalidation edge may
        define its own transmission rule; it must not reuse this broad relation.
        Historical bytes and statuses are never rewritten.
        """

        invalidations: list[tuple[str, str, str]] = []
        for invalidator_id, record in records.items():
            metadata = record.get("metadata", {})
            if not isinstance(metadata, dict):
                continue
            for target_id in metadata.get("route_invalidations", []):
                if target_id in records:
                    invalidations.append(
                        (target_id, invalidator_id, record["created_at"])
                    )

        stale: dict[str, list[str]] = {}
        for target_id, invalidator_id, _invalidated_at in invalidations:
            stale.setdefault(target_id, []).append(invalidator_id)
        return {
            research_id: sorted(dict.fromkeys(invalidator_ids))
            for research_id, invalidator_ids in stale.items()
        }

    @staticmethod
    def _campaign_snapshot_bytes(snapshot: dict[str, Any]) -> bytes:
        raw = (
            json.dumps(snapshot, ensure_ascii=False, indent=2, sort_keys=True)
            + "\n"
        ).encode("utf-8")
        if len(raw) > V5_MAX_CAMPAIGN_SNAPSHOT_BYTES:
            raise ValueError(
                "V5 Campaign snapshot exceeds the 256 KiB planning cap"
            )
        return raw

    def _campaign_snapshot_for_planning(
        self,
        campaign_id: str,
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> tuple[dict[str, Any], bytes]:
        """Validate and freeze one explicit nontruth Campaign envelope."""

        _inspection_context = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert _inspection_context is not None
        campaign_id = validate_campaign_id(campaign_id)
        status = _inspection_context.campaign_statuses.get(campaign_id)
        if status is None:
            status = self.store.campaigns().status(campaign_id)
            _inspection_context.campaign_statuses[campaign_id] = status
        # ``CampaignStore.status`` remains the complete internal replay because
        # frontier checkpoint recovery needs the append-only event history.
        # Planning, however, must freeze only current semantics plus an exact
        # commitment to the observed history prefix.  Otherwise a healthy
        # long-running Campaign eventually becomes impossible to plan merely
        # because its historical notes cross the snapshot byte cap.
        expected_status_fields = {
            "campaign_id",
            "active",
            "name",
            "objective",
            "source_claim_ids",
            "targets",
            "constraints",
            "stop_conditions",
            "value_definition",
            "updates",
            "event_count",
            "history",
        }
        if not isinstance(status, dict) or set(status) != expected_status_fields:
            raise ValueError("V5 Campaign status fields are not exact")
        if status.get("campaign_id") != campaign_id:
            raise ValueError("V5 Campaign status id mismatch")
        if not isinstance(status.get("active"), bool):
            raise ValueError("V5 Campaign active projection must be boolean")
        for key in ("name", "objective", "value_definition"):
            if not isinstance(status.get(key), str) or not status[key].strip():
                raise ValueError(f"V5 Campaign {key} must be nonempty")
        for key in ("source_claim_ids", "constraints", "stop_conditions"):
            values = status.get(key)
            if (
                not isinstance(values, list)
                or any(not isinstance(item, str) for item in values)
                or len(values) != len(set(values))
            ):
                raise ValueError(f"V5 Campaign {key} must be unique strings")
        event_count = status.get("event_count")
        if (
            isinstance(event_count, bool)
            or not isinstance(event_count, int)
            or event_count < 1
        ):
            raise ValueError("V5 Campaign event count is invalid")
        if not isinstance(status.get("updates"), list) or any(
            not isinstance(item, dict) for item in status["updates"]
        ):
            raise ValueError("V5 Campaign updates must be objects")
        for source_claim_id in status["source_claim_ids"]:
            self.store.claims().show_claim(source_claim_id)
        targets = status.get("targets")
        if not isinstance(targets, dict):
            raise ValueError("V5 Campaign targets must be an object")
        active_proof_target_fact_ids: set[str] = set()
        compact_targets: dict[str, dict[str, str]] = {}
        for target_id, target in targets.items():
            if not isinstance(target_id, str) or not isinstance(target, dict):
                raise ValueError("V5 Campaign target projection is malformed")
            if target.get("target_id") != target_id:
                raise ValueError("V5 Campaign target id projection mismatch")
            if target.get("role") not in {
                "headline_proof",
                "supporting_proof",
                "research_goal",
                "communication",
            }:
                raise ValueError("V5 Campaign target role is invalid")
            if target.get("status") not in {"active", "archived"}:
                raise ValueError("V5 Campaign target status is invalid")
            for key in ("subject_kind", "subject_id", "label"):
                if not isinstance(target.get(key), str) or not target[key].strip():
                    raise ValueError(f"V5 Campaign target {key} must be nonempty")
            if (
                target["status"] == "active"
                and target["role"] in {"headline_proof", "supporting_proof"}
            ):
                active_proof_target_fact_ids.add(
                    validate_fact_id(target["subject_id"])
                )
            if target["status"] == "active":
                compact_targets[target_id] = {
                    key: target[key]
                    for key in (
                        "target_id",
                        "role",
                        "subject_kind",
                        "subject_id",
                        "label",
                        "status",
                    )
                }
        if active_proof_target_fact_ids:
            try:
                self._active_fact_premise_bindings(
                    sorted(active_proof_target_fact_ids),
                    _inspection_context=_inspection_context,
                )
            except ValueError as exc:
                raise ValueError(
                    "V5 Campaign active proof targets are not exact admitted Facts: "
                    + ", ".join(sorted(active_proof_target_fact_ids))
                ) from exc
        history = status.get("history")
        if (
            not isinstance(history, dict)
            or set(history)
            != {"event_count", "last_event_id", "events_sha256"}
            or history.get("event_count") != event_count
            or not isinstance(history.get("last_event_id"), str)
            or SHA256_RE.fullmatch(history["last_event_id"]) is None
            or not isinstance(history.get("events_sha256"), str)
            or SHA256_RE.fullmatch(history["events_sha256"]) is None
        ):
            raise ValueError("V5 Campaign history commitment is malformed")
        compact_status = {
            "campaign_id": campaign_id,
            "active": status["active"],
            "name": status["name"],
            "objective": status["objective"],
            "source_claim_ids": list(status["source_claim_ids"]),
            "targets": compact_targets,
            "constraints": list(status["constraints"]),
            "stop_conditions": list(status["stop_conditions"]),
            "value_definition": status["value_definition"],
            "event_count": event_count,
            "history": history,
        }
        snapshot = {
            "schema_version": 1,
            "revision": V5_CAMPAIGN_SCOPE_REVISION,
            "campaign_id": campaign_id,
            "campaign_status": compact_status,
            "selection_policy": "explicit_exact_research_campaign_id_match",
            "scheduler": "v5_main_four_factor_frontier",
            "truth_effect": "none",
            "fact_admission_effect": "none",
        }
        return snapshot, self._campaign_snapshot_bytes(snapshot)

    @staticmethod
    def _validate_frontier_target_in_campaign_snapshot(
        snapshot: dict[str, Any],
        frontier_target_id: str,
    ) -> str:
        """Require one explicit active research goal before any plan writes."""

        target_id = validate_campaign_target_id(frontier_target_id)
        status = snapshot.get("campaign_status")
        targets = status.get("targets") if isinstance(status, dict) else None
        target = targets.get(target_id) if isinstance(targets, dict) else None
        if (
            not isinstance(target, dict)
            or target.get("status") != "active"
            or target.get("role") != "research_goal"
        ):
            raise ValueError(
                "--frontier-target must name an active Campaign research goal"
            )
        return target_id

    @staticmethod
    def _campaign_scope_from_snapshot(
        snapshot: dict[str, Any],
        *,
        snapshot_relpath: str,
        snapshot_sha256: str,
    ) -> dict[str, Any]:
        required = {
            "schema_version",
            "revision",
            "campaign_id",
            "campaign_status",
            "selection_policy",
            "scheduler",
            "truth_effect",
            "fact_admission_effect",
        }
        if not isinstance(snapshot, dict) or set(snapshot) != required:
            raise ValueError("V5 Campaign snapshot fields are not exact")
        revision = snapshot.get("revision")
        if (
            snapshot.get("schema_version") != 1
            or revision
            not in {
                V5_LEGACY_CAMPAIGN_SCOPE_REVISION,
                V5_CAMPAIGN_SCOPE_REVISION,
            }
            or snapshot.get("selection_policy")
            != "explicit_exact_research_campaign_id_match"
            or snapshot.get("scheduler") != "v5_main_four_factor_frontier"
            or snapshot.get("truth_effect") != "none"
            or snapshot.get("fact_admission_effect") != "none"
        ):
            raise ValueError("V5 Campaign snapshot contract mismatch")
        campaign_id = validate_campaign_id(snapshot.get("campaign_id"))
        status = snapshot.get("campaign_status")
        if not isinstance(status, dict) or status.get("campaign_id") != campaign_id:
            raise ValueError("V5 Campaign snapshot status mismatch")
        common_status_fields = {
            "campaign_id",
            "active",
            "name",
            "objective",
            "source_claim_ids",
            "targets",
            "constraints",
            "stop_conditions",
            "value_definition",
            "event_count",
        }
        expected_status_fields = (
            common_status_fields | {"updates"}
            if revision == V5_LEGACY_CAMPAIGN_SCOPE_REVISION
            else common_status_fields | {"history"}
        )
        if set(status) != expected_status_fields:
            raise ValueError("V5 Campaign snapshot status fields are not exact")
        if revision == V5_LEGACY_CAMPAIGN_SCOPE_REVISION:
            if not isinstance(status.get("updates"), list) or any(
                not isinstance(item, dict) for item in status["updates"]
            ):
                raise ValueError("V5 legacy Campaign updates are malformed")
        targets = status.get("targets")
        if not isinstance(targets, dict):
            raise ValueError("V5 Campaign snapshot targets are invalid")
        active_targets: list[dict[str, str]] = []
        for target_id, target in sorted(targets.items()):
            if not isinstance(target, dict) or target.get("target_id") != target_id:
                raise ValueError("V5 Campaign snapshot target projection is invalid")
            if revision == V5_CAMPAIGN_SCOPE_REVISION and set(target) != {
                "target_id",
                "role",
                "subject_kind",
                "subject_id",
                "label",
                "status",
            }:
                raise ValueError("V5 compact Campaign target fields are not exact")
            if target.get("status") != "active":
                if revision == V5_CAMPAIGN_SCOPE_REVISION:
                    raise ValueError(
                        "V5 compact Campaign snapshot contains an inactive target"
                    )
                continue
            compact = {
                key: target.get(key)
                for key in (
                    "target_id",
                    "role",
                    "subject_kind",
                    "subject_id",
                    "label",
                )
            }
            if any(not isinstance(value, str) or not value for value in compact.values()):
                raise ValueError("V5 Campaign active target is not compactable")
            active_targets.append(compact)
        event_count = status.get("event_count")
        if (
            isinstance(event_count, bool)
            or not isinstance(event_count, int)
            or event_count < 1
        ):
            raise ValueError("V5 Campaign snapshot event count is invalid")
        if revision == V5_CAMPAIGN_SCOPE_REVISION:
            history = status.get("history")
            if (
                not isinstance(history, dict)
                or set(history)
                != {"event_count", "last_event_id", "events_sha256"}
                or history.get("event_count") != event_count
                or not isinstance(history.get("last_event_id"), str)
                or SHA256_RE.fullmatch(history["last_event_id"]) is None
                or not isinstance(history.get("events_sha256"), str)
                or SHA256_RE.fullmatch(history["events_sha256"]) is None
            ):
                raise ValueError("V5 Campaign snapshot history is malformed")
        source_claim_ids = _require_string_list(
            status.get("source_claim_ids"), "Campaign snapshot source claim ids"
        )
        constraints = _require_string_list(
            status.get("constraints"), "Campaign snapshot constraints"
        )
        stop_conditions = _require_string_list(
            status.get("stop_conditions"), "Campaign snapshot stop conditions"
        )
        for key in ("name", "objective", "value_definition"):
            if not isinstance(status.get(key), str) or not status[key].strip():
                raise ValueError(f"V5 Campaign snapshot {key} must be nonempty")
        if not isinstance(status.get("active"), bool):
            raise ValueError("V5 Campaign snapshot active state is invalid")
        return {
            "revision": revision,
            "campaign_id": campaign_id,
            "selection_policy": snapshot["selection_policy"],
            "scheduler": snapshot["scheduler"],
            "snapshot_relpath": snapshot_relpath,
            "snapshot_sha256": snapshot_sha256,
            "event_count": event_count,
            "active_at_freeze": status["active"],
            "objective": status["objective"],
            "source_claim_ids": source_claim_ids,
            "constraints": constraints,
            "stop_conditions": stop_conditions,
            "value_definition": status["value_definition"],
            "active_targets": active_targets,
            "truth_effect": "none",
            "fact_admission_effect": "none",
        }

    def _validate_campaign_scope_binding(
        self,
        scope: Any,
        *,
        round_id: str,
        _inspection_context: RoundInspectionContext | None = None,
        _materialized_round_dir: Path | None = None,
    ) -> dict[str, Any]:
        _inspection_context = self._bind_inspection_context(
            _inspection_context
        )
        if (
            _inspection_context is not None
            and round_id in _inspection_context.campaign_scopes
        ):
            cached = _inspection_context.campaign_scopes[round_id]
            if scope != cached:
                raise ValueError("V5 Campaign scope changed within one inspection")
            return cached
        if not isinstance(scope, dict):
            raise ValueError("V5 Campaign scope must be one object")
        expected_fields = {
            "revision",
            "campaign_id",
            "selection_policy",
            "scheduler",
            "snapshot_relpath",
            "snapshot_sha256",
            "event_count",
            "active_at_freeze",
            "objective",
            "source_claim_ids",
            "constraints",
            "stop_conditions",
            "value_definition",
            "active_targets",
            "truth_effect",
            "fact_admission_effect",
        }
        if set(scope) != expected_fields:
            raise ValueError("V5 Campaign scope fields are not exact")
        campaign_id = validate_campaign_id(scope.get("campaign_id"))
        expected_relpath = f"rounds/{round_id}/context/campaign.snapshot.json"
        if scope.get("snapshot_relpath") != expected_relpath:
            raise ValueError("V5 Campaign snapshot path is noncanonical")
        digest = scope.get("snapshot_sha256")
        if not isinstance(digest, str) or SHA256_RE.fullmatch(digest) is None:
            raise ValueError("V5 Campaign snapshot hash is invalid")
        snapshot_path = (
            _materialized_round_dir / "context" / "campaign.snapshot.json"
            if _materialized_round_dir is not None
            else contained_path(
                self.store.root,
                expected_relpath,
                "V5 Campaign snapshot path",
            )
        )
        if snapshot_path.is_symlink() or not snapshot_path.is_file():
            raise ValueError("V5 Campaign snapshot is missing or unsafe")
        raw = snapshot_path.read_bytes()
        if (
            len(raw) > V5_MAX_CAMPAIGN_SNAPSHOT_BYTES
            or sha256_bytes(raw) != digest
        ):
            raise ValueError("V5 Campaign snapshot bytes/hash mismatch")
        try:
            snapshot = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise ValueError("V5 Campaign snapshot is not valid UTF-8 JSON") from exc
        expected_scope = self._campaign_scope_from_snapshot(
            snapshot,
            snapshot_relpath=expected_relpath,
            snapshot_sha256=digest,
        )
        if scope != expected_scope:
            raise ValueError("V5 Campaign scope drifted from its frozen snapshot")
        if _inspection_context is None:
            current = self.store.campaigns().status(campaign_id)
        else:
            current = _inspection_context.campaign_statuses.get(campaign_id)
            if current is None:
                current = self.store.campaigns().status(campaign_id)
                _inspection_context.campaign_statuses[campaign_id] = current
        if current.get("event_count", 0) < scope["event_count"]:
            raise ValueError("V5 Campaign history was truncated after round freeze")
        if scope["revision"] == V5_CAMPAIGN_SCOPE_REVISION:
            frozen_history = snapshot["campaign_status"]["history"]
            current_prefix = self.store.campaigns().history_summary(
                campaign_id,
                event_count=scope["event_count"],
            )
            if current_prefix != frozen_history:
                raise ValueError(
                    "V5 Campaign frozen history prefix changed after round freeze"
                )
        if _inspection_context is not None:
            _inspection_context.campaign_scopes[round_id] = scope
        return scope

    def frontier(
        self,
        *,
        limit: int = 10,
        include_history: bool = False,
        campaign_id: str | None = None,
        _inspection_context: RoundInspectionContext | None = None,
        _exclude_production_review_only: bool = False,
        _execution_records: bool = False,
    ) -> list[dict[str, Any]]:
        _inspection_context = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert _inspection_context is not None
        if limit < 1:
            raise ValueError("frontier limit must be positive")
        if campaign_id is not None:
            campaign_id = validate_campaign_id(campaign_id)
            if campaign_id not in _inspection_context.campaign_statuses:
                _inspection_context.campaign_statuses[campaign_id] = (
                    self.store.campaigns().status(campaign_id)
                )
        # Frontier scoring needs immutable identity, metadata, and direct
        # connectivity for the complete ledger, not a replay of every artifact,
        # supervision round, historical runtime, and Fact authority.  Validate
        # structural envelopes globally, then fully validate only the visible
        # records returned to Main.  This is a read optimization, never an
        # authority or premise cache.
        records = self.research_envelopes(
            _inspection_context=_inspection_context,
        )
        (
            bases,
            dispositions,
            route_staleness,
            workgroups,
            work_keys,
        ) = self._frontier_structural_state_for_inspection(
            records,
            _inspection_context,
        )
        dependency_ids = sorted(
            {
                fact_id
                for record in bases.values()
                for fact_id in record["dependencies"]
            }
        )
        active_fact_ids = set(
            self._active_fact_premise_bindings(
                dependency_ids,
                _inspection_context=_inspection_context,
                _allow_inactive=True,
            )
            if dependency_ids
            else {}
        )
        visible: list[dict[str, Any]] = []
        for research_id, record in bases.items():
            if (
                campaign_id is not None
                and record["metadata"].get("campaign_id") != campaign_id
            ):
                continue
            projection = dict(record)
            disposition = dispositions.get(research_id)
            if disposition is not None:
                projection["status"] = disposition["metadata"][
                    "disposition_status"
                ]
                projection["latest_disposition_id"] = disposition["research_id"]
                projection["latest_disposition_note"] = disposition["content"]
            if research_id in route_staleness:
                projection["route_status"] = "stale_pending_copy_on_write_repair"
                projection["route_invalidated_by"] = route_staleness[research_id]
                if not include_history:
                    continue
            else:
                projection["route_status"] = "current"
                projection["route_invalidated_by"] = []
            if not include_history and projection["status"] not in ACTIVE_MEMORY_STATUSES:
                continue
            if (
                _exclude_production_review_only
                and self._production_entry_is_review_only(projection)
            ):
                continue
            readiness = (
                1.0
                if all(
                    fact_id in active_fact_ids
                    for fact_id in projection["dependencies"]
                )
                else 0.0
            )
            decision_profile = _research_decision_profile(
                projection["metadata"]
            )
            scoring_entry = {"decision_profile": decision_profile}
            projection["decision_profile"] = decision_profile
            projection["decision_factors"] = decision_factors(
                scoring_entry,
                readiness=readiness,
            )
            projection["score_model"] = COMPACT_SCORE_MODEL
            projection["score_role"] = COMPACT_SCORE_ROLE
            projection["readiness"] = readiness
            projection["score"] = actionable_score(
                scoring_entry,
                readiness=readiness,
            )
            work_key = work_keys[research_id]
            members = workgroups[work_key]
            projection["work_key_sha256"] = work_key
            projection["workgroup_representative_id"] = members[0]
            projection["workgroup_member_count"] = len(members)
            projection["workgroup_member_ids_sha256"] = sha256_json(
                sorted(members)
            )
            projection["id"] = research_id
            visible.append(projection)
        actionable_representatives = self._frontier_actionable_representatives(
            workgroups=workgroups,
            bases=bases,
            dispositions=dispositions,
            route_staleness=route_staleness,
            campaign_id=campaign_id,
            exclude_production_review_only=_exclude_production_review_only,
        )
        for projection in visible:
            actionable_representative_id = actionable_representatives.get(
                projection["work_key_sha256"]
            )
            projection["workgroup_actionable_representative_id"] = (
                actionable_representative_id
            )
            projection["workgroup_member_role"] = (
                "representative"
                if projection["research_id"] == actionable_representative_id
                else "duplicate"
            )
        visible.sort(
            key=lambda item: (
                -item["score"],
                item["created_at"],
                item["research_id"],
            )
        )
        group_completion = _inspection_context.frontier_group_completions
        group_actions = _inspection_context.frontier_group_actions

        def inspect_completion(work_key_batch: set[str]) -> None:
            pending_keys = work_key_batch.difference(group_completion)
            if not pending_keys:
                return
            completion_batch = self._frontier_group_completion(
                workgroups=workgroups,
                work_keys=pending_keys,
                bases=bases,
                dispositions=dispositions,
                route_staleness=route_staleness,
                _inspection_context=_inspection_context,
            )
            group_completion.update(completion_batch)
            group_actions.update(
                project_frontier_group_actions(
                    self,
                    workgroups=workgroups,
                    work_keys=pending_keys,
                    bases=bases,
                    dispositions=dispositions,
                    route_staleness=route_staleness,
                    group_completion=completion_batch,
                    inspection=_inspection_context,
                )
            )

        if include_history:
            selected = visible[:limit]
            inspect_completion(
                {item["work_key_sha256"] for item in selected}
            )
        else:
            actionable = [
                item
                for item in visible
                if item["research_id"]
                == item["workgroup_actionable_representative_id"]
            ]
            selected = []
            cursor = 0
            batch_size = max(limit, 8)
            while cursor < len(actionable) and len(selected) < limit:
                batch = actionable[cursor : cursor + batch_size]
                inspect_completion(
                    {item["work_key_sha256"] for item in batch}
                )
                selected.extend(
                    item
                    for item in batch
                    if group_completion[item["work_key_sha256"]][0]
                    == "pending"
                )
                cursor += len(batch)
            selected = selected[:limit]
        for projection in selected:
            completion = group_completion[projection["work_key_sha256"]]
            projection["work_completion_status"] = completion[0]
            projection["work_completion_research_id"] = completion[1]
            projection["work_completion_member_count"] = completion[2]
            projection["work_completion_member_ids_sha256"] = completion[3]
            projection.update(
                group_actions[projection["work_key_sha256"]]
            )
            actionable_id = projection.get("actionable_research_id")
            projection["plan_round_argv"] = (
                self._exact_plan_round_argv(
                    [actionable_id],
                    campaign_id=campaign_id,
                )
                if projection["next_action"] == "production"
                and isinstance(actionable_id, str)
                else None
            )
        if not _execution_records:
            return [self._compact_frontier_entry(item) for item in selected]

        fully_validated: list[dict[str, Any]] = []
        projection_fields = {
            "status",
            "latest_disposition_id",
            "latest_disposition_note",
            "route_status",
            "route_invalidated_by",
            "decision_profile",
            "decision_factors",
            "score_model",
            "score_role",
            "readiness",
            "score",
            "work_key_sha256",
            "workgroup_representative_id",
            "workgroup_actionable_representative_id",
            "workgroup_member_count",
            "workgroup_member_ids_sha256",
            "workgroup_member_role",
            "work_completion_status",
            "work_completion_research_id",
            "work_completion_member_count",
            "work_completion_member_ids_sha256",
            "next_action",
            "pending_reason",
            "next_attention",
            "disposition",
            "attention_basis_research_ids",
            "attention_basis_round_ids",
            "attention_reason",
            "plan_round_argv",
            "actionable_research_id",
            "actionable_round_id",
            "actionable_research_ids",
            "actionable_research_count",
            "actionable_research_ids_sha256",
            "actionable_round_ids",
            "actionable_round_count",
            "actionable_round_ids_sha256",
            "actionable_claim",
            "actionable_claim_sha256",
            "actionable_kind",
            "id",
        }
        for projection in selected:
            record = self._inspection_research_record(
                projection["research_id"],
                _inspection_context,
            )
            preserved = {
                key: projection[key]
                for key in projection_fields
                if key in projection
            }
            fully_validated.append({**record, **preserved})
        return fully_validated

    @staticmethod
    def _frontier_action_class(next_action: str) -> str:
        if next_action == "production":
            return "research_development"
        if next_action == "main_reconciliation":
            return "semantic_choice"
        if next_action == "none":
            return "complete"
        return "workflow_completion"

    @staticmethod
    def _campaign_mathematical_memory(
        record: dict[str, Any],
        *,
        compact: bool = False,
    ) -> dict[str, Any]:
        """Project canonical Research prose for Main's mathematical judgment."""

        def bounded(value: Any, maximum: int) -> str:
            text = value if isinstance(value, str) else ""
            return text if len(text) <= maximum else text[: maximum - 3] + "..."

        if compact:
            return {
                "research_id": record["research_id"],
                "claim": bounded(record.get("claim"), 240),
            }
        result: dict[str, Any] = {
            "research_id": record["research_id"],
            "kind": record["kind"],
            "relation": record.get("relation"),
            "claim": bounded(record.get("claim"), 320),
            "content": bounded(record.get("content"), 360),
        }
        rationale = bounded(record.get("rationale"), 180)
        if rationale:
            result["rationale"] = rationale
        return result

    @staticmethod
    def _latest_campaign_frontier_checkpoint(
        status: dict[str, Any],
    ) -> dict[str, Any] | None:
        """Read Main's newest advisory Campaign head checkpoint.

        Campaign notes intentionally remain a flexible nontruth surface.  A
        malformed or partially stale note is therefore reported to Main by the
        projection below; it is never promoted into a write gate, scheduler, or
        truth-stage contract.
        """

        updates = status.get("updates")
        if not isinstance(updates, list):
            return None
        checkpoint_updates: list[dict[str, Any]] = []
        for update in updates:
            if not isinstance(update, dict) or update.get("event") != "note":
                continue
            payload = update.get("payload")
            if (
                isinstance(payload, dict)
                and payload.get("kind")
                == "campaign_frontier_head_checkpoint"
            ):
                checkpoint_updates.append(update)
        if not checkpoint_updates:
            return None

        update = checkpoint_updates[-1]
        payload = update["payload"]
        raw_frontiers = payload.get("target_frontiers")
        checkpoint: dict[str, Any] = {
            "event_id": update.get("event_id"),
            "generation": payload.get("generation"),
            "supersedes_event_id": payload.get("supersedes_event_id"),
            "targets": {},
            "diagnostics": [],
            "malformed": False,
        }

        def diagnose(code: str, **fields: Any) -> None:
            diagnostics = checkpoint["diagnostics"]
            if len(diagnostics) >= 32:
                return
            diagnostic = {"code": code}
            diagnostic.update(fields)
            if diagnostic not in diagnostics:
                diagnostics.append(diagnostic)
            checkpoint["malformed"] = True

        generation = payload.get("generation")
        generation_is_valid = (
            not isinstance(generation, bool)
            and isinstance(generation, int)
            and generation >= 1
        )
        previous = (
            checkpoint_updates[-2] if len(checkpoint_updates) > 1 else None
        )
        previous_generation: Any = None
        expected_generation = 1
        expected_supersedes: Any = None
        if previous is not None:
            previous_payload = previous.get("payload")
            if isinstance(previous_payload, dict):
                previous_generation = previous_payload.get("generation")
            if (
                not isinstance(previous_generation, bool)
                and isinstance(previous_generation, int)
                and previous_generation >= 1
            ):
                expected_generation = previous_generation + 1
            else:
                expected_generation = None
            expected_supersedes = previous.get("event_id")
        if not generation_is_valid or generation != expected_generation:
            diagnose(
                "checkpoint_generation_mismatch",
                expected=expected_generation,
                actual=generation,
            )
        actual_supersedes = payload.get("supersedes_event_id")
        if actual_supersedes != expected_supersedes:
            diagnose(
                "checkpoint_supersedes_mismatch",
                expected=expected_supersedes,
                actual=actual_supersedes,
            )

        if not isinstance(raw_frontiers, list):
            diagnose("checkpoint_target_list_malformed")
            return checkpoint
        if len(raw_frontiers) > 64:
            diagnose(
                "checkpoint_target_list_truncated",
                actual=len(raw_frontiers),
                maximum=64,
            )
        for raw_frontier in raw_frontiers[:64]:
            if not isinstance(raw_frontier, dict):
                diagnose("checkpoint_target_entry_malformed")
                continue
            target_id = raw_frontier.get("target_id")
            if not isinstance(target_id, str) or not target_id:
                diagnose("checkpoint_target_id_malformed")
                continue
            if target_id in checkpoint["targets"]:
                diagnose(
                    "checkpoint_target_duplicate",
                    target_id=target_id,
                )
                # A duplicate is ambiguous.  Preserve the first bounded view
                # instead of giving array order a hidden last-write-wins role.
                continue
            active_ids: list[str] = []
            attained_ids: list[str] = []
            for field, destination in (
                ("active_heads", active_ids),
                ("attained_checkpoints", attained_ids),
            ):
                values = raw_frontier.get(field, [])
                if not isinstance(values, list):
                    diagnose(
                        "checkpoint_research_list_malformed",
                        target_id=target_id,
                        field=field,
                    )
                    continue
                for value in values[:8]:
                    research_id = (
                        value.get("research_id")
                        if isinstance(value, dict)
                        else None
                    )
                    if (
                        not isinstance(research_id, str)
                        or MEMORY_ID_RE.fullmatch(research_id) is None
                    ):
                        diagnose(
                            "checkpoint_research_id_malformed",
                            target_id=target_id,
                            field=field,
                        )
                        continue
                    if research_id not in destination:
                        destination.append(research_id)
            raw_disposition = raw_frontier.get("main_disposition", "")
            if not isinstance(raw_disposition, str):
                diagnose(
                    "checkpoint_main_disposition_nontext",
                    target_id=target_id,
                )
                raw_disposition = ""
            recovery_provided = "recovery_root_research_id" in raw_frontier
            recovery_id = raw_frontier.get("recovery_root_research_id")
            if recovery_provided and (
                not isinstance(recovery_id, str)
                or MEMORY_ID_RE.fullmatch(recovery_id) is None
            ):
                diagnose(
                    "checkpoint_recovery_root_malformed",
                    target_id=target_id,
                )
                recovery_id = None
            checkpoint["targets"][target_id] = {
                "active_head_research_ids": active_ids,
                "attained_checkpoint_research_ids": attained_ids,
                "recovery_root_research_id": recovery_id,
                "recovery_root_provided": recovery_provided,
                "main_disposition": raw_disposition,
            }
        return checkpoint

    def _frontier_state_path(self, campaign_id: str) -> Path:
        return self.store.root / "campaigns" / validate_campaign_id(
            campaign_id
        ) / "frontier-state.json"

    def _read_campaign_frontier_working_state(
        self, campaign_id: str
    ) -> dict[str, Any] | None:
        """Read one compact, atomically replaced nontruth work-memory map."""

        campaign_id = validate_campaign_id(campaign_id)
        path = self._frontier_state_path(campaign_id)
        if not path.exists():
            return None
        if path.is_symlink() or not path.is_file():
            raise ValueError("Campaign frontier working state is unsafe")
        value = self.store._read_json(path)
        if (
            not isinstance(value, dict)
            or value.get("revision") != V5_CAMPAIGN_FRONTIER_STATE_REVISION
            or value.get("campaign_id") != campaign_id
            or not isinstance(value.get("generation"), int)
            or value["generation"] < 1
            or not isinstance(value.get("updated_at"), str)
            or not isinstance(value.get("targets"), dict)
            or len(value) != 5
        ):
            raise ValueError("Campaign frontier working state is invalid")
        for target_id, row in value["targets"].items():
            validate_campaign_target_id(target_id)
            if not isinstance(row, dict) or set(row) != {
                "recovery_root_research_id",
                "active_head_research_ids",
                "historical_landmark_research_ids",
                "recent_attained_research_ids",
            }:
                raise ValueError("Campaign frontier target state is invalid")
            validate_memory_id(row["recovery_root_research_id"])
            seen: set[str] = set()
            for field, maximum in (
                ("active_head_research_ids", 8),
                ("historical_landmark_research_ids", 8),
                ("recent_attained_research_ids", 4),
            ):
                ids = row[field]
                if not isinstance(ids, list) or len(ids) > maximum:
                    raise ValueError("Campaign frontier Research list is invalid")
                normalized = [validate_memory_id(item) for item in ids]
                if len(normalized) != len(set(normalized)) or seen.intersection(
                    normalized
                ):
                    raise ValueError("Campaign frontier Research ids repeat")
                seen.update(normalized)
        return value

    def _replace_campaign_frontier_working_state(
        self,
        campaign_id: str,
        *,
        targets: dict[str, dict[str, Any]],
    ) -> dict[str, Any]:
        try:
            current = self._read_campaign_frontier_working_state(campaign_id)
        except ValueError:
            current = None
        if current is not None and current["targets"] == targets:
            return current
        value = {
            "revision": V5_CAMPAIGN_FRONTIER_STATE_REVISION,
            "campaign_id": validate_campaign_id(campaign_id),
            "generation": current["generation"] + 1 if current else 1,
            "updated_at": _utc_now(),
            "targets": targets,
        }
        path = self._frontier_state_path(campaign_id)
        if path.is_symlink():
            raise ValueError("Campaign frontier working state is unsafe")
        self.store._write_json_atomic(path, value)
        return value

    def _current_campaign_frontier_state(
        self,
        campaign_id: str,
        *,
        status: dict[str, Any],
    ) -> dict[str, Any] | None:
        """Use current work memory, bootstrapping once from an old checkpoint."""

        try:
            state = self._read_campaign_frontier_working_state(campaign_id)
        except ValueError:
            checkpoint = self._latest_campaign_frontier_checkpoint(status) or {
                "event_id": None,
                "generation": None,
                "targets": {},
                "diagnostics": [],
                "malformed": True,
            }
            checkpoint["diagnostics"].append(
                {"code": "frontier_working_state_invalid"}
            )
            checkpoint["malformed"] = True
            return checkpoint
        if state is None:
            return self._latest_campaign_frontier_checkpoint(status)
        return {
            "event_id": None,
            "generation": state["generation"],
            "targets": {
                target_id: {
                    **row,
                    "attained_checkpoint_research_ids": list(
                        dict.fromkeys(
                            [
                                *row["recent_attained_research_ids"],
                                *row["historical_landmark_research_ids"],
                            ]
                        )
                    ),
                    "recovery_root_provided": True,
                    "main_disposition": "",
                    "frontier_source": "working_state",
                }
                for target_id, row in state["targets"].items()
            },
            "diagnostics": [],
            "malformed": False,
        }

    @staticmethod
    def _checkpoint_research_campaign_ids(
        research_id: str,
        bases: dict[str, dict[str, Any]],
    ) -> frozenset[str]:
        """Resolve exact Campaign provenance used by checkpoint diagnostics.

        New production records carry ``campaign_id`` directly.  Legacy
        supervision plans and their returned products did not, although their
        frozen supervision receipts identify the exact Campaign-scoped source
        products.  Recognize only that narrow, receipt-consistent shape; do not
        turn generic Research ancestry into Campaign membership.
        """

        record = bases.get(research_id)
        if not isinstance(record, dict):
            return frozenset()
        metadata = record.get("metadata")
        if not isinstance(metadata, dict):
            return frozenset()
        direct_campaign_id = metadata.get("campaign_id")
        if isinstance(direct_campaign_id, str):
            return frozenset({direct_campaign_id})

        plan = record
        if record.get("relation") == "responds_to":
            provenance = metadata.get("assignment_provenance")
            related = record.get("related_research_ids")
            if (
                not isinstance(provenance, dict)
                or provenance.get("work_mode") != "refute"
                or provenance.get("adverse_assignment") is not True
                or not isinstance(related, list)
                or len(related) != 1
            ):
                return frozenset()
            plan = bases.get(related[0])
        if not isinstance(plan, dict) or plan.get("relation") != "challenges":
            return frozenset()
        plan_metadata = plan.get("metadata")
        if not isinstance(plan_metadata, dict):
            return frozenset()
        supervision = plan_metadata.get("research_supervision")
        plan_related = plan.get("related_research_ids")
        if (
            not isinstance(supervision, dict)
            or not isinstance(plan_related, list)
        ):
            return frozenset()
        receipts = supervision.get("source_receipts")
        if not isinstance(receipts, list) or not receipts:
            return frozenset()
        receipt_ids: list[str] = []
        campaign_ids: set[str] = set()
        for receipt in receipts:
            source_id = (
                receipt.get("result_research_id")
                if isinstance(receipt, dict)
                else None
            )
            if not isinstance(source_id, str):
                return frozenset()
            source = bases.get(source_id)
            source_metadata = (
                source.get("metadata") if isinstance(source, dict) else None
            )
            source_campaign_id = (
                source_metadata.get("campaign_id")
                if isinstance(source_metadata, dict)
                else None
            )
            if not isinstance(source_campaign_id, str):
                return frozenset()
            receipt_ids.append(source_id)
            campaign_ids.add(source_campaign_id)
        if (
            len(receipt_ids) != len(plan_related)
            or set(receipt_ids) != set(plan_related)
        ):
            return frozenset()
        return frozenset(campaign_ids)

    @classmethod
    def _campaign_semantic_successor_index(
        cls,
        bases: dict[str, dict[str, Any]],
    ) -> dict[str, Any]:
        """Index exact production, supervision, and COW workflow edges.

        The index projects only already-recorded identities.  It does not rank
        mathematical relevance, mutate a Campaign checkpoint, or authorize a
        new round.
        """

        children: dict[str, set[str]] = {}
        production_products: set[str] = set()
        production_source_by_product: dict[str, str] = {}
        supervision_plans: set[str] = set()
        supervision_results: set[str] = set()
        cow_repairs: set[str] = set()
        legacy_repair_tasks: set[str] = set()

        for research_id, record in bases.items():
            metadata = record.get("metadata")
            provenance = (
                metadata.get("assignment_provenance")
                if isinstance(metadata, dict)
                else None
            )
            related = record.get("related_research_ids")
            if (
                record.get("relation") == "responds_to"
                and isinstance(provenance, dict)
                and provenance.get("adverse_assignment") is False
                and provenance.get("work_mode") != "refute"
                and isinstance(related, list)
                and len(related) == 1
                and related[0] in bases
            ):
                # Freshness follows exact workflow publication, not product
                # completion.  A blocked or challenge-bearing product is still
                # a real successor that makes an older checkpoint head stale;
                # its completion and next action remain separate projections.
                production_products.add(research_id)
                production_source_by_product[research_id] = related[0]
                children.setdefault(related[0], set()).add(research_id)

            supervision = (
                metadata.get("research_supervision")
                if isinstance(metadata, dict)
                else None
            )
            receipts = (
                supervision.get("source_receipts")
                if isinstance(supervision, dict)
                else None
            )
            if (
                record.get("relation") == "challenges"
                and isinstance(related, list)
                and isinstance(receipts, list)
                and receipts
            ):
                receipt_ids = [
                    item.get("result_research_id")
                    if isinstance(item, dict)
                    else None
                    for item in receipts
                ]
                if (
                    all(isinstance(item, str) for item in receipt_ids)
                    and len(receipt_ids) == len(related)
                    and sorted(receipt_ids) == sorted(related)
                    and all(item in bases for item in receipt_ids)
                ):
                    supervision_plans.add(research_id)
                    for source_id in receipt_ids:
                        children.setdefault(source_id, set()).add(research_id)

        for research_id, record in bases.items():
            metadata = record.get("metadata")
            provenance = (
                metadata.get("assignment_provenance")
                if isinstance(metadata, dict)
                else None
            )
            related = record.get("related_research_ids")
            if (
                record.get("relation") == "responds_to"
                and isinstance(provenance, dict)
                and provenance.get("adverse_assignment") is True
                and provenance.get("work_mode") == "refute"
                and isinstance(related, list)
                and len(related) == 1
                and related[0] in supervision_plans
            ):
                supervision_results.add(research_id)
                children.setdefault(related[0], set()).add(research_id)

            if (
                record.get("kind") != "repair"
                or record.get("relation") != "repairs"
                or not isinstance(metadata, dict)
            ):
                continue
            source = record.get("source")
            source_parts = (
                [part.strip() for part in source.split(";")]
                if isinstance(source, str)
                else []
            )
            source_research_ids = [
                part.removeprefix("research:")
                for part in source_parts
                if part.startswith("research:")
                and MEMORY_ID_RE.fullmatch(
                    part.removeprefix("research:")
                )
                is not None
            ]
            if (
                isinstance(metadata.get("campaign_id"), str)
                and isinstance(related, list)
                and len(related) >= 2
                and len(set(related)) == len(related)
                and len(source_research_ids) == len(source_parts)
                and set(source_research_ids) == set(related)
                and all(item in bases for item in related)
                and all(
                    record.get("created_at", "")
                    > bases[item].get("created_at", "")
                    for item in related
                )
            ):
                # Before repair_of/trigger metadata was standardized, Main
                # authored exact COW task roots whose complete ``research:``
                # source set equalled their immutable related-id set.  The
                # bytes already state the bridge.  Following it here restores
                # deep Campaign visibility without treating the repair as
                # completed, choosing a branch, or accepting fuzzy ancestry.
                legacy_repair_tasks.add(research_id)
                for source_id in related:
                    children.setdefault(source_id, set()).add(research_id)
            product_id = metadata.get("repair_of_research_id")
            trigger_id = metadata.get("trigger_research_id")
            if (
                not isinstance(product_id, str)
                or product_id not in production_products
                or not isinstance(trigger_id, str)
                or trigger_id not in supervision_results
                or record.get("source") != f"research:{product_id}"
                or related != sorted({product_id, trigger_id})
            ):
                continue
            # Campaign freshness follows the semantic COW edge that is already
            # present in the immutable graph.  A historical repair may predate
            # the optional hash-bound ``repair_spec`` projection; requiring
            # that later administrative field here would strand an otherwise
            # exact kind/relation/source/product/trigger edge.  The stricter
            # repair-continuity predicate remains in the workgroup-completion
            # path, where it decides whether a repair can close work rather
            # than whether Main is allowed to see that the route advanced.
            cow_repairs.add(research_id)
            children.setdefault(product_id, set()).add(research_id)
            children.setdefault(trigger_id, set()).add(research_id)

        return {
            "children": {
                research_id: sorted(values)
                for research_id, values in children.items()
            },
            "production_products": production_products,
            "production_source_by_product": production_source_by_product,
            "supervision_plans": supervision_plans,
            "supervision_results": supervision_results,
            "cow_repairs": cow_repairs,
            "legacy_repair_tasks": legacy_repair_tasks,
        }

    def _campaign_attained_semantic_successor_summary(
        self,
        *,
        attained_research_id: str,
        campaign_id: str,
        bases: dict[str, dict[str, Any]],
        index: dict[str, Any],
    ) -> tuple[dict[str, Any], list[str]]:
        children = index["children"]
        seen = {attained_research_id}
        pending = list(children.get(attained_research_id, []))
        successors: list[str] = []
        while pending:
            research_id = pending.pop(0)
            if research_id in seen:
                continue
            if self._checkpoint_research_campaign_ids(
                research_id,
                bases,
            ) != frozenset({campaign_id}):
                continue
            seen.add(research_id)
            successors.append(research_id)
            pending.extend(children.get(research_id, []))
        successor_ids = sorted(successors)
        successor_set = set(successor_ids)
        terminal_ids = sorted(
            research_id
            for research_id in successor_ids
            if not any(
                child in successor_set
                for child in children.get(research_id, [])
            )
        )

        # A clean supervision result is attained review evidence, not a new
        # research question.  Productive challenges remain current route heads
        # until a COW repair succeeds them.  Every other exact terminal shape
        # (production product, live supervision plan, or repair) is likewise a
        # workflow route.  This role split is structural and advisory: it does
        # not choose the next mathematical target or mutate a checkpoint.
        current_route_ids: list[str] = []
        terminal_evidence_ids: list[str] = []
        for research_id in terminal_ids:
            if research_id not in index["supervision_results"]:
                current_route_ids.append(research_id)
                continue
            record = bases[research_id]
            metadata = record.get("metadata")
            worker_outcome = (
                metadata.get("worker_outcome")
                if isinstance(metadata, dict)
                else None
            )
            route_invalidations = (
                metadata.get("route_invalidations", [])
                if isinstance(metadata, dict)
                else []
            )
            productive = (
                record.get("kind")
                in {"challenge", "counterexample", "obstacle", "dead_end"}
                or worker_outcome
                in {"challenge", "counterexample", "dead_end"}
                or bool(route_invalidations)
            )
            if productive:
                current_route_ids.append(research_id)
            else:
                terminal_evidence_ids.append(research_id)

        def bounded_members(member_ids: set[str]) -> list[str]:
            return sorted(successor_set.intersection(member_ids))[:8]

        summary = {
            "attained_research_id": attained_research_id,
            "production_product_research_ids": bounded_members(
                index["production_products"]
            ),
            "supervision_plan_research_ids": bounded_members(
                index["supervision_plans"]
            ),
            "supervision_result_research_ids": bounded_members(
                index["supervision_results"]
            ),
            "cow_repair_research_ids": bounded_members(index["cow_repairs"]),
            "legacy_repair_task_research_ids": bounded_members(
                index["legacy_repair_tasks"]
            ),
            "terminal_research_ids": terminal_ids[:8],
            "current_route_research_ids": current_route_ids[:8],
            "current_route_count": len(current_route_ids),
            "current_route_ids_sha256": sha256_json(current_route_ids),
            "terminal_evidence_research_ids": terminal_evidence_ids[:8],
            "terminal_evidence_count": len(terminal_evidence_ids),
            "terminal_evidence_ids_sha256": sha256_json(
                terminal_evidence_ids
            ),
            "successor_count": len(successor_ids),
            "successor_ids_sha256": sha256_json(successor_ids),
            "terminal_count": len(terminal_ids),
            "terminal_ids_sha256": sha256_json(terminal_ids),
            "selection_effect": "none",
        }
        return summary, terminal_ids

    def campaign_goal_coverage(
        self,
        campaign_id: str,
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> list[dict[str, Any]]:
        """Project nonworkflow Campaign goals onto their exact live routes.

        A ``research_goal`` target is a durable semantic root.  Routine reads
        use Main's newest exact ``frontier_heads`` checkpoint when present;
        the root remains provenance and final recovery input rather than a
        request to traverse an old branch every time.  This read-only view
        never edits the target, dispatches work, closes a goal, or affects
        Candidate/Fact state.
        """

        inspection = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert inspection is not None
        campaign_id = validate_campaign_id(campaign_id)
        status = inspection.campaign_statuses.get(campaign_id)
        if status is None:
            status = self.store.campaigns().status(campaign_id)
            inspection.campaign_statuses[campaign_id] = status
        targets = status.get("targets")
        if not isinstance(targets, dict):
            raise ValueError("Campaign goal targets must be an object")
        goal_targets = [
            (target_id, target)
            for target_id, target in sorted(targets.items())
            if isinstance(target, dict)
            and target.get("status") == "active"
            and target.get("role") == "research_goal"
        ]
        if not goal_targets:
            return []

        checkpoint = self._current_campaign_frontier_state(
            campaign_id,
            status=status,
        )
        checkpoint_targets = (
            checkpoint["targets"]
            if isinstance(checkpoint, dict)
            and isinstance(checkpoint.get("targets"), dict)
            else {}
        )
        checkpoint_diagnostics = (
            list(checkpoint.get("diagnostics", []))
            if isinstance(checkpoint, dict)
            and isinstance(checkpoint.get("diagnostics"), list)
            else []
        )

        def diagnose_checkpoint(code: str, **fields: Any) -> None:
            if len(checkpoint_diagnostics) >= 32:
                return
            diagnostic = {"code": code}
            diagnostic.update(fields)
            if diagnostic not in checkpoint_diagnostics:
                checkpoint_diagnostics.append(diagnostic)
            if isinstance(checkpoint, dict):
                checkpoint["malformed"] = True

        if isinstance(checkpoint, dict):
            for target_id, _target in goal_targets:
                if target_id not in checkpoint_targets:
                    diagnose_checkpoint(
                        "checkpoint_target_missing",
                        target_id=target_id,
                    )

        def target_checkpoint_diagnostics(
            target_id: str,
        ) -> list[dict[str, Any]]:
            return [
                diagnostic
                for diagnostic in checkpoint_diagnostics
                if diagnostic.get("target_id") in {None, target_id}
            ]

        records = self.research_envelopes(
            _inspection_context=inspection,
        )
        (
            bases,
            dispositions,
            route_staleness,
            workgroups,
            work_keys,
        ) = self._frontier_structural_state_for_inspection(
            records,
            inspection,
        )
        semantic_successor_index = self._campaign_semantic_successor_index(
            bases
        )
        prepared: list[dict[str, Any]] = []
        goal_work_keys: set[str] = set()
        for target_id, target in goal_targets:
            if target.get("subject_kind") != "research":
                raise ValueError("Campaign research_goal subject kind is invalid")
            root_id = validate_memory_id(target.get("subject_id"))
            label = target.get("label")
            if not isinstance(label, str) or not label.strip():
                raise ValueError("Campaign research_goal label must be nonempty")
            root = bases.get(root_id)
            checkpoint_target = checkpoint_targets.get(target_id)
            if isinstance(checkpoint_target, dict):
                frontier_source = checkpoint_target.get(
                    "frontier_source", "main_checkpoint"
                )
                root_claim = (
                    root["claim"]
                    if isinstance(root, dict)
                    and isinstance(root.get("claim"), str)
                    else ""
                )
                active_head_ids = checkpoint_target.get(
                    "active_head_research_ids", []
                )
                attained_ids = checkpoint_target.get(
                    "attained_checkpoint_research_ids", []
                )
                if not isinstance(active_head_ids, list):
                    active_head_ids = []
                if not isinstance(attained_ids, list):
                    attained_ids = []
                if frontier_source == "working_state":
                    historical_ids = checkpoint_target.get(
                        "historical_landmark_research_ids", []
                    )
                    recent_attained_ids = checkpoint_target.get(
                        "recent_attained_research_ids", []
                    )
                else:
                    # Historical checkpoints used one curated attained list.
                    # Treat it as the durable spine on first bootstrap.
                    historical_ids = list(attained_ids)
                    recent_attained_ids = []
                head_work_keys: list[tuple[str, str]] = []
                head_action_root_ids: dict[str, str] = {}
                invalid_head_ids: list[str] = []
                invalid_attained_ids: list[str] = []
                valid_attained_ids: list[str] = []
                for head_id in active_head_ids[:8]:
                    head = bases.get(head_id)
                    if (
                        not isinstance(head, dict)
                        or self._checkpoint_research_campaign_ids(
                            head_id,
                            bases,
                        )
                        != frozenset({campaign_id})
                    ):
                        invalid_head_ids.append(head_id)
                        continue
                    action_root_id = head_id
                    production_source_id = semantic_successor_index[
                        "production_source_by_product"
                    ].get(head_id)
                    head_metadata = head.get("metadata")
                    provenance = (
                        head_metadata.get("assignment_provenance")
                        if isinstance(head_metadata, dict)
                        else None
                    )
                    task_binding = (
                        head_metadata.get("task_binding")
                        if isinstance(head_metadata, dict)
                        else None
                    )
                    if (
                        isinstance(production_source_id, str)
                        and production_source_id in bases
                        and isinstance(provenance, dict)
                        and isinstance(task_binding, dict)
                        and provenance.get("adverse_assignment") is False
                        and provenance.get("assignment_id")
                        == task_binding.get("assignment_id")
                        and provenance.get("round_id")
                        == task_binding.get("round_id")
                        and provenance.get("task_card_sha256")
                        == task_binding.get("task_card_sha256")
                        and self._checkpoint_research_campaign_ids(
                            production_source_id,
                            bases,
                        )
                        == frozenset({campaign_id})
                    ):
                        # A frozen product is a valid semantic checkpoint head,
                        # but its next lifecycle action belongs to the exact
                        # production task root named by the bound return.  This
                        # read-only redirect prevents "produce the product"
                        # recursion while preserving the product as Main's
                        # chosen semantic object.
                        action_root_id = production_source_id
                    work_key = work_keys[action_root_id]
                    head_work_keys.append((head_id, work_key))
                    head_action_root_ids[head_id] = action_root_id
                    goal_work_keys.add(work_key)
                if invalid_head_ids:
                    diagnose_checkpoint(
                        "checkpoint_active_head_missing_or_cross_campaign",
                        target_id=target_id,
                        research_ids=invalid_head_ids,
                    )
                for attained_id in attained_ids[:16]:
                    attained = bases.get(attained_id)
                    if (
                        not isinstance(attained, dict)
                        or self._checkpoint_research_campaign_ids(
                            attained_id,
                            bases,
                        )
                        != frozenset({campaign_id})
                    ):
                        invalid_attained_ids.append(attained_id)
                    else:
                        valid_attained_ids.append(attained_id)
                if invalid_attained_ids:
                    diagnose_checkpoint(
                        "checkpoint_attained_missing_or_cross_campaign",
                        target_id=target_id,
                        research_ids=invalid_attained_ids,
                    )
                valid_historical_ids = [
                    research_id
                    for research_id in historical_ids[:8]
                    if research_id in valid_attained_ids
                ]
                valid_recent_attained_ids = [
                    research_id
                    for research_id in recent_attained_ids[:8]
                    if research_id in valid_attained_ids
                    and research_id not in set(valid_historical_ids)
                ]
                attained_semantic_successors: list[dict[str, Any]] = []
                terminal_successor_ids: set[str] = set()
                checkpointed_research_ids = set(active_head_ids).union(
                    attained_ids
                )
                active_head_semantic_successors: list[dict[str, Any]] = []
                head_terminal_ids: dict[str, list[str]] = {}
                current_active_head_ids: list[str] = []
                stale_active_head_ids: list[str] = []
                for head_id, _work_key in head_work_keys:
                    summary, terminal_ids = (
                        self._campaign_attained_semantic_successor_summary(
                            attained_research_id=head_id,
                            campaign_id=campaign_id,
                            bases=bases,
                            index=semantic_successor_index,
                        )
                    )
                    summary["checkpoint_active_head_research_id"] = (
                        summary.pop("attained_research_id")
                    )
                    head_terminal_ids[head_id] = terminal_ids
                    if summary["successor_count"]:
                        stale_active_head_ids.append(head_id)
                        summary["projection_scope"] = (
                            "exact_workflow_successors_of_checkpoint_head"
                        )
                        active_head_semantic_successors.append(summary)
                        candidates = summary[
                            "current_route_research_ids"
                        ]
                    else:
                        candidates = [head_id]
                    for candidate_id in candidates:
                        if candidate_id not in current_active_head_ids:
                            current_active_head_ids.append(candidate_id)
                successor_root_ids: list[str] = []
                for attained_id in valid_attained_ids:
                    summary, terminal_ids = (
                        self._campaign_attained_semantic_successor_summary(
                            attained_research_id=attained_id,
                            campaign_id=campaign_id,
                            bases=bases,
                            index=semantic_successor_index,
                        )
                    )
                    if summary["successor_count"]:
                        successor_root_ids.append(attained_id)
                    new_terminal_ids = sorted(
                        set(terminal_ids).difference(
                            checkpointed_research_ids
                        )
                    )
                    if new_terminal_ids:
                        summary["projection_scope"] = (
                            "uncheckpointed_terminal_routes_only"
                        )
                        attained_semantic_successors.append(summary)
                        terminal_successor_ids.update(new_terminal_ids)
                uncheckpointed_terminal_ids = sorted(
                    terminal_successor_ids
                )
                recovery_id = checkpoint_target.get(
                    "recovery_root_research_id"
                )
                recovery_provided = bool(
                    checkpoint_target.get("recovery_root_provided")
                )
                if not recovery_provided:
                    diagnose_checkpoint(
                        "checkpoint_recovery_root_missing",
                        target_id=target_id,
                    )
                    recovery_id = root_id
                    recovery_source = "immutable_campaign_anchor_fallback"
                else:
                    recovery = (
                        bases.get(recovery_id)
                        if isinstance(recovery_id, str)
                        else None
                    )
                    if (
                        not isinstance(recovery, dict)
                        or self._checkpoint_research_campaign_ids(
                            recovery_id,
                            bases,
                        )
                        != frozenset({campaign_id})
                    ):
                        if isinstance(recovery_id, str):
                            diagnose_checkpoint(
                                "checkpoint_recovery_root_missing_or_"
                                "cross_campaign",
                                target_id=target_id,
                                research_ids=[recovery_id],
                            )
                        recovery_id = root_id
                        recovery_source = (
                            "immutable_campaign_anchor_fallback"
                        )
                    else:
                        recovery_source = "explicit_checkpoint_root"
                diagnostics = target_checkpoint_diagnostics(target_id)
                prepared.append(
                    {
                        "target_id": target_id,
                        "label": label,
                        "root_research_id": root_id,
                        "root_claim": root_claim,
                        "historical_landmark_research_ids": (
                            valid_historical_ids
                        ),
                        "recent_attained_research_ids": (
                            valid_recent_attained_ids
                        ),
                        "historical_mathematical_summary": [
                            self._campaign_mathematical_memory(
                                bases[research_id],
                                compact=True,
                            )
                            for research_id in valid_historical_ids[:8]
                        ],
                        "recent_attained_mathematical_history": [
                            self._campaign_mathematical_memory(
                                bases[research_id],
                                compact=True,
                            )
                            for research_id in valid_recent_attained_ids[:4]
                        ],
                        "history_review_recommended": bool(
                            len(valid_historical_ids) > 4
                            or (
                                valid_recent_attained_ids
                                and (
                                    not valid_historical_ids
                                    or len(valid_recent_attained_ids) >= 4
                                )
                            )
                        ),
                        "history_review_reasons": [
                            reason
                            for reason, applies in (
                                (
                                    "historical_landmarks_empty",
                                    bool(valid_recent_attained_ids)
                                    and not valid_historical_ids,
                                ),
                                (
                                    "recent_mathematical_progress_accumulated",
                                    len(valid_recent_attained_ids) >= 4,
                                ),
                                (
                                    "historical_landmarks_need_main_curation",
                                    len(valid_historical_ids) > 4,
                                ),
                            )
                            if applies
                        ],
                        "frontier_source": frontier_source,
                        "frontier_generation": checkpoint.get("generation"),
                        "frontier_checkpoint_event_id": checkpoint.get(
                            "event_id"
                        ),
                        "active_head_research_ids": active_head_ids[:8],
                        "current_active_head_research_ids": (
                            current_active_head_ids[:8]
                        ),
                        "current_active_head_count": len(
                            current_active_head_ids
                        ),
                        "current_active_head_ids_sha256": sha256_json(
                            current_active_head_ids
                        ),
                        "stale_active_head_research_ids": (
                            stale_active_head_ids[:8]
                        ),
                        "active_head_semantic_successors": (
                            active_head_semantic_successors
                        ),
                        "active_head_selection_effect": "none",
                        "active_head_workflow_roots": [
                            {
                                "active_head_research_id": head_id,
                                "workflow_root_research_id": (
                                    head_action_root_ids[head_id]
                                ),
                                "selection_effect": "none",
                            }
                            for head_id, _work_key in head_work_keys
                        ],
                        "attained_checkpoint_research_ids": (
                            valid_attained_ids[:16]
                        ),
                        "attained_semantic_successors": (
                            attained_semantic_successors
                        ),
                        "attained_successor_root_count": len(
                            successor_root_ids
                        ),
                        "attained_successor_root_ids_sha256": sha256_json(
                            sorted(successor_root_ids)
                        ),
                        "uncheckpointed_terminal_successor_research_ids": (
                            uncheckpointed_terminal_ids[:8]
                        ),
                        "uncheckpointed_terminal_successor_count": len(
                            uncheckpointed_terminal_ids
                        ),
                        "uncheckpointed_terminal_successor_ids_sha256": (
                            sha256_json(uncheckpointed_terminal_ids)
                        ),
                        "terminal_successor_selection_effect": "none",
                        "recovery_root_research_id": recovery_id,
                        "recovery_root_source": recovery_source,
                        "checkpoint_main_disposition": checkpoint_target.get(
                            "main_disposition", ""
                        ),
                        # A diagnostic about a different target must not make
                        # every otherwise valid target look malformed.
                        "checkpoint_malformed": bool(diagnostics),
                        "checkpoint_refresh_recommended": bool(
                            diagnostics
                            or stale_active_head_ids
                            or uncheckpointed_terminal_ids
                        ),
                        "checkpoint_refresh_reasons": sorted(
                            {
                                *(
                                    ["checkpoint_diagnostic"]
                                    if diagnostics
                                    else []
                                ),
                                *(
                                    ["active_head_has_newer_terminal_successor"]
                                    if stale_active_head_ids
                                    else []
                                ),
                                *(
                                    ["attained_checkpoint_has_unrecorded_terminal_successor"]
                                    if uncheckpointed_terminal_ids
                                    else []
                                ),
                            }
                        ),
                        "invalid_head_research_ids": invalid_head_ids,
                        "invalid_attained_checkpoint_research_ids": (
                            invalid_attained_ids
                        ),
                        "checkpoint_diagnostic_codes": [
                            diagnostic["code"]
                            for diagnostic in diagnostics
                        ],
                        "_head_work_keys": head_work_keys,
                        "_head_action_root_ids": head_action_root_ids,
                        "_head_terminal_ids": head_terminal_ids,
                        "_uncheckpointed_terminal_ids": (
                            uncheckpointed_terminal_ids
                        ),
                        "_work_key_sha256s": [
                            work_key for _, work_key in head_work_keys
                        ],
                        "_checkpoint_diagnostics": diagnostics,
                    }
                )
                continue
            checkpoint_fallback: dict[str, Any] = {}
            if isinstance(checkpoint, dict):
                diagnostics = target_checkpoint_diagnostics(target_id)
                checkpoint_fallback = {
                    "frontier_source": "immutable_anchor_fallback",
                    "frontier_generation": checkpoint.get("generation"),
                    "frontier_checkpoint_event_id": checkpoint.get(
                        "event_id"
                    ),
                    "recovery_root_research_id": root_id,
                    "recovery_root_source": (
                        "immutable_campaign_anchor_fallback"
                    ),
                    "checkpoint_malformed": True,
                    "checkpoint_diagnostic_codes": [
                        diagnostic["code"] for diagnostic in diagnostics
                    ],
                    "_checkpoint_diagnostics": diagnostics,
                }
            if root is None:
                prepared.append(
                    {
                        "target_id": target_id,
                        "label": label,
                        "root_research_id": root_id,
                        "coverage_status": "orphaned",
                        "action_class": "semantic_choice",
                        "next_action": "exact_research_search",
                        "why_now": "research_goal_root_missing_or_nonexecutable",
                        "actionable_research_id": None,
                        "actionable_round_id": None,
                        "actionable_research_ids": [],
                        "root_claim": "",
                        "_work_key_sha256": None,
                        "_work_key_sha256s": [],
                        **checkpoint_fallback,
                    }
                )
                continue
            metadata = root.get("metadata")
            if (
                not isinstance(metadata, dict)
                or metadata.get("campaign_id") != campaign_id
            ):
                prepared.append(
                    {
                        "target_id": target_id,
                        "label": label,
                        "root_research_id": root_id,
                        "coverage_status": "orphaned",
                        "action_class": "semantic_choice",
                        "next_action": "exact_research_search",
                        "why_now": "research_goal_root_crosses_campaign_boundary",
                        "actionable_research_id": None,
                        "actionable_round_id": None,
                        "actionable_research_ids": [],
                        "root_claim": "",
                        "_work_key_sha256": None,
                        "_work_key_sha256s": [],
                        **checkpoint_fallback,
                    }
                )
                continue
            work_key = work_keys[root_id]
            goal_work_keys.add(work_key)
            prepared.append(
                {
                    "target_id": target_id,
                    "label": label,
                    "root_research_id": root_id,
                    "root_claim": root["claim"],
                    "_work_key_sha256": work_key,
                    "_work_key_sha256s": [work_key],
                    **checkpoint_fallback,
                }
            )

        missing_completion = goal_work_keys.difference(
            inspection.frontier_group_completions
        )
        if missing_completion:
            inspection.frontier_group_completions.update(
                self._frontier_group_completion(
                    workgroups=workgroups,
                    work_keys=missing_completion,
                    bases=bases,
                    dispositions=dispositions,
                    route_staleness=route_staleness,
                    _inspection_context=inspection,
                )
            )
        missing_actions = goal_work_keys.difference(
            inspection.frontier_group_actions
        )
        if missing_actions:
            inspection.frontier_group_actions.update(
                project_frontier_group_actions(
                    self,
                    workgroups=workgroups,
                    work_keys=missing_actions,
                    bases=bases,
                    dispositions=dispositions,
                    route_staleness=route_staleness,
                    group_completion={
                        work_key: inspection.frontier_group_completions[work_key]
                        for work_key in missing_actions
                    },
                    inspection=inspection,
                )
            )

        # A Campaign checkpoint may deliberately keep the durable production
        # task as its active head while recording the ingested product as
        # attained.  A subsequently planned supervision node is operational
        # evidence, not a new mathematical frontier choice.  Decide freshness
        # only after exact round actions are visible so an in-flight plan does
        # not force Main to rewrite the checkpoint after every workflow step.
        # Productive reviews, COW tasks, completed review results, and other
        # uncheckpointed semantic terminals still make the head stale.
        for item in prepared:
            if item.get("frontier_source") not in {
                "main_checkpoint",
                "working_state",
            }:
                continue
            checkpointed_ids = set(
                item.get("active_head_research_ids", [])
            ).union(item.get("attained_checkpoint_research_ids", []))
            stale_head_ids: list[str] = []
            current_head_ids: list[str] = []
            suppressed_plan_ids: set[str] = set()
            for head_id, work_key in item["_head_work_keys"]:
                summary = next(
                    (
                        candidate
                        for candidate in item[
                            "active_head_semantic_successors"
                        ]
                        if candidate.get(
                            "checkpoint_active_head_research_id"
                        )
                        == head_id
                    ),
                    None,
                )
                if summary is None:
                    current_head_ids.append(head_id)
                    continue
                terminal_ids = set(
                    item["_head_terminal_ids"].get(head_id, [])
                )
                uncheckpointed_ids = terminal_ids.difference(
                    checkpointed_ids
                )
                action = inspection.frontier_group_actions[work_key]
                pending_reason = str(action.get("pending_reason", ""))
                in_flight_plan_ids = uncheckpointed_ids.intersection(
                    semantic_successor_index["supervision_plans"]
                )
                plan_only_in_flight = bool(uncheckpointed_ids) and (
                    in_flight_plan_ids == uncheckpointed_ids
                    and action.get("next_action")
                    in {"await_return", "ingest_return"}
                    and pending_reason.startswith("supervision_")
                )
                if not uncheckpointed_ids or plan_only_in_flight:
                    current_head_ids.append(head_id)
                    summary["checkpoint_refresh_required"] = False
                    summary["checkpoint_route_state"] = (
                        "current_with_in_flight_supervision"
                        if plan_only_in_flight
                        else "current_with_checkpointed_successors"
                    )
                    if plan_only_in_flight:
                        bounded_plans = sorted(in_flight_plan_ids)[:8]
                        summary[
                            "in_flight_supervision_plan_research_ids"
                        ] = bounded_plans
                        suppressed_plan_ids.update(in_flight_plan_ids)
                    continue
                stale_head_ids.append(head_id)
                summary["checkpoint_refresh_required"] = True
                summary["checkpoint_route_state"] = (
                    "stale_exact_successor_available"
                )
                for candidate_id in summary.get(
                    "current_route_research_ids", []
                ):
                    if candidate_id not in current_head_ids:
                        current_head_ids.append(candidate_id)

            item["stale_active_head_research_ids"] = stale_head_ids[:8]
            item["current_active_head_research_ids"] = current_head_ids[:8]
            item["current_active_head_count"] = len(current_head_ids)
            item["current_active_head_ids_sha256"] = sha256_json(
                current_head_ids
            )
            remaining_terminal_ids = sorted(
                set(item["_uncheckpointed_terminal_ids"]).difference(
                    suppressed_plan_ids
                )
            )
            item[
                "uncheckpointed_terminal_successor_research_ids"
            ] = remaining_terminal_ids[:8]
            item["uncheckpointed_terminal_successor_count"] = len(
                remaining_terminal_ids
            )
            item[
                "uncheckpointed_terminal_successor_ids_sha256"
            ] = sha256_json(remaining_terminal_ids)
            for summary in item.get("attained_semantic_successors", []):
                terminal_ids = set(
                    summary.get("terminal_research_ids", [])
                ).difference(checkpointed_ids)
                unresolved_ids = terminal_ids.difference(
                    suppressed_plan_ids
                )
                summary["checkpoint_refresh_required"] = bool(
                    unresolved_ids
                )
                summary["checkpoint_route_state"] = (
                    "stale_exact_successor_available"
                    if unresolved_ids
                    else "current_with_in_flight_supervision"
                )
                summary[
                    "uncheckpointed_terminal_research_ids"
                ] = sorted(unresolved_ids)[:8]
            diagnostics = item["_checkpoint_diagnostics"]
            item["checkpoint_refresh_recommended"] = bool(
                diagnostics or stale_head_ids or remaining_terminal_ids
            )
            item["checkpoint_refresh_reasons"] = sorted(
                {
                    *(
                        ["checkpoint_diagnostic"]
                        if diagnostics
                        else []
                    ),
                    *(
                        ["active_head_has_newer_terminal_successor"]
                        if stale_head_ids
                        else []
                    ),
                    *(
                        [
                            "attained_checkpoint_has_unrecorded_terminal_successor"
                        ]
                        if remaining_terminal_ids
                        else []
                    ),
                }
            )
            if item.get("frontier_source") == "working_state":
                # The replaceable working state, not an immutable Campaign
                # checkpoint, is the current Main memory.  Exact terminal
                # successors remain visible in the route projection, but they
                # must not instruct Main to copy another full checkpoint.
                item["checkpoint_refresh_recommended"] = False
                item["checkpoint_refresh_reasons"] = []

        coverage: list[dict[str, Any]] = []
        for item in prepared:
            if item.get("frontier_source") in {
                "main_checkpoint",
                "working_state",
            }:
                head_work_keys = item["_head_work_keys"]
                invalid_head_ids = item["invalid_head_research_ids"]
                root_claim = item["root_claim"]
                public = {
                    key: value
                    for key, value in item.items()
                    if not key.startswith("_")
                }
                public["_work_key_sha256s"] = item[
                    "_work_key_sha256s"
                ]
                public["_checkpoint_diagnostics"] = item[
                    "_checkpoint_diagnostics"
                ]
                public["root_claim"] = (
                    root_claim
                    if len(root_claim) <= 320
                    else root_claim[:317] + "..."
                )
                if invalid_head_ids:
                    coverage.append(
                        {
                            **public,
                            "coverage_status": "needs_main_choice",
                            "work_completion_status": "unknown",
                            "action_class": "semantic_choice",
                            "next_action": "exact_research_search",
                            "why_now": (
                                "campaign_checkpoint_head_missing_or_"
                                "cross_campaign"
                            ),
                            "actionable_research_id": None,
                            "actionable_round_id": None,
                            "actionable_research_ids": [],
                            "active_head_actions": [],
                        }
                    )
                    continue
                if not head_work_keys:
                    coverage.append(
                        {
                            **public,
                            "coverage_status": "needs_main_choice",
                            "work_completion_status": "checkpoint_only",
                            "action_class": "semantic_choice",
                            "next_action": "select_frontier_head",
                            "why_now": "campaign_checkpoint_has_no_active_head",
                            "actionable_research_id": None,
                            "actionable_round_id": None,
                            "actionable_research_ids": [],
                            "active_head_actions": [],
                        }
                    )
                    continue
                head_actions: list[dict[str, Any]] = []
                for head_id, work_key in head_work_keys:
                    action = inspection.frontier_group_actions[work_key]
                    completion = inspection.frontier_group_completions[
                        work_key
                    ]
                    successor_summary = next(
                        (
                            summary
                            for summary in item[
                                "active_head_semantic_successors"
                            ]
                            if summary.get(
                                "checkpoint_active_head_research_id"
                            )
                            == head_id
                        ),
                        None,
                    )
                    head_actions.append(
                        {
                            "research_id": head_id,
                            "mathematical_summary": (
                                self._campaign_mathematical_memory(
                                    bases[head_id]
                                )
                            ),
                            "workflow_root_research_id": item[
                                "_head_action_root_ids"
                            ].get(head_id, head_id),
                            "checkpoint_head_state": (
                                successor_summary.get(
                                    "checkpoint_route_state",
                                    "stale_exact_successor_available",
                                )
                                if successor_summary is not None
                                else "current"
                            ),
                            "current_terminal_research_ids": (
                                successor_summary.get(
                                    "terminal_research_ids", []
                                )
                                if successor_summary is not None
                                else [head_id]
                            ),
                            "current_route_research_ids": (
                                successor_summary.get(
                                    "current_route_research_ids", []
                                )
                                if successor_summary is not None
                                else [head_id]
                            ),
                            "current_route_mathematical_summaries": [
                                self._campaign_mathematical_memory(
                                    bases[research_id],
                                    compact=True,
                                )
                                for research_id in (
                                    successor_summary.get(
                                        "current_route_research_ids", []
                                    )
                                    if successor_summary is not None
                                    else []
                                )[:2]
                                if research_id in bases
                                and research_id != head_id
                            ],
                            "terminal_evidence_research_ids": (
                                successor_summary.get(
                                    "terminal_evidence_research_ids", []
                                )
                                if successor_summary is not None
                                else []
                            ),
                            "work_completion_status": completion[0],
                            "action_class": self._frontier_action_class(
                                action["next_action"]
                            ),
                            "next_action": action["next_action"],
                            "why_now": action["pending_reason"],
                            "actionable_research_id": action[
                                "actionable_research_id"
                            ],
                            "actionable_round_id": action[
                                "actionable_round_id"
                            ],
                        }
                    )
                if len(head_actions) == 1:
                    head_action = head_actions[0]
                    next_action = head_action["next_action"]
                    if next_action == "none":
                        coverage_status = "needs_main_choice"
                        action_class = "semantic_choice"
                        goal_next_action = "main_disposition"
                        why_now = (
                            "campaign_target_active_after_heads_completed"
                        )
                        actionable_research_id = None
                        actionable_round_id = None
                    else:
                        coverage_status = (
                            "research_open"
                            if next_action == "production"
                            else "in_flight"
                            if next_action == "await_return"
                            else "needs_main_choice"
                            if next_action == "main_reconciliation"
                            else "workflow_pending"
                        )
                        action_class = head_action["action_class"]
                        goal_next_action = next_action
                        why_now = head_action["why_now"]
                        actionable_research_id = head_action[
                            "actionable_research_id"
                        ]
                        actionable_round_id = head_action[
                            "actionable_round_id"
                        ]
                    coverage.append(
                        {
                            **public,
                            "coverage_status": coverage_status,
                            "work_completion_status": head_action[
                                "work_completion_status"
                            ],
                            "action_class": action_class,
                            "next_action": goal_next_action,
                            "why_now": why_now,
                            "actionable_research_id": (
                                actionable_research_id
                            ),
                            "actionable_round_id": actionable_round_id,
                            "actionable_research_ids": [
                                actionable_research_id
                            ]
                            if isinstance(actionable_research_id, str)
                            else [],
                            "active_head_actions": head_actions,
                        }
                    )
                    continue
                pending_actions = [
                    action
                    for action in head_actions
                    if action["next_action"] != "none"
                ]
                next_actions = {
                    action["next_action"] for action in pending_actions
                }
                if not pending_actions:
                    coverage_status = "needs_main_choice"
                    action_class = "semantic_choice"
                    next_action = "main_disposition"
                elif "main_reconciliation" in next_actions:
                    coverage_status = "needs_main_choice"
                    action_class = "semantic_choice"
                    next_action = "advance_active_heads"
                elif "await_return" in next_actions:
                    coverage_status = "in_flight"
                    action_class = "multi_branch_progress"
                    next_action = "advance_active_heads"
                elif "production" in next_actions:
                    coverage_status = "research_open"
                    action_class = "multi_branch_progress"
                    next_action = "advance_active_heads"
                else:
                    coverage_status = "workflow_pending"
                    action_class = "multi_branch_progress"
                    next_action = "advance_active_heads"
                actionable_ids: list[str] = []
                for action in pending_actions:
                    actionable_id = action["actionable_research_id"]
                    if (
                        isinstance(actionable_id, str)
                        and actionable_id not in actionable_ids
                    ):
                        actionable_ids.append(actionable_id)
                coverage.append(
                    {
                        **public,
                        "coverage_status": coverage_status,
                        "work_completion_status": "multiple_heads",
                        "action_class": action_class,
                        "next_action": next_action,
                        "why_now": (
                            "campaign_target_active_after_heads_completed"
                            if not pending_actions
                            else "campaign_checkpoint_has_multiple_active_heads"
                        ),
                        "actionable_research_id": None,
                        "actionable_round_id": None,
                        "actionable_research_ids": actionable_ids[:8],
                        "active_head_actions": head_actions,
                    }
                )
                continue
            work_key = item["_work_key_sha256"]
            if work_key is None:
                coverage.append(item)
                continue
            action = inspection.frontier_group_actions[work_key]
            completion = inspection.frontier_group_completions[work_key]
            next_action = action["next_action"]
            if next_action == "none":
                coverage_status = "needs_main_choice"
                action_class = "semantic_choice"
                goal_next_action = "main_disposition"
                why_now = "campaign_target_active_after_work_completed"
                actionable_research_id = None
                actionable_round_id = None
                actionable_research_ids: list[str] = []
            else:
                coverage_status = (
                    "research_open"
                    if next_action == "production"
                    else "in_flight"
                    if next_action == "await_return"
                    else "needs_main_choice"
                    if next_action == "main_reconciliation"
                    else "workflow_pending"
                )
                action_class = self._frontier_action_class(next_action)
                goal_next_action = next_action
                why_now = action["pending_reason"]
                actionable_research_id = action[
                    "actionable_research_id"
                ]
                actionable_round_id = action["actionable_round_id"]
                actionable_research_ids = action[
                    "actionable_research_ids"
                ][:4]
            root_claim = item["root_claim"]
            coverage.append(
                {
                    **item,
                    "root_claim": (
                        root_claim
                        if len(root_claim) <= 320
                        else root_claim[:317] + "..."
                    ),
                    "coverage_status": coverage_status,
                    "work_completion_status": completion[0],
                    "action_class": action_class,
                    "next_action": goal_next_action,
                    "why_now": why_now,
                    "actionable_research_id": actionable_research_id,
                    "actionable_round_id": actionable_round_id,
                    "actionable_research_ids": actionable_research_ids,
                }
            )
        for item in coverage:
            next_action = item.get("next_action")
            reason = item.get("why_now", "")
            if next_action == "production":
                next_attention = "production"
            elif next_action == "repair":
                next_attention = "repair"
            elif next_action == "supervision" or (
                isinstance(reason, str) and reason.startswith("supervision_")
            ):
                next_attention = "supervision"
            elif next_action in {"await_return", "ingest_return"}:
                next_attention = (
                    "supervision"
                    if isinstance(reason, str)
                    and reason.startswith("supervision_")
                    else "production"
                )
            elif item.get("coverage_status") == "covered":
                next_attention = "none"
            else:
                next_attention = "reconcile"
            disposition = (
                "complete"
                if next_attention == "none"
                else "in_flight"
                if item.get("coverage_status") == "in_flight"
                else "active"
            )
            actionable_id = item.get("actionable_research_id")
            item["next_attention"] = next_attention
            item["disposition"] = disposition
            item["attention_basis_research_ids"] = (
                list(item.get("actionable_research_ids", []))[:8]
                if isinstance(item.get("actionable_research_ids"), list)
                else []
            )
            item["attention_basis_round_ids"] = (
                [item["actionable_round_id"]]
                if isinstance(item.get("actionable_round_id"), str)
                else []
            )
            item["attention_reason"] = reason
            item["plan_round_argv"] = (
                self._exact_plan_round_argv(
                    [actionable_id],
                    campaign_id=campaign_id,
                    frontier_target_id=item["target_id"],
                )
                if next_action == "production"
                and isinstance(actionable_id, str)
                else None
            )
            head_actions = item.get("active_head_actions")
            if isinstance(head_actions, list):
                for head_action in head_actions:
                    if not isinstance(head_action, dict):
                        continue
                    head_id = head_action.get("actionable_research_id")
                    head_action["plan_round_argv"] = (
                        self._exact_plan_round_argv(
                            [head_id],
                            campaign_id=campaign_id,
                            frontier_target_id=item["target_id"],
                        )
                        if head_action.get("next_action") == "production"
                        and isinstance(head_id, str)
                        else None
                    )
        return coverage

    def _campaign_frontier_seed(
        self,
        campaign_id: str,
        *,
        inspection: RoundInspectionContext | None = None,
    ) -> tuple[dict[str, dict[str, Any]], dict[str, dict[str, Any]]]:
        """Return one current row per active goal plus its live projection."""

        campaign_id = validate_campaign_id(campaign_id)
        status = self.store.campaigns().status(campaign_id)
        goals = {
            item["target_id"]: item
            for item in self.campaign_goal_coverage(
                campaign_id,
                _inspection_context=inspection or RoundInspectionContext(),
            )
        }
        try:
            current = self._read_campaign_frontier_working_state(campaign_id)
        except ValueError:
            current = None
        stored = current["targets"] if current is not None else {}
        rows: dict[str, dict[str, Any]] = {}
        for target_id, target in sorted(status["targets"].items()):
            if (
                target.get("status") != "active"
                or target.get("role") != "research_goal"
            ):
                continue
            if target_id in stored:
                rows[target_id] = {
                    key: list(value) if isinstance(value, list) else value
                    for key, value in stored[target_id].items()
                }
                continue
            root_id = validate_memory_id(target["subject_id"])
            goal = goals.get(target_id, {})
            active = goal.get("active_head_research_ids")
            attained = goal.get("attained_checkpoint_research_ids")
            invalid = {
                item
                for field in (
                    "invalid_head_research_ids",
                    "invalid_attained_checkpoint_research_ids",
                )
                for item in (
                    goal.get(field) if isinstance(goal.get(field), list) else []
                )
            }
            active_ids = [
                item
                for item in (active if isinstance(active, list) else [root_id])
                if item not in invalid
            ]
            rows[target_id] = {
                "recovery_root_research_id": (
                    goal["recovery_root_research_id"]
                    if isinstance(
                        goal.get("recovery_root_research_id"), str
                    )
                    else root_id
                ),
                "active_head_research_ids": active_ids or [root_id],
                "historical_landmark_research_ids": [
                    item
                    for item in (
                        attained if isinstance(attained, list) else []
                    )
                    if item not in invalid and item not in active_ids
                ][:8],
                "recent_attained_research_ids": [],
            }
        return rows, goals

    def _advance_campaign_frontier_for_plan(
        self,
        *,
        campaign_id: str,
        frontier_target_id: str,
        selected_research_ids: list[str],
        inspection: RoundInspectionContext | None = None,
    ) -> dict[str, Any]:
        """Replace the sole current state before publishing the planned round."""

        target_id = validate_campaign_target_id(frontier_target_id)
        selected = list(dict.fromkeys(
            validate_memory_id(item) for item in selected_research_ids
        ))
        if not selected or len(selected) != len(selected_research_ids):
            raise ValueError("frontier planning requires unique Research ids")
        rows, goals = self._campaign_frontier_seed(
            campaign_id,
            inspection=inspection,
        )
        if target_id not in rows:
            raise ValueError(
                "--frontier-target must name an active Campaign research goal"
            )
        row = rows[target_id]
        goal = goals.get(target_id, {})
        actions = {
            item["research_id"]: item
            for item in goal.get("active_head_actions", [])
            if isinstance(item, dict)
            and isinstance(item.get("research_id"), str)
        }
        selected_set = set(selected)
        # A repair round may select a newly materialized COW record whose
        # direct ``repair_of_research_id`` is already the terminal successor
        # of a stored head.  Retire that stored route as one mathematical
        # branch; otherwise the projection shows both the old head and its
        # in-flight repair and falsely asks Main to choose between them.
        replacement_basis = set(selected_set)
        nonadvancing_relations = {
            "challenges",
            "copy_on_write_repair",
            "corrects",
            "disposes",
            "investigates",
            "repairs",
            "repairs_assurance_of",
            "responds_to",
        }
        for research_id in selected:
            record = self._research_record(
                research_id,
                _inspection_context=inspection,
            )
            relation = record.get("relation")
            if relation == "repairs":
                repair_of = record.get("metadata", {}).get(
                    "repair_of_research_id"
                )
                if isinstance(repair_of, str):
                    replacement_basis.add(validate_memory_id(repair_of))
            elif relation not in nonadvancing_relations:
                # Selecting a positive Research descendant as the target's
                # next production head is Main's semantic handoff.  Its exact
                # related route may still have supervision in flight; that
                # workflow remains independently visible, but the old route
                # must not survive as a second head and later ask Main to make
                # the same choice again.
                replacement_basis.update(
                    validate_memory_id(item)
                    for item in record.get("related_research_ids", [])
                )
        preserved: list[str] = []
        retired: list[str] = []
        for head_id in row["active_head_research_ids"]:
            if head_id in selected_set:
                continue
            action = actions.get(head_id, {})
            # A completed workflow has no current route, but its exact
            # terminal products and clean review results are still the
            # mathematical ancestry from which Main may choose the next cut.
            # Treat that already projected lineage as part of the same head;
            # otherwise plan-round asks Main to repeat an unambiguous choice
            # through a separate frontier update and may retain a dead root as
            # a ninth live head.
            exact_lineage: set[str] = set()
            for field in (
                "current_route_research_ids",
                "current_terminal_research_ids",
                "terminal_evidence_research_ids",
            ):
                values = action.get(field, [])
                if isinstance(values, list):
                    exact_lineage.update(
                        validate_memory_id(item) for item in values
                    )
            replaced = bool(
                replacement_basis.intersection(exact_lineage)
            ) or (
                action.get("actionable_research_id") in selected_set
                and action.get("actionable_research_id") != head_id
            )
            (retired if replaced or action.get("next_action") == "none" else preserved).append(
                head_id
            )
        active = list(dict.fromkeys([*selected, *preserved]))
        if len(active) > 8:
            raise ValueError("a Campaign target has more than eight live heads")
        historical = [
            item
            for item in row["historical_landmark_research_ids"]
            if item not in active
        ]
        recent = [
            item
            for item in dict.fromkeys(
                [*retired, *row["recent_attained_research_ids"]]
            )
            if item not in active and item not in historical
        ][:4]
        rows[target_id] = {
            **row,
            "active_head_research_ids": active,
            "historical_landmark_research_ids": historical,
            "recent_attained_research_ids": recent,
        }
        return self._replace_campaign_frontier_working_state(
            campaign_id,
            targets=rows,
        )

    def reconcile_campaign_frontier(
        self,
        campaign_id: str,
        payload: dict[str, Any],
    ) -> dict[str, Any]:
        """Apply a sparse Main override to the sole current work-memory state."""

        with self.store.v5_mutation_lock(command="campaign-frontier-reconcile"):
            return self._reconcile_campaign_frontier(campaign_id, payload)

    def _reconcile_campaign_frontier(
        self,
        campaign_id: str,
        payload: dict[str, Any],
    ) -> dict[str, Any]:

        campaign_id = validate_campaign_id(campaign_id)
        if (
            not isinstance(payload, dict)
            or payload.get("kind") != "campaign_frontier_update"
        ):
            raise ValueError("Campaign frontier update kind is invalid")
        rows, _goals = self._campaign_frontier_seed(campaign_id)
        target_id = validate_campaign_target_id(payload.get("target_id"))
        if target_id not in rows:
            raise ValueError("Campaign frontier update target is not active")

        def research_ids(field: str, maximum: int) -> list[str]:
            value = payload[field]
            if not isinstance(value, list) or len(value) > maximum:
                raise ValueError(f"{field} must contain at most {maximum} ids")
            result = [validate_memory_id(item) for item in value]
            if len(result) != len(set(result)):
                raise ValueError(f"{field} contains duplicate Research ids")
            return result

        row = dict(rows[target_id])
        fields = {
            "active_head_research_ids": 8,
            "historical_landmark_research_ids": 8,
            "recent_attained_research_ids": 4,
        }
        changed = False
        for field, maximum in fields.items():
            if field in payload:
                row[field] = research_ids(field, maximum)
                changed = True
        if "recovery_root_research_id" in payload:
            row["recovery_root_research_id"] = validate_memory_id(
                payload["recovery_root_research_id"]
            )
            changed = True
        if not changed:
            raise ValueError("Campaign frontier update contains no state change")
        active = set(row["active_head_research_ids"])
        historical = [
            item
            for item in row["historical_landmark_research_ids"]
            if item not in active
        ]
        row["historical_landmark_research_ids"] = historical
        row["recent_attained_research_ids"] = [
            item
            for item in row["recent_attained_research_ids"]
            if item not in active and item not in historical
        ]

        bases = {
            item["research_id"]: item
            for item in self.research_envelopes(
                _inspection_context=RoundInspectionContext(),
            )
        }
        referenced = [
            row["recovery_root_research_id"],
            *row["active_head_research_ids"],
            *row["historical_landmark_research_ids"],
            *row["recent_attained_research_ids"],
        ]
        invalid = [
            item
            for item in referenced
            if self._checkpoint_research_campaign_ids(item, bases)
            != frozenset({campaign_id})
        ]
        if invalid:
            raise ValueError(
                "Campaign frontier update contains missing or cross-Campaign Research: "
                + ", ".join(sorted(set(invalid)))
            )
        rows[target_id] = row
        state = self._replace_campaign_frontier_working_state(
            campaign_id,
            targets=rows,
        )
        return {
            "campaign_id": campaign_id,
            "state_generation": state["generation"],
            "updated_target_id": target_id,
            "project_effect": "frontier_working_state_only",
            "truth_effect": "none",
        }

    @staticmethod
    def _compact_goal_coverage_entry(
        entry: dict[str, Any],
    ) -> dict[str, Any]:
        """Keep Main's routine goal row exact without copying diagnostics."""

        def bounded_text(value: Any, maximum: int) -> str:
            text = value if isinstance(value, str) else ""
            return text if len(text) <= maximum else text[: maximum - 3] + "..."

        def compact_mathematical_summary(value: Any) -> Any:
            if not isinstance(value, dict):
                return value
            summary = {
                key: value[key]
                for key in ("research_id", "kind", "relation")
                if key in value
            }
            claim = bounded_text(value.get("claim"), 220)
            content = bounded_text(value.get("content"), 100)
            if claim:
                summary["claim"] = claim
            if content:
                summary["content"] = content
            return summary

        routine_fields = (
            "target_id",
            "label",
            "root_research_id",
            "root_claim",
            "historical_landmark_research_ids",
            "recent_attained_research_ids",
            "historical_mathematical_summary",
            "recent_attained_mathematical_history",
            "history_review_recommended",
            "history_review_reasons",
            "recovery_root_research_id",
            "recovery_root_source",
            "coverage_status",
            "work_completion_status",
            "action_class",
            "next_action",
            "why_now",
            "actionable_research_id",
            "actionable_round_id",
            "actionable_research_ids",
            "next_attention",
            "disposition",
            "attention_basis_research_ids",
            "attention_basis_round_ids",
            "attention_reason",
            "plan_round_argv",
            "active_head_research_ids",
            "active_head_workflow_roots",
            "current_active_head_research_ids",
            "current_active_head_count",
            "current_active_head_ids_sha256",
            "stale_active_head_research_ids",
            "attained_checkpoint_research_ids",
            "frontier_generation",
            "frontier_source",
            "frontier_checkpoint_event_id",
            "checkpoint_main_disposition",
            "checkpoint_refresh_recommended",
            "checkpoint_refresh_reasons",
            "checkpoint_diagnostic_codes",
            "checkpoint_malformed",
            "invalid_head_research_ids",
            "invalid_attained_checkpoint_research_ids",
            "terminal_successor_selection_effect",
            "uncheckpointed_terminal_successor_count",
            "uncheckpointed_terminal_successor_ids_sha256",
            "uncheckpointed_terminal_successor_research_ids",
        )
        compact = {
            key: entry[key] for key in routine_fields if key in entry
        }
        if isinstance(compact.get("root_claim"), str):
            compact["root_claim"] = bounded_text(compact["root_claim"], 240)
        for field, maximum in (
            ("historical_mathematical_summary", 2),
            ("recent_attained_mathematical_history", 2),
        ):
            values = compact.get(field)
            if isinstance(values, list):
                compact[field] = [
                    {
                        **{
                            key: value[key]
                            for key in ("research_id", "kind", "relation")
                            if isinstance(value, dict) and key in value
                        },
                        **(
                            {
                                "claim": bounded_text(
                                    value.get("claim"), 160
                                )
                            }
                            if isinstance(value, dict)
                            and bounded_text(value.get("claim"), 160)
                            else {}
                        ),
                    }
                    for value in values[:maximum]
                ]
        workflow_roots = compact.get("active_head_workflow_roots")
        if isinstance(workflow_roots, list):
            nontrivial_roots = [
                item
                for item in workflow_roots
                if isinstance(item, dict)
                and item.get("active_head_research_id")
                != item.get("workflow_root_research_id")
            ]
            if nontrivial_roots:
                compact["active_head_workflow_roots"] = nontrivial_roots
            else:
                compact.pop("active_head_workflow_roots", None)
        # These exact ids are already partitioned into the curated historical
        # and recent lists above.  Repeating their concatenation adds no Main
        # decision information.
        compact.pop("attained_checkpoint_research_ids", None)
        raw_head_actions = entry.get("active_head_actions")
        if isinstance(raw_head_actions, list):
            compact_actions: list[dict[str, Any]] = []
            for action in raw_head_actions:
                if not isinstance(action, dict):
                    continue
                compact_action = {
                    key: action[key]
                    for key in (
                        "research_id",
                        "workflow_root_research_id",
                        "checkpoint_head_state",
                        "action_class",
                        "next_action",
                        "why_now",
                        "actionable_research_id",
                        "actionable_round_id",
                        "current_route_research_ids",
                        "current_route_mathematical_summaries",
                        "current_terminal_research_ids",
                        "terminal_evidence_research_ids",
                        "work_completion_status",
                        "plan_round_argv",
                    )
                    if key in action
                }
                if "mathematical_summary" in action:
                    compact_action["mathematical_summary"] = (
                        compact_mathematical_summary(
                            action["mathematical_summary"]
                        )
                    )
                route_summaries = compact_action.get(
                    "current_route_mathematical_summaries"
                )
                if isinstance(route_summaries, list):
                    compact_action[
                        "current_route_mathematical_summaries"
                    ] = [
                        {
                            **(
                                {"research_id": value["research_id"]}
                                if isinstance(value, dict)
                                and "research_id" in value
                                else {}
                            ),
                            **(
                                {
                                    "claim": bounded_text(
                                        value.get("claim"), 140
                                    )
                                }
                                if isinstance(value, dict)
                                and bounded_text(value.get("claim"), 140)
                                else {}
                            ),
                        }
                        for value in route_summaries[:2]
                    ]
                if (
                    compact_action.get("workflow_root_research_id")
                    == compact_action.get("research_id")
                ):
                    compact_action.pop("workflow_root_research_id", None)
                compact_actions.append(compact_action)
            compact["active_head_actions"] = compact_actions
        return compact

    def frontier_decision_surface(
        self,
        *,
        limit: int = 10,
        campaign_id: str | None = None,
        diagnostic: bool = False,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any]:
        """Return Main's small goal-aware decision surface.

        ``goal_coverage`` preserves semantic direction; ``workflow_queue``
        shows bounded operational follow-up.  Neither list is a dispatcher or
        a closure authority, and Main remains responsible for the exact choice.
        """

        inspection = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert inspection is not None
        goal_campaign_id = campaign_id
        goal_context_source = "explicit_scope" if campaign_id is not None else "none"
        if goal_campaign_id is None:
            goal_campaign_id = self.store.campaigns().active()
            if goal_campaign_id is not None:
                goal_context_source = "active_hint"
        goal_coverage = (
            self.campaign_goal_coverage(
                goal_campaign_id,
                _inspection_context=inspection,
            )
            if goal_campaign_id is not None
            else []
        )
        entries = self.frontier(
            limit=limit,
            campaign_id=campaign_id,
            _inspection_context=inspection,
        )
        target_ids_by_work_key: dict[str, list[str]] = {}
        target_ids_by_research_id: dict[str, list[str]] = {}
        for goal in goal_coverage:
            work_keys = goal.get("_work_key_sha256s")
            if not isinstance(work_keys, list):
                work_key = goal.get("_work_key_sha256")
                work_keys = [work_key] if isinstance(work_key, str) else []
            for work_key in work_keys:
                if not isinstance(work_key, str):
                    continue
                target_ids_by_work_key.setdefault(work_key, []).append(
                    goal["target_id"]
                )
            exact_ids: list[str] = []
            for field in (
                "active_head_research_ids",
                "actionable_research_ids",
            ):
                values = goal.get(field)
                if not isinstance(values, list):
                    continue
                for research_id in values:
                    if (
                        isinstance(research_id, str)
                        and research_id not in exact_ids
                    ):
                        exact_ids.append(research_id)
            head_actions = goal.get("active_head_actions")
            if isinstance(head_actions, list):
                for action in head_actions:
                    if not isinstance(action, dict):
                        continue
                    for field in (
                        "research_id",
                        "actionable_research_id",
                    ):
                        research_id = action.get(field)
                        if (
                            isinstance(research_id, str)
                            and research_id not in exact_ids
                        ):
                            exact_ids.append(research_id)
            for research_id in exact_ids:
                target_ids_by_research_id.setdefault(
                    research_id, []
                ).append(goal["target_id"])

        projected: list[dict[str, Any]] = []
        for entry in entries:
            next_action = entry["next_action"]
            derived_next_attention = (
                "production"
                if next_action == "production"
                else "repair"
                if next_action == "repair"
                else "supervision"
                if next_action == "supervision"
                or str(entry.get("pending_reason", "")).startswith(
                    "supervision_"
                )
                else "none"
                if next_action == "none"
                else "reconcile"
            )
            derived_disposition = (
                "in_flight"
                if next_action in {"await_return", "ingest_return"}
                else "complete"
                if next_action == "none"
                else "active"
            )
            actionable_id = entry["actionable_research_id"]
            actionable_claim = (
                entry["actionable_claim"]
                if actionable_id != entry["research_id"]
                else ""
            )
            candidate_limit = 4 if next_action == "main_reconciliation" else 1
            goal_target_ids: list[str] = list(
                target_ids_by_work_key.get(entry["work_key_sha256"], [])
            )
            exact_entry_ids = [entry["research_id"], actionable_id]
            exact_entry_ids.extend(entry["actionable_research_ids"])
            for research_id in exact_entry_ids:
                if not isinstance(research_id, str):
                    continue
                for target_id in target_ids_by_research_id.get(
                    research_id, []
                ):
                    if target_id not in goal_target_ids:
                        goal_target_ids.append(target_id)
            plan_round_argv = entry.get("plan_round_argv")
            if (
                campaign_id is not None
                and next_action == "production"
                and isinstance(actionable_id, str)
                and len(goal_target_ids) == 1
            ):
                plan_round_argv = self._exact_plan_round_argv(
                    [actionable_id],
                    campaign_id=campaign_id,
                    frontier_target_id=goal_target_ids[0],
                )
            projected.append(
                {
                    "research_id": entry["research_id"],
                    "claim": (
                        entry["claim"]
                        if len(entry["claim"]) <= 320
                        else entry["claim"][:317] + "..."
                    ),
                    "campaign_id": entry["campaign_id"],
                    "score": entry["score"],
                    "readiness": entry["readiness"],
                    "goal_relevance": "direct" if goal_target_ids else "none",
                    "goal_target_ids": goal_target_ids,
                    "action_class": self._frontier_action_class(next_action),
                    "next_action": next_action,
                    "why_now": entry["pending_reason"],
                    "next_attention": entry.get(
                        "next_attention", derived_next_attention
                    ),
                    "disposition": entry.get(
                        "disposition", derived_disposition
                    ),
                    "attention_basis_research_ids": entry.get(
                        "attention_basis_research_ids",
                        entry.get("actionable_research_ids", []),
                    )[:4],
                    "attention_basis_round_ids": entry.get(
                        "attention_basis_round_ids",
                        [entry["actionable_round_id"]]
                        if isinstance(entry.get("actionable_round_id"), str)
                        else [],
                    )[:4],
                    "attention_reason": entry.get(
                        "attention_reason", entry["pending_reason"]
                    ),
                    "plan_round_argv": plan_round_argv,
                    "actionable_research_id": actionable_id,
                    "actionable_round_id": entry["actionable_round_id"],
                    "actionable_research_ids": entry[
                        "actionable_research_ids"
                    ][:candidate_limit],
                    "actionable_research_count": entry[
                        "actionable_research_count"
                    ],
                    "actionable_claim": (
                        actionable_claim
                        if len(actionable_claim) <= 256
                        else actionable_claim[:253] + "..."
                    ),
                    "actionable_kind": entry["actionable_kind"],
                    "workgroup_member_count": entry[
                        "workgroup_member_count"
                    ],
                }
            )
        unmapped_campaign_attention: dict[str, Any] | None = None
        if campaign_id is not None and goal_coverage:
            goal_mapped = [
                item
                for item in projected
                if item["goal_relevance"] == "direct"
            ]
            goal_unmapped = [
                item
                for item in projected
                if item["goal_relevance"] == "none"
            ]
            unmapped_ids = [
                item["research_id"] for item in goal_unmapped
            ]
            unmapped_campaign_attention = {
                "visible_count": len(goal_unmapped),
                "visible_research_ids": unmapped_ids[:8],
                "visible_research_ids_sha256": sha256_json(unmapped_ids),
                "items": [
                    {
                        "research_id": item["research_id"],
                        "claim": (
                            item["claim"]
                            if len(item["claim"]) <= 160
                            else item["claim"][:157] + "..."
                        ),
                        "next_action": item["next_action"],
                        "why_now": item["why_now"],
                        "actionable_round_id": item[
                            "actionable_round_id"
                        ],
                    }
                    for item in goal_unmapped[:3]
                ],
                "bounded_selection_exhausted": len(entries) >= limit,
                "selection_effect": "none",
                "instruction": (
                    "These Campaign-associated items are not mapped to an "
                    "active goal target. Main may exact-search and promote a "
                    "promising item into a target; none is deleted, closed, "
                    "dispatched, or treated as mathematically irrelevant."
                ),
            }
            projected = goal_mapped
        status = (
            inspection.campaign_statuses[goal_campaign_id]
            if goal_campaign_id is not None
            else None
        )
        clean_coverage = [
            {
                key: value
                for key, value in item.items()
                if not key.startswith("_")
            }
            for item in goal_coverage
        ]
        # An active Campaign is only an advisory hint for an unscoped
        # frontier.  Its exact Research ids remain useful, but its Campaign id
        # must not silently filter or bind Main's replay command.
        for item in clean_coverage:
            actionable_id = item.get("actionable_research_id")
            if item.get("next_action") == "production" and isinstance(
                actionable_id, str
            ):
                item["plan_round_argv"] = self._exact_plan_round_argv(
                    [actionable_id],
                    campaign_id=campaign_id,
                    frontier_target_id=(
                        item["target_id"]
                        if campaign_id is not None
                        else None
                    ),
                )
            head_actions = item.get("active_head_actions")
            if isinstance(head_actions, list):
                for head_action in head_actions:
                    if not isinstance(head_action, dict):
                        continue
                    head_id = head_action.get("actionable_research_id")
                    if head_action.get("next_action") == "production" and isinstance(
                        head_id, str
                    ):
                        head_action["plan_round_argv"] = (
                            self._exact_plan_round_argv(
                                [head_id],
                                campaign_id=campaign_id,
                                frontier_target_id=(
                                    item["target_id"]
                                    if campaign_id is not None
                                    else None
                                ),
                            )
                        )
        checkpoint_diagnostics: list[dict[str, Any]] = []
        for item in goal_coverage:
            diagnostics = item.get("_checkpoint_diagnostics")
            if not isinstance(diagnostics, list):
                continue
            for diagnostic in diagnostics:
                if (
                    isinstance(diagnostic, dict)
                    and diagnostic not in checkpoint_diagnostics
                    and len(checkpoint_diagnostics) < 32
                ):
                    checkpoint_diagnostics.append(diagnostic)
        refresh_goal_rows = [
            item
            for item in clean_coverage
            if item.get("checkpoint_refresh_recommended") is True
            or item.get("frontier_source") == "immutable_anchor_fallback"
        ]
        checkpoint_refresh_reasons = sorted(
            {
                reason
                for item in refresh_goal_rows
                for reason in (
                    item.get("checkpoint_refresh_reasons", [])
                    if isinstance(
                        item.get("checkpoint_refresh_reasons"), list
                    )
                    else []
                )
            }.union(
                {"checkpoint_target_missing"}
                if any(
                    item.get("frontier_source")
                    == "immutable_anchor_fallback"
                    for item in refresh_goal_rows
                )
                else set()
            )
        )
        objective = status.get("objective") if isinstance(status, dict) else None
        if isinstance(objective, str) and len(objective) > 640:
            objective = objective[:637] + "..."
        progress_counts: dict[str, int] = {}
        for item in clean_coverage:
            coverage_status = item["coverage_status"]
            progress_counts[coverage_status] = (
                progress_counts.get(coverage_status, 0) + 1
            )
        queue_policy = (
            "goal-mapped workflow_queue as operational follow-up, and "
            "consults unmapped_campaign_attention only when an exact "
            "side-route search is useful"
            if unmapped_campaign_attention is not None
            else "the bounded workflow_queue as operational follow-up"
        )
        return {
            "campaign_id": campaign_id,
            "goal_campaign_id": goal_campaign_id,
            "goal_context_source": goal_context_source,
            "campaign_selection_effect": (
                "exact_filter" if campaign_id is not None else "none"
            ),
            "objective": objective,
            "goal_target_count": len(clean_coverage),
            "goal_progress": {
                "covered": progress_counts.get("covered", 0),
                "research_open": progress_counts.get("research_open", 0),
                "workflow_pending": progress_counts.get(
                    "workflow_pending", 0
                ),
                "in_flight": progress_counts.get("in_flight", 0),
                "needs_main_choice": progress_counts.get(
                    "needs_main_choice", 0
                ),
                "orphaned": progress_counts.get("orphaned", 0),
            },
            "goal_coverage": (
                clean_coverage
                if diagnostic
                else [
                    self._compact_goal_coverage_entry(item)
                    for item in clean_coverage
                ]
            ),
            "checkpoint_diagnostics": checkpoint_diagnostics,
            "checkpoint_refresh": {
                "recommended": bool(refresh_goal_rows),
                "reason_codes": checkpoint_refresh_reasons,
                "target_ids": sorted(
                    {item["target_id"] for item in refresh_goal_rows}
                ),
                "selection_effect": "none",
                "instruction": (
                    "Main should exact-search the listed Research ids and "
                    "write one new advisory checkpoint when the semantic "
                    "choice is clear; this hint neither mutates Campaign "
                    "state nor blocks planning."
                    if refresh_goal_rows
                    else "The current frontier working state is aligned with "
                    "the exact recorded workflow successors."
                ),
            },
            "workflow_queue": projected,
            **(
                {
                    "unmapped_campaign_attention": (
                        unmapped_campaign_attention
                    )
                }
                if unmapped_campaign_attention is not None
                else {}
            ),
            "main_selection_policy": (
                "Main reads goal_coverage, compares current heads with compact "
                "mathematical history, and lets plan-round atomically advance "
                "its chosen route. Sparse frontier updates are only for branch "
                "reordering or history curation. Routine work then uses "
                + queue_policy
                + ". Main chooses one goal-serving action; no entry dispatches "
                "or admits itself. active_hint is advisory only."
            ),
        }

    @staticmethod
    def _compact_frontier_entry(projection: dict[str, Any]) -> dict[str, Any]:
        """Return Main's bounded selection surface, never full artifact metadata."""

        metadata = projection["metadata"]
        artifacts = metadata.get("artifacts", [])
        obligations = metadata.get("obligations", [])
        stops = metadata.get("stop_conditions", [])
        suggested_actions = metadata.get("suggested_actions", [])
        tags = metadata.get("tags", [])
        dependencies = projection["dependencies"]
        related = projection["related_research_ids"]
        invalidators = projection["route_invalidated_by"]

        def text_preview(value: str, maximum: int) -> str:
            return value if len(value) <= maximum else value[: maximum - 3] + "..."

        def bounded_strings(value: Any, maximum: int = 8) -> list[str]:
            if not isinstance(value, list):
                return []
            return [item for item in value if isinstance(item, str)][:maximum]

        return {
            "research_id": projection["research_id"],
            "id": projection["research_id"],
            "record_sha256": projection["record_sha256"],
            "kind": projection["kind"],
            "status": projection["status"],
            "claim": text_preview(projection["claim"], 768),
            "claim_sha256": sha256_bytes(projection["claim"].encode("utf-8")),
            "content_sha256": sha256_bytes(projection["content"].encode("utf-8")),
            "rationale_sha256": sha256_bytes(
                projection["rationale"].encode("utf-8")
            ),
            "source": text_preview(projection["source"], 256),
            "source_sha256": sha256_bytes(projection["source"].encode("utf-8")),
            "relation": projection["relation"],
            "campaign_id": metadata.get("campaign_id"),
            "dependency_ids": dependencies[:8],
            "dependency_count": len(dependencies),
            "dependency_ids_sha256": sha256_json(dependencies),
            "related_research_count": len(related),
            "related_research_ids_sha256": sha256_json(related),
            "artifact_count": len(artifacts) if isinstance(artifacts, list) else 0,
            "artifact_manifest_sha256": sha256_json(artifacts),
            "obligation_ids": (
                [
                    item["obligation_id"]
                    for item in obligations[:8]
                    if isinstance(item, dict)
                    and isinstance(item.get("obligation_id"), str)
                ]
                if isinstance(obligations, list)
                else []
            ),
            "obligation_count": (
                len(obligations) if isinstance(obligations, list) else 0
            ),
            "obligation_manifest_sha256": sha256_json(obligations),
            "stop_condition_count": len(stops) if isinstance(stops, list) else 0,
            "stop_conditions_sha256": sha256_json(stops),
            "source_dependent": metadata.get("source_dependent", False),
            "suggested_actions": bounded_strings(suggested_actions),
            "suggested_actions_sha256": sha256_json(suggested_actions),
            "tags": bounded_strings(tags),
            "tags_sha256": sha256_json(tags),
            "latest_disposition_id": projection.get("latest_disposition_id"),
            "latest_disposition_note_sha256": (
                sha256_bytes(
                    projection["latest_disposition_note"].encode("utf-8")
                )
                if "latest_disposition_note" in projection
                else None
            ),
            "route_status": projection["route_status"],
            "route_invalidated_by": invalidators[:8],
            "route_invalidator_count": len(invalidators),
            "route_invalidator_ids_sha256": sha256_json(invalidators),
            "decision_profile": projection["decision_profile"],
            "decision_factors": projection["decision_factors"],
            "score_model": projection["score_model"],
            "score_role": projection["score_role"],
            "readiness": projection["readiness"],
            "score": projection["score"],
            "work_key_sha256": projection["work_key_sha256"],
            "workgroup_representative_id": projection[
                "workgroup_representative_id"
            ],
            "workgroup_actionable_representative_id": projection[
                "workgroup_actionable_representative_id"
            ],
            "workgroup_member_count": projection["workgroup_member_count"],
            "workgroup_member_ids_sha256": projection[
                "workgroup_member_ids_sha256"
            ],
            "workgroup_member_role": projection["workgroup_member_role"],
            "work_completion_status": projection["work_completion_status"],
            "work_completion_research_id": projection[
                "work_completion_research_id"
            ],
            "work_completion_member_count": projection[
                "work_completion_member_count"
            ],
            "work_completion_member_ids_sha256": projection[
                "work_completion_member_ids_sha256"
            ],
            "next_action": projection["next_action"],
            "pending_reason": projection["pending_reason"],
            "next_attention": projection["next_attention"],
            "disposition": projection["disposition"],
            "attention_basis_research_ids": projection[
                "attention_basis_research_ids"
            ][:8],
            "attention_basis_round_ids": projection[
                "attention_basis_round_ids"
            ][:8],
            "attention_reason": projection["attention_reason"],
            "plan_round_argv": projection["plan_round_argv"],
            "actionable_research_id": projection[
                "actionable_research_id"
            ],
            "actionable_round_id": projection["actionable_round_id"],
            "actionable_research_ids": projection[
                "actionable_research_ids"
            ][:8],
            "actionable_research_count": projection[
                "actionable_research_count"
            ],
            "actionable_research_ids_sha256": projection[
                "actionable_research_ids_sha256"
            ],
            "actionable_round_ids": projection["actionable_round_ids"][:8],
            "actionable_round_count": projection["actionable_round_count"],
            "actionable_round_ids_sha256": projection[
                "actionable_round_ids_sha256"
            ],
            "actionable_claim": text_preview(
                projection["actionable_claim"], 512
            ),
            "actionable_claim_sha256": projection[
                "actionable_claim_sha256"
            ],
            "actionable_kind": projection["actionable_kind"],
            "created_at": projection["created_at"],
        }

    @staticmethod
    def _frontier_work_key(record: dict[str, Any]) -> str:
        """Hash one exact executable Research objective, not its provenance.

        The key deliberately excludes ids, timestamps, actors, and explicitly
        non-executable provenance metadata.  Related Research remains exact
        input: current task cards expose its dossier and artifacts and use its
        ancestry for supervision.  Task-bound worker and supervisor Research
        stays singleton-keyed: those records are evidence products, not
        duplicate Main roots.  No fuzzy text normalization or persisted cache
        participates in this projection.
        """

        metadata = record["metadata"]
        task_result_fields = sorted(
            set(metadata).intersection(_FRONTIER_TASK_RESULT_METADATA_FIELDS)
        )
        # Worker products and supervisor tasks are evidence, not duplicate Main
        # roots.  Other present and future metadata is exact work semantics by
        # default, so a schema extension cannot silently disable workgrouping.
        if task_result_fields:
            return sha256_json(
                {
                    "bound_research_id": record["research_id"],
                    "task_result_fields": task_result_fields,
                }
            )
        work_metadata = {
            key: metadata[key]
            for key in sorted(metadata)
            if key not in _FRONTIER_NONWORK_PROVENANCE_FIELDS
        }
        if "artifacts" in work_metadata:
            artifacts = work_metadata["artifacts"]
            if not isinstance(artifacts, list) or any(
                not isinstance(item, dict)
                or not {"path", "sha256", "role"}.issubset(item)
                for item in artifacts
            ):
                return sha256_json(
                    {
                        "bound_research_id": record["research_id"],
                        "malformed_fields": ["artifacts"],
                    }
                )
            work_metadata["artifacts"] = sorted(
                [
                    {
                        "path": item["path"],
                        "sha256": item["sha256"],
                        "role": item["role"],
                    }
                    for item in artifacts
                ],
                key=lambda item: (
                    item["path"],
                    item["sha256"],
                    item["role"],
                ),
            )
        if "obligations" in work_metadata:
            work_metadata["obligations"] = sorted(
                normalize_obligations(work_metadata["obligations"]),
                key=lambda item: item["obligation_id"],
            )
        return sha256_json(
            {
                "kind": record["kind"],
                "claim": record["claim"],
                "content": record["content"],
                "rationale": record["rationale"],
                "dependencies": record["dependencies"],
                "source": record["source"],
                "relation": record["relation"],
                "related_research_ids": sorted(
                    record["related_research_ids"]
                ),
                "metadata": work_metadata,
            }
        )

    def _frontier_structural_state(
        self,
        records: list[dict[str, Any]],
    ) -> tuple[
        dict[str, dict[str, Any]],
        dict[str, dict[str, Any]],
        dict[str, list[str]],
        dict[str, list[str]],
        dict[str, str],
    ]:
        """Build one exact command-local workgroup projection."""

        bases: dict[str, dict[str, Any]] = {}
        dispositions: dict[str, dict[str, Any]] = {}
        for record in records:
            if record["kind"] != "disposition":
                bases[record["research_id"]] = record
                continue
            target_id = record["metadata"].get("target_research_id")
            if not isinstance(target_id, str):
                continue
            previous = dispositions.get(target_id)
            if previous is None or (
                record["created_at"], record["research_id"]
            ) > (previous["created_at"], previous["research_id"]):
                dispositions[target_id] = record
        route_staleness = self._route_staleness(bases)
        workgroups: dict[str, list[str]] = {}
        work_keys: dict[str, str] = {}
        for research_id, record in bases.items():
            work_key = self._frontier_work_key(record)
            work_keys[research_id] = work_key
            workgroups.setdefault(work_key, []).append(research_id)
        for members in workgroups.values():
            members.sort(
                key=lambda item: (bases[item]["created_at"], item)
            )
        return bases, dispositions, route_staleness, workgroups, work_keys

    def _frontier_structural_state_for_inspection(
        self,
        records: list[dict[str, Any]],
        inspection: RoundInspectionContext,
    ) -> tuple[
        dict[str, dict[str, Any]],
        dict[str, dict[str, Any]],
        dict[str, list[str]],
        dict[str, list[str]],
        dict[str, str],
    ]:
        """Reuse one structural projection inside a single Main command."""

        cached = inspection.frontier_structural_state
        if cached is None:
            cached = self._frontier_structural_state(records)
            inspection.frontier_structural_state = cached
        return cached  # type: ignore[return-value]

    def _frontier_actionable_representatives(
        self,
        *,
        workgroups: dict[str, list[str]],
        bases: dict[str, dict[str, Any]],
        dispositions: dict[str, dict[str, Any]],
        route_staleness: dict[str, list[str]],
        campaign_id: str | None,
        exclude_production_review_only: bool,
    ) -> dict[str, str]:
        """Choose the oldest current member of each exact workgroup."""

        representatives: dict[str, str] = {}
        for work_key, members in workgroups.items():
            for research_id in members:
                record = bases[research_id]
                effective_status = (
                    dispositions.get(research_id, {})
                    .get("metadata", {})
                    .get("disposition_status", record["status"])
                )
                if (
                    research_id in route_staleness
                    or effective_status not in ACTIVE_MEMORY_STATUSES
                    or (
                        campaign_id is not None
                        and record["metadata"].get("campaign_id")
                        != campaign_id
                    )
                    or (
                        exclude_production_review_only
                        and self._production_entry_is_review_only(record)
                    )
                ):
                    continue
                representatives[work_key] = research_id
                break
        return representatives

    @staticmethod
    def _frontier_product_has_complete_obligations(
        *,
        product: dict[str, Any],
    ) -> bool:
        metadata = product.get("metadata", {})
        if not isinstance(metadata, dict):
            return False
        dispositions = metadata.get("obligation_dispositions")
        return (
            isinstance(dispositions, list)
            and bool(dispositions)
            and all(
                isinstance(item, dict)
                and item.get("status") in {"complete", "not_applicable"}
                for item in dispositions
            )
        )

    @classmethod
    def _frontier_completion_product_is_safe(
        cls,
        *,
        product: dict[str, Any],
        dispositions: dict[str, dict[str, Any]],
        route_staleness: dict[str, list[str]],
    ) -> bool:
        """Accept only a current product whose own obligations are complete."""

        metadata = product.get("metadata", {})
        if not isinstance(metadata, dict) or not (
            cls._frontier_product_has_complete_obligations(product=product)
        ):
            return False
        effective_status = product["status"]
        disposition = dispositions.get(product["research_id"])
        if disposition is not None:
            effective_status = disposition["metadata"]["disposition_status"]
        return not (
            product["kind"] in {"counterexample", "obstacle", "dead_end"}
            or effective_status
            in {"challenged", "blocked", "dead_end", "refuted_by_fact"}
            or product["research_id"] in route_staleness
            or metadata.get("attack_learning") is not None
            or bool(metadata.get("route_invalidations", []))
            or metadata.get("worker_outcome")
            in {"counterexample", "dead_end"}
        )

    @classmethod
    def _frontier_repair_continuity_is_exact(
        cls,
        *,
        repair: dict[str, Any],
    ) -> bool:
        """Recognize the existing hash-bound repair objective projection.

        Research replay already validates the complete record.  This small
        command-local predicate keeps the frontier projector honest when it is
        exercised directly: a COW edge must carry one canonical repair spec,
        and the obligations/stop conditions exposed on the Research record
        must be the exact projection of that spec.  Semantic conservation is
        still Main's judgment; this check does not claim to prove it.
        """

        metadata = repair.get("metadata", {})
        if not isinstance(metadata, dict):
            return False
        spec = metadata.get("repair_spec")
        try:
            normalized = cls._normalize_exact_repair_spec(spec)
        except (TypeError, ValueError):
            return False
        return (
            normalized == spec
            and metadata.get("repair_spec_sha256")
            == sha256_json(normalized)
            and metadata.get("obligations") == normalized["obligations"]
            and metadata.get("stop_conditions")
            == normalized["stop_conditions"]
        )

    @classmethod
    def _frontier_cow_terminal_members(
        cls,
        *,
        seed_members: list[str],
        bases: dict[str, dict[str, Any]],
        route_staleness: dict[str, list[str]],
        repair_children: dict[str, tuple[str, ...]] | None = None,
    ) -> dict[str, str | None]:
        """Resolve exact, unique COW terminals for original workgroup members.

        The edge is deliberately narrower than general Research provenance:
        one validated-shape production product, exact exhaustion of its active
        invalidators, and one hash-bound canonical repair declaration.
        Ambiguous branches and cycles remain pending rather than letting an
        older success mask current work.
        """

        if repair_children is None:
            repair_children = cls._frontier_cow_repair_children_index(
                bases=bases,
                route_staleness=route_staleness,
            )

        terminals: dict[str, str | None] = {}
        for seed in seed_members:
            current = seed
            seen: set[str] = set()
            while current in bases and current not in seen:
                seen.add(current)
                children = repair_children.get(current, ())
                if not children:
                    terminals[seed] = current
                    break
                if len(children) != 1:
                    terminals[seed] = None
                    break
                current = children[0]
            else:
                terminals[seed] = None
        return terminals

    @classmethod
    def _frontier_cow_repair_children_index(
        cls,
        *,
        bases: dict[str, dict[str, Any]],
        route_staleness: dict[str, list[str]],
    ) -> dict[str, tuple[str, ...]]:
        """Build the complete exact repair adjacency for one structural view."""

        production_parent: dict[str, str] = {}
        for product_id, product in bases.items():
            metadata = product.get("metadata", {})
            provenance = (
                metadata.get("assignment_provenance")
                if isinstance(metadata, dict)
                else None
            )
            related = product.get("related_research_ids")
            if (
                not isinstance(provenance, dict)
                or provenance.get("adverse_assignment") is not False
                or provenance.get("work_mode") == "refute"
                or not isinstance(related, list)
                or len(related) != 1
                or related[0] not in bases
                or not cls._frontier_product_has_complete_obligations(
                    product=product
                )
            ):
                continue
            production_parent[product_id] = related[0]

        repair_children: dict[str, set[str]] = {}
        for repair_id, repair in bases.items():
            if (
                repair.get("kind") != "repair"
                or repair.get("relation") != "repairs"
                or not cls._frontier_repair_continuity_is_exact(repair=repair)
            ):
                continue
            metadata = repair.get("metadata", {})
            if not isinstance(metadata, dict):
                continue
            product_id = metadata.get("repair_of_research_id")
            trigger_id = metadata.get("trigger_research_id")
            parent_id = production_parent.get(product_id)
            if (
                parent_id is None
                or not isinstance(trigger_id, str)
                or trigger_id not in bases
                or repair.get("source") != f"research:{product_id}"
            ):
                continue
            related = repair.get("related_research_ids")
            if (
                not isinstance(related, list)
                or related != sorted({product_id, trigger_id})
            ):
                continue
            trigger_metadata = bases[trigger_id].get("metadata", {})
            if (
                not isinstance(trigger_metadata, dict)
                or product_id
                not in trigger_metadata.get("route_invalidations", [])
                or route_staleness.get(product_id) != [trigger_id]
            ):
                continue
            parent = bases[parent_id]
            product = bases[product_id]
            parent_metadata = parent.get("metadata", {})
            product_metadata = product.get("metadata", {})
            if not isinstance(parent_metadata, dict) or not isinstance(
                product_metadata, dict
            ):
                continue
            if not (
                parent_metadata.get("campaign_id")
                == product_metadata.get("campaign_id")
                == metadata.get("campaign_id")
                and parent.get("dependencies")
                == product.get("dependencies")
                == repair.get("dependencies")
                and parent.get("created_at", "")
                < product.get("created_at", "")
                < repair.get("created_at", "")
                and bases[trigger_id].get("created_at", "")
                < repair.get("created_at", "")
            ):
                continue
            repair_children.setdefault(parent_id, set()).add(repair_id)

        return {
            parent_id: tuple(sorted(children))
            for parent_id, children in repair_children.items()
        }

    def _frontier_cow_terminal_members_for_inspection(
        self,
        *,
        seed_members: list[str],
        bases: dict[str, dict[str, Any]],
        route_staleness: dict[str, list[str]],
        inspection: RoundInspectionContext,
    ) -> dict[str, str | None]:
        """Reuse one complete COW index throughout a Main frontier command."""

        key = tuple(seed_members)
        cached = inspection.frontier_cow_terminal_members.get(key)
        if cached is not None:
            return cached
        repair_children = inspection.frontier_cow_repair_children
        if repair_children is None:
            repair_children = self._frontier_cow_repair_children_index(
                bases=bases,
                route_staleness=route_staleness,
            )
            inspection.frontier_cow_repair_children = repair_children
        terminals = self._frontier_cow_terminal_members(
            seed_members=seed_members,
            bases=bases,
            route_staleness=route_staleness,
            repair_children=repair_children,
        )
        inspection.frontier_cow_terminal_members[key] = terminals
        return terminals

    def _frontier_group_completion(
        self,
        *,
        workgroups: dict[str, list[str]],
        work_keys: set[str],
        bases: dict[str, dict[str, Any]],
        dispositions: dict[str, dict[str, Any]],
        route_staleness: dict[str, list[str]],
        _inspection_context: RoundInspectionContext,
    ) -> dict[str, tuple[str, str | None, int, str]]:
        """Project closure for exact groups requested by this command."""

        terminal_members = {
            work_key: self._frontier_cow_terminal_members_for_inspection(
                seed_members=workgroups.get(work_key, []),
                bases=bases,
                route_staleness=route_staleness,
                inspection=_inspection_context,
            )
            for work_key in work_keys
        }
        candidate_members = {
            terminal
            for work_key in work_keys
            for terminal in terminal_members[work_key].values()
            if terminal is not None
        }
        completion_statuses = (
            self._validated_completed_research_obligation_statuses(
                candidate_members,
                _inspection_context=_inspection_context,
                _all_bases=bases,
                _latest_dispositions=dispositions,
                _route_staleness=route_staleness,
            )
        )
        projected: dict[str, tuple[str, str | None, int, str]] = {}
        for work_key in sorted(work_keys):
            terminals = terminal_members[work_key]
            completed_members = [
                member
                for member, terminal in terminals.items()
                if (
                    terminal is not None
                    and terminal in completion_statuses
                    and terminal not in route_staleness
                    and dispositions.get(terminal, {})
                    .get("metadata", {})
                    .get(
                        "disposition_status",
                        bases[terminal]["status"],
                    )
                    in (
                        (ACTIVE_MEMORY_STATUSES - {"challenged"})
                        | V5_SAFE_SUPERVISION_DISPOSITIONS
                    )
                )
            ]
            completion_research_id = (
                min(
                    completed_members,
                    key=lambda item: (bases[item]["created_at"], item),
                )
                if completed_members
                else None
            )
            completion_status = (
                "completed_supervision"
                if any(
                    completion_statuses[terminals[item]]
                    == "completed_supervision"
                    for item in completed_members
                )
                else "completed_production" if completed_members else "pending"
            )
            projected[work_key] = (
                completion_status,
                completion_research_id,
                len(completed_members),
                sha256_json(sorted(completed_members)),
            )
        return projected


    def _validated_completed_research_obligation_statuses(
        self,
        candidate_ids: set[str],
        *,
        _inspection_context: RoundInspectionContext,
        _all_bases: dict[str, dict[str, Any]] | None = None,
        _latest_dispositions: dict[str, dict[str, Any]] | None = None,
        _route_staleness: dict[str, list[str]] | None = None,
    ) -> dict[str, str]:
        """Derive safe two-subround closure from exact worker lineage."""

        requested_ids = set(candidate_ids)
        if not requested_ids:
            return {}
        cached_statuses = _inspection_context.frontier_completion_statuses
        candidate_ids = requested_ids.difference(cached_statuses)
        if not candidate_ids:
            return {
                research_id: status
                for research_id in requested_ids
                if (status := cached_statuses[research_id]) is not None
            }
        if not self.store.rounds_dir.is_dir():
            cached_statuses.update(
                {research_id: None for research_id in candidate_ids}
            )
            return {
                research_id: status
                for research_id in requested_ids
                if (status := cached_statuses.get(research_id)) is not None
            }
        if _inspection_context.completion_obligation_rounds is None:
            rounds_by_research: dict[str, list[tuple[str, str]]] = {}
            supervision_rounds_by_source: dict[str, list[str]] = {}
            for round_dir in sorted(self.store.rounds_dir.glob("round-*")):
                manifest_path = round_dir / "round.json"
                if (
                    round_dir.is_symlink()
                    or not round_dir.is_dir()
                    or manifest_path.is_symlink()
                    or not manifest_path.is_file()
                ):
                    continue
                try:
                    preview = self.store._read_json(manifest_path)
                except (OSError, ValueError, json.JSONDecodeError):
                    continue
                cycle = preview.get("research_cycle")
                assignments = preview.get("assignments")
                subround = cycle.get("subround") if isinstance(cycle, dict) else None
                if (
                    subround not in {"production", "supervision"}
                    or not isinstance(assignments, list)
                ):
                    continue
                if subround == "supervision":
                    source_round_id = cycle.get("source_round_id")
                    if (
                        isinstance(source_round_id, str)
                        and source_round_id.startswith("round-")
                    ):
                        supervision_rounds_by_source.setdefault(
                            source_round_id, []
                        ).append(round_dir.name)
                for assignment in assignments:
                    if not isinstance(assignment, dict):
                        continue
                    research_id = assignment.get("research_id")
                    if (
                        not isinstance(research_id, str)
                        or MEMORY_ID_RE.fullmatch(research_id) is None
                        or assignment.get("assignment_role") == "paired_adverse"
                    ):
                        continue
                    rounds_by_research.setdefault(research_id, []).append(
                        (round_dir.name, subround)
                    )
            _inspection_context.completion_obligation_rounds = {
                research_id: sorted(set(rounds))
                for research_id, rounds in rounds_by_research.items()
            }
            _inspection_context.supervision_round_ids_by_production_round = {
                source_round_id: sorted(set(round_ids))
                for source_round_id, round_ids in supervision_rounds_by_source.items()
            }
        if (
            _inspection_context.supervision_round_ids_by_production_round
            is None
        ):
            _inspection_context.supervision_round_ids_by_production_round = {}
        completed: dict[str, str] = {}
        if (
            _all_bases is None
            or _latest_dispositions is None
            or _route_staleness is None
        ):
            all_envelopes = self.research_envelopes(
                _inspection_context=_inspection_context,
            )
            all_bases = {
                item["research_id"]: item
                for item in all_envelopes
                if item["kind"] != "disposition"
            }
            latest_dispositions: dict[str, dict[str, Any]] = {}
            for item in all_envelopes:
                if item["kind"] != "disposition":
                    continue
                target_id = item.get("metadata", {}).get(
                    "target_research_id"
                )
                if not isinstance(target_id, str):
                    continue
                previous = latest_dispositions.get(target_id)
                if previous is None or (
                    item["created_at"], item["research_id"]
                ) > (previous["created_at"], previous["research_id"]):
                    latest_dispositions[target_id] = item
            route_staleness = self._route_staleness(all_bases)
        else:
            all_bases = _all_bases
            latest_dispositions = _latest_dispositions
            route_staleness = _route_staleness

        completion_candidates: dict[str, dict[str, str]] = {}
        product_ids_by_research: dict[str, set[str]] = {}
        incomplete_or_unsafe: set[str] = set()
        round_research_ids: dict[tuple[str, str], set[str]] = {}
        for research_id in candidate_ids:
            for round_binding in (
                _inspection_context.completion_obligation_rounds.get(
                    research_id, []
                )
            ):
                round_research_ids.setdefault(round_binding, set()).add(
                    research_id
                )
        candidate_rounds = sorted(round_research_ids)
        for round_id, subround in candidate_rounds:
            try:
                validated_dir, manifest = self._round_manifest(
                    round_id,
                    _inspection_context=_inspection_context,
                )
            except (KeyError, OSError, ValueError):
                incomplete_or_unsafe.update(
                    round_research_ids[(round_id, subround)]
                )
                continue
            if _inspection_context.round_aborts.get(round_id) is not None:
                continue
            for assignment in manifest["assignments"]:
                research_id = assignment["research_id"]
                if (
                    research_id not in candidate_ids
                    or assignment.get("assignment_role") == "paired_adverse"
                ):
                    continue
                try:
                    product, _receipt = self._research_product_for_assignment(
                        round_dir=validated_dir,
                        manifest=manifest,
                        assignment=assignment,
                        _inspection_context=_inspection_context,
                    )
                except (KeyError, OSError, ValueError):
                    incomplete_or_unsafe.add(research_id)
                    continue
                if product.get("related_research_ids") != [research_id]:
                    incomplete_or_unsafe.add(research_id)
                    continue
                product_id = product["research_id"]
                product_ids_by_research.setdefault(research_id, set()).add(
                    product_id
                )
                if not self._frontier_completion_product_is_safe(
                    product=product,
                    dispositions=latest_dispositions,
                    route_staleness=route_staleness,
                ):
                    incomplete_or_unsafe.add(research_id)
                    continue
                if subround == "supervision":
                    completion_candidates.setdefault(research_id, {})[
                        product_id
                    ] = "completed_supervision"
                    continue
                production_round_id = manifest["round_id"]
                if (
                    production_round_id
                    not in _inspection_context.supervision_manifests_by_production_round
                ):
                    matching_manifests: list[tuple[Path, dict[str, Any]]] = []
                    for supervision_round_id in (
                        _inspection_context.supervision_round_ids_by_production_round.get(
                            production_round_id, []
                        )
                    ):
                        try:
                            supervision_round = self._round_manifest(
                                supervision_round_id,
                                _inspection_context=_inspection_context,
                            )
                        except (KeyError, OSError, ValueError):
                            continue
                        if (
                            _inspection_context.round_aborts.get(
                                supervision_round_id
                            )
                            is None
                        ):
                            matching_manifests.append(supervision_round)
                    _inspection_context.supervision_manifests_by_production_round[
                        production_round_id
                    ] = matching_manifests
                try:
                    supervision_result_ids = (
                        self._required_supervision_results_for_candidate(
                            [product],
                            _inspection_context=_inspection_context,
                        )
                    )
                except (KeyError, OSError, ValueError):
                    incomplete_or_unsafe.add(research_id)
                    continue
                try:
                    supervision_results = [
                        self._inspection_research_record(
                            result_id,
                            _inspection_context,
                        )
                        for result_id in sorted(supervision_result_ids)
                    ]
                except (KeyError, OSError, ValueError):
                    incomplete_or_unsafe.add(research_id)
                    continue
                if supervision_results and all(
                    self._frontier_completion_product_is_safe(
                        product=item,
                        dispositions=latest_dispositions,
                        route_staleness=route_staleness,
                    )
                    for item in supervision_results
                ):
                    completion_candidates.setdefault(research_id, {})[
                        product_id
                    ] = "completed_production"
                else:
                    incomplete_or_unsafe.add(research_id)
        for research_id, product_ids in product_ids_by_research.items():
            if research_id in incomplete_or_unsafe or len(product_ids) != 1:
                continue
            product_id = next(iter(product_ids))
            status = completion_candidates.get(research_id, {}).get(product_id)
            if status is not None:
                completed[research_id] = status
        cached_statuses.update(
            {
                research_id: completed.get(research_id)
                for research_id in candidate_ids
            }
        )
        return {
            research_id: status
            for research_id in requested_ids
            if (status := cached_statuses.get(research_id)) is not None
        }

    def _explicit_research_projections(
        self,
        research_ids: list[str],
        *,
        campaign_id: str | None,
        _inspection_context: RoundInspectionContext,
    ) -> dict[str, dict[str, Any]]:
        """Project exact requested Research without rebuilding the full frontier.

        Explicit Main selection does not need scores for unrelated Research.  It
        does still need the selected records' immutable ancestry, route
        invalidations, and latest dispositions.  Read those exact records and
        scan unrelated ledger bytes only for the two typed event keys that can
        change liveness.  This keeps the safety boundary while avoiding artifact
        and assurance validation for every historical branch.
        """

        requested = set(research_ids)
        lineage: dict[str, dict[str, Any]] = {}
        pending = list(reversed(research_ids))
        while pending:
            research_id = pending.pop()
            if research_id in lineage:
                continue
            record = (
                self._inspection_research_record(
                    research_id,
                    _inspection_context,
                )
                if research_id in requested
                else self._research_record_envelope(research_id)
            )
            lineage[research_id] = record
            pending.extend(
                parent_id
                for parent_id in reversed(record["related_research_ids"])
                if parent_id not in lineage
            )

        lineage_ids = set(lineage)
        route_records = {
            research_id: record
            for research_id, record in lineage.items()
            if record["kind"] != "disposition"
        }
        dispositions: dict[str, list[dict[str, Any]]] = {
            research_id: [] for research_id in requested
        }
        if self.research_entries_dir.exists():
            id_tokens = {
                research_id: research_id.encode("ascii")
                for research_id in lineage_ids
            }
            for path in sorted(self.research_entries_dir.glob("*.json")):
                if path.is_symlink() or not path.is_file():
                    raise ValueError("research ledger contains an unsafe entry")
                raw = path.read_bytes()
                might_dispose = (
                    b'"kind": "disposition"' in raw
                    and any(
                        research_id.encode("ascii") in raw
                        for research_id in requested
                    )
                )
                might_invalidate = (
                    b'"route_invalidations"' in raw
                    and any(token in raw for token in id_tokens.values())
                )
                if not might_dispose and not might_invalidate:
                    continue
                record = (
                    self._inspection_research_record(
                        path.stem,
                        _inspection_context,
                    )
                    if might_dispose
                    else self._research_record_envelope(path.stem)
                )
                if might_dispose and record["kind"] == "disposition":
                    target_id = record.get("metadata", {}).get(
                        "target_research_id"
                    )
                    if target_id in dispositions:
                        dispositions[target_id].append(record)
                if might_invalidate:
                    invalidated = set(
                        record.get("metadata", {}).get(
                            "route_invalidations", []
                        )
                    )
                    if invalidated.intersection(lineage_ids):
                        route_records[record["research_id"]] = record

        route_staleness = self._route_staleness(route_records)
        projections: dict[str, dict[str, Any]] = {}
        for research_id in research_ids:
            record = lineage[research_id]
            if (
                campaign_id is not None
                and record["metadata"].get("campaign_id") != campaign_id
            ):
                continue
            projection = dict(record)
            candidates = dispositions[research_id]
            if candidates:
                latest = max(
                    candidates,
                    key=lambda item: (
                        item["created_at"],
                        item["research_id"],
                    ),
                )
                projection["status"] = latest["metadata"][
                    "disposition_status"
                ]
                projection["latest_disposition_id"] = latest["research_id"]
                projection["latest_disposition_note"] = latest["content"]
            if research_id in route_staleness:
                projection["route_status"] = (
                    "stale_pending_copy_on_write_repair"
                )
                projection["route_invalidated_by"] = route_staleness[
                    research_id
                ]
            else:
                projection["route_status"] = "current"
                projection["route_invalidated_by"] = []
            projection["id"] = research_id
            projections[research_id] = projection
        return projections

    def _work_mode(self, entry: dict[str, Any], index: int) -> str:
        kind = entry["kind"]
        if kind == "repair":
            repair_mode = entry.get("metadata", {}).get("repair_work_mode")
            if repair_mode in WORK_MODES:
                return repair_mode
        if kind in {"counterexample", "obstacle", "challenge"}:
            return "refute"
        if kind == "computation":
            return "compute"
        if kind == "literature":
            return "literature"
        return WORK_MODES[index % len(WORK_MODES)] if kind == "plan" else "prove"

    def _production_entry_is_review_only(
        self,
        entry: dict[str, Any],
    ) -> bool:
        """Keep completed attacks and supervisor tasks out of subround 1."""

        metadata = entry.get("metadata", {})
        return (
            entry.get("kind") in {"challenge", "counterexample", "obstacle"}
            or (
                isinstance(metadata, dict)
                and isinstance(metadata.get("research_supervision"), dict)
            )
            or self._research_is_adverse_assignment(entry)
        )

    @staticmethod
    def _mode_architecture_signature(
        entry: dict[str, Any],
        *,
        work_mode: str,
        adverse_routing_enabled: bool,
        computation_design_only: bool = False,
    ) -> dict[str, Any]:
        """Project every mode-sensitive cross-component effect.

        L2 suggestions are advisory.  They may alter the worker's research
        posture, but they may not silently alter an assurance contract, attach
        an adverse capability, or suppress the later program-math review path.
        Explicit user modes are intentionally outside this equivalence gate.
        """

        obligations = entry["metadata"].get("obligations", [])
        assurance = build_assurance_contract(
            entry=entry,
            obligations=obligations,
            work_mode=work_mode,
            related_artifacts=[],
            computation_design_only=computation_design_only,
        )
        stage_count = assurance["computation_stage_count"]
        semantic = {
            "revision": "chalxius-v5-mode-architecture-signature-1",
            "assurance_contract_without_artifact_roles": assurance,
            "frozen_adverse_task_binding": (
                "available_when_refute_selected"
                if adverse_routing_enabled
                else "absent"
            ),
            "program_math_adverse_review": (
                "suppressed_by_refute_mode"
                if stage_count > 0 and work_mode == "refute"
                else (
                    "eligible_when_routing_enabled"
                    if stage_count > 0
                    else "not_applicable"
                )
            ),
        }
        return {**semantic, "signature_sha256": sha256_json(semantic)}

    def _mode_selection(
        self,
        entry: dict[str, Any],
        *,
        requested_mode: str,
        index: int,
        adverse_routing_enabled: bool | None = None,
        research_cycle: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        if requested_mode != "auto" and requested_mode not in WORK_MODES:
            raise ValueError(f"unsupported work mode: {requested_mode}")
        supplied = entry["metadata"].get("suggested_actions")
        malformed = supplied is not None and (
            not isinstance(supplied, list)
            or any(not isinstance(item, str) for item in supplied)
        )
        suggestions = list(supplied) if isinstance(supplied, list) and not malformed else []
        accepted: list[str] = []
        rejected: list[str] = []
        for suggestion in suggestions:
            if suggestion in WORK_MODES:
                if suggestion not in accepted:
                    accepted.append(suggestion)
            else:
                rejected.append(suggestion)
        default_mode = self._work_mode(entry, index)
        eligible: list[str] = []
        blocked: list[dict[str, str]] = []
        adverse_enabled = (
            self.store.adverse_routes().enabled()
            if adverse_routing_enabled is None
            else adverse_routing_enabled
        )
        if not isinstance(adverse_enabled, bool):
            raise ValueError("adverse-routing freeze state must be boolean")
        default_signature = self._mode_architecture_signature(
            entry,
            work_mode=default_mode,
            adverse_routing_enabled=adverse_enabled,
            computation_design_only=self._computation_design_only(
                entry=entry,
                work_mode=default_mode,
                research_cycle=research_cycle,
            ),
        )
        eligible_signatures: list[dict[str, str]] = []
        for suggestion in accepted:
            reason: str | None = None
            suggestion_signature = self._mode_architecture_signature(
                entry,
                work_mode=suggestion,
                adverse_routing_enabled=adverse_enabled,
                computation_design_only=self._computation_design_only(
                    entry=entry,
                    work_mode=suggestion,
                    research_cycle=research_cycle,
                ),
            )
            if (
                suggestion_signature[
                    "assurance_contract_without_artifact_roles"
                ]
                != default_signature[
                    "assurance_contract_without_artifact_roles"
                ]
            ):
                reason = "would_change_assurance_contract"
            elif (
                suggestion_signature["frozen_adverse_task_binding"]
                != default_signature["frozen_adverse_task_binding"]
            ):
                reason = "would_change_active_adverse_routing_capability"
            elif (
                suggestion_signature["program_math_adverse_review"]
                != default_signature["program_math_adverse_review"]
            ):
                reason = "would_change_program_math_adverse_review"
            if reason is None:
                eligible.append(suggestion)
                eligible_signatures.append(
                    {
                        "mode": suggestion,
                        "signature_sha256": suggestion_signature[
                            "signature_sha256"
                        ],
                    }
                )
            else:
                blocked.append({"mode": suggestion, "reason": reason})
        if requested_mode != "auto":
            selected_mode = requested_mode
            source = "explicit_user_mode"
        elif eligible:
            selected_mode = eligible[0]
            source = "bounded_research_suggestion"
        else:
            selected_mode = default_mode
            source = "research_kind_default"
        semantic = {
            "source": source,
            "requested_mode": requested_mode,
            "fallback_index": index,
            "default_mode": default_mode,
            "adverse_routing_enabled_at_freeze": adverse_enabled,
            "raw_suggestions": suggestions,
            "accepted_suggestions": accepted,
            "eligible_suggestions": eligible,
            "rejected_suggestions": rejected,
            "blocked_suggestions": blocked,
            "malformed_suggestions_ignored": malformed,
            "selected_mode": selected_mode,
            "architecture_equivalence": {
                "revision": "chalxius-v5-mode-equivalence-1",
                "rule": "automatic_suggestion_signature_must_equal_default",
                "default_signature_sha256": default_signature[
                    "signature_sha256"
                ],
                "eligible_suggestion_signatures": eligible_signatures,
            },
            "precedence": "explicit_user_mode_over_suggestion_over_kind_default",
            "effect": (
                "hint_applies_only_when_assurance_and_capability_equivalent"
            ),
        }
        return {**semantic, "selection_sha256": sha256_json(semantic)}

    def _promoted_context_binding(
        self,
        entry: dict[str, Any],
        *,
        require_current_origin: bool = True,
    ) -> tuple[dict[str, Any], dict[str, Any]] | None:
        metadata = entry["metadata"]
        required = {
            "origin_blackboard_node_id",
            "origin_blackboard_snapshot_id",
            "origin_blackboard_node_sha256",
            "blackboard_query_sha256",
            "blackboard_query",
            "promotion_task_sha256",
        }
        present = required.intersection(metadata)
        if not present:
            return None
        if present != required:
            raise ValueError(
                "promoted V5 Research has incomplete Blackboard provenance"
            )
        node_id = _require_nonempty_text(
            metadata["origin_blackboard_node_id"],
            "promoted Blackboard origin node id",
        )
        snapshot_id = _require_nonempty_text(
            metadata["origin_blackboard_snapshot_id"],
            "promoted Blackboard origin snapshot id",
        )
        node_sha256 = _require_nonempty_text(
            metadata["origin_blackboard_node_sha256"],
            "promoted Blackboard origin node hash",
        )
        query_sha256 = _require_nonempty_text(
            metadata["blackboard_query_sha256"],
            "promoted Blackboard query hash",
        )
        promotion_task_sha256 = _require_nonempty_text(
            metadata["promotion_task_sha256"],
            "promoted Blackboard task hash",
        )
        if any(
            SHA256_RE.fullmatch(value) is None
            for value in (node_sha256, query_sha256, promotion_task_sha256)
        ):
            raise ValueError("promoted V5 Research has an invalid provenance hash")
        query_value = metadata["blackboard_query"]
        if not isinstance(query_value, dict):
            raise ValueError("promoted V5 Research lacks its Blackboard query")
        query = json.loads(json.dumps(query_value))
        blackboard = self.store.blackboard()
        blackboard.validate_query(query)
        if sha256_json(query) != query_sha256:
            raise ValueError("promoted V5 Research Blackboard query hash mismatch")
        if node_id not in query["seed_node_ids"]:
            raise ValueError(
                "promoted V5 Research query does not seed its origin node"
            )
        if (
            query["node_budget"] > V5_MAX_CONTEXT_SNAPSHOT_NODES
            or query["edge_budget"] > V5_MAX_CONTEXT_SNAPSHOT_EDGES
        ):
            raise ValueError(
                "promoted V5 Research query exceeds the V5 context snapshot budget"
            )
        origin_manifest = blackboard.snapshot_manifest(snapshot_id)
        if origin_manifest["query_sha256"] != query_sha256:
            raise ValueError(
                "promoted V5 Research query disagrees with its origin snapshot"
            )
        origin_entries = {
            item["node_id"]: item["sha256"]
            for item in origin_manifest["node_entries"]
        }
        if origin_entries.get(node_id) != node_sha256:
            raise ValueError(
                "promoted V5 Research node disagrees with its origin snapshot"
            )
        if require_current_origin:
            current_nodes = blackboard.current_nodes()
            if node_id not in current_nodes:
                raise ValueError("promoted V5 Research origin node is no longer active")
            current_sha256 = sha256_bytes(
                json.dumps(
                    current_nodes[node_id],
                    ensure_ascii=False,
                    separators=(",", ":"),
                    sort_keys=True,
                ).encode("utf-8")
            )
            if current_sha256 != node_sha256:
                raise ValueError("promoted V5 Research origin node hash mismatch")
        lineage = {
            "research_id": entry["research_id"],
            "origin_blackboard_node_id": node_id,
            "origin_blackboard_node_sha256": node_sha256,
            "origin_blackboard_snapshot_id": snapshot_id,
            "blackboard_query_sha256": query_sha256,
            "promotion_task_sha256": promotion_task_sha256,
        }
        return query, lineage

    def _snapshot_for_round(
        self,
        selected: list[dict[str, Any]],
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        blackboard = self.store.blackboard()
        nodes = blackboard.current_nodes()
        spaces = sorted(
            node_id
            for node_id, node in nodes.items()
            if node.get("node_type") == "space"
        )
        if not spaces:
            raise ValueError("V5 round planning requires one Blackboard space")
        promoted = [
            binding
            for entry in selected
            if (binding := self._promoted_context_binding(entry)) is not None
        ]
        if promoted and len(selected) != 1:
            raise ValueError(
                "a promoted Blackboard query must be planned as one exact V5 task; "
                "plan unrelated Research in a separate round"
            )
        if promoted:
            query, lineage = promoted[0]
            source = "promoted_blackboard_query"
            origins = [lineage]
        else:
            query = {
                "seed_node_ids": [spaces[0]],
                "direction": "both",
                "max_hops": 0,
                "edge_type_allowlist": ["*"],
                "node_type_allowlist": ["*"],
                "node_budget": 1,
                "edge_budget": 0,
            }
            source = "default_project_space"
            origins = []
        snapshot = blackboard.snapshot(
            query=query,
            actor="v5-orchestrator",
        )
        semantic = {
            "source": source,
            "query": query,
            "query_sha256": snapshot["query_sha256"],
            "origin_bindings": origins,
            "snapshot_id": snapshot["snapshot_id"],
            "snapshot_sha256": snapshot["snapshot_sha256"],
            "omission_receipt": snapshot["omission_receipt"],
            "budget_contract": {
                "max_nodes": V5_MAX_CONTEXT_SNAPSHOT_NODES,
                "max_edges": V5_MAX_CONTEXT_SNAPSHOT_EDGES,
                "overflow": "fail_before_round_or_explicit_snapshot_omission_receipt",
            },
            "truth_effect": "none",
        }
        return snapshot, {
            **semantic,
            "selection_sha256": sha256_json(semantic),
        }

    def project_background_index(self) -> dict[str, Any] | None:
        return current_background_index(self.store.root)

    @staticmethod
    def _background_snapshot_relpath(round_id: str, source_sha256: str) -> str:
        return (
            f"rounds/{validate_round_id(round_id)}/context/"
            f"project-background-{source_sha256}.md"
        )

    def _freeze_project_background(
        self,
        *,
        round_id: str,
        raw: bytes | None,
        selected_chunk_ids: list[str],
        _materialized_round_dir: Path | None = None,
    ) -> dict[str, Any] | None:
        if raw is None:
            if selected_chunk_ids:
                raise ValueError(
                    "background chunk selection requires PROJECT_BACKGROUND.md"
                )
            return None
        source_sha256 = sha256_bytes(raw)
        snapshot_relpath = self._background_snapshot_relpath(
            round_id, source_sha256
        )
        snapshot_path = (
            _materialized_round_dir
            / "context"
            / Path(snapshot_relpath).name
            if _materialized_round_dir is not None
            else self.store.root / snapshot_relpath
        )
        self.store._write_bytes_once(snapshot_path, raw)
        return build_frozen_background_binding(
            raw=raw,
            snapshot_relpath=snapshot_relpath,
            selected_chunk_ids=selected_chunk_ids,
        )

    def project_background_chunk(
        self,
        *,
        card: dict[str, Any],
        chunk_id: str,
    ) -> dict[str, Any]:
        self.validate_task_card(card)
        if card.get("task_context_revision") != V5_TASK_CONTEXT_REVISION:
            raise ValueError(
                "exact background chunks require a current indexed V5 task card"
            )
        binding = card["mathematical_state"]["project_background"]
        if binding is None:
            raise ValueError("this V5 task card has no project background")
        return background_chunk_from_binding(
            self.store.root,
            binding,
            chunk_id=_require_nonempty_text(chunk_id, "background chunk id"),
        )

    def current_project_background_chunk(self, chunk_id: str) -> dict[str, Any]:
        raw = read_project_background(self.store.root)
        if raw is None:
            raise ValueError("this V5 project has no PROJECT_BACKGROUND.md")
        binding = build_frozen_background_binding(
            raw=raw,
            snapshot_relpath=V5_PROJECT_BACKGROUND_FILENAME,
            selected_chunk_ids=[],
        )
        return background_chunk_from_binding(
            self.store.root,
            binding,
            chunk_id=_require_nonempty_text(chunk_id, "background chunk id"),
        )

    @staticmethod
    def _context_selection_binding(
        *,
        blackboard_selection: dict[str, Any],
        project_background: dict[str, Any] | None,
        mode_selection: dict[str, Any],
    ) -> dict[str, Any]:
        background_selection = (
            {
                "source_sha256": None,
                "index_sha256": None,
                "selection_receipt": {
                    "compiler_role": "v5_main_planner",
                    "policy": "background_absent",
                    "selected_chunk_ids": [],
                    "unselected_chunk_count": 0,
                    "all_unselected_chunks_retrievable": True,
                    "omission_effect": "none",
                    "selection_sha256": sha256_json(
                        {
                            "compiler_role": "v5_main_planner",
                            "policy": "background_absent",
                            "selected_chunk_ids": [],
                            "unselected_chunk_count": 0,
                            "all_unselected_chunks_retrievable": True,
                            "omission_effect": "none",
                        }
                    ),
                },
            }
            if project_background is None
            else {
                "source_sha256": project_background["source_sha256"],
                "index_sha256": project_background["index"]["index_sha256"],
                "selection_receipt": project_background["selection_receipt"],
            }
        )
        semantic = {
            "revision": V5_CONTEXT_SELECTION_REVISION,
            "compiler_role": "v5_main_planner",
            "blackboard": blackboard_selection,
            "background": background_selection,
            "mode": mode_selection,
            "precedence": [
                "machine_validated_authority",
                "source_research_dossier",
                "task_specific_blackboard_snapshot",
                "project_background_index",
            ],
            "host_mathematical_output_rule": (
                "durable_mathematical_findings_must_enter_research_or_worker_return"
            ),
            "truth_effect": "none",
            "admission_effect": "none",
        }
        return {
            **semantic,
            "context_selection_sha256": sha256_json(semantic),
        }

    def _task_card_path(self, round_id: str, assignment_id: str) -> Path:
        return (
            self.store.rounds_dir
            / validate_round_id(round_id)
            / "task-cards"
            / f"{validate_assignment_id(assignment_id)}.json"
        )

    def _terminal_bundle_dir(
        self,
        round_dir: Path,
        assignment_id: str,
    ) -> Path:
        """Return the private, content-addressed terminal bundle location.

        Worker-facing return and artifact paths remain compatible with older
        cards.  A successful current ingest additionally publishes a sealed
        copy below this assignment-owned directory.  The directory is created
        by one atomic rename, so a duplicate finalizer cannot replace a live
        terminal bundle.
        """

        return round_dir / "terminal" / validate_assignment_id(assignment_id)

    def _terminal_seal_path(self, round_dir: Path, assignment_id: str) -> Path:
        return self._terminal_bundle_dir(round_dir, assignment_id) / "seal.json"

    @staticmethod
    def _tree_inventory(path: Path) -> list[tuple[Path, os.stat_result]]:
        """Inventory one regular-file/directory tree without following links."""

        try:
            root_stat = path.lstat()
        except OSError as exc:
            raise ValueError("terminal worker path is missing or unsafe") from exc
        root_device = root_stat.st_dev
        inventory: list[tuple[Path, os.stat_result]] = []

        def inspect(candidate: Path) -> None:
            try:
                current = candidate.lstat()
            except OSError as exc:
                raise ValueError(
                    "terminal worker tree changed during inventory"
                ) from exc
            if stat.S_ISLNK(current.st_mode):
                raise ValueError("terminal worker tree contains a symlink")
            if current.st_dev != root_device:
                raise ValueError("terminal worker tree crosses a device boundary")
            if stat.S_ISREG(current.st_mode):
                if current.st_nlink != 1:
                    raise ValueError(
                        "terminal worker tree contains a multiply linked file"
                    )
            elif not stat.S_ISDIR(current.st_mode):
                raise ValueError("terminal worker tree contains a special entry")
            inventory.append((candidate, current))

        inspect(path)
        if stat.S_ISDIR(root_stat.st_mode):
            try:
                for current_root, directories, files in os.walk(
                    path,
                    topdown=True,
                    followlinks=False,
                ):
                    directories.sort()
                    files.sort()
                    current_path = Path(current_root)
                    for name in [*directories, *files]:
                        inspect(current_path / name)
            except OSError as exc:
                raise ValueError(
                    "terminal worker tree changed during inventory"
                ) from exc
        return inventory

    @staticmethod
    def _apply_readonly_inventory(
        inventory: list[tuple[Path, os.stat_result]],
    ) -> None:
        """Apply chmod only after the complete target inventory is accepted."""

        deduplicated: dict[Path, os.stat_result] = {}
        for path, original in inventory:
            existing = deduplicated.get(path)
            if existing is not None and (
                existing.st_dev != original.st_dev
                or existing.st_ino != original.st_ino
                or stat.S_IFMT(existing.st_mode) != stat.S_IFMT(original.st_mode)
            ):
                raise ValueError("terminal worker tree inventory identity conflicts")
            deduplicated[path] = original

        files = sorted(
            (
                (path, original)
                for path, original in deduplicated.items()
                if stat.S_ISREG(original.st_mode)
            ),
            key=lambda item: str(item[0]),
        )
        directories = sorted(
            (
                (path, original)
                for path, original in deduplicated.items()
                if stat.S_ISDIR(original.st_mode)
            ),
            key=lambda item: (-len(item[0].parts), str(item[0])),
        )
        for path, original in [*files, *directories]:
            try:
                current = path.lstat()
            except OSError as exc:
                raise ValueError(
                    "terminal worker tree changed before permission sealing"
                ) from exc
            if (
                current.st_dev != original.st_dev
                or current.st_ino != original.st_ino
                or stat.S_IFMT(current.st_mode) != stat.S_IFMT(original.st_mode)
                or (
                    stat.S_ISREG(current.st_mode)
                    and current.st_nlink != 1
                )
            ):
                raise ValueError(
                    "terminal worker tree changed before permission sealing"
                )
            os.chmod(
                path,
                stat.S_IMODE(current.st_mode) & ~0o222,
                follow_symlinks=False,
            )

    @classmethod
    def _readonly_paths(cls, paths: list[Path]) -> None:
        inventories: list[tuple[Path, os.stat_result]] = []
        seen: set[Path] = set()
        for path in paths:
            if path in seen:
                continue
            seen.add(path)
            inventories.extend(cls._tree_inventory(path))
        cls._apply_readonly_inventory(inventories)

    @classmethod
    def _readonly_tree(cls, path: Path) -> None:
        """Make one fully inventoried worker tree read-only."""

        cls._readonly_paths([path])

    @classmethod
    def _validate_readonly_tree(cls, path: Path) -> list[tuple[Path, os.stat_result]]:
        inventory = cls._tree_inventory(path)
        # Directories are traversal containers on hosts that normalize
        # directory modes during ordinary writes.  The sealed content
        # authority is the exact regular-file inventory plus identity and
        # hash checks performed by the caller; writable directories do not
        # grant authority to add an unsealed file without changing that
        # inventory.  Keep rejecting every writable sealed regular file.
        if any(
            stat.S_ISREG(item.st_mode) and stat.S_IMODE(item.st_mode) & 0o222
            for _, item in inventory
        ):
            raise ValueError("terminal worker sealed tree became writable")
        return inventory

    def _lexical_contained_path(self, relative: str, label: str) -> Path:
        contained_path(self.store.root, relative, label)
        return self.store.root / Path(relative)

    @staticmethod
    def _read_regular_bytes_once(
        path: Path,
        *,
        label: str,
        containment_root: Path | None = None,
        require_single_link: bool = False,
        retryable_visibility: bool = False,
    ) -> bytes:
        """Read one stable regular-file snapshot through a no-follow descriptor."""
        descriptor = -1
        directory_descriptors: list[int] = []
        transient_errnos = {errno.ENOENT}
        if hasattr(errno, "ESTALE"):
            transient_errnos.add(errno.ESTALE)

        def read_error(message: str, exc: BaseException) -> ValueError:
            if (
                retryable_visibility
                and isinstance(exc, OSError)
                and exc.errno in transient_errnos
            ):
                return _CanonicalSourceNotVisible(
                    f"{label} is not stably visible; retry ingest-return"
                )
            return ValueError(message)

        def changed_error(message: str) -> ValueError:
            if retryable_visibility:
                return _CanonicalSourceNotVisible(
                    f"{label} changed during its snapshot; retry ingest-return"
                )
            return ValueError(message)

        try:
            flags = os.O_RDONLY
            if hasattr(os, "O_CLOEXEC"):
                flags |= os.O_CLOEXEC
            if hasattr(os, "O_NOFOLLOW"):
                flags |= os.O_NOFOLLOW

            if containment_root is not None:
                try:
                    relative = path.relative_to(containment_root)
                except ValueError as exc:
                    raise ValueError(f"{label} escapes its root") from exc
                if (
                    not relative.parts
                    or not hasattr(os, "O_NOFOLLOW")
                ):
                    raise ValueError(
                        f"{label} requires no-follow directory-descriptor support"
                    )
                directory_flags = flags
                if hasattr(os, "O_DIRECTORY"):
                    directory_flags |= os.O_DIRECTORY
                try:
                    root_descriptor = os.open(containment_root, directory_flags)
                except (OSError, TypeError) as exc:
                    raise read_error(
                        f"{label} root is missing or unsafe", exc
                    ) from exc
                directory_descriptors.append(root_descriptor)
                root_stat = os.fstat(root_descriptor)
                if not stat.S_ISDIR(root_stat.st_mode):
                    raise ValueError(f"{label} root is missing or unsafe")
                parent_descriptor = root_descriptor
                for part in relative.parts[:-1]:
                    try:
                        next_descriptor = os.open(
                            part,
                            directory_flags,
                            dir_fd=parent_descriptor,
                        )
                    except (OSError, TypeError) as exc:
                        raise read_error(
                            f"{label} parent is missing or unsafe", exc
                        ) from exc
                    directory_descriptors.append(next_descriptor)
                    component = os.fstat(next_descriptor)
                    if (
                        not stat.S_ISDIR(component.st_mode)
                        or component.st_dev != root_stat.st_dev
                    ):
                        raise ValueError(f"{label} parent is unsafe")
                    parent_descriptor = next_descriptor
                try:
                    descriptor = os.open(
                        relative.parts[-1],
                        flags,
                        dir_fd=parent_descriptor,
                    )
                except (OSError, TypeError) as exc:
                    raise read_error(
                        f"{label} is missing or unsafe", exc
                    ) from exc
                opened = os.fstat(descriptor)
                if opened.st_dev != root_stat.st_dev:
                    raise ValueError(f"{label} crosses a device boundary")
            else:
                try:
                    before = path.lstat()
                except OSError as exc:
                    raise read_error(
                        f"{label} is missing or unsafe", exc
                    ) from exc
                if stat.S_ISLNK(before.st_mode) or not stat.S_ISREG(
                    before.st_mode
                ):
                    raise ValueError(f"{label} is missing or unsafe")
                if require_single_link and before.st_nlink != 1:
                    raise ValueError(f"{label} is multiply linked")
                try:
                    descriptor = os.open(path, flags)
                except OSError as exc:
                    raise read_error(
                        f"{label} is missing or unsafe", exc
                    ) from exc
                opened = os.fstat(descriptor)
                if (
                    opened.st_dev != before.st_dev
                    or opened.st_ino != before.st_ino
                ):
                    raise changed_error(f"{label} changed before snapshot")

            opened = os.fstat(descriptor)
            if (
                not stat.S_ISREG(opened.st_mode)
                or (require_single_link and opened.st_nlink != 1)
            ):
                raise changed_error(f"{label} changed before snapshot")
            chunks: list[bytes] = []
            while True:
                chunk = os.read(descriptor, 1024 * 1024)
                if not chunk:
                    break
                chunks.append(chunk)
            after = os.fstat(descriptor)
            # Byte identity is the authority. FileProvider/APFS may localize
            # unchanged bytes and update mtime/ctime while this descriptor is
            # open; those metadata-only changes must not reject a valid
            # content-addressed capability. Device, inode, type, size, link
            # count, and the caller's final SHA-256 still fail closed.
            if (
                after.st_dev != opened.st_dev
                or after.st_ino != opened.st_ino
                or after.st_size != opened.st_size
                or (require_single_link and after.st_nlink != 1)
            ):
                raise changed_error(f"{label} changed while snapshotting")
            return b"".join(chunks)
        finally:
            if descriptor >= 0:
                os.close(descriptor)
            for directory_descriptor in reversed(directory_descriptors):
                os.close(directory_descriptor)

    def _validate_terminal_seal(
        self,
        *,
        round_dir: Path,
        assignment: dict[str, Any],
        required: bool = False,
        staged_bundle_dir: Path | None = None,
    ) -> dict[str, Any] | None:
        """Validate the sealed terminal authority without trusting source paths."""

        published_bundle_dir = self._terminal_bundle_dir(
            round_dir, assignment["assignment_id"]
        )
        bundle_dir = published_bundle_dir
        if staged_bundle_dir is not None:
            expected_prefix = (
                f".terminal-{assignment['assignment_id']}.staging-"
            )
            if (
                staged_bundle_dir.parent != published_bundle_dir.parent
                or not staged_bundle_dir.name.startswith(expected_prefix)
            ):
                raise ValueError("terminal worker staging path is invalid")
            bundle_dir = staged_bundle_dir
        if not os.path.lexists(bundle_dir):
            if required:
                raise ValueError("prospective terminal worker seal is missing")
            return None
        seal_path = bundle_dir / "seal.json"
        if not os.path.lexists(seal_path):
            raise ValueError("terminal worker seal is missing")
        inventory = self._tree_inventory(bundle_dir)
        authority_inventory = [
            (path, item)
            for path, item in inventory
            if not (
                stat.S_ISREG(item.st_mode)
                and path.relative_to(bundle_dir).as_posix()
                in V5_TERMINAL_NONAUTHORITY_METADATA_RELPATHS
            )
        ]
        if any(
            stat.S_ISREG(item.st_mode) and stat.S_IMODE(item.st_mode) & 0o222
            for _, item in authority_inventory
        ):
            raise ValueError("terminal worker sealed tree became writable")
        raw_seal = self._read_regular_bytes_once(
            seal_path,
            label="terminal worker seal",
            containment_root=bundle_dir,
            require_single_link=True,
        )
        try:
            seal = json.loads(raw_seal.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise ValueError("terminal worker seal is not valid UTF-8 JSON") from exc
        required = {
            "schema_version",
            "policy_revision",
            "terminal_seal_revision",
            "project_id",
            "round_id",
            "assignment_id",
            "task_card_sha256",
            "worker_context_id",
            "host_task_scope_id",
            "writer_lease_id",
            "source_return_relpath",
            "source_return_sha256",
            "sealed_return_relpath",
            "sealed_return_sha256",
            "artifacts",
            "sealed_at",
            "seal_sha256",
        }
        if set(seal) != required:
            raise ValueError("terminal worker seal fields are not exact")
        if (
            seal["schema_version"] != 1
            or seal["policy_revision"] != V5_POLICY_REVISION
            or seal["terminal_seal_revision"] != V5_TERMINAL_SEAL_REVISION
            or assignment.get("terminal_seal_revision")
            != V5_TERMINAL_SEAL_REVISION
            or seal["project_id"] != self.store.project_id()
            or seal["round_id"] != round_dir.name
            or seal["assignment_id"] != assignment["assignment_id"]
            or seal["task_card_sha256"] != assignment["task_card_sha256"]
            or seal["worker_context_id"] != assignment["worker_context_id"]
            or seal["host_task_scope_id"] != assignment["host_task_scope_id"]
        ):
            raise ValueError("terminal worker seal binding is invalid")
        self._validate_writer_lease_id(
            seal["writer_lease_id"],
            round_id=round_dir.name,
            assignment_id=assignment["assignment_id"],
            task_card_sha256=assignment["task_card_sha256"],
            worker_context_id=assignment["worker_context_id"],
            host_task_scope_id=assignment["host_task_scope_id"],
        )
        if seal["writer_lease_id"] != assignment.get("writer_lease_id"):
            raise ValueError("terminal worker seal writer lease drifted")
        for field_name in (
            "source_return_sha256",
            "sealed_return_sha256",
        ):
            if SHA256_RE.fullmatch(seal[field_name]) is None:
                raise ValueError(f"terminal worker seal {field_name} is invalid")
        _parse_utc_timestamp(seal["sealed_at"], label="terminal worker seal sealed_at")
        semantic = {key: value for key, value in seal.items() if key != "seal_sha256"}
        if seal["seal_sha256"] != sha256_json(semantic):
            raise ValueError("terminal worker seal hash mismatch")
        if seal["source_return_relpath"] != assignment["return_relpath"]:
            raise ValueError("terminal worker source return binding drifted")
        contained_path(
            self.store.root,
            seal["source_return_relpath"],
            "terminal worker source return path",
        )
        sealed_return = contained_path(
            self.store.root,
            seal["sealed_return_relpath"],
            "terminal worker sealed return path",
        )
        expected_published_return = published_bundle_dir / "return.json"
        if sealed_return != expected_published_return.resolve():
            raise ValueError("terminal worker sealed return path is invalid")
        expected_return = bundle_dir / "return.json"
        sealed_return_bytes = self._read_regular_bytes_once(
            expected_return,
            label="terminal worker sealed return",
            containment_root=bundle_dir,
            require_single_link=True,
        )
        if (
            seal["sealed_return_sha256"] != seal["source_return_sha256"]
            or sha256_bytes(sealed_return_bytes) != seal["sealed_return_sha256"]
        ):
            raise ValueError("terminal worker sealed return drifted")
        artifacts = seal["artifacts"]
        if not isinstance(artifacts, list):
            raise ValueError("terminal worker seal artifacts must be a list")
        expected_files = {"seal.json", "return.json"}
        seen_source_paths: set[str] = set()
        seen_sealed_paths: set[str] = set()
        for index, item in enumerate(artifacts):
            if not isinstance(item, dict) or set(item) not in (
                {"source_path", "sealed_path", "sha256"},
                {"source_path", "sealed_path", "sha256", "role"},
            ):
                raise ValueError("terminal worker seal artifact fields are not exact")
            for key in ("source_path", "sealed_path"):
                if not isinstance(item[key], str):
                    raise ValueError("terminal worker seal artifact path is invalid")
            if "role" in item and (
                not isinstance(item["role"], str) or not item["role"].strip()
            ):
                raise ValueError("terminal worker seal artifact role is invalid")
            if SHA256_RE.fullmatch(item["sha256"]) is None:
                raise ValueError("terminal worker seal artifact SHA-256 is invalid")
            if item["source_path"] in seen_source_paths:
                raise ValueError("terminal worker seal duplicates a source artifact")
            if item["sealed_path"] in seen_sealed_paths:
                raise ValueError("terminal worker seal duplicates a sealed artifact")
            seen_source_paths.add(item["source_path"])
            seen_sealed_paths.add(item["sealed_path"])
            contained_path(
                self.store.root,
                item["source_path"],
                "terminal worker source artifact path",
            )
            sealed = contained_path(
                self.store.root,
                item["sealed_path"],
                "terminal worker sealed artifact path",
            )
            expected_name = f"{index:04d}-{Path(item['source_path']).name}"
            expected_published_artifact = (
                published_bundle_dir / "artifacts" / expected_name
            )
            if sealed != expected_published_artifact.resolve():
                raise ValueError("terminal worker sealed artifact path is invalid")
            expected_artifact = bundle_dir / "artifacts" / expected_name
            sealed_bytes = self._read_regular_bytes_once(
                expected_artifact,
                label="terminal worker sealed artifact",
                containment_root=bundle_dir,
                require_single_link=True,
            )
            if sha256_bytes(sealed_bytes) != item["sha256"]:
                raise ValueError("terminal worker sealed artifact drifted")
            expected_files.add(f"artifacts/{expected_name}")
        actual_files = {
            path.relative_to(bundle_dir).as_posix()
            for path, item in authority_inventory
            if stat.S_ISREG(item.st_mode)
        }
        actual_directories = {
            path.relative_to(bundle_dir).as_posix() or "."
            for path, item in inventory
            if stat.S_ISDIR(item.st_mode)
        }
        if actual_files != expected_files or actual_directories != {".", "artifacts"}:
            raise ValueError("terminal worker sealed tree file set drifted")
        return seal

    def _prepare_terminal_seal(
        self,
        *,
        round_dir: Path,
        assignment: dict[str, Any],
        snapshot: TerminalIngestSnapshot,
    ) -> dict[str, Any]:
        """Publish one immutable return/artifact bundle under the ingest lock."""

        source_artifact_paths = [
            item.source_relpath for item in snapshot.artifacts
        ]
        if len(source_artifact_paths) != len(set(source_artifact_paths)):
            raise ValueError("terminal ingest duplicates a source artifact")

        existing = self._validate_terminal_seal(
            round_dir=round_dir,
            assignment=assignment,
        )
        if existing is not None:
            expected_artifacts = [
                {
                    "source_path": item.source_relpath,
                    "sha256": item.sha256,
                    **({"role": item.role} if item.role is not None else {}),
                }
                for item in snapshot.artifacts
            ]
            existing_artifacts = [
                {
                    "source_path": item["source_path"],
                    "sha256": item["sha256"],
                    **({"role": item["role"]} if "role" in item else {}),
                }
                for item in existing["artifacts"]
            ]
            if (
                existing["source_return_sha256"] != snapshot.return_sha256
                or existing_artifacts != expected_artifacts
            ):
                raise ValueError(
                    "terminal ingest conflict: sealed bytes differ from this finalization"
                )
            return existing
        assignment_id = assignment["assignment_id"]
        bundle_dir = self._terminal_bundle_dir(round_dir, assignment_id)
        if os.path.lexists(bundle_dir):
            raise ValueError("terminal worker bundle already exists without a valid seal")
        bundle_dir.parent.mkdir(parents=True, exist_ok=True)
        staging = bundle_dir.parent / (
            f".terminal-{assignment_id}.staging-"
            f"{sha256_json([assignment_id, snapshot.return_sha256, time.time_ns()])[:16]}"
        )
        staging.mkdir(parents=True, exist_ok=False)
        try:
            staged_artifacts = staging / "artifacts"
            staged_artifacts.mkdir()
            sealed_return = staging / "return.json"
            self.store._write_bytes_once(sealed_return, snapshot.return_bytes)
            sealed_bindings: list[dict[str, str]] = []
            for index, item in enumerate(snapshot.artifacts):
                destination = (
                    staged_artifacts
                    / f"{index:04d}-{Path(item.source_relpath).name}"
                )
                self.store._write_bytes_once(destination, item.raw)
                binding = {
                    "source_path": item.source_relpath,
                    "sealed_path": str(
                        (bundle_dir / "artifacts" / destination.name)
                        .relative_to(self.store.root)
                    ),
                    "sha256": item.sha256,
                }
                if item.role is not None:
                    binding["role"] = item.role
                sealed_bindings.append(binding)
            sealed_return_relpath = str(
                (bundle_dir / "return.json").relative_to(self.store.root)
            )
            semantic = {
                "schema_version": 1,
                "policy_revision": V5_POLICY_REVISION,
                "terminal_seal_revision": V5_TERMINAL_SEAL_REVISION,
                "project_id": self.store.project_id(),
                "round_id": round_dir.name,
                "assignment_id": assignment_id,
                "task_card_sha256": assignment["task_card_sha256"],
                "worker_context_id": assignment["worker_context_id"],
                "host_task_scope_id": assignment["host_task_scope_id"],
                "writer_lease_id": assignment["writer_lease_id"],
                "source_return_relpath": assignment["return_relpath"],
                "source_return_sha256": snapshot.return_sha256,
                "sealed_return_relpath": sealed_return_relpath,
                "sealed_return_sha256": snapshot.return_sha256,
                "artifacts": sealed_bindings,
                "sealed_at": _utc_now(),
            }
            seal = {**semantic, "seal_sha256": sha256_json(semantic)}
            self.store._write_json_once(staging / "seal.json", seal)
            self._readonly_tree(staging)
            validated = self._validate_terminal_seal(
                round_dir=round_dir,
                assignment=assignment,
                required=True,
                staged_bundle_dir=staging,
            )
            assert validated is not None
            # This rename is the publication boundary and the final fallible
            # operation.  The destination becomes visible only after the
            # complete staged tree is already read-only and fully validated.
            os.replace(staging, bundle_dir)
            return validated
        except Exception:
            if os.path.lexists(staging):
                for current_root, directories, _ in os.walk(
                    staging, topdown=False, followlinks=False
                ):
                    for name in directories:
                        directory = Path(current_root) / name
                        if not directory.is_symlink():
                            os.chmod(
                                directory,
                                stat.S_IMODE(directory.lstat().st_mode) | 0o700,
                                follow_symlinks=False,
                            )
                    current = Path(current_root)
                    if not current.is_symlink():
                        os.chmod(
                            current,
                            stat.S_IMODE(current.lstat().st_mode) | 0o700,
                            follow_symlinks=False,
                        )
                shutil.rmtree(staging)
            raise

    def _terminal_source_diagnostics(
        self,
        *,
        assignment: dict[str, Any],
        seal: dict[str, Any],
    ) -> list[str]:
        """Report source drift without making mutable worker paths authoritative."""

        diagnostics: set[str] = set()

        def inspect_file(relative: str, digest: str, label: str) -> None:
            try:
                path = self._lexical_contained_path(relative, label)
                item = path.lstat()
                if (
                    stat.S_ISLNK(item.st_mode)
                    or not stat.S_ISREG(item.st_mode)
                    or item.st_nlink != 1
                ):
                    diagnostics.add(f"{label}:unsafe")
                    return
                raw = self._read_regular_bytes_once(
                    path,
                    label=label,
                    containment_root=self.store.root,
                    require_single_link=True,
                )
                if sha256_bytes(raw) != digest:
                    diagnostics.add(f"{label}:bytes_drifted")
            except (OSError, ValueError):
                diagnostics.add(f"{label}:missing_or_unstable")

        inspect_file(
            seal["source_return_relpath"],
            seal["source_return_sha256"],
            "source_return",
        )
        for index, item in enumerate(seal["artifacts"]):
            inspect_file(
                item["source_path"],
                item["sha256"],
                f"source_artifact_{index}",
            )
        for field_name, label in (
            ("artifact_dir_relpath", "source_artifact_root"),
            ("work_dir_relpath", "source_work_root"),
        ):
            relative = assignment.get(field_name)
            if not isinstance(relative, str):
                continue
            try:
                path = self._lexical_contained_path(relative, label)
                item = path.lstat()
                if not stat.S_ISDIR(item.st_mode) or stat.S_ISLNK(item.st_mode):
                    diagnostics.add(f"{label}:unsafe")
            except (OSError, ValueError):
                diagnostics.add(f"{label}:missing_or_unstable")
        return sorted(diagnostics)

    def _terminalized_root(self, round_dir: Path) -> Path:
        """Return the nontruth worker-terminalization projection root.

        This root is intentionally a sibling of ``terminal/<assignment>``.
        The terminal seal keeps its exact file-set contract, while this
        separate marker/detached tree records the operational copy-on-write
        transition.  Nothing below this root is a Research or graph authority.
        """

        return round_dir / "terminalized"

    def _terminalized_marker_path(
        self,
        round_dir: Path,
        assignment_id: str,
    ) -> Path:
        return (
            self._terminalized_root(round_dir)
            / f"{validate_assignment_id(assignment_id)}.json"
        )

    def _terminalized_detached_paths(
        self,
        round_dir: Path,
        assignment: dict[str, Any],
    ) -> dict[str, Path]:
        """Derive deterministic detached worker paths for COW retries.

        The writer lease suffix makes a stale path from a different assignment
        impossible to silently reuse.  A deterministic name (rather than a
        timestamp) lets a retry recover after a process dies between the
        atomic detach and canonical replacement.
        """

        assignment_id = validate_assignment_id(assignment["assignment_id"])
        lease = assignment.get("writer_lease_id")
        if (
            not isinstance(lease, str)
            or not lease.startswith("writer-lease-")
            or SHA256_RE.fullmatch(lease.removeprefix("writer-lease-")) is None
        ):
            raise ValueError("terminalized worker lease is invalid")
        suffix = lease.removeprefix("writer-lease-")[:16]
        base = self._terminalized_root(round_dir) / "detached" / assignment_id
        return {
            "return": base / f"return-{suffix}.json",
            "artifacts": base / f"artifacts-{suffix}",
            "work": base / f"work-{suffix}",
        }

    @staticmethod
    def _terminalized_semantic(
        *,
        project_id: str,
        round_id: str,
        assignment: dict[str, Any],
        seal: dict[str, Any],
        detached_paths: dict[str, Path],
        project_root: Path,
    ) -> dict[str, Any]:
        """Build the exact nontruth lease-marker semantic payload."""

        source_paths = {
            "return": assignment["return_relpath"],
            "artifacts": assignment["artifact_dir_relpath"],
            "work": assignment["work_dir_relpath"],
        }
        detached = {
            key: value.relative_to(project_root).as_posix()
            for key, value in detached_paths.items()
        }
        return {
            "schema_version": 1,
            "policy_revision": V5_POLICY_REVISION,
            "terminalized_lease_revision": V5_TERMINALIZED_LEASE_REVISION,
            "project_id": project_id,
            "round_id": round_id,
            "assignment_id": assignment["assignment_id"],
            "writer_lease_id": assignment["writer_lease_id"],
            "terminal_seal_sha256": seal["seal_sha256"],
            "source_paths": source_paths,
            "detached_paths": detached,
            # PHX is advisory only; these fields make that boundary explicit
            # in the marker itself and are not consumed by Research admission.
            "truth_effect": "none",
            "project_effect": "none",
        }

    def _validate_terminalized_canonical_paths(
        self,
        *,
        assignment: dict[str, Any],
        seal: dict[str, Any],
    ) -> None:
        """Check the COW successor paths without trusting them as authority."""

        return_path = self._lexical_contained_path(
            assignment["return_relpath"],
            "terminalized canonical return",
        )
        try:
            return_stat = return_path.lstat()
        except OSError as exc:
            raise ValueError("terminalized canonical return is missing") from exc
        if (
            stat.S_ISLNK(return_stat.st_mode)
            or not stat.S_ISREG(return_stat.st_mode)
            or return_stat.st_nlink != 1
            or stat.S_IMODE(return_stat.st_mode) & 0o222
        ):
            raise ValueError("terminalized canonical return is writable or unsafe")
        return_bytes = self._read_regular_bytes_once(
            return_path,
            label="terminalized canonical return",
            containment_root=self.store.root,
            require_single_link=True,
        )
        if sha256_bytes(return_bytes) != seal["source_return_sha256"]:
            raise ValueError("terminalized canonical return bytes drifted")

        artifact_root = self._lexical_contained_path(
            assignment["artifact_dir_relpath"],
            "terminalized canonical artifact root",
        )
        try:
            artifact_root_stat = artifact_root.lstat()
        except OSError as exc:
            raise ValueError("terminalized canonical artifact root is missing") from exc
        if stat.S_ISLNK(artifact_root_stat.st_mode) or not stat.S_ISDIR(
            artifact_root_stat.st_mode
        ):
            raise ValueError("terminalized canonical artifact root is unsafe")
        artifact_inventory = self._validate_readonly_tree(artifact_root)
        expected_artifacts: dict[str, dict[str, Any]] = {}
        artifact_base = Path(assignment["artifact_dir_relpath"])
        for item in seal["artifacts"]:
            source = Path(item["source_path"])
            try:
                relative = source.relative_to(artifact_base).as_posix()
            except ValueError as exc:
                raise ValueError(
                    "terminalized source artifact escaped its assignment root"
                ) from exc
            expected_artifacts[relative] = item
        actual_artifacts = {
            path.relative_to(artifact_root).as_posix()
            for path, item in artifact_inventory
            if stat.S_ISREG(item.st_mode)
        }
        if actual_artifacts != set(expected_artifacts):
            raise ValueError("terminalized canonical artifact file set drifted")
        for relative, item in expected_artifacts.items():
            path = artifact_root / relative
            raw = self._read_regular_bytes_once(
                path,
                label="terminalized canonical artifact",
                containment_root=artifact_root,
                require_single_link=True,
            )
            if sha256_bytes(raw) != item["sha256"]:
                raise ValueError("terminalized canonical artifact bytes drifted")

        work_root = self._lexical_contained_path(
            assignment["work_dir_relpath"],
            "terminalized canonical work root",
        )
        try:
            work_stat = work_root.lstat()
        except OSError as exc:
            raise ValueError("terminalized canonical work root is missing") from exc
        if stat.S_ISLNK(work_stat.st_mode) or not stat.S_ISDIR(work_stat.st_mode):
            raise ValueError("terminalized canonical work root is unsafe")
        work_inventory = self._validate_readonly_tree(work_root)
        # The COW successor deliberately has no mutable draft bytes.  The
        # detached tree remains available as nontruth recovery evidence.
        if any(stat.S_ISREG(item.st_mode) for _, item in work_inventory):
            raise ValueError("terminalized canonical work root is not empty")

    def _validate_terminalized_lease_marker(
        self,
        *,
        round_dir: Path,
        assignment: dict[str, Any],
        seal: dict[str, Any],
        required: bool = False,
    ) -> dict[str, Any] | None:
        """Validate an optional nontruth terminalized lease marker.

        Absence is accepted for pre-COW cards and already-installed rounds.
        If present, the marker is checked strongly enough to make lifecycle
        recovery deterministic, but it never becomes a Research/Candidate/Fact
        gate (PHX-005 owner-boundary rule).
        """

        marker_path = self._terminalized_marker_path(
            round_dir, assignment["assignment_id"]
        )
        if not os.path.lexists(marker_path):
            if required:
                raise ValueError("terminalized worker lease marker is missing")
            return None
        if marker_path.is_symlink() or not marker_path.is_file():
            raise ValueError("terminalized worker lease marker is unsafe")
        marker_stat = marker_path.lstat()
        if marker_stat.st_nlink != 1 or stat.S_IMODE(marker_stat.st_mode) & 0o222:
            raise ValueError("terminalized worker lease marker is writable or unsafe")
        raw = self._read_regular_bytes_once(
            marker_path,
            label="terminalized worker lease marker",
            containment_root=self.store.root,
            require_single_link=True,
        )
        try:
            marker = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise ValueError("terminalized worker lease marker is not valid JSON") from exc
        required_fields = {
            "schema_version",
            "policy_revision",
            "terminalized_lease_revision",
            "project_id",
            "round_id",
            "assignment_id",
            "writer_lease_id",
            "terminal_seal_sha256",
            "source_paths",
            "detached_paths",
            "truth_effect",
            "project_effect",
            "marker_sha256",
        }
        if not isinstance(marker, dict) or set(marker) != required_fields:
            raise ValueError("terminalized worker lease marker fields are not exact")
        semantic = {
            key: value for key, value in marker.items() if key != "marker_sha256"
        }
        if marker["marker_sha256"] != sha256_json(semantic):
            raise ValueError("terminalized worker lease marker hash mismatch")
        if (
            marker["schema_version"] != 1
            or marker["policy_revision"] != V5_POLICY_REVISION
            or marker["terminalized_lease_revision"]
            != V5_TERMINALIZED_LEASE_REVISION
            or marker["project_id"] != self.store.project_id()
            or marker["round_id"] != round_dir.name
            or marker["assignment_id"] != assignment["assignment_id"]
            or marker["writer_lease_id"] != assignment.get("writer_lease_id")
            or marker["terminal_seal_sha256"] != seal.get("seal_sha256")
            or marker["truth_effect"] != "none"
            or marker["project_effect"] != "none"
        ):
            raise ValueError("terminalized worker lease marker binding is invalid")
        source_paths = marker["source_paths"]
        expected_sources = {
            "return": assignment["return_relpath"],
            "artifacts": assignment["artifact_dir_relpath"],
            "work": assignment["work_dir_relpath"],
        }
        if source_paths != expected_sources:
            raise ValueError("terminalized worker source paths drifted")
        detached_paths = marker["detached_paths"]
        expected_detached = {
            key: value.relative_to(self.store.root).as_posix()
            for key, value in self._terminalized_detached_paths(
                round_dir, assignment
            ).items()
        }
        if detached_paths != expected_detached:
            raise ValueError("terminalized worker detached paths drifted")
        for key, relative in detached_paths.items():
            detached = self._lexical_contained_path(
                relative,
                f"terminalized detached {key} path",
            )
            if not os.path.lexists(detached):
                # A crash can happen before a source path exists (for example,
                # an old card with no return draft).  The terminal bundle is
                # still the recovery authority, so absence is diagnostic.
                continue
            if key == "return":
                item = detached.lstat()
                if (
                    stat.S_ISLNK(item.st_mode)
                    or not stat.S_ISREG(item.st_mode)
                    or item.st_nlink != 1
                    or stat.S_IMODE(item.st_mode) & 0o222
                ):
                    raise ValueError("terminalized detached return is unsafe")
            else:
                self._validate_readonly_tree(detached)
        self._validate_terminalized_canonical_paths(
            assignment=assignment,
            seal=seal,
        )
        return marker

    @classmethod
    def _terminalized_make_writable_for_cleanup(cls, path: Path) -> None:
        """Temporarily open a private COW tree for deterministic cleanup."""

        if not os.path.lexists(path):
            return
        inventory = cls._tree_inventory(path)
        for candidate, item in sorted(
            inventory,
            key=lambda pair: (-len(pair[0].parts), str(pair[0])),
        ):
            os.chmod(
                candidate,
                stat.S_IMODE(item.st_mode) | 0o700,
                follow_symlinks=False,
            )

    @classmethod
    def _terminalized_cleanup_path(cls, path: Path) -> None:
        if not os.path.lexists(path):
            return
        cls._terminalized_make_writable_for_cleanup(path)
        if path.is_dir() and not path.is_symlink():
            shutil.rmtree(path)
        else:
            path.unlink()

    @classmethod
    def _terminalized_readonly_path(cls, path: Path) -> None:
        if not os.path.lexists(path):
            raise ValueError("terminalized path disappeared before sealing")
        if path.is_dir() and not path.is_symlink():
            cls._readonly_tree(path)
        else:
            cls._readonly_paths([path])

    def _terminalized_detach_source(
        self,
        *,
        source: Path,
        destination: Path,
        label: str,
    ) -> None:
        """Atomically detach one live worker path into private recovery space."""

        destination.parent.mkdir(parents=True, exist_ok=True)
        if os.path.lexists(destination):
            if os.path.lexists(source):
                # A prior attempt already detached a predecessor.  Preserve a
                # newly recreated path under a conflict suffix instead of
                # replacing the deterministic recovery copy.
                conflict = destination.with_name(
                    destination.name + f".conflict-{time.time_ns()}"
                )
                os.replace(source, conflict)
                self._terminalized_readonly_path(conflict)
            self._terminalized_readonly_path(destination)
            return
        if not os.path.lexists(source):
            # The source may be absent after a crash at the detach boundary;
            # the terminal bundle can still reconstruct its canonical bytes.
            return
        source_item = source.lstat()
        if stat.S_ISLNK(source_item.st_mode):
            raise ValueError(f"{label} is a symlink")
        if not (stat.S_ISREG(source_item.st_mode) or stat.S_ISDIR(source_item.st_mode)):
            raise ValueError(f"{label} is not a regular file or directory")
        os.replace(source, destination)
        self._terminalized_readonly_path(destination)

    def _terminalized_publish_directory(
        self,
        *,
        replacement: Path,
        canonical: Path,
        detached_parent: Path,
        label: str,
    ) -> None:
        """Publish a prepared read-only directory after a COW detach.

        The parent of ``canonical`` is shared by legacy cards.  A stale worker
        can therefore race by recreating that directory between two renames;
        bounded retries detach such a recreation instead of allowing it to
        become the canonical successor.  Persistent races fail closed and are
        recoverable from the terminal bundle on the next ingest attempt.
        """

        for _ in range(4):
            if os.path.lexists(canonical):
                conflict = detached_parent / (
                    f"{canonical.name}.recreated-{time.time_ns()}"
                )
                conflict.parent.mkdir(parents=True, exist_ok=True)
                os.replace(canonical, conflict)
                self._terminalized_readonly_path(conflict)
            try:
                os.replace(replacement, canonical)
                self._terminalized_readonly_path(canonical)
                return
            except FileExistsError:
                # A stale worker recreated the path in the tiny publication
                # window; detach it and retry with the same prepared bytes.
                continue
        raise ValueError(f"{label} could not be published without a stale race")

    def _terminalized_build_artifact_tree(
        self,
        *,
        destination: Path,
        assignment: dict[str, Any],
        snapshot: TerminalIngestSnapshot,
    ) -> None:
        destination.mkdir(parents=True, exist_ok=False)
        artifact_base = Path(assignment["artifact_dir_relpath"])
        for item in snapshot.artifacts:
            source = Path(item.source_relpath)
            try:
                relative = source.relative_to(artifact_base)
            except ValueError as exc:
                raise ValueError(
                    "terminalized artifact source escaped its assignment root"
                ) from exc
            if not relative.parts or any(part in {"", ".", ".."} for part in relative.parts):
                raise ValueError("terminalized artifact relative path is invalid")
            target = destination / relative
            target.parent.mkdir(parents=True, exist_ok=True)
            self.store._write_bytes_once(target, item.raw, mode=0o444)
        self._readonly_tree(destination)

    def _terminalize_worker_paths(
        self,
        *,
        round_dir: Path,
        assignment: dict[str, Any],
        snapshot: TerminalIngestSnapshot,
        seal: dict[str, Any],
    ) -> dict[str, Any]:
        """COW-detach assignment-owned worker paths after terminal sealing.

        The operation is deliberately after ``_prepare_terminal_seal`` *and*
        after the Research/receipt transaction.  It is a best-effort,
        nontruth projection: if any step fails, the already-sealed terminal
        bundle plus Research/receipt remain authoritative and the next ingest
        retries from the bundle; no mathematical content gate is added.
        """

        if assignment.get("terminal_seal_revision") != V5_TERMINAL_SEAL_REVISION:
            raise ValueError("terminalized worker paths require a current terminal seal")
        marker_path = self._terminalized_marker_path(
            round_dir, assignment["assignment_id"]
        )
        if os.path.lexists(marker_path):
            try:
                existing_marker = self._validate_terminalized_lease_marker(
                    round_dir=round_dir,
                    assignment=assignment,
                    seal=seal,
                )
            except (OSError, ValueError):
                # A stale worker may have atomically replaced a canonical
                # source after the marker was written.  The marker is
                # nontruth metadata, so discard that projection and rebuild it
                # from the still-valid terminal seal; do not reopen or weaken
                # any Research/Fact authority check.
                if marker_path.is_symlink() or not marker_path.is_file():
                    raise
                self._terminalized_make_writable_for_cleanup(marker_path)
                marker_path.unlink()
                existing_marker = None
            if existing_marker is not None:
                return existing_marker

        detached_paths = self._terminalized_detached_paths(round_dir, assignment)
        terminalized_root = self._terminalized_root(round_dir)
        terminalized_root.mkdir(parents=True, exist_ok=True)
        detached_parent = detached_paths["return"].parent
        detached_parent.mkdir(parents=True, exist_ok=True)

        canonical_return = self._lexical_contained_path(
            assignment["return_relpath"],
            "terminalized canonical return",
        )
        canonical_artifacts = self._lexical_contained_path(
            assignment["artifact_dir_relpath"],
            "terminalized canonical artifact root",
        )
        canonical_work = self._lexical_contained_path(
            assignment["work_dir_relpath"],
            "terminalized canonical work root",
        )

        # Detach first.  The terminal bytes are already immutable, so a stale
        # process holding an open descriptor can only mutate this detached,
        # non-authoritative inode after the rename.
        self._terminalized_detach_source(
            source=canonical_return,
            destination=detached_paths["return"],
            label="terminalized canonical return",
        )
        self._terminalized_detach_source(
            source=canonical_artifacts,
            destination=detached_paths["artifacts"],
            label="terminalized canonical artifact root",
        )
        self._terminalized_detach_source(
            source=canonical_work,
            destination=detached_paths["work"],
            label="terminalized canonical work root",
        )

        # Rebuild the canonical return from the sealed snapshot, not from any
        # worker-owned inode that may have been changed during handoff.
        canonical_return.parent.mkdir(parents=True, exist_ok=True)
        replacement_return = canonical_return.parent / (
            f".{canonical_return.name}.terminalizing-"
            f"{assignment['writer_lease_id'].removeprefix('writer-lease-')[:16]}"
        )
        self._terminalized_cleanup_path(replacement_return)
        self.store._write_bytes_atomic(
            replacement_return,
            snapshot.return_bytes,
            mode=0o444,
        )
        os.replace(replacement_return, canonical_return)
        self._terminalized_readonly_path(canonical_return)

        # Rebuild the artifact root from the exact declared snapshot.  Any
        # undeclared worker files stay only in the detached nontruth tree.
        replacement_artifacts = canonical_artifacts.parent / (
            f".{canonical_artifacts.name}.terminalizing-"
            f"{assignment['writer_lease_id'].removeprefix('writer-lease-')[:16]}"
        )
        self._terminalized_cleanup_path(replacement_artifacts)
        self._terminalized_build_artifact_tree(
            destination=replacement_artifacts,
            assignment=assignment,
            snapshot=snapshot,
        )
        self._terminalized_publish_directory(
            replacement=replacement_artifacts,
            canonical=canonical_artifacts,
            detached_parent=detached_parent,
            label="terminalized canonical artifact root",
        )

        # Work is a draft-only capability.  Preserve the old tree privately,
        # then expose an empty read-only successor so a stale worker cannot
        # recreate an unsealed draft through the assignment path.
        replacement_work = canonical_work.parent / (
            f".{canonical_work.name}.terminalizing-"
            f"{assignment['writer_lease_id'].removeprefix('writer-lease-')[:16]}"
        )
        self._terminalized_cleanup_path(replacement_work)
        replacement_work.mkdir(parents=True, exist_ok=False)
        self._readonly_tree(replacement_work)
        self._terminalized_publish_directory(
            replacement=replacement_work,
            canonical=canonical_work,
            detached_parent=detached_parent,
            label="terminalized canonical work root",
        )

        # Publish the marker last.  A crash before this write is recoverable:
        # the next ingest sees the terminal seal and reconstructs the marker
        # after validating the canonical successors.
        semantic = self._terminalized_semantic(
            project_id=self.store.project_id(),
            round_id=round_dir.name,
            assignment=assignment,
            seal=seal,
            detached_paths=detached_paths,
            project_root=self.store.root,
        )
        marker = {**semantic, "marker_sha256": sha256_json(semantic)}
        marker_path = self._terminalized_marker_path(
            round_dir, assignment["assignment_id"]
        )
        self.store._write_json_once(marker_path, marker)
        self._terminalized_readonly_path(marker_path)
        self._validate_terminalized_lease_marker(
            round_dir=round_dir,
            assignment=assignment,
            seal=seal,
            required=True,
        )
        return marker

    @staticmethod
    def _runtime_binding() -> dict[str, Any]:
        skill_root = Path(__file__).resolve().parents[2]
        return runtime_binding_from_root(skill_root)

    @staticmethod
    def _task_card_skill_version_at_least(
        card: dict[str, Any],
        minimum: tuple[int, int, int],
    ) -> bool:
        """Gate prospective contracts without rewriting historical returns."""

        runtime_binding = card.get("runtime_binding")
        if not isinstance(runtime_binding, dict):
            return False
        skill_version = runtime_binding.get("skill_version")
        if not isinstance(skill_version, str):
            return False
        match = re.fullmatch(r"(\d+)\.(\d+)\.(\d+)", skill_version.strip())
        if match is None:
            return False
        return tuple(int(part) for part in match.groups()) >= minimum

    @staticmethod
    def _validate_bound_runtime_binding(
        value: Any,
        *,
        historical_runtime: bool = False,
    ) -> dict[str, Any]:
        normalized = validate_runtime_binding(value)
        # Runtime identity is provenance, never a capability token.  The
        # agent operates on graph bytes and workflow semantics; it does not
        # need a historical archive or an exact installed tree to read a card,
        # continue a Research successor, or inspect a live round.  A future
        # runtime may still record a richer binding, but unsupported/relocated
        # runtime metadata cannot block the MathGraph owner operations.
        return normalized

    def _project_background_binding(
        self,
    ) -> dict[str, Any] | None:
        """Read the one summary by default, but never generate it implicitly."""

        path = self.store.root / V5_PROJECT_BACKGROUND_FILENAME
        if path.is_symlink():
            raise ValueError("PROJECT_BACKGROUND.md may not be a symlink")
        if not path.exists():
            return None
        if not path.is_file():
            raise ValueError(
                "PROJECT_BACKGROUND.md must be a regular file; summary "
                "generation is never automatic"
            )
        raw = path.read_bytes()
        if len(raw) > V5_MAX_PROJECT_BACKGROUND_BYTES:
            raise ValueError("PROJECT_BACKGROUND.md exceeds the 256 KiB task-card limit")
        try:
            body = raw.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError("PROJECT_BACKGROUND.md must be UTF-8") from exc
        if not body.strip():
            raise ValueError("PROJECT_BACKGROUND.md must have a nonempty body")
        return {
            "read_policy": "default_if_present",
            "relpath": V5_PROJECT_BACKGROUND_FILENAME,
            "sha256": sha256_bytes(raw),
            "body": body,
            "truth_effect": "nontruth_background_only",
            "load_bearing_rule": "return_to_exact_cited_source",
        }

    def _source_research_dossier(
        self,
        record: dict[str, Any],
    ) -> dict[str, Any]:
        """Project the complete immutable source Research record into a task card."""

        dossier = {
            key: record[key] for key in V5_SOURCE_RESEARCH_DOSSIER_FIELDS
        }
        encoded = json.dumps(
            dossier,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
        if len(encoded) > V5_MAX_SOURCE_RESEARCH_DOSSIER_BYTES:
            raise ValueError(
                "source Research dossier exceeds the 256 KiB task-card limit"
            )
        return dossier

    def _inspection_research_record(
        self,
        research_id: str,
        context: RoundInspectionContext | None,
    ) -> dict[str, Any]:
        context = self._bind_inspection_context(context)
        if context is None:
            return self._research_record(research_id)
        cached = context.research_records.get(research_id)
        if cached is None:
            cached = self._research_record(
                research_id,
                _inspection_context=context,
            )
            context.research_records[research_id] = cached
        return cached

    def _inspection_paper_continuation_scope(
        self,
        record: dict[str, Any],
        context: RoundInspectionContext | None,
    ) -> dict[str, Any] | None:
        context = self._bind_inspection_context(context)
        if context is None:
            return self.paper_continuation().scope_for_research(record)
        research_id = record["research_id"]
        if research_id not in context.paper_continuation_scopes:
            context.paper_continuation_scopes[research_id] = (
                self.paper_continuation(
                    _inspection_context=context
                ).scope_for_research(
                    record,
                    _plan_cache=context.paper_continuation_plans,
                )
            )
        return context.paper_continuation_scopes[research_id]

    def _active_fact_premise_bindings(
        self,
        fact_ids: list[str] | set[str],
        *,
        _inspection_context: RoundInspectionContext | None = None,
        _allow_inactive: bool = False,
    ) -> dict[str, dict[str, Any]]:
        """Validate exactly the admitted Fact nodes consumed by one operation.

        A Fact is already the result of Candidate, verifier, Certification, and
        Gateway ownership.  An ordinary Research read therefore validates its
        immutable local Release/marker/Decision/event/interface/Fact binding
        and revocation visibility.  It does not replay unrelated admissions or
        the Research history that preceded those already-admitted graph nodes.
        """

        inspection = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert inspection is not None
        requested = sorted(
            dict.fromkeys(validate_fact_id(fact_id) for fact_id in fact_ids)
        )
        missing = [
            fact_id
            for fact_id in requested
            if fact_id not in inspection.direct_active_fact_bindings
        ]
        if not missing:
            return {
                fact_id: inspection.direct_active_fact_bindings[fact_id]
                for fact_id in requested
                if fact_id in inspection.direct_active_fact_bindings
            }

        events = self.store._read_jsonl(self.store.verification_log)
        events_by_fact: dict[str, list[dict[str, Any]]] = {
            fact_id: [] for fact_id in missing
        }
        for event in events:
            fact_id = event.get("fact_id") if isinstance(event, dict) else None
            if fact_id in events_by_fact:
                events_by_fact[fact_id].append(event)

        event_fields = {
            "evidence_version",
            "event",
            "event_id",
            "fact_id",
            "release_id",
            "release_sha256",
            "decision_id",
            "decision_sha256",
            "capsule_sha256",
            "acceptance_id",
            "gateway",
            "reviewer",
            "fact_sha256",
            "claim_relation",
            "timestamp",
        }
        selected_events: dict[str, dict[str, Any]] = {}
        release_ids: set[str] = set()
        for fact_id in missing:
            matches = events_by_fact[fact_id]
            if len(matches) != 1:
                raise ValueError(
                    f"active Fact premise {fact_id} must have exactly one "
                    "acceptance event"
                )
            event = matches[0]
            if set(event) != event_fields or (
                event.get("evidence_version") != V5_WORKFLOW_EVIDENCE_VERSION
                or event.get("event") != "accepted"
                or event.get("fact_id") != fact_id
            ):
                raise ValueError(
                    f"active Fact premise {fact_id} acceptance event is invalid"
                )
            release_id = event.get("release_id")
            if not isinstance(release_id, str):
                raise ValueError(
                    f"active Fact premise {fact_id} lacks a Release binding"
                )
            release_ids.add(release_id)
            selected_events[fact_id] = event

        facts, paths = self._provisional_active_fact_snapshot(
            release_ids=release_ids,
            _inspection_context=inspection,
        )
        for fact_id in missing:
            event = selected_events[fact_id]
            release_id = event["release_id"]
            fact = facts.get(fact_id)
            path = paths.get(fact_id)
            if fact is None or path is None:
                if _allow_inactive:
                    continue
                raise ValueError(
                    f"research dependency is not an active V5 Fact: {fact_id}"
                )

            marker_path = self._admission_dir(release_id) / "ACCEPTED.json"
            marker = self.store._read_json(marker_path)
            decision = self.decision(
                marker["decision_id"],
                validate_bindings=False,
                _inspection_context=inspection,
            )
            release = self.store._read_json(self._release_path(release_id))
            expected_event_id = sha256_json(
                [
                    "accepted-v5",
                    fact_id,
                    release_id,
                    marker["decision_id"],
                    marker["acceptance_id"],
                ]
            )
            expected_event_values = {
                "event_id": expected_event_id,
                "release_sha256": marker["release_sha256"],
                "decision_id": marker["decision_id"],
                "decision_sha256": marker["decision_sha256"],
                "capsule_sha256": marker["capsule_sha256"],
                "acceptance_id": marker["acceptance_id"],
                "gateway": marker["gateway"],
                "reviewer": marker["reviewer"],
                "fact_sha256": marker["fact_sha256"][fact_id],
                "claim_relation": release["claim_relation"],
                "timestamp": marker["accepted_at"],
            }
            if any(
                event.get(key) != expected
                for key, expected in expected_event_values.items()
            ):
                raise ValueError(
                    f"active Fact premise {fact_id} acceptance binding drifted"
                )
            if (
                decision.get("verdict") != "correct"
                or decision.get("release_id") != release_id
                or decision.get("release_sha256") != release["release_sha256"]
                or decision.get("decision_sha256") != marker["decision_sha256"]
                or decision.get("capsule_sha256") != marker["capsule_sha256"]
            ):
                raise ValueError(
                    f"active Fact premise {fact_id} Certification binding drifted"
                )

            interface_path = self.store.interfaces_dir / f"{fact_id}.json"
            if interface_path.is_symlink() or not interface_path.is_file():
                raise ValueError(
                    f"active Fact premise {fact_id} lacks its immutable interface"
                )
            statement_interface = validate_statement_interface(
                self.store._read_json(interface_path),
                active_fact_ids={fact_id},
            )
            fact_sha = sha256_bytes(path.read_bytes())
            if (
                statement_interface["fact_id"] != fact_id
                or statement_interface["stored_fact_sha256"] != fact_sha
                or statement_interface["statement_sha256"]
                != sha256_bytes(fact.statement.encode("utf-8"))
                or statement_interface["acceptance_event_sha256"]
                != event["event_id"]
                or statement_interface["admission_review_id"]
                != marker["decision_sha256"]
            ):
                raise ValueError(
                    f"active Fact premise {fact_id} interface binding drifted"
                )
            inspection.direct_active_fact_bindings[fact_id] = {
                "fact": fact,
                "path": path,
                "statement_interface": statement_interface,
                "release_id": release_id,
            }

        return {
            fact_id: inspection.direct_active_fact_bindings[fact_id]
            for fact_id in requested
            if fact_id in inspection.direct_active_fact_bindings
        }

    def _task_authority_snapshot(
        self,
        record: dict[str, Any],
        *,
        contract_revision: str = V5_TASK_CONTEXT_REVISION,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any]:
        """Bind only task-referenced V5 authority and exact read capabilities.

        PROJECT_BACKGROUND.md remains useful historical context, but it is a
        nontruth document and cannot state the current admission status.  This
        projection is deliberately narrow: ordinary tasks see only their
        explicit Fact references, while an attack receives the exact
        Release/Decision/Admission bundle named in frozen Research metadata.
        """

        _inspection_context = self._bind_inspection_context(
            _inspection_context
        )
        cache_key = (record["research_id"], contract_revision)
        if (
            _inspection_context is not None
            and cache_key in _inspection_context.authority_snapshots
        ):
            return _inspection_context.authority_snapshots[cache_key]

        metadata = record["metadata"]
        related_fact_id = metadata.get("related_fact_id")
        if related_fact_id is not None:
            if not isinstance(related_fact_id, str):
                raise ValueError("Research related_fact_id must be a Fact id or null")
            related_fact_id = validate_fact_id(related_fact_id)

        attack_values = {
            key: metadata.get(key) for key in V5_ATTACK_TARGET_METADATA_FIELDS
        }
        attack_present = {
            key for key, value in attack_values.items() if value is not None
        }
        if attack_present and attack_present != set(V5_ATTACK_TARGET_METADATA_FIELDS):
            raise ValueError(
                "Research attack target must bind both Candidate Release and "
                "Certification Decision ids"
            )
        if attack_present and related_fact_id is None:
            raise ValueError("Research attack target requires related_fact_id")

        referenced_fact_ids = set(record["dependencies"])
        if related_fact_id is not None:
            referenced_fact_ids.add(related_fact_id)
        obligations = metadata.get("obligations", [])
        fact_closure_reconstruction_required = (
            "fact_closure_reconstruction"
            in metadata.get("logic_signals", [])
            and
            isinstance(obligations, list)
            and any(
                isinstance(obligation, dict)
                and isinstance(obligation.get("evidence_types"), list)
                and "fact_closure_reconstruction"
                in obligation["evidence_types"]
                for obligation in obligations
            )
        )

        direct_fact_bindings: dict[str, dict[str, Any]] = {}
        # Empty task authority is a complete, canonical projection.  Derive
        # applicability before opening the active-Fact lineage so a card that
        # references no Fact cannot recursively reconstruct every admission,
        # Candidate Release, and Paper closure merely to prove that it sees
        # nothing.  Ordinary explicit premises consume their exact admitted
        # graph bindings; an attack target or an explicit closure-
        # reconstruction obligation retains the broader authority projection.
        if not referenced_fact_ids:
            active_paths: dict[str, Path] = {}
            revoked_fact_ids: set[str] = set()
        elif not attack_present and not fact_closure_reconstruction_required:
            direct_fact_bindings = self._active_fact_premise_bindings(
                referenced_fact_ids,
                _inspection_context=_inspection_context,
            )
            active_paths = {
                fact_id: binding["path"]
                for fact_id, binding in direct_fact_bindings.items()
            }
            revoked_fact_ids = set()
        elif _inspection_context is None:
            active_paths = self.active_fact_paths()
            revoked_fact_ids = self.revoked_fact_ids()
        else:
            if _inspection_context.active_fact_paths is None:
                _inspection_context.active_fact_paths = self.active_fact_paths(
                    _inspection_context=_inspection_context
                )
            if _inspection_context.revoked_fact_ids is None:
                _inspection_context.revoked_fact_ids = self.revoked_fact_ids(
                    _inspection_context=_inspection_context
                )
            active_paths = _inspection_context.active_fact_paths
            revoked_fact_ids = _inspection_context.revoked_fact_ids

        # A typed closure-reconstruction obligation is an explicit request for
        # the admitted statement interfaces in the dependency closure.  Pay
        # that cost only for this exact evidence type; ordinary and empty
        # authority snapshots retain their bounded direct-reference behavior.
        if fact_closure_reconstruction_required and referenced_fact_ids:
            non_active_root_ids = sorted(
                fact_id
                for fact_id in referenced_fact_ids
                if fact_id not in active_paths
            )
            if non_active_root_ids:
                raise ValueError(
                    "Fact-closure authority root is not active: "
                    + non_active_root_ids[0]
                )
            selected_closure_ids: set[str] = set()
            pending_closure_ids = sorted(referenced_fact_ids)
            while pending_closure_ids:
                fact_id = pending_closure_ids.pop()
                if fact_id in selected_closure_ids:
                    continue
                path = active_paths.get(fact_id)
                if path is None:
                    raise ValueError(
                        "Fact-closure authority contains a non-active predecessor: "
                        + fact_id
                    )
                fact = parse_fact_markdown(path.read_text(encoding="utf-8"))
                if fact.fact_id != fact_id:
                    raise ValueError(
                        "Fact-closure authority path/id mismatch: " + fact_id
                    )
                selected_closure_ids.add(fact_id)
                for predecessor_id in fact.predecessors:
                    if predecessor_id not in active_paths:
                        raise ValueError(
                            "Fact-closure authority predecessor is not active: "
                            + predecessor_id
                        )
                    if predecessor_id not in selected_closure_ids:
                        pending_closure_ids.append(predecessor_id)
            referenced_fact_ids.update(selected_closure_ids)

        capabilities: list[dict[str, str]] = []

        def add_capability(path: Path, *, role: str) -> None:
            resolved_root = self.store.root.resolve()
            if path.is_symlink() or not path.is_file():
                raise ValueError(f"V5 authority capability is missing or unsafe: {role}")
            resolved = path.resolve()
            if not resolved.is_relative_to(resolved_root):
                raise ValueError(f"V5 authority capability escapes project root: {role}")
            capabilities.append(
                {
                    "path": resolved.relative_to(resolved_root).as_posix(),
                    "sha256": sha256_bytes(resolved.read_bytes()),
                    "role": role,
                }
            )

        attack_target: dict[str, Any] | None = None
        candidate_sha256: dict[str, str] = {}
        if attack_present:
            release_id = attack_values["attack_target_release_id"]
            decision_id = attack_values["attack_target_decision_id"]
            if not isinstance(release_id, str) or not isinstance(decision_id, str):
                raise ValueError("Research attack target ids must be strings")
            release = self.release(
                release_id,
                _inspection_context=_inspection_context,
            )
            decision = self.decision(
                decision_id,
                _inspection_context=_inspection_context,
            )
            if (
                decision["release_id"] != release_id
                or decision["release_sha256"] != release["release_sha256"]
            ):
                raise ValueError(
                    "Research attack target Release/Decision binding is inconsistent"
                )
            if related_fact_id not in release["fact_ids"]:
                raise ValueError(
                    "Research related_fact_id is outside the attack target Release"
                )

            referenced_fact_ids.update(release["fact_ids"])
            candidate_sha256 = {
                item["fact_id"]: item["fact_sha256"]
                for item in release["candidates"]
            }
            release_path = self._release_path(release_id)
            decision_path = self._decision_path(decision_id)
            add_capability(
                release_path,
                role="attack_target_candidate_release",
            )
            add_capability(
                decision_path,
                role="attack_target_certification_decision",
            )
            for artifact in release["artifacts"]:
                add_capability(
                    contained_path(
                        self.store.root,
                        artifact["sealed_relpath"],
                        "attack target sealed artifact",
                    ),
                    role=f"attack_target_artifact:{artifact['role']}",
                )

            marker_path = self._admission_dir(release_id) / "ACCEPTED.json"
            marker: dict[str, Any] | None = None
            admitted_paths: dict[str, Path] = {}
            if marker_path.is_symlink() or marker_path.exists():
                marker, admitted_paths = self._validated_admission(
                    release_id,
                    _inspection_context=_inspection_context,
                )
                if marker["decision_id"] != decision_id:
                    raise ValueError(
                        "Research attack target admission used a different Decision"
                    )
                add_capability(
                    marker_path,
                    role="attack_target_admission_marker",
                )
                for fact_id in release["fact_ids"]:
                    add_capability(
                        admitted_paths[fact_id],
                        role=f"attack_target_admitted_fact:{fact_id}",
                    )

            if marker is None:
                admission_status = "not_admitted"
                acceptance_id = None
            elif related_fact_id in revoked_fact_ids:
                admission_status = "revoked"
                acceptance_id = marker["acceptance_id"]
            elif related_fact_id in active_paths:
                admission_status = "active"
                acceptance_id = marker["acceptance_id"]
            else:
                raise ValueError(
                    "Research attack target admission is not visible as active or revoked"
                )
            attack_target = {
                "release_id": release_id,
                "release_sha256": release["release_sha256"],
                "release_record_sha256": release["record_sha256"],
                "decision_id": decision_id,
                "decision_sha256": decision["decision_sha256"],
                "decision_record_sha256": decision["record_sha256"],
                "decision_verdict": decision["verdict"],
                "target_fact_id": related_fact_id,
                "release_fact_ids": list(release["fact_ids"]),
                "admission_status": admission_status,
                "acceptance_id": acceptance_id,
            }

        fact_bindings: list[dict[str, Any]] = []
        for fact_id in sorted(referenced_fact_ids):
            if fact_id in active_paths:
                path = active_paths[fact_id]
                fact_sha = sha256_bytes(path.read_bytes())
                status = "active"
                direct_binding = direct_fact_bindings.get(fact_id)
                statement_interface = (
                    direct_binding["statement_interface"]
                    if direct_binding is not None
                    else self.store.statement_interface(
                        fact_id,
                        materialize=False,
                        _inspection_context=_inspection_context,
                    )
                )
            elif fact_id in revoked_fact_ids:
                fact_sha = candidate_sha256.get(fact_id)
                status = "revoked"
                statement_interface = None
            elif fact_id in candidate_sha256:
                fact_sha = candidate_sha256[fact_id]
                status = "candidate_only"
                statement_interface = None
            else:
                fact_sha = None
                status = "missing"
                statement_interface = None
            fact_bindings.append(
                {
                    "fact_id": fact_id,
                    "status": status,
                    "fact_sha256": fact_sha,
                    "statement_interface": statement_interface,
                }
            )

        capabilities.sort(
            key=lambda item: (item["role"], item["path"], item["sha256"])
        )
        semantic = {
            "schema_version": 1,
            "contract_revision": contract_revision,
            "research_id": record["research_id"],
            "scope": "task_referenced_v5_authority_only",
            "precedence_rule": (
                "machine_validated_v5_authority_overrides_nontruth_"
                "project_background_status_claims"
            ),
            "background_truth_effect": "none",
            "fact_bindings": fact_bindings,
            "attack_target": attack_target,
            "capabilities": capabilities,
        }
        snapshot = {**semantic, "snapshot_sha256": sha256_json(semantic)}
        if _inspection_context is not None:
            _inspection_context.authority_snapshots[cache_key] = snapshot
        return snapshot

    def _validate_context_selection(
        self,
        *,
        card: dict[str, Any],
        source_research: dict[str, Any],
        historical_runtime: bool = False,
        _materialized_round_dir: Path | None = None,
    ) -> dict[str, Any]:
        selection = card.get("context_selection")
        required = {
            "revision",
            "compiler_role",
            "blackboard",
            "background",
            "mode",
            "precedence",
            "host_mathematical_output_rule",
            "truth_effect",
            "admission_effect",
            "context_selection_sha256",
        }
        if not isinstance(selection, dict) or set(selection) != required:
            raise ValueError("V5 context-selection fields are not exact")
        selection_semantic = {
            key: value
            for key, value in selection.items()
            if key != "context_selection_sha256"
        }
        if (
            selection["revision"] != V5_CONTEXT_SELECTION_REVISION
            or selection["compiler_role"] != "v5_main_planner"
            or selection["precedence"]
            != [
                "machine_validated_authority",
                "source_research_dossier",
                "task_specific_blackboard_snapshot",
                "project_background_index",
            ]
            or selection["host_mathematical_output_rule"]
            != "durable_mathematical_findings_must_enter_research_or_worker_return"
            or selection["truth_effect"] != "none"
            or selection["admission_effect"] != "none"
            or selection["context_selection_sha256"]
            != sha256_json(selection_semantic)
        ):
            raise ValueError("V5 context-selection contract/hash is invalid")
        blackboard_selection = selection.get("blackboard")
        blackboard_required = {
            "source",
            "query",
            "query_sha256",
            "origin_bindings",
            "snapshot_id",
            "snapshot_sha256",
            "omission_receipt",
            "budget_contract",
            "truth_effect",
            "selection_sha256",
        }
        if (
            not isinstance(blackboard_selection, dict)
            or set(blackboard_selection) != blackboard_required
        ):
            raise ValueError("V5 Blackboard context-selection fields are not exact")
        blackboard_semantic = {
            key: value
            for key, value in blackboard_selection.items()
            if key != "selection_sha256"
        }
        if blackboard_selection["selection_sha256"] != sha256_json(
            blackboard_semantic
        ):
            raise ValueError("V5 Blackboard context-selection hash mismatch")
        if (
            blackboard_selection["snapshot_id"]
            != card["blackboard_view"]["snapshot_id"]
            or blackboard_selection["snapshot_sha256"]
            != card["blackboard_view"]["snapshot_sha256"]
            or blackboard_selection["truth_effect"] != "none"
            or blackboard_selection["budget_contract"]
            != {
                "max_nodes": V5_MAX_CONTEXT_SNAPSHOT_NODES,
                "max_edges": V5_MAX_CONTEXT_SNAPSHOT_EDGES,
                "overflow": (
                    "fail_before_round_or_explicit_snapshot_omission_receipt"
                ),
            }
        ):
            raise ValueError("V5 Blackboard context-selection binding is invalid")
        query = blackboard_selection.get("query")
        if not isinstance(query, dict):
            raise ValueError("V5 Blackboard context-selection query is invalid")
        self.store.blackboard().validate_query(query)
        if (
            blackboard_selection["query_sha256"] != sha256_json(query)
            or query["node_budget"] > V5_MAX_CONTEXT_SNAPSHOT_NODES
            or query["edge_budget"] > V5_MAX_CONTEXT_SNAPSHOT_EDGES
        ):
            raise ValueError("V5 Blackboard context-selection query/hash is invalid")
        snapshot_id = blackboard_selection["snapshot_id"]
        manifest = self.store.blackboard().snapshot_manifest(snapshot_id)
        manifest_path = (
            self.store.blackboard().snapshots_dir / snapshot_id / "manifest.json"
        )
        if (
            sha256_bytes(manifest_path.read_bytes())
            != blackboard_selection["snapshot_sha256"]
            or manifest["query"] != query
            or manifest["query_sha256"] != blackboard_selection["query_sha256"]
            or manifest["omission_receipt"]
            != blackboard_selection["omission_receipt"]
        ):
            raise ValueError("V5 Blackboard context-selection snapshot drifted")
        source = blackboard_selection["source"]
        if source == "promoted_blackboard_query":
            promoted = self._promoted_context_binding(
                source_research,
                require_current_origin=False,
            )
            if promoted is None:
                raise ValueError(
                    "V5 promoted context selection lacks Research provenance"
                )
            expected_query, expected_lineage = promoted
            if (
                query != expected_query
                or blackboard_selection["origin_bindings"]
                != [expected_lineage]
            ):
                raise ValueError("V5 promoted context selection drifted")
        elif source == "default_project_space":
            if blackboard_selection["origin_bindings"] != []:
                raise ValueError("V5 default context selection has promotion lineage")
            snapshot_nodes, _ = self.store.blackboard().snapshot_objects(snapshot_id)
            default_budget = (
                query["max_hops"],
                query["node_budget"],
                query["edge_budget"],
            )
            if (
                len(query["seed_node_ids"]) != 1
                or snapshot_nodes.get(query["seed_node_ids"][0], {}).get("node_type")
                != "space"
                or query["direction"] != "both"
                or query["edge_type_allowlist"] != ["*"]
                or query["node_type_allowlist"] != ["*"]
                or default_budget
                not in {
                    (0, 1, 0),
                    (
                        3,
                        V5_MAX_CONTEXT_SNAPSHOT_NODES,
                        V5_MAX_CONTEXT_SNAPSHOT_EDGES,
                    ),
                }
            ):
                raise ValueError("V5 default context selection query is invalid")
        else:
            raise ValueError("V5 Blackboard context-selection source is unsupported")
        mode_selection = selection.get("mode")
        if not isinstance(mode_selection, dict):
            raise ValueError("V5 mode-selection binding must be an object")
        requested_mode = mode_selection.get("requested_mode")
        fallback_index = mode_selection.get("fallback_index")
        if (
            not isinstance(requested_mode, str)
            or isinstance(fallback_index, bool)
            or not isinstance(fallback_index, int)
            or fallback_index < 0
        ):
            raise ValueError("V5 mode-selection request/index is invalid")
        # A completed/aborted card owns its sealed planning choice.  Re-running
        # a newer assurance selector here would make immutable Research cease
        # to be readable after a software upgrade.  Live cards still recompute
        # the current selector; historical cards are checked by their nested
        # context hash and the task-card semantic hash below.
        expected_mode = (
            mode_selection
            if historical_runtime
            else self._mode_selection(
                source_research,
                requested_mode=requested_mode,
                index=fallback_index,
                adverse_routing_enabled=mode_selection.get(
                    "adverse_routing_enabled_at_freeze"
                ),
                research_cycle=card.get("research_cycle"),
            )
        )
        if (
            (
                "adverse_routing" in card
                and mode_selection.get("adverse_routing_enabled_at_freeze")
                is not True
            )
            or mode_selection != expected_mode
            or card["work_mode"] != expected_mode["selected_mode"]
        ):
            raise ValueError("V5 mode-selection binding drifted")
        background = card["mathematical_state"].get("project_background")
        if background is not None:
            if not isinstance(background, dict):
                raise ValueError(
                    "V5 indexed project-background binding must be an object"
                )
            expected_snapshot_relpath = self._background_snapshot_relpath(
                card["round_id"],
                _require_nonempty_text(
                    background.get("source_sha256"),
                    "indexed project-background source hash",
                ),
            )
            validate_frozen_background_binding(
                self.store.root,
                background,
                expected_snapshot_relpath=expected_snapshot_relpath,
                snapshot_path_override=(
                    _materialized_round_dir
                    / "context"
                    / Path(expected_snapshot_relpath).name
                    if _materialized_round_dir is not None
                    else None
                ),
            )
        expected = self._context_selection_binding(
            blackboard_selection=blackboard_selection,
            project_background=background,
            mode_selection=expected_mode,
        )
        if selection != expected:
            raise ValueError("V5 host context-selection receipt drifted")
        return selection

    def validate_task_card(
        self,
        card: Any,
        *,
        expected_path: Path | None = None,
        historical_runtime: bool = False,
        _runtime_validation_cache: set[tuple[bool, str]] | None = None,
        _inspection_context: RoundInspectionContext | None = None,
        _materialized_round_dir: Path | None = None,
    ) -> dict[str, Any]:
        _inspection_context = self._bind_inspection_context(
            _inspection_context
        )
        if not isinstance(card, dict):
            raise ValueError("V5 task card must be one object")
        required = {
            "schema_version",
            "policy_revision",
            "project_id",
            "round_id",
            "assignment_id",
            "worker_id",
            "research_id",
            "work_mode",
            "requested_claim_relation",
            "source_claim_id",
            "convention_profile_ids",
            "campaign_id",
            "control_plane",
            "mathematical_state",
            "blackboard_view",
            "narrative_plane",
            "obligations",
            "stop_conditions",
            "artifact_capability",
            "return_contract",
            "reasoning_mode_binding",
            "task_card_semantic_sha256",
        }
        if "adverse_routing" in card:
            required.add("adverse_routing")
        if "assurance_contract" in card:
            required.add("assurance_contract")
        if "task_context_revision" in card:
            required.add("task_context_revision")
        if "runtime_binding" in card:
            required.add("runtime_binding")
        if "campaign_scope" in card:
            required.add("campaign_scope")
        if "paper_continuation_scope" in card:
            required.add("paper_continuation_scope")
        if "research_cycle" in card:
            required.add("research_cycle")
        if card.get("task_context_revision") == V5_TASK_CONTEXT_REVISION:
            required.add("context_selection")
        if set(card) != required:
            raise ValueError("V5 task card fields are not exact")
        if (
            card.get("schema_version") != 5
            or card.get("policy_revision") != V5_POLICY_REVISION
            or card.get("project_id") != self.store.project_id()
        ):
            raise ValueError("V5 task card schema/policy/project mismatch")
        if "runtime_binding" in card:
            # Runtime identity is diagnostic provenance only.  Graph work is
            # owned by the task-card hash, Research lineage, dependencies, and
            # workflow stage; it must remain operable after a runtime move or
            # on a host that does not retain an old archive.  Keep the field
            # optional and opaque here so legacy cards remain actionable.
            if card["runtime_binding"] is not None and not isinstance(
                card["runtime_binding"], dict
            ):
                raise ValueError("V5 task-card runtime binding must be an object or null")
        round_id = validate_round_id(
            _require_nonempty_text(card.get("round_id"), "task-card round id")
        )
        assignment_id = validate_assignment_id(
            _require_nonempty_text(
                card.get("assignment_id"), "task-card assignment id"
            )
        )
        validate_memory_id(
            _require_nonempty_text(card.get("research_id"), "task-card research id")
        )
        if card.get("work_mode") not in WORK_MODES:
            raise ValueError("V5 task card work mode is invalid")
        if "research_cycle" in card:
            cycle = self._validate_research_cycle_binding(
                card["research_cycle"]
            )
            if cycle["subround"] == "supervision" and card["work_mode"] != "refute":
                raise ValueError("V5 supervision task cards must use refute mode")
        if card.get("requested_claim_relation") not in CLAIM_RELATIONS:
            raise ValueError("V5 task card claim relation is invalid")
        if not isinstance(card.get("worker_id"), str):
            raise ValueError("V5 task card worker id must be a string")
        if card.get("source_claim_id") is not None and not isinstance(
            card.get("source_claim_id"), str
        ):
            raise ValueError("V5 task card source claim id is invalid")
        convention_ids = _require_string_list(
            card.get("convention_profile_ids"), "task-card convention profile ids"
        )
        for convention_id in convention_ids:
            self.store.claims().show_convention(convention_id)
        if card.get("campaign_id") is not None and not isinstance(
            card.get("campaign_id"), str
        ):
            raise ValueError("V5 task card campaign id is invalid")
        if card.get("campaign_id") is not None:
            if _inspection_context is None:
                self.store.campaigns().status(card["campaign_id"])
            elif card["campaign_id"] not in _inspection_context.campaign_statuses:
                _inspection_context.campaign_statuses[card["campaign_id"]] = (
                    self.store.campaigns().status(card["campaign_id"])
                )
        if "campaign_scope" in card:
            if card.get("campaign_id") is None:
                raise ValueError(
                    "V5 Campaign scope requires an exact task-card campaign id"
                )
            scope = self._validate_campaign_scope_binding(
                card["campaign_scope"],
                round_id=round_id,
                _inspection_context=_inspection_context,
                _materialized_round_dir=_materialized_round_dir,
            )
            if scope["campaign_id"] != card["campaign_id"]:
                raise ValueError("V5 task-card Campaign scope/id mismatch")
        if card.get("source_claim_id") is not None:
            self.store.claims().show_claim(card["source_claim_id"])
        for name in (
            "control_plane",
            "mathematical_state",
            "blackboard_view",
            "narrative_plane",
            "artifact_capability",
            "return_contract",
            "reasoning_mode_binding",
        ):
            if not isinstance(card.get(name), dict):
                raise ValueError(f"V5 task card {name} must be an object")
        if card["control_plane"].get("plane") != "control":
            raise ValueError("V5 control-plane marker is missing")
        if card["mathematical_state"].get("plane") != "mathematical_state":
            raise ValueError("V5 mathematical-state-plane marker is missing")
        if card["narrative_plane"].get("plane") != "narrative":
            raise ValueError("V5 narrative-plane marker is missing")
        if (
            card["mathematical_state"].get("blackboard_snapshot_id")
            != card["blackboard_view"].get("snapshot_id")
            or card["mathematical_state"].get("blackboard_snapshot_sha256")
            != card["blackboard_view"].get("snapshot_sha256")
        ):
            raise ValueError("V5 task card snapshot projections disagree")
        research_context = card["mathematical_state"].get("research_context")
        if not isinstance(research_context, list) or any(
            not isinstance(item, dict) for item in research_context
        ):
            raise ValueError("V5 task card research_context must be object entries")
        context_ids: list[str] = []
        for item in research_context:
            expected_fields = {
                "research_id",
                "record_sha256",
                "kind",
                "status",
                "claim",
                "content",
                "rationale",
                "actor",
            }
            if set(item) != expected_fields:
                raise ValueError("V5 task card research_context fields are not exact")
            related = self._inspection_research_record(
                item["research_id"], _inspection_context
            )
            expected = {key: related[key] for key in expected_fields}
            if item != expected:
                raise ValueError("V5 task card research_context bytes/hash mismatch")
            context_ids.append(item["research_id"])
        source_research = self._inspection_research_record(
            card["research_id"], _inspection_context
        )
        control = card["control_plane"]
        if "assignment_role" in control:
            expected_control_fields = {
                "plane",
                "prompt_relpath",
                "allowed_followups",
                "final_handoff_fields",
                "host_task_scope_id",
                "worker_context_id",
                "assignment_role",
                "independent_adverse_pair",
            }
            if set(control) != expected_control_fields:
                raise ValueError(
                    "current V5 control-plane allocation fields are not exact"
                )
            final_handoff_fields = control.get("final_handoff_fields")
            return_contract = card["return_contract"]
            legacy_handoff = [
                "assignment_id",
                "return_sha256",
                "status",
            ]
            canonical_handoff = ["assignment_id", "status"]
            legacy_hash_contract = (
                "sha256_of_exact_return_bytes_reported_in_final_handoff"
            )
            canonical_hash_contract = (
                "sha256_of_exact_return_bytes_derived_by_canonical_ingestion"
            )
            if (
                final_handoff_fields == legacy_handoff
                and return_contract.get("hash_contract") == legacy_hash_contract
            ) or (
                final_handoff_fields == canonical_handoff
                and return_contract.get("hash_contract") == canonical_hash_contract
            ):
                pass
            else:
                raise ValueError("V5 final-handoff contract drifted")
            host_scope = control.get("host_task_scope_id")
            if (
                not isinstance(host_scope, str)
                or HOST_TASK_SCOPE_ID_RE.fullmatch(host_scope) is None
            ):
                raise ValueError("current V5 task card host scope is invalid")
            worker_context_id = _require_nonempty_text(
                control.get("worker_context_id"), "V5 worker context id"
            )
            assignment_role = control.get("assignment_role")
            if assignment_role not in {"primary", "paired_adverse"}:
                raise ValueError("V5 assignment role is invalid")
            pair_binding = control.get("independent_adverse_pair")
            if pair_binding is None:
                if assignment_role != "primary":
                    raise ValueError(
                        "paired adverse assignment lacks its immutable pair binding"
                    )
                expected_context_id = "hostctx-" + sha256_json(
                    {
                        "namespace": "chalxius-v5-worker-context-1",
                        "round_id": round_id,
                        "assignment_id": assignment_id,
                    }
                )
                if worker_context_id != expected_context_id:
                    raise ValueError("V5 primary worker context id drifted")
            else:
                if not isinstance(pair_binding, dict):
                    raise ValueError("independent adverse pair binding is invalid")
                counterpart = pair_binding.get("counterpart_assignment_id")
                if assignment_role == "primary":
                    primary_assignment_id = assignment_id
                    adverse_assignment_id = counterpart
                    binding_key = "primary_binding"
                else:
                    primary_assignment_id = counterpart
                    adverse_assignment_id = assignment_id
                    binding_key = "adverse_binding"
                handoff = build_paired_proof_philosophy_attack_handoff(
                    research_id=card["research_id"],
                    round_id=round_id,
                    primary_assignment_id=primary_assignment_id,
                    adverse_assignment_id=adverse_assignment_id,
                )
                validate_independent_adverse_pair(
                    handoff["pair"],
                    primary_binding=handoff["primary_binding"],
                    adverse_binding=handoff["adverse_binding"],
                )
                if pair_binding != handoff[binding_key]:
                    raise ValueError("independent adverse pair binding drifted")
                if worker_context_id != pair_binding["worker_context_id"]:
                    raise ValueError("independent adverse worker context drifted")
                if assignment_role == "paired_adverse" and (
                    card["work_mode"] != "refute" or "adverse_routing" not in card
                ):
                    raise ValueError(
                        "paired adverse card must be a rule-bound refute assignment"
                    )
        expected_paper_scope = self._inspection_paper_continuation_scope(
            source_research,
            _inspection_context,
        )
        if card.get("paper_continuation_scope") != expected_paper_scope:
            raise ValueError(
                "V5 task-card Paper continuation scope drifted or was omitted"
            )
        mathematical_state = card["mathematical_state"]
        reference_revision = mathematical_state.get(
            "research_reference_revision"
        )
        if reference_revision is None:
            expected_context_ids = source_research["related_research_ids"]
        elif reference_revision == V5_EXACT_RESEARCH_REFERENCE_REVISION:
            literal_ids = mathematical_state.get(
                "literal_research_reference_ids"
            )
            if (
                not isinstance(literal_ids, list)
                or literal_ids != sorted(set(literal_ids))
                or any(
                    not isinstance(item, str)
                    or MEMORY_ID_RE.fullmatch(item) is None
                    for item in literal_ids
                )
            ):
                raise ValueError(
                    "V5 task-card literal Research references are malformed"
                )
            literal_tokens = set(
                self._literal_research_reference_tokens(source_research)
            )
            explicit_ids = set(source_research["related_research_ids"])
            if any(
                item not in literal_tokens or item in explicit_ids
                for item in literal_ids
            ):
                raise ValueError(
                    "V5 task-card literal Research references drifted from source prose"
                )
            expected_context_ids = sorted(explicit_ids.union(literal_ids))
        else:
            raise ValueError(
                "V5 task-card Research-reference revision is unsupported"
            )
        if context_ids != expected_context_ids:
            raise ValueError(
                "V5 task card research_context does not exactly match its "
                "structured and literal Research references"
            )
        task_context_revision = card.get("task_context_revision")
        if task_context_revision is not None:
            if task_context_revision not in {
                V5_LEGACY_TASK_CONTEXT_REVISION,
                V5_TASK_CONTEXT_REVISION,
            }:
                raise ValueError("V5 task context revision is unsupported")
            dossier = card["mathematical_state"].get(
                "source_research_dossier"
            )
            if dossier != self._source_research_dossier(source_research):
                raise ValueError(
                    "V5 task-card source Research dossier drifted or is incomplete"
                )
            authority_snapshot = card["mathematical_state"].get(
                "authority_snapshot"
            )
            if authority_snapshot != self._task_authority_snapshot(
                source_research,
                contract_revision=task_context_revision,
                _inspection_context=_inspection_context,
            ):
                raise ValueError(
                    "V5 task-card authority snapshot is stale or incomplete"
                )
            if (
                card["narrative_plane"].get("claim") != source_research["claim"]
                or card["narrative_plane"].get("rationale")
                != source_research["rationale"]
            ):
                raise ValueError(
                    "V5 task-card narrative does not match source Research"
                )
            if task_context_revision == V5_TASK_CONTEXT_REVISION:
                self._validate_context_selection(
                    card=card,
                    source_research=source_research,
                    historical_runtime=historical_runtime,
                    _materialized_round_dir=_materialized_round_dir,
                )
        if "assurance_contract" in card:
            contract = validate_assurance_contract(card["assurance_contract"])
            if card["obligations"] != contract["obligations"]:
                raise ValueError(
                    "V5 task-card obligations do not match the frozen assurance contract"
                )
            related_artifacts = card["mathematical_state"].get(
                "related_artifacts"
            )
            if not isinstance(related_artifacts, list) or any(
                not isinstance(item, dict)
                or set(item)
                != {"path", "sha256", "role", "source_research_id"}
                for item in related_artifacts
            ):
                raise ValueError(
                    "V5 task-card related_artifacts must be exact capability objects"
                )
            roles: set[str] = set()
            repair_capability_scope = (
                self._schema_v2_repair_capability_manifest(
                    source_research,
                    _inspection_context=_inspection_context,
                )
                is not None
            )
            for item in related_artifacts:
                validate_memory_id(item["source_research_id"])
                _require_nonempty_text(item["role"], "related artifact role")
                if item["role"] in roles:
                    raise ValueError(
                        "V5 task-card related artifact roles must be unique"
                    )
                roles.add(item["role"])
                if SHA256_RE.fullmatch(item["sha256"]) is None:
                    raise ValueError("V5 task-card related artifact hash is invalid")
                path = self._lexical_contained_path(
                    item["path"], "V5 task-card related artifact"
                )
                if repair_capability_scope:
                    self._repair_capability_bytes(
                        path,
                        item["sha256"],
                        label="V5 task-card related artifact",
                        _inspection_context=_inspection_context,
                    )
                else:
                    self._ordinary_capability_bytes(
                        path,
                        item["sha256"],
                        label="V5 task-card related artifact",
                        _inspection_context=_inspection_context,
                    )
            self._validate_repair_task_capability_closure(
                record=source_research,
                related_artifacts=related_artifacts,
                _inspection_context=_inspection_context,
            )
            if sorted(roles) != contract["related_artifact_roles"]:
                raise ValueError(
                    "V5 task-card related artifact roles disagree with assurance contract"
                )
        if "project_background" not in card["mathematical_state"]:
            raise ValueError("V5 task card project_background binding is missing")
        background = card["mathematical_state"]["project_background"]
        if background is not None:
            if task_context_revision == V5_TASK_CONTEXT_REVISION:
                if not isinstance(background, dict):
                    raise ValueError(
                        "V5 indexed project-background binding must be an object"
                    )
                expected_snapshot_relpath = self._background_snapshot_relpath(
                    round_id,
                    _require_nonempty_text(
                        background.get("source_sha256"),
                        "indexed project-background source hash",
                    ),
                )
                validate_frozen_background_binding(
                    self.store.root,
                    background,
                    expected_snapshot_relpath=expected_snapshot_relpath,
                    snapshot_path_override=(
                        _materialized_round_dir
                        / "context"
                        / Path(expected_snapshot_relpath).name
                        if _materialized_round_dir is not None
                        else None
                    ),
                )
            else:
                expected_fields = {
                    "read_policy",
                    "relpath",
                    "sha256",
                    "body",
                    "truth_effect",
                    "load_bearing_rule",
                }
                if not isinstance(background, dict) or set(background) != expected_fields:
                    raise ValueError("V5 task-card project background fields are not exact")
                if (
                    background["read_policy"] != "default_if_present"
                    or background["relpath"] != V5_PROJECT_BACKGROUND_FILENAME
                    or background["truth_effect"] != "nontruth_background_only"
                    or background["load_bearing_rule"]
                    != "return_to_exact_cited_source"
                    or not isinstance(background["body"], str)
                    or not background["body"].strip()
                    or background["sha256"]
                    != sha256_bytes(background["body"].encode("utf-8"))
                ):
                    raise ValueError("V5 task-card project background binding is invalid")
        if not isinstance(card.get("obligations"), list) or any(
            not isinstance(item, dict) for item in card["obligations"]
        ):
            raise ValueError("V5 task card obligations must be objects")
        if "adverse_routing" in card:
            if (
                _inspection_context is not None
                and _inspection_context.adverse_rules is None
            ):
                routes = self.store.adverse_routes()
                _inspection_context.adverse_rules = {
                    record["rule_id"]: routes._rule_projection(record)
                    for record in routes.rules()
                }
            self.store.adverse_routes().validate_task_card_binding(
                card["adverse_routing"],
                work_mode=card["work_mode"],
                related_artifacts=card["mathematical_state"].get(
                    "related_artifacts", []
                ),
                entry=source_research,
                _stored_rules=(
                    _inspection_context.adverse_rules
                    if _inspection_context is not None
                    else None
                ),
            )
        _require_string_list(card.get("stop_conditions"), "task-card stop conditions")
        semantic = {
            key: value
            for key, value in card.items()
            if key != "task_card_semantic_sha256"
        }
        if card.get("task_card_semantic_sha256") != sha256_json(semantic):
            raise ValueError("V5 task card semantic hash mismatch")
        if expected_path is not None:
            canonical = (
                _materialized_round_dir
                / "task-cards"
                / f"{assignment_id}.json"
                if _materialized_round_dir is not None
                else self._task_card_path(round_id, assignment_id)
            )
            if expected_path.resolve() != canonical.resolve():
                raise ValueError("V5 task card path is noncanonical")
        return card

    def _compact_prompt(
        self,
        *,
        card: dict[str, Any],
        task_card_sha256: str,
    ) -> str:
        adverse_note = ""
        if "adverse_routing" in card:
            adverse_note = (
                "Adverse routing and the worker failure-report contract are frozen in the "
                "task card. Include exact structured `attack_learning` for "
                "a surviving counterexample, or for a productive challenge that forces a "
                "load-bearing hypothesis, scope, definition, source, computation, boundary, "
                "or proof-route repair even when the theorem survives. Otherwise return "
                "`attack_learning=null`. Do not propose a route rule: Main alone compares "
                "failure reports and may synthesize a compact mechanism-level future rule.\n\n"
            )
        pair_note = ""
        pair_binding = card.get("control_plane", {}).get(
            "independent_adverse_pair"
        )
        if pair_binding is not None:
            if pair_binding["role"] == "paired_adverse":
                pair_note = (
                    "This is the independently paired adverse assignment for the exact "
                    "source Research. Use the distinct worker_context_id frozen in the "
                    "card. Do not receive, reuse, summarize, or share the primary worker's "
                    "context. Attack with the frozen adverse_routing rules; the return is "
                    "nontruth Research and the existing Candidate adverse closure remains "
                    "the sole release-review authority.\n\n"
                )
            else:
                pair_note = (
                    "A distinct adverse worker and context are paired with this primary. "
                    "Do not share active context with that worker; both returns enter "
                    "Research independently.\n\n"
                )
        research_cycle_note = ""
        cycle = card.get("research_cycle")
        if cycle is not None:
            source_metadata = card["mathematical_state"][
                "source_research_dossier"
            ]["metadata"]
            if cycle["subround"] == "supervision":
                supervision = source_metadata["research_supervision"]
                research_cycle_note = (
                    "This is Research subround 2, a scoped supervisor assignment. "
                    f"Your exact scope is `{supervision['supervisor_scope']}`. Attack "
                    "the frozen subround-1 return bindings in research_supervision and "
                    "the corresponding related Research/artifacts; do not replace them "
                    "with a free-standing proof attempt. A copy-on-write successor is a "
                    "new complete product: prior defects and repair obligations are "
                    "mandatory but non-exhaustive attack seeds, not a defect allowlist. "
                    "Freshly review the whole exact successor and every conserved claim "
                    "inside this assigned scope, including new, inherited, repair-induced, "
                    "and cross-component defects. PHX constrains architecture, never "
                    "adversarial scrutiny. Admitted Fact dependencies are "
                    "frozen premises, not default attack targets. If exact new evidence "
                    "contradicts one, report that conflict separately for an "
                    "authority-governed reopening; do not casually re-refute the Fact. "
                    "Report a narrow challenge or a "
                    "clean bounded result. Any defect causes copy-on-write repair in a "
                    "later Research cycle; there is no live Blackboard/Pulse repair bus.\n\n"
                )
            elif card["work_mode"] == "refute":
                research_cycle_note = (
                    "This is a subround-1 proposition refutation worker. Attack the "
                    "assigned proposition T under its exact hypotheses H: seek H and "
                    "not-T, a boundary failure, obstruction, hidden assumption, or "
                    "scope defect. You may attack frozen prior-cycle Research in the "
                    "card, but you cannot see or attack mutable same-subround peer "
                    "outputs. A subround-2 supervisor will separately review this return.\n\n"
                )
            elif card["work_mode"] == "compute":
                approved = source_metadata.get("approved_computation_execution")
                if approved is None:
                    research_cycle_note = (
                        "This is subround-1 computation design, not formal execution. "
                        "Return exactly three review artifacts: computation_source "
                        "containing the core executable code, computation_design binding "
                        "the mathematics, inputs, outputs, precision/truncation and boundary "
                        "policy, and computation_dependencies listing exact runtime and "
                        "dependency identities. Do not return computation_output, an "
                        "execution manifest, logs, or formal target results. Program-math "
                        "supervision must disposition these exact hashes before execution.\n\n"
                    )
                else:
                    approved_hashes = {
                        item["role"]: item["sha256"]
                        for item in approved["design_artifacts"]
                    }
                    research_cycle_note = (
                        "This is an approved subround-1 computation execution. Execute only "
                        f"core source SHA-256 `{approved_hashes['computation_source']}` with "
                        "dependency manifest SHA-256 "
                        f"`{approved_hashes['computation_dependencies']}`. The "
                        "returned computation_source and computation_dependencies bytes must "
                        "match those hashes exactly; code replacement fails closed. The actual "
                        "source, logs, manifest and output will receive subround-2 review.\n\n"
                    )
            else:
                research_cycle_note = (
                    "This is Research subround 1. Work from the frozen card; same-subround "
                    "peer outputs are not visible. Your exact return will be eligible for "
                    "a later scoped subround-2 supervisor review.\n\n"
                )
        assurance_note = ""
        if "assurance_contract" in card:
            assurance_contract = card["assurance_contract"]
            if cycle is not None and cycle["subround"] == "supervision":
                assurance_note = (
                    "Scoped supervisor startup contract: "
                    "references/v5_supervisor_worker_bootstrap.md. For this exact "
                    "current supervision card it replaces broad protocol preloading; "
                    "load a broader reference only at one of that contract's explicit "
                    "fail-closed conditional branches. It includes the exact return "
                    "shape, CHX start/close path, preflight, canonical byte-copy, "
                    "validation, and authority boundaries.\n\n"
                )
            elif (
                cycle is None
                and card["work_mode"] == "refute"
                and card["mathematical_state"]["source_research_dossier"][
                    "metadata"
                ].get("independent_adverse_required")
                is True
            ):
                assurance_note = (
                    "Exact Candidate-adverse startup contract: "
                    "references/v5_candidate_adverse_worker_bootstrap.md. "
                    "This refute assignment is not production and must not load the "
                    "production bootstrap. Attack only the one exact canonical "
                    "candidate_fact and its frozen supervision lineage. Use the exact "
                    "worker-return shape, CHX path, preflight, canonical byte-copy, "
                    "validation, and nontruth boundaries in that compact contract.\n\n"
                )
            else:
                assurance_note = (
                    "Scoped production startup contract: "
                    "references/v5_production_worker_bootstrap.md. For this exact "
                    "current production card it replaces broad protocol preloading; "
                    "load a broader reference only at one of that contract's explicit "
                    "fail-closed conditional branches. Exact public worker-return schema: "
                    "references/v5_worker_return_contract.md; copyable template: "
                    "assets/worker_return.v5.assurance-no-adverse.template.json. "
                    "This task card uses the prospective assurance contract. "
                    "Return exact per-obligation dispositions, a typed computation manifest "
                    "when required, and the exact research_assurance object. Related "
                    "Research artifacts are authorized only through the frozen allowlist.\n\n"
                )
            if "source_use_required" in assurance_contract["risk_signals"]:
                source_obligation_ids: list[str] = []
                applicability_obligation_ids: list[str] = []
                for obligation in assurance_contract["obligations"]:
                    source_required, applicability_required = (
                        _obligation_source_requirements(obligation)
                    )
                    if source_required:
                        source_obligation_ids.append(
                            obligation["obligation_id"]
                        )
                    if applicability_required:
                        applicability_obligation_ids.append(
                            obligation["obligation_id"]
                        )
                source_ids_text = (
                    ", ".join(source_obligation_ids)
                    if source_obligation_ids
                    else "none"
                )
                applicability_ids_text = (
                    ", ".join(applicability_obligation_ids)
                    if applicability_obligation_ids
                    else "none"
                )
                source_use_skeleton = json.dumps(
                    {
                        "source_key": (
                            "<exact structured obligation_id; when none is listed, "
                            "use one exact descriptive source key>"
                        ),
                        "use_kind": "result",
                        "source_strength": "fixed_object",
                        "target_strength": "fixed_object",
                        "source_artifact_sha256": (
                            "<exact returned artifact or frozen primary-source SHA-256>"
                        ),
                        "toy_check_artifact_sha256": None,
                        "bridge_artifact_sha256s": [],
                    },
                    ensure_ascii=False,
                    sort_keys=True,
                )
                assurance_note += (
                    "Source assurance is structurally required. Structured source "
                    f"obligation ids: {source_ids_text}. Structured applicability "
                    f"obligation ids: {applicability_ids_text}. Include at least one "
                    "`research_assurance.source_uses` object and cover every listed "
                    "source obligation by exact `source_key`; bind every witness "
                    "declared by a completed obligation disposition through source, "
                    "toy-check, or bridge artifact hashes. JSON object skeleton: "
                    f"`{source_use_skeleton}`\n\n"
                )
        campaign_note = ""
        if "campaign_scope" in card:
            campaign_note = (
                "This round was explicitly scoped to the frozen Campaign envelope in "
                "the task card. Use its objective, active targets, constraints, value "
                "definition, and stop conditions as nontruth planning context. Main's "
                "four-factor frontier remains the only scheduler; Campaign status does "
                "not close this task, certify a result, or change Fact admission.\n\n"
            )
        paper_continuation_note = ""
        if "paper_continuation_scope" in card:
            paper_continuation_note = (
                "This is one exact Paper continuation target. Read its complete frozen "
                "target closure and source capabilities from paper_continuation_scope; "
                "state the issue, importance, burden holder, strongest charitable "
                "objection, response or revision, and every independent failure surface. "
                "Produce the required paper_target_analysis artifact. A clean worker "
                "return remains Research only: Main must separately record a current "
                "target disposition and revised-writing mapping before Paper adequacy can "
                "be complete.\n\n"
            )
        task_context_note = ""
        if card.get("task_context_revision") == V5_TASK_CONTEXT_REVISION:
            background = card["mathematical_state"]["project_background"]
            if background is None:
                background_note = (
                    "No PROJECT_BACKGROUND.md was present when this card was frozen. "
                )
            else:
                selected = background["selection_receipt"]["selected_chunk_ids"]
                selected_text = ", ".join(selected) if selected else "none"
                task_card_relpath = (
                    f"rounds/{card['round_id']}/task-cards/"
                    f"{card['assignment_id']}.json"
                )
                background_note = (
                    "PROJECT_BACKGROUND.md is represented only by its complete exact-byte "
                    "index; it is lower-priority nontruth context, not task authority. "
                    f"Planner-committed chunk ids: {selected_text}. Retrieve any exact chunk "
                    "on demand with `project-background-read CHUNK_ID --task-card "
                    f"{task_card_relpath}`. After context compaction, reread the card/index "
                    "and rerun the same retrieval instead of relying on memory. "
                )
            task_context_note = (
                "Read the complete source_research_dossier and the machine-validated "
                "authority_snapshot in mathematical_state. When project-background "
                "prose disagrees about current Fact, Release, Decision, or admission "
                "status, the authority_snapshot controls. Read target evidence only "
                "through its exact path/hash capability list. The context_selection "
                "receipt records the Main-planner-compiled Blackboard query and bounded "
                "mode hint; it does not change capabilities, assurance, truth, or "
                "admission. "
                f"{background_note}\n\n"
            )
        return (
            "# Chalxius V5 worker assignment\n\n"
            f"Round: `{card['round_id']}`  \n"
            f"Assignment: `{card['assignment_id']}`  \n"
            f"Task-card SHA-256: `{task_card_sha256}`\n\n"
            "Read the immutable task card for exact capabilities. Use only its frozen "
            "mathematical-state snapshot. Keep rationale and intuition in the bounded "
            "narrative return fields; do not move them into the control channel.\n\n"
            "Start the worker CHX ledger with this candidate's `scripts/chx_ledger.py` "
            f"and pass `--task-card {self._task_card_path(card['round_id'], card['assignment_id'])}`; "
            "runtime mismatch must fail before the ledger is created.\n\n"
            f"Research claim: {card['narrative_plane']['claim']}\n\n"
            f"{pair_note}"
            f"{research_cycle_note}"
            f"{adverse_note}"
            f"{assurance_note}"
            f"{campaign_note}"
            f"{paper_continuation_note}"
            f"{task_context_note}"
            f"Write the exact return to `{card['return_contract']['return_relpath']}`, "
            "then hand off assignment_id and status=\"final\". Canonical ingestion "
            "derives the SHA-256 from those exact bytes.\n"
        )

    def create_production_round(
        self,
        *,
        workers: int,
        mode: str = "auto",
        research_ids: list[str] | None = None,
        campaign_id: str | None = None,
        host_task_scope_id: str | None = None,
        background_chunk_ids: list[str] | None = None,
        frontier_target_id: str | None = None,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any]:
        """Plan constructive Research subround 1 without changing legacy cards."""

        if mode == "refute":
            raise ValueError(
                "Research refute is reserved for subround-2 supervision; "
                "production accepts only constructive work"
            )

        return self.create_round(
            workers=workers,
            mode=mode,
            research_ids=research_ids,
            campaign_id=campaign_id,
            host_task_scope_id=host_task_scope_id,
            background_chunk_ids=background_chunk_ids,
            frontier_target_id=frontier_target_id,
            research_cycle=self.production_research_cycle_binding(),
            _inspection_context=_inspection_context,
        )

    @staticmethod
    def _exact_plan_round_argv(
        research_ids: list[str],
        *,
        campaign_id: str | None,
        requested_mode: str = "auto",
        frontier_target_id: str | None = None,
    ) -> list[str]:
        """Build a copy-safe exact Research selection for Main."""

        normalized_ids = [validate_memory_id(item) for item in research_ids]
        if not normalized_ids or len(normalized_ids) != len(set(normalized_ids)):
            raise ValueError("exact plan-round argv requires unique Research ids")
        if requested_mode != "auto" and requested_mode not in WORK_MODES:
            raise ValueError("exact plan-round argv mode is invalid")
        argv = [
            "plan-round",
            "--workers",
            str(len(normalized_ids)),
            "--mode",
            requested_mode,
        ]
        if campaign_id is not None:
            argv.extend(["--campaign", validate_campaign_id(campaign_id)])
        if frontier_target_id is not None:
            if campaign_id is None:
                raise ValueError(
                    "exact plan-round frontier target requires a Campaign"
                )
            argv.extend(
                [
                    "--frontier-target",
                    validate_campaign_target_id(frontier_target_id),
                ]
            )
        for research_id in normalized_ids:
            argv.extend(["--memory-id", research_id])
        return argv

    @classmethod
    def _plan_round_selection_receipt(
        cls,
        *,
        selected_research_ids: list[str],
        research_ids_were_explicit: bool,
        campaign_id: str | None,
        requested_mode: str,
        frontier_target_id: str | None = None,
    ) -> dict[str, Any]:
        selection_source = (
            "explicit_research_ids"
            if research_ids_were_explicit
            else "campaign_frontier"
            if campaign_id is not None
            else "global_frontier"
        )
        return {
            "revision": "chalxius-v5-plan-round-selection-2",
            "selection_source": selection_source,
            "selected_research_ids": list(selected_research_ids),
            "campaign_id": campaign_id,
            "requested_mode": requested_mode,
            "frontier_target_id": frontier_target_id,
            "exact_replay_argv": cls._exact_plan_round_argv(
                list(selected_research_ids),
                campaign_id=campaign_id,
                requested_mode=requested_mode,
                frontier_target_id=frontier_target_id,
            ),
        }

    @classmethod
    def _validate_plan_round_selection_receipt(
        cls,
        value: Any,
        *,
        assignments: list[dict[str, Any]],
        campaign_scope: dict[str, Any] | None,
    ) -> dict[str, Any]:
        legacy_expected = {
            "revision",
            "selection_source",
            "selected_research_ids",
            "campaign_id",
            "requested_mode",
            "exact_replay_argv",
        }
        current_expected = legacy_expected | {"frontier_target_id"}
        if not isinstance(value, dict) or frozenset(value) not in {
            frozenset(legacy_expected),
            frozenset(current_expected),
        }:
            raise ValueError("plan-round selection receipt fields are not exact")
        if value["revision"] not in {
            "chalxius-v5-plan-round-selection-1",
            "chalxius-v5-plan-round-selection-2",
        }:
            raise ValueError("plan-round selection receipt revision is invalid")
        current = value["revision"] == "chalxius-v5-plan-round-selection-2"
        if current != (set(value) == current_expected):
            raise ValueError(
                "plan-round selection receipt revision/fields drifted"
            )
        if value["selection_source"] not in {
            "explicit_research_ids",
            "campaign_frontier",
            "global_frontier",
        }:
            raise ValueError("plan-round selection source is invalid")
        if any(not isinstance(item, dict) for item in assignments):
            raise ValueError("plan-round selection assignments are malformed")
        selected = [
            item["research_id"]
            for item in assignments
            if item.get("assignment_role") != "paired_adverse"
        ]
        if value["selected_research_ids"] != selected:
            raise ValueError("plan-round selected Research ids drifted")
        expected_campaign = (
            campaign_scope["campaign_id"]
            if campaign_scope is not None
            else None
        )
        if value["campaign_id"] != expected_campaign:
            raise ValueError("plan-round selection Campaign drifted")
        frontier_target_id = (
            value["frontier_target_id"] if current else None
        )
        if frontier_target_id is not None:
            validate_campaign_target_id(frontier_target_id)
            if expected_campaign is None:
                raise ValueError(
                    "plan-round frontier target lacks Campaign scope"
                )
            active_target_ids = {
                item.get("target_id")
                for item in campaign_scope.get("active_targets", [])
                if isinstance(item, dict)
            }
            if frontier_target_id not in active_target_ids:
                raise ValueError(
                    "plan-round frontier target is absent from frozen Campaign scope"
                )
        if (
            value["selection_source"] == "campaign_frontier"
            and expected_campaign is None
        ):
            raise ValueError("Campaign frontier selection lacks Campaign scope")
        if (
            value["selection_source"] == "global_frontier"
            and expected_campaign is not None
        ):
            raise ValueError("global frontier selection carries Campaign scope")
        expected_argv = cls._exact_plan_round_argv(
            selected,
            campaign_id=expected_campaign,
            requested_mode=value["requested_mode"],
            frontier_target_id=frontier_target_id,
        )
        if value["exact_replay_argv"] != expected_argv:
            raise ValueError("plan-round exact replay argv drifted")
        return value

    def prepare_candidate_adverse_target(
        self,
        selected_research_id: str,
        *,
        candidate_fact_path: str,
        actor: str = "v5-main-candidate-adverse-preparer",
    ) -> dict[str, Any]:
        """Create or reuse the exact nontruth target for Candidate attack.

        The preparation is deliberately narrow.  Main selects one active
        Research head and supplies one project-contained canonical Candidate
        Fact.  The Fact bytes need not have been authored by that Research or
        by any worker.  Applicable completed Research-supervision results are
        bound as mathematical lineage, and one content-addressed synthesis
        Research entry transports the exact Fact bytes to the adverse card.
        This does not atomize a claim, plan the attack, package a Candidate,
        invoke a verifier, create a Certification Decision, or admit a Fact.
        """

        inspection = self._bind_inspection_context(
            RoundInspectionContext(),
            create=True,
        )
        assert inspection is not None
        selected_research_id = validate_memory_id(selected_research_id)
        selected = self._inspection_research_record(
            selected_research_id,
            inspection,
        )
        if selected["status"] not in ACTIVE_MEMORY_STATUSES:
            raise ValueError("Main-selected Candidate Research must be active")
        if self._research_is_adverse_assignment(selected):
            raise ValueError("Main-selected Candidate Research cannot be adverse work")
        if not isinstance(candidate_fact_path, str):
            raise ValueError("Candidate adverse target Fact path must be a string")
        candidate_path = contained_path(
            self.store.root,
            candidate_fact_path,
            "Candidate adverse target Fact path",
        )
        if candidate_path.is_symlink() or not candidate_path.is_file():
            raise ValueError("Candidate adverse target Fact is missing or unsafe")
        raw = self._read_regular_bytes_once(
            candidate_path,
            label="Candidate adverse target Fact",
        )
        fact = self._validate_candidate_fact_artifact_bytes(raw)
        candidate_binding = {
            "path": candidate_path.relative_to(
                self.store.root.resolve()
            ).as_posix(),
            "sha256": sha256_bytes(raw),
            "role": "candidate_fact",
        }

        required_supervision = self._required_supervision_results_for_candidate(
            [selected],
            _inspection_context=inspection,
        )
        supervision_ids = sorted(required_supervision)
        for supervision_id in supervision_ids:
            supervision = self._inspection_research_record(
                supervision_id,
                inspection,
            )
            if not self._research_is_adverse_assignment(supervision):
                raise ValueError(
                    "Candidate adverse preparation supervision is not independent refute work"
                )

        payload = {
            "kind": "synthesis",
            "status": "open",
            "claim": (
                f"Exact canonical Fact {fact.fact_id} is ready for fresh "
                "whole-Candidate adverse review."
            ),
            "content": (
                "This Main preparation transports the exact canonical Candidate Fact "
                "bytes selected for review and binds every applicable completed "
                "Research-supervision result. Fact authorship and worker provenance "
                "are descriptive metadata, not a mathematical capability. It adds no "
                "mathematical conclusion."
            ),
            "rationale": (
                "Whole-Candidate adverse review must target the exact one-conclusion "
                "Fact after Research supervision and before Candidate packaging."
            ),
            "dependencies": [],
            "source": "",
            "relation": "prepares_candidate_from",
            "related_research_ids": sorted(
                {selected_research_id, *supervision_ids}
            ),
            "independent_adverse_required": True,
            "adverse_domain_profile": "mathematics",
            "source_dependent": False,
            "route_invalidations": [],
            "artifacts": [candidate_binding],
        }
        target = self.add_research(
            payload,
            actor=actor,
            assurance_contract_revision=V5_ASSURANCE_CONTRACT_REVISION,
            _inspection_context=inspection,
        )
        return {
            "research_id": target["research_id"],
            "selected_research_id": selected_research_id,
            "supervision_research_ids": supervision_ids,
            "fact_id": fact.fact_id,
            "candidate_fact_sha256": candidate_binding["sha256"],
            "next_command": (
                "plan-candidate-adverse " + target["research_id"]
            ),
            "project_effect": "one_nontruth_research_target",
            "truth_effect": "none",
        }

    def plan_candidate_adverse_round(
        self,
        research_id: str,
        *,
        host_task_scope_id: str | None = None,
    ) -> dict[str, Any]:
        """Plan one fresh refute card for an exact Candidate-Fact target.

        This lane is intentionally outside both constructive production and
        Research supervision.  It creates ordinary nontruth Research work and
        cannot replace Candidate disposition, verifier, Certification,
        Gateway, or Fact admission.
        """

        inspection = self._bind_inspection_context(
            RoundInspectionContext(),
            create=True,
        )
        assert inspection is not None
        research_id = validate_memory_id(research_id)
        target = self._inspection_research_record(research_id, inspection)
        metadata = target.get("metadata")
        if not isinstance(metadata, dict):
            raise ValueError("Candidate adverse target metadata is invalid")
        if target.get("status") not in ACTIVE_MEMORY_STATUSES:
            raise ValueError("Candidate adverse target must be active Research")
        all_records = {
            item["research_id"]: item
            for item in self.research_records(
                _inspection_context=inspection,
            )
        }
        stale_routes = self._route_staleness(all_records)
        if research_id in stale_routes:
            raise ValueError(
                "Candidate adverse target is stale; create a copy-on-write "
                "repair before planning another attack"
            )
        if self._research_is_adverse_assignment(target):
            raise ValueError("Candidate adverse target cannot itself be adverse work")
        if metadata.get("independent_adverse_required") is not True:
            raise ValueError(
                "Candidate adverse target must require independent adverse review"
            )
        self._typed_research_artifacts(
            target,
            _inspection_context=inspection,
        )
        artifacts = metadata.get("artifacts", [])
        candidate_facts = [
            item for item in artifacts if item["role"] == "candidate_fact"
        ]
        if len(candidate_facts) != 1:
            raise ValueError(
                "Candidate adverse target must bind exactly one candidate_fact artifact"
            )

        target_binding = candidate_facts[0]
        target_path = contained_path(
            self.store.root,
            target_binding["path"],
            "Candidate adverse target Fact path",
        )
        if target_path.is_symlink() or not target_path.is_file():
            raise ValueError("Candidate adverse target Fact is missing or unsafe")
        target_raw = self._read_regular_bytes_once(
            target_path,
            label="Candidate adverse target Fact",
        )
        if sha256_bytes(target_raw) != target_binding["sha256"]:
            raise ValueError("Candidate adverse target Fact hash drifted")
        self._validate_candidate_fact_artifact_bytes(target_raw)
        normalized_host_scope = normalize_host_task_scope_id(
            host_task_scope_id,
            workflow_evidence_version=5,
            project_id=self.store.project_id(),
            local_seed={
                "research_ids": [research_id],
                "requested_mode": "refute",
                "campaign_id": None,
                "background_chunk_ids": [],
                "research_cycle": None,
            },
        )
        if normalized_host_scope is None:
            raise RuntimeError("Candidate adverse host scope allocation returned null")
        active_matches: list[dict[str, Any]] = []
        for candidate_dir in sorted(self.store.rounds_dir.glob("round-*")):
            if candidate_dir.is_symlink() or not candidate_dir.is_dir():
                continue
            # An immutable abort authority permanently removes this work unit
            # from exact-retry ownership.  Exclude it before reconstructing
            # the old round or reading worker cards: after a runtime cutover,
            # an aborted card is historical evidence, not an active card that
            # must match the new runtime.  Full project audit retains the
            # independent responsibility for the frozen aborted bytes.
            if (
                self.store.reasoning_modes().work_unit_abort(
                    candidate_dir.name
                )
                is not None
            ):
                continue
            round_dir, manifest = self._round_manifest(
                candidate_dir.name,
                _inspection_context=inspection,
            )
            if manifest.get("research_cycle") is not None:
                continue
            for assignment in manifest["assignments"]:
                if assignment["research_id"] != research_id:
                    continue
                card_path = self._task_card_path(
                    manifest["round_id"],
                    assignment["assignment_id"],
                )
                if card_path.is_symlink() or not card_path.is_file():
                    raise ValueError("Candidate adverse task card is missing")
                card = self.validate_task_card(
                    self.store._read_json(card_path),
                    expected_path=card_path,
                    historical_runtime=self._round_is_completed(
                        round_dir,
                        manifest,
                        _inspection_context=inspection,
                    ),
                    _inspection_context=inspection,
                )
                if card["work_mode"] != "refute":
                    continue
                card_bindings = [
                    item
                    for item in card["mathematical_state"][
                        "source_research_dossier"
                    ]["metadata"].get("artifacts", [])
                    if item.get("role") == "candidate_fact"
                ]
                if card_bindings != [target_binding]:
                    continue
                if manifest["host_task_scope_id"] != normalized_host_scope:
                    raise ValueError(
                        "Candidate adverse exact retry belongs to a different host scope"
                    )
                active_matches.append(
                    self.round_status(
                        manifest["round_id"],
                        _inspection_context=inspection,
                    )
                )
        if len(active_matches) > 1:
            raise ValueError("Candidate adverse planning has multiple live exact retries")
        if active_matches:
            return active_matches[0]

        return self.create_round(
            workers=1,
            mode="refute",
            research_ids=[research_id],
            host_task_scope_id=normalized_host_scope,
            research_cycle=None,
            _inspection_context=inspection,
        )

    def _existing_cycle_round_for_research(
        self,
        *,
        research_id: str,
        subround: str,
    ) -> dict[str, Any] | None:
        matches: list[str] = []
        if not self.store.rounds_dir.exists():
            return None
        for round_dir in sorted(self.store.rounds_dir.glob("round-*")):
            if round_dir.is_symlink() or not round_dir.is_dir():
                continue
            _, manifest = self._round_manifest(round_dir.name)
            cycle = manifest.get("research_cycle")
            if cycle is None or self._validate_research_cycle_binding(cycle)[
                "subround"
            ] != subround:
                continue
            if any(
                assignment["research_id"] == research_id
                for assignment in manifest["assignments"]
            ):
                matches.append(manifest["round_id"])
        if len(matches) > 1:
            raise ValueError(
                "one Research entry was scheduled into multiple prospective cycle rounds"
            )
        return self.round_status(matches[0]) if matches else None

    def _authoritative_supervision_retry_or_overlap(
        self,
        *,
        research_cycle: dict[str, Any],
        host_task_scope_id: str,
    ) -> str | None:
        """Recheck supervision retry/overlap while the mutation lock is held.

        Aborted rounds do not reserve coverage.  An exact retry is reusable
        only for the same normalized host scope.  Every other live round for
        the same source component whose supervisor scopes overlap is a hard
        conflict, including an otherwise identical request from another host.
        """

        cycle = self._validate_research_cycle_binding(research_cycle)
        if cycle["subround"] != "supervision":
            return None
        requested_scopes = set(cycle["supervisor_scopes"])
        source_component_id = cycle.get("source_component_id")
        exact: list[str] = []
        overlapping: list[str] = []
        if not self.store.rounds_dir.exists():
            return None
        inspection = RoundInspectionContext()
        for round_dir in sorted(self.store.rounds_dir.glob("round-*")):
            if round_dir.is_symlink() or not round_dir.is_dir():
                continue
            manifest_path = round_dir / "round.json"
            if manifest_path.is_symlink() or not manifest_path.is_file():
                raise ValueError("round ledger contains an unsafe manifest")
            raw_manifest = self._read_regular_bytes_once(
                manifest_path,
                label="Research supervision overlap manifest",
            )
            if cycle["source_round_id"].encode("ascii") not in raw_manifest:
                continue
            if (
                source_component_id is not None
                and source_component_id.encode("ascii") not in raw_manifest
            ):
                continue
            _, manifest = self._round_manifest(
                round_dir.name,
                _inspection_context=inspection,
            )
            if self.store.reasoning_modes().work_unit_abort(
                manifest["round_id"]
            ) is not None:
                continue
            other = manifest.get("research_cycle")
            if (
                not isinstance(other, dict)
                or other.get("subround") != "supervision"
                or other.get("source_round_id") != cycle["source_round_id"]
                or other.get("source_component_id") != source_component_id
            ):
                continue
            same_cycle = other == cycle
            same_host = (
                manifest.get("host_task_scope_id") == host_task_scope_id
            )
            if same_cycle and same_host:
                exact.append(manifest["round_id"])
                continue
            other_scopes = other.get("supervisor_scopes", [])
            if isinstance(other_scopes, list) and requested_scopes.intersection(
                other_scopes
            ):
                overlapping.append(manifest["round_id"])
        if len(exact) > 1:
            raise ValueError("duplicate exact Research supervision rounds exist")
        if overlapping:
            raise ValueError(
                "logical component already has overlapping supervisor scope "
                "coverage: "
                + ", ".join(sorted(overlapping))
            )
        return exact[0] if exact else None

    def create_supervision_round(
        self,
        source_round_id: str,
        *,
        source_component_id: str | None = None,
        supervisor_scopes: list[str] | None = None,
        host_task_scope_id: str | None = None,
    ) -> dict[str, Any]:
        """Plan subround 2 against one exact completed logical component."""

        inspection = self._bind_inspection_context(
            RoundInspectionContext(),
            create=True,
        )
        assert inspection is not None
        source_manifest, descriptors = self._source_round_receipt_descriptors(
            source_round_id,
            source_component_id=source_component_id,
            _inspection_context=inspection,
        )
        source_component = self._source_supervision_component(
            source_manifest,
            source_component_id,
            _inspection_context=inspection,
        )
        selection_logic_signals = self._source_round_selection_logic_signals(
            source_manifest,
            descriptors,
        )
        applicable = self._applicable_research_supervisor_scopes(
            descriptors,
            selection_logic_signals=selection_logic_signals,
        )
        if supervisor_scopes is None:
            chosen = applicable[:V5_RESEARCH_SUPERVISOR_LIMIT]
        else:
            chosen = _require_string_list(
                supervisor_scopes, "Research supervisor scopes"
            )
            if (
                chosen != list(dict.fromkeys(chosen))
                or len(chosen) > V5_RESEARCH_SUPERVISOR_LIMIT
                or any(scope not in V5_RESEARCH_SUPERVISOR_SCOPES for scope in chosen)
            ):
                raise ValueError(
                    "Research supervision accepts one to three distinct supported scopes"
                )
            # Primary scopes are Main-selectable over the exact frozen
            # component even when the sparse automatic selector omitted them.
            # Integration retains its structural cross-primary definition.
            inapplicable = sorted(
                scope
                for scope in set(chosen).difference(applicable)
                if scope == "integration"
            )
            if inapplicable:
                raise ValueError(
                    "Research supervisor scopes do not apply to this production: "
                    + ", ".join(inapplicable)
                )
        if not chosen:
            raise ValueError("production has no applicable Research supervisor scope")
        cycle_revision = (
            V5_RESEARCH_CYCLE_REVISION
            if source_component is not None
            else V5_LEGACY_RESEARCH_CYCLE_REVISION
        )
        cycle: dict[str, Any] = {
            "revision": cycle_revision,
            "subround": "supervision",
            "source_round_id": source_manifest["round_id"],
            "source_round_manifest_sha256": source_manifest["manifest_sha256"],
            "source_receipts_sha256": sha256_json(descriptors),
            "supervisor_scopes": sorted(chosen),
            "computation_policy": "core_code_review_before_formal_execution",
            "repair_policy": "copy_on_write_next_research_cycle",
            "pulse_policy": "not_used",
            "truth_effect": "none",
        }
        if source_component is not None:
            cycle["source_component_id"] = source_component["component_id"]
            cycle["source_component_sha256"] = source_component[
                "component_sha256"
            ]
        self._validate_research_cycle_binding(cycle)

        # An exact retry already has immutable supervisor Research and round
        # bytes. Rebuilding the same planner Research first would recursively
        # revalidate unrelated graph history before discovering that nothing
        # needs to be written. Resolve the existing cycle under the ordinary
        # mutation lock and return it before any add_research call. A missing
        # explicit/environment host scope still follows the normal deterministic
        # local-allocation path below.
        early_host_scope = normalize_host_task_scope_id(
            host_task_scope_id,
            workflow_evidence_version=5,
        )
        if early_host_scope is not None:
            with self.store.v5_mutation_lock(command="plan-supervision-round"):
                existing_round_id = (
                    self._authoritative_supervision_retry_or_overlap(
                        research_cycle=cycle,
                        host_task_scope_id=early_host_scope,
                    )
                )
                if existing_round_id is not None:
                    return self.round_status(
                        existing_round_id,
                        _inspection_context=inspection,
                    )

        source_assignment_by_id = {
            item["assignment_id"]: item for item in source_manifest["assignments"]
        }
        current_closure = all(
            self._task_card_skill_version_at_least(
                self.store._read_json(
                    contained_path(
                        self.store.root,
                        assignment["task_card_relpath"],
                        "supervised production task card",
                    )
                ),
                (0, 7, 14),
            )
            for assignment in source_assignment_by_id.values()
        )
        # Freeze the attacked production authority into the supervisor's normal
        # task-card capability machinery.  Output Research alone does not own
        # the production card's admitted-Fact premises or its input-source
        # allowlist.  Carry those exact bytes and active premise ids forward so
        # the supervisor can replay the attacked route without reconstructing
        # authority from prose or asking Main for an ad-hoc repair card.
        source_authority_by_assignment: dict[str, dict[str, Any]] = {}
        source_task_cards_by_assignment: dict[str, dict[str, Any]] = {}
        for descriptor in (descriptors if current_closure else []):
            assignment = source_assignment_by_id[descriptor["assignment_id"]]
            task_card_path = contained_path(
                self.store.root,
                assignment["task_card_relpath"],
                "supervised production task card",
            )
            task_card_raw = task_card_path.read_bytes()
            if sha256_bytes(task_card_raw) != assignment["task_card_sha256"]:
                raise ValueError("supervised production task-card hash drifted")
            task_card = self.store._read_json(task_card_path)
            source_task_cards_by_assignment[descriptor["assignment_id"]] = task_card
            mathematical_state = task_card["mathematical_state"]
            fact_ids = sorted(
                binding["fact_id"]
                for binding in mathematical_state["authority_snapshot"][
                    "fact_bindings"
                ]
                if binding["status"] == "active"
            )
            # Every supervisor can follow the exact production card and the
            # active Fact premises it names. Scope-independent baseline bytes
            # are not copied into proof/program/integration cards merely
            # because they appeared in the production context; source-scope
            # supervision projects them below where they are applicable.
            capabilities = [
                {
                    "path": assignment["task_card_relpath"],
                    "sha256": assignment["task_card_sha256"],
                    "source_role": "production_task_card",
                }
            ]
            semantic = {
                "revision": V5_SUPERVISED_AUTHORITY_CLOSURE_REVISION,
                "assignment_id": descriptor["assignment_id"],
                "task_card_path": assignment["task_card_relpath"],
                "task_card_sha256": assignment["task_card_sha256"],
                "active_fact_ids": fact_ids,
                "capabilities": capabilities,
                "truth_effect": "none",
            }
            source_authority_by_assignment[descriptor["assignment_id"]] = {
                **semantic,
                "receipt_sha256": sha256_json(semantic),
            }
        campaign_scope = source_manifest.get("campaign_scope")
        campaign_id = (
            campaign_scope["campaign_id"] if campaign_scope is not None else None
        )
        supervisor_ids: list[str] = []
        for scope in chosen:
            scoped_receipts = self._research_supervision_scope_receipts(
                scope,
                descriptors,
            )
            binding_revision = (
                V5_RESEARCH_SUPERVISION_REVISION
                if source_component is not None
                else V5_LEGACY_RESEARCH_SUPERVISION_REVISION
            )
            binding: dict[str, Any] = {
                "revision": binding_revision,
                "supervisor_scope": scope,
                "source_round_id": source_manifest["round_id"],
                "source_round_manifest_sha256": source_manifest[
                    "manifest_sha256"
                ],
                "source_receipts": scoped_receipts,
                "source_receipts_sha256": sha256_json(scoped_receipts),
                "review_policy": "attack_exact_production_outputs",
                "repair_policy": "copy_on_write_next_research_cycle",
                "pulse_policy": "not_used",
                "truth_effect": "none",
            }
            if source_component is not None:
                binding["source_component_id"] = source_component[
                    "component_id"
                ]
                binding["source_component_sha256"] = source_component[
                    "component_sha256"
                ]
            self._validate_research_supervision_binding(binding)
            related_ids = {
                item["result_research_id"] for item in scoped_receipts
            }
            supervised_fact_ids: set[str] = set()
            supervised_capabilities: dict[
                tuple[str, str], dict[str, str]
            ] = {}
            supervised_authority: list[dict[str, Any]] = []
            for descriptor in (scoped_receipts if current_closure else []):
                base_receipt = source_authority_by_assignment[
                    descriptor["assignment_id"]
                ]
                receipt = base_receipt
                source_card = source_task_cards_by_assignment.get(
                    descriptor["assignment_id"]
                )
                if source_card is None:
                    raise ValueError(
                        "supervision lacks its frozen production task card"
                    )
                if scope == "source_scope":
                    source_state = source_card["mathematical_state"]
                    source_capabilities = list(base_receipt["capabilities"])
                    for capability in [
                        *source_state.get("related_artifacts", []),
                        *source_state["authority_snapshot"].get(
                            "capabilities", []
                        ),
                    ]:
                        source_capabilities.append(
                            {
                                "path": capability["path"],
                                "sha256": capability["sha256"],
                                "source_role": capability["role"],
                            }
                        )
                    prior_review_ids, prior_source_capabilities = (
                        self._source_scope_continuity_for_card(
                            source_card,
                            inspection,
                        )
                    )
                    related_ids.update(prior_review_ids)
                    source_capabilities.extend(prior_source_capabilities)
                    source_capabilities = list(
                        {
                            (item["path"], item["sha256"]): item
                            for item in source_capabilities
                        }.values()
                    )
                    scoped_semantic = {
                        key: base_receipt[key]
                        for key in (
                            "revision",
                            "assignment_id",
                            "task_card_path",
                            "task_card_sha256",
                            "active_fact_ids",
                            "truth_effect",
                        )
                    }
                    scoped_semantic["capabilities"] = source_capabilities
                    receipt = {
                        **scoped_semantic,
                        "receipt_sha256": sha256_json(scoped_semantic),
                    }
                supervised_authority.append(receipt)
                supervised_fact_ids.update(receipt["active_fact_ids"])
                for capability in receipt["capabilities"]:
                    key = (capability["path"], capability["sha256"])
                    if key in supervised_capabilities:
                        continue
                    role_index = len(supervised_capabilities) + 1
                    supervised_capabilities[key] = {
                        "path": capability["path"],
                        "sha256": capability["sha256"],
                        "role": (
                            f"supervised_input_{role_index:03d}:"
                            f"{descriptor['assignment_id']}:"
                            f"{capability['source_role']}"
                        ),
                    }
                if scope == "source_scope":
                    for capability in self._structured_source_evidence_capabilities_from_card(
                        card=source_card,
                        origin=f"{descriptor['assignment_id']}",
                    ):
                        key = (capability["path"], capability["sha256"])
                        if key in supervised_capabilities:
                            continue
                        role_index = len(supervised_capabilities) + 1
                        supervised_capabilities[key] = {
                            "path": capability["path"],
                            "sha256": capability["sha256"],
                            "role": (
                                f"supervised_input_{role_index:03d}:"
                                f"{descriptor['assignment_id']}:"
                                f"{capability['role']}"
                            ),
                        }
            supervised_artifacts = list(supervised_capabilities.values())
            if len(supervised_artifacts) > 256:
                raise ValueError(
                    "supervised production authority exceeds the task-card "
                    "artifact capability limit"
                )
            required_roles: set[str] = set()
            if scope == "program_math":
                for descriptor in scoped_receipts:
                    if descriptor["computation_phase"] == "core_code_design":
                        required_roles.update(
                            V5_COMPUTATION_DESIGN_ARTIFACT_ROLES
                        )
                    elif descriptor["computation_phase"] == "approved_execution":
                        required_roles.update(
                            {
                                "computation_dependencies",
                                "computation_design",
                                "computation_log",
                                "computation_output",
                                "computation_source",
                            }
                        )
                        assignment = source_assignment_by_id[
                            descriptor["assignment_id"]
                        ]
                        card = self.store._read_json(
                            self.store.root / assignment["task_card_relpath"]
                        )
                        approved = card["mathematical_state"][
                            "source_research_dossier"
                        ]["metadata"].get("approved_computation_execution")
                        approved = self._validate_approved_computation_execution_binding(
                            approved
                        )
                        related_ids.add(approved["design_research_id"])
            failure_family_ids, supervision_focus = (
                self._research_supervision_focus(scope)
            )
            payload: dict[str, Any] = {
                "kind": "challenge",
                "status": "open",
                "claim": (
                    f"Research supervisor ({scope}) attacks the exact frozen "
                    f"returns of {source_manifest['round_id']}."
                ),
                "content": (
                    "Review the complete hash-bound production products and conserved "
                    "claims inside this exact scope. Treat prior defects and repair "
                    "obligations as mandatory but non-exhaustive attack seeds, not a "
                    "defect allowlist; report new, inherited, repair-induced, or cross-"
                    "component defects as well as a bounded no-obstruction finding. "
                    "Do not use realtime Pulse or silently rewrite production; "
                    "any defect opens a copy-on-write Research repair in a later cycle. "
                    "The evidenced focus for this scope is: "
                    f"{supervision_focus}. Do not widen the review beyond the exact "
                    "receipts or re-attack admitted Fact premises without separately "
                    "escalated contradiction evidence."
                ),
                "rationale": (
                    "A dedicated second subround catches reasoning, projection, source, "
                    "or integration defects before Candidate construction."
                ),
                "source": f"round:{source_manifest['round_id']}",
                "relation": "challenges",
                "related_research_ids": sorted(related_ids),
                "research_supervision": binding,
                "failure_informed_assurance": {
                    "revision": V5_RESEARCH_ASSURANCE_SELECTION_REVISION,
                    "registry_sha256": (
                        V5_RESEARCH_FAILURE_FAMILY_REGISTRY_SHA256
                    ),
                    "family_ids": failure_family_ids,
                    "supervisor_scope": scope,
                    "selection_policy": V5_RESEARCH_ASSURANCE_SELECTION_POLICY,
                    "truth_effect": "none",
                },
                "required_related_artifact_roles": sorted(required_roles),
                "obligations": [
                    {
                        "obligation_id": f"obl-research-supervision-{scope}",
                        "description": (
                            "Return one concise, artifact-bound fresh supervision report "
                            "covering every complete frozen product and conserved claim "
                            "assigned to this scope; prior defects are non-exhaustive seeds."
                        ),
                        "required_artifact_roles": [
                            "research_supervision_report"
                        ],
                        "evidence_types": ["adversarial_review_report"],
                        "not_applicable_allowed": False,
                    }
                ],
                "truth_effect": "none",
            }
            if current_closure:
                payload.update(
                    {
                        "dependencies": sorted(supervised_fact_ids),
                        "artifacts": supervised_artifacts,
                        "source_dependent": (
                            scope == "source_scope"
                            and bool(supervised_artifacts)
                        ),
                        "supervised_production_authority": supervised_authority,
                    }
                )
            if required_roles:
                payload["decision_profile"] = dict(
                    V5_PROGRAM_MATH_REVIEW_DECISION_PROFILE
                )
            if campaign_id is not None:
                payload["campaign_id"] = campaign_id
            supervisor = self.add_research(
                payload,
                actor="v5-research-supervisor-planner",
                assurance_contract_revision=V5_ASSURANCE_CONTRACT_REVISION,
                _inspection_context=inspection,
            )
            supervisor_ids.append(supervisor["research_id"])
        self._validate_supervision_round_selection(
            research_cycle=cycle,
            selected=[
                self._inspection_research_record(item, inspection)
                for item in supervisor_ids
            ],
            _inspection_context=inspection,
        )
        return self.create_round(
            workers=len(supervisor_ids),
            mode="refute",
            research_ids=supervisor_ids,
            campaign_id=campaign_id,
            host_task_scope_id=host_task_scope_id,
            research_cycle=cycle,
            _inspection_context=inspection,
        )

    def _program_math_supervision_result(
        self,
        *,
        design_round_id: str,
        design_assignment_id: str,
    ) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
        matches: list[tuple[dict[str, Any], dict[str, Any], dict[str, Any]]] = []
        pending = False
        for round_dir in sorted(self.store.rounds_dir.glob("round-*")):
            if round_dir.is_symlink() or not round_dir.is_dir():
                continue
            validated_dir, manifest = self._round_manifest(round_dir.name)
            if self.store.reasoning_modes().work_unit_abort(
                manifest["round_id"]
            ) is not None:
                continue
            cycle = manifest.get("research_cycle")
            if (
                cycle is None
                or self._validate_research_cycle_binding(cycle)["subround"]
                != "supervision"
                or cycle["source_round_id"] != design_round_id
                or "program_math" not in cycle["supervisor_scopes"]
            ):
                continue
            for assignment in manifest["assignments"]:
                source = self._research_record(assignment["research_id"])
                binding = source.get("metadata", {}).get("research_supervision")
                if binding is None:
                    continue
                binding = self._validate_research_supervision_binding(binding)
                if binding["supervisor_scope"] != "program_math" or design_assignment_id not in {
                    item["assignment_id"] for item in binding["source_receipts"]
                }:
                    continue
                try:
                    result, _receipt = self._research_product_for_assignment(
                        round_dir=validated_dir,
                        manifest=manifest,
                        assignment=assignment,
                    )
                except ValueError as exc:
                    if "worker Research product is missing" in str(exc):
                        pending = True
                        continue
                    raise
                matches.append((manifest, assignment, result))
        if len(matches) > 1:
            raise ValueError("multiple completed program-math supervision results exist")
        if not matches:
            if pending:
                raise ValueError(
                    "program-math supervision has an incomplete Research product"
                )
            raise ValueError("no program-math supervision covers this computation design")
        return matches[0]

    def _latest_supervision_disposition(
        self,
        supervision_research_id: str,
    ) -> dict[str, Any]:
        dispositions: list[dict[str, Any]] = []
        target_token = supervision_research_id.encode("ascii")
        if self.research_entries_dir.exists():
            for path in sorted(self.research_entries_dir.glob("*.json")):
                if path.is_symlink() or not path.is_file():
                    raise ValueError("research ledger contains an unsafe entry")
                raw = path.read_bytes()
                if (
                    target_token not in raw
                    or b'"kind": "disposition"' not in raw
                ):
                    continue
                record = self._research_record(path.stem)
                if (
                    record["kind"] == "disposition"
                    and record.get("metadata", {}).get("target_research_id")
                    == supervision_research_id
                ):
                    dispositions.append(record)
        if not dispositions:
            raise ValueError(
                "program-math supervision must be explicitly disposed before execution"
            )
        latest = max(
            dispositions,
            key=lambda item: (item["created_at"], item["research_id"]),
        )
        if latest["metadata"].get("disposition_status") not in (
            V5_SAFE_SUPERVISION_DISPOSITIONS
        ):
            raise ValueError(
                "latest program-math supervision disposition does not permit execution"
            )
        return latest

    def _build_approved_computation_execution_binding(
        self,
        *,
        design_manifest: dict[str, Any],
        design_descriptor: dict[str, Any],
        design_record: dict[str, Any],
        design_artifacts: list[dict[str, str]],
        supervision_manifest: dict[str, Any],
        supervision_assignment: dict[str, Any],
        supervision_return_sha256: str,
        supervision_record: dict[str, Any],
        disposition: dict[str, Any],
    ) -> dict[str, Any]:
        binding = {
            "revision": V5_APPROVED_COMPUTATION_EXECUTION_REVISION,
            "design_round_id": design_manifest["round_id"],
            "design_round_manifest_sha256": design_manifest["manifest_sha256"],
            "design_assignment_id": design_descriptor["assignment_id"],
            "design_task_card_sha256": design_descriptor["task_card_sha256"],
            "design_return_sha256": design_descriptor["return_sha256"],
            "design_research_id": design_record["research_id"],
            "design_record_sha256": design_record["record_sha256"],
            "design_artifacts": design_artifacts,
            "supervision_round_id": supervision_manifest["round_id"],
            "supervision_round_manifest_sha256": supervision_manifest[
                "manifest_sha256"
            ],
            "supervision_assignment_id": supervision_assignment["assignment_id"],
            "supervision_task_card_sha256": supervision_assignment[
                "task_card_sha256"
            ],
            "supervision_return_sha256": supervision_return_sha256,
            "supervision_research_id": supervision_record["research_id"],
            "supervision_record_sha256": supervision_record["record_sha256"],
            "disposition_research_id": disposition["research_id"],
            "disposition_record_sha256": disposition["record_sha256"],
            "disposition_status": disposition["metadata"]["disposition_status"],
            "execution_policy": "execute_exact_supervised_source_and_dependencies",
            "repair_policy": "changed_code_requires_new_production_and_supervision",
            "pulse_policy": "not_used",
            "truth_effect": "none",
        }
        return self._validate_approved_computation_execution_binding(binding)

    def create_computation_execution_round(
        self,
        source_round_id: str,
        assignment_id: str,
        *,
        host_task_scope_id: str | None = None,
    ) -> dict[str, Any]:
        """Execute only code already frozen, supervised, and safely disposed."""

        _, design_manifest_preview = self._round_manifest(source_round_id)
        design_component_id = self._source_component_id_for_assignment(
            design_manifest_preview,
            assignment_id,
        )
        supervision_manifest, supervision_assignment, supervision_record = (
            self._program_math_supervision_result(
                design_round_id=design_manifest_preview["round_id"],
                design_assignment_id=assignment_id,
            )
        )
        # A missing or blocking disposition is cheap and decisive.  Reject it
        # before rehashing the full computation design and artifact closure.
        disposition = self._latest_supervision_disposition(
            supervision_record["research_id"]
        )
        design_manifest, descriptors = self._source_round_receipt_descriptors(
            source_round_id,
            source_component_id=design_component_id,
        )
        matches = [
            item for item in descriptors if item["assignment_id"] == assignment_id
        ]
        if len(matches) != 1:
            raise ValueError("unknown computation-design assignment")
        descriptor = matches[0]
        if (
            descriptor["work_mode"] != "compute"
            or descriptor["computation_phase"] != "core_code_design"
        ):
            raise ValueError(
                "formal execution requires a first-subround core-code design return"
            )
        design_record = self._research_record(descriptor["result_research_id"])
        design_artifacts = self._canonical_design_artifacts(design_record)
        supervision_metadata = supervision_record.get("metadata", {})
        supervision_task_binding = (
            supervision_metadata.get("task_binding")
            if isinstance(supervision_metadata, dict)
            else None
        )
        supervision_return_sha256 = (
            supervision_task_binding.get("return_sha256")
            if isinstance(supervision_task_binding, dict)
            else None
        )
        if (
            not isinstance(supervision_return_sha256, str)
            or SHA256_RE.fullmatch(supervision_return_sha256) is None
        ):
            raise ValueError(
                "approved computation supervision product lacks return binding"
            )
        binding = self._build_approved_computation_execution_binding(
            design_manifest=design_manifest,
            design_descriptor=descriptor,
            design_record=design_record,
            design_artifacts=design_artifacts,
            supervision_manifest=supervision_manifest,
            supervision_assignment=supervision_assignment,
            supervision_return_sha256=supervision_return_sha256,
            supervision_record=supervision_record,
            disposition=disposition,
        )
        workload = workload_profile_for_entry(
            {
                "kind": "computation",
                "verification_plan": {"mode": "artifact_replay"},
                "budgets": {"max_wall_seconds": 0},
            }
        )
        workload["computation"]["stage_count"] = 1
        campaign_scope = design_manifest.get("campaign_scope")
        payload: dict[str, Any] = {
            "kind": "computation",
            "status": "open",
            "claim": f"Execute the exact supervised computation for: {design_record['claim']}",
            "content": (
                "Execute the frozen core source with the frozen dependency manifest. "
                "Any byte change is a new Research design and must return through "
                "program-math supervision before execution."
            ),
            "rationale": (
                "Formal computation begins only after exact code review and explicit "
                "safe disposition of the program-math supervision result."
            ),
            "source": f"research:{design_record['research_id']}",
            "relation": "executes",
            "related_research_ids": sorted(
                {
                    design_record["research_id"],
                    supervision_record["research_id"],
                    disposition["research_id"],
                }
            ),
            "approved_computation_execution": binding,
            "required_related_artifact_roles": sorted(
                V5_COMPUTATION_DESIGN_ARTIFACT_ROLES
            ),
            "logic_signals": ["formula_to_code", "program_math_hybrid"],
            "workload_profile": validate_workload_profile(workload),
            "truth_effect": "none",
        }
        if campaign_scope is not None:
            payload["campaign_id"] = campaign_scope["campaign_id"]
        execution = self.add_research(
            payload,
            actor="v5-approved-computation-planner",
            assurance_contract_revision=V5_ASSURANCE_CONTRACT_REVISION,
        )
        existing = self._existing_cycle_round_for_research(
            research_id=execution["research_id"],
            subround="production",
        )
        if existing is not None:
            return existing
        return self.create_production_round(
            workers=1,
            mode="compute",
            research_ids=[execution["research_id"]],
            campaign_id=(
                campaign_scope["campaign_id"]
                if campaign_scope is not None
                else None
            ),
            host_task_scope_id=host_task_scope_id,
        )

    def create_round(
        self,
        *,
        workers: int,
        mode: str = "auto",
        research_ids: list[str] | None = None,
        campaign_id: str | None = None,
        host_task_scope_id: str | None = None,
        background_chunk_ids: list[str] | None = None,
        frontier_target_id: str | None = None,
        research_cycle: dict[str, Any] | None = None,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any]:
        """Plan one round while keeping incomplete materialization private."""

        before = set(self.store.rounds_dir.glob(".round-*.staging-*"))
        try:
            return self._create_round_impl(
                workers=workers,
                mode=mode,
                research_ids=research_ids,
                campaign_id=campaign_id,
                host_task_scope_id=host_task_scope_id,
                background_chunk_ids=background_chunk_ids,
                frontier_target_id=frontier_target_id,
                research_cycle=research_cycle,
                _inspection_context=_inspection_context,
            )
        finally:
            after = set(self.store.rounds_dir.glob(".round-*.staging-*"))
            for path in sorted(after.difference(before)):
                if path.is_dir() and not path.is_symlink():
                    shutil.rmtree(path)

    def _create_round_impl(
        self,
        *,
        workers: int,
        mode: str = "auto",
        research_ids: list[str] | None = None,
        campaign_id: str | None = None,
        host_task_scope_id: str | None = None,
        background_chunk_ids: list[str] | None = None,
        frontier_target_id: str | None = None,
        research_cycle: dict[str, Any] | None = None,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any]:
        inspection = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert inspection is not None
        if workers < 1:
            raise ValueError("workers must be positive")
        if mode != "auto" and mode not in WORK_MODES:
            raise ValueError(f"unsupported work mode: {mode}")
        if research_cycle is not None:
            research_cycle = dict(
                self._validate_research_cycle_binding(research_cycle)
            )
            if (
                research_cycle["subround"] == "production"
                and research_cycle["revision"]
                != V5_RESEARCH_CYCLE_REVISION
            ):
                raise ValueError(
                    "new production rounds require the current logical-component "
                    "Research-cycle revision"
                )
        host_task_scope_id = normalize_host_task_scope_id(
            host_task_scope_id,
            workflow_evidence_version=5,
        )
        if frontier_target_id is not None:
            frontier_target_id = validate_campaign_target_id(
                frontier_target_id
            )
            if campaign_id is None:
                raise ValueError(
                    "--frontier-target requires an explicit Campaign"
                )
            if (
                research_cycle is None
                or research_cycle["subround"] != "production"
            ):
                raise ValueError(
                    "only production planning can advance a frontier target"
                )
        if campaign_id is not None:
            campaign_id = validate_campaign_id(campaign_id)
            # Read-only preflight keeps unknown, malformed, or currently invalid
            # Campaigns from influencing selection or creating round bytes.
            campaign_snapshot_preflight, _ = self._campaign_snapshot_for_planning(
                campaign_id,
                _inspection_context=inspection,
            )
            if frontier_target_id is not None:
                frontier_target_id = (
                    self._validate_frontier_target_in_campaign_snapshot(
                        campaign_snapshot_preflight,
                        frontier_target_id,
                    )
                )
        selected_background_chunks = _require_string_list(
            background_chunk_ids or [],
            "background chunk ids",
        )
        if len(set(selected_background_chunks)) != len(selected_background_chunks):
            raise ValueError("background chunk ids must be unique")
        if research_ids is not None:
            normalized_ids = [validate_memory_id(item) for item in research_ids]
            if len(set(normalized_ids)) != len(normalized_ids):
                raise ValueError("requested research ids must be unique")
            if workers != len(normalized_ids):
                raise ValueError(
                    "--workers must equal the number of explicit research ids"
                )
            supervision_selection = (
                research_cycle is not None
                and research_cycle["subround"] == "supervision"
            )
            production_selection = (
                research_cycle is not None
                and research_cycle["subround"] == "production"
            )
            by_id = self._explicit_research_projections(
                normalized_ids,
                campaign_id=campaign_id,
                _inspection_context=inspection,
            )
            missing: list[str] = []
            production_review_only: list[str] = []
            selected = []
            for research_id in normalized_ids:
                projection = by_id.get(research_id)
                if projection is None:
                    missing.append(research_id)
                    continue
                if production_selection and self._production_entry_is_review_only(
                    projection
                ):
                    production_review_only.append(research_id)
                    continue
                if projection["route_status"] == "current" and projection[
                    "status"
                ] in ACTIVE_MEMORY_STATUSES:
                    selected.append(projection)
                    continue
                if supervision_selection and self._supervision_review_lane_allows_stale_projection(
                    projection=projection,
                    research_cycle=research_cycle,
                ):
                    selected.append(projection)
                    continue
                missing.append(research_id)
            if production_review_only:
                raise ValueError(
                    "Research refute is reserved for subround-2 supervision; "
                    "production selection contains refute Research: "
                    + ", ".join(sorted(production_review_only))
                )
            missing = sorted(missing)
            if missing:
                scope_note = (
                    f" in Campaign {campaign_id}" if campaign_id is not None else ""
                )
                raise ValueError(
                    "not active V5 Research entries"
                    + scope_note
                    + ": "
                    + ", ".join(missing)
                )
        else:
            if (
                research_cycle is not None
                and research_cycle["subround"] == "production"
            ):
                selected = self.frontier(
                    limit=workers,
                    campaign_id=campaign_id,
                    _inspection_context=inspection,
                    _exclude_production_review_only=True,
                    _execution_records=True,
                )
            else:
                selected = self.frontier(
                    limit=workers,
                    campaign_id=campaign_id,
                    _inspection_context=inspection,
                    _execution_records=True,
                )
        if len(selected) != workers:
            scope_note = (
                f" in Campaign {campaign_id}" if campaign_id is not None else ""
            )
            raise ValueError(
                f"requested {workers} workers but only {len(selected)} active "
                f"V5 Research entries{scope_note} are available"
            )
        if research_cycle is not None and research_cycle["subround"] == "supervision":
            self._validate_supervision_round_selection(
                research_cycle=research_cycle,
                selected=selected,
                _inspection_context=inspection,
            )
        host_task_scope_id = normalize_host_task_scope_id(
            host_task_scope_id,
            workflow_evidence_version=5,
            project_id=self.store.project_id(),
            local_seed={
                "research_ids": [item["research_id"] for item in selected],
                "requested_mode": mode,
                "campaign_id": campaign_id,
                "frontier_target_id": frontier_target_id,
                "background_chunk_ids": selected_background_chunks,
                "research_cycle": research_cycle,
            },
        )
        if host_task_scope_id is None:
            raise RuntimeError("V5 local host task scope allocation returned null")

        with self.store.v5_mutation_lock(command="plan-round"):
            self._validate_selected_execution_authority_liveness(selected)
            # Re-read repair capabilities under the write boundary.  The
            # preflight inspection may reuse immutable bytes, but publication
            # must never rely on that snapshot after another writer could have
            # changed the declared inputs.
            for selected_record in selected:
                selected_metadata = selected_record.get("metadata", {})
                if not isinstance(selected_metadata, dict):
                    raise ValueError("selected Research metadata is invalid")
                self._validate_repair_input_capability_metadata(
                    kind=selected_record["kind"],
                    metadata=selected_metadata,
                )
            if (
                research_ids is None
                and research_cycle is not None
                and research_cycle["subround"] == "production"
            ):
                lock_inspection = self._bind_inspection_context(
                    RoundInspectionContext(),
                    create=True,
                )
                assert lock_inspection is not None
                fresh_envelopes = self.research_envelopes(
                    _inspection_context=lock_inspection,
                )
                (
                    fresh_bases,
                    fresh_dispositions,
                    fresh_route_staleness,
                    all_fresh_workgroups,
                    _fresh_work_keys,
                ) = self._frontier_structural_state(fresh_envelopes)
                selected_work_keys = {
                    item["work_key_sha256"] for item in selected
                }
                fresh_workgroups = {
                    work_key: all_fresh_workgroups.get(work_key, [])
                    for work_key in selected_work_keys
                }
                fresh_completion = self._frontier_group_completion(
                    workgroups=fresh_workgroups,
                    work_keys=selected_work_keys,
                    bases=fresh_bases,
                    dispositions=fresh_dispositions,
                    route_staleness=fresh_route_staleness,
                    _inspection_context=lock_inspection,
                )
                fresh_representatives = (
                    self._frontier_actionable_representatives(
                        workgroups=fresh_workgroups,
                        bases=fresh_bases,
                        dispositions=fresh_dispositions,
                        route_staleness=fresh_route_staleness,
                        campaign_id=campaign_id,
                        exclude_production_review_only=True,
                    )
                )
                changed = sorted(
                    item["research_id"]
                    for item in selected
                    if (
                        fresh_completion[item["work_key_sha256"]][0]
                        != "pending"
                        or fresh_representatives.get(item["work_key_sha256"])
                        != item["research_id"]
                    )
                )
                if changed:
                    raise ValueError(
                        "generic production frontier changed before round creation; "
                        "workgroups are no longer actionable: "
                        + ", ".join(changed)
                    )
            if (
                research_cycle is not None
                and research_cycle["subround"] == "supervision"
            ):
                existing_supervision_round_id = (
                    self._authoritative_supervision_retry_or_overlap(
                        research_cycle=research_cycle,
                        host_task_scope_id=host_task_scope_id,
                    )
                )
                if existing_supervision_round_id is not None:
                    return self.round_status(
                        existing_supervision_round_id,
                        _inspection_context=inspection,
                    )
            try:
                planned_runtime_binding = validate_runtime_binding(
                    self._runtime_binding()
                )
            except (OSError, ValueError):
                # A missing or moved runtime identity must not prevent a new
                # Research round.  The binding is optional diagnostic
                # provenance, never an execution prerequisite.
                planned_runtime_binding = None
            runtime_validation_cache: set[tuple[bool, str]] = set()
            campaign_snapshot: dict[str, Any] | None = None
            campaign_snapshot_raw: bytes | None = None
            if campaign_id is not None:
                lock_inspection = self._bind_inspection_context(
                    RoundInspectionContext(),
                    create=True,
                )
                assert lock_inspection is not None
                campaign_snapshot, campaign_snapshot_raw = (
                    self._campaign_snapshot_for_planning(
                        campaign_id,
                        _inspection_context=lock_inspection,
                    )
                )
                if frontier_target_id is not None:
                    frontier_target_id = (
                        self._validate_frontier_target_in_campaign_snapshot(
                            campaign_snapshot,
                            frontier_target_id,
                        )
                    )
                mismatched = sorted(
                    entry["research_id"]
                    for entry in selected
                    if entry["metadata"].get("campaign_id") != campaign_id
                )
                if mismatched:
                    raise ValueError(
                        "selected Research drifted outside explicit Campaign scope: "
                        + ", ".join(mismatched)
                    )
            source_records = {
                entry["research_id"]: self._inspection_research_record(
                    entry["research_id"],
                    inspection,
                )
                for entry in selected
            }
            source_dossiers = {
                research_id: self._source_research_dossier(record)
                for research_id, record in source_records.items()
            }
            literal_reference_ids = {
                research_id: self._resolvable_literal_research_reference_ids(
                    record,
                    _inspection_context=inspection,
                )
                for research_id, record in source_records.items()
            }
            authority_snapshots = {
                research_id: self._task_authority_snapshot(
                    record,
                    _inspection_context=inspection,
                )
                for research_id, record in source_records.items()
            }
            typed_artifacts_by_research: dict[
                str, list[dict[str, str]]
            ] = {}
            for research_id, record in source_records.items():
                typed_artifacts = self._typed_research_artifacts(
                    record,
                    _inspection_context=inspection,
                )
                # Validate the repair-specific path/SHA/role closure before a
                # staging round directory or any other round byte is created.
                self._validate_repair_task_capability_closure(
                    record=record,
                    related_artifacts=typed_artifacts,
                    _inspection_context=inspection,
                )
                typed_artifacts_by_research[research_id] = typed_artifacts
                if (
                    self._research_is_source_dependent(record)
                    and not typed_artifacts
                    and not authority_snapshots[research_id]["capabilities"]
                ):
                    raise ValueError(
                        "source-dependent Research cannot be planned without an exact "
                        "project-relative path/SHA-256/role artifact capability; append "
                        "a current-assurance Research successor instead of trusting prose"
                    )
            background_raw = read_project_background(self.store.root)
            if background_raw is None:
                if selected_background_chunks:
                    raise ValueError(
                        "background chunk ids require PROJECT_BACKGROUND.md"
                    )
            else:
                available_background_chunks = {
                    item["chunk_id"]
                    for item in build_background_index(background_raw)["chunks"]
                }
                unknown_background_chunks = sorted(
                    set(selected_background_chunks).difference(
                        available_background_chunks
                    )
                )
                if unknown_background_chunks:
                    raise ValueError(
                        "unknown PROJECT_BACKGROUND.md chunk ids: "
                        + ", ".join(unknown_background_chunks)
                    )
            mode_selections = {
                entry["research_id"]: self._mode_selection(
                    entry,
                    requested_mode=mode,
                    index=index,
                    research_cycle=research_cycle,
                )
                for index, entry in enumerate(selected)
            }
            if (
                research_cycle is not None
                and research_cycle["subround"] == "production"
            ):
                refute_ids = sorted(
                    research_id
                    for research_id, selection in mode_selections.items()
                    if selection["selected_mode"] == "refute"
                )
                if refute_ids:
                    raise ValueError(
                        "Research refute is reserved for subround-2 supervision; "
                        "production selection contains refute Research: "
                        + ", ".join(refute_ids)
                    )
                for entry in selected:
                    selected_mode = mode_selections[entry["research_id"]][
                        "selected_mode"
                    ]
                    if self._computation_design_only(
                        entry=entry,
                        work_mode=selected_mode,
                        research_cycle=research_cycle,
                    ):
                        validate_computation_design_role_contract(
                            entry["metadata"].get("obligations", [])
                        )
            snapshot, blackboard_selection = self._snapshot_for_round(selected)
            stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
            round_id = (
                f"round-{stamp}-"
                f"{sha256_json([[item['research_id'] for item in selected], time.time_ns()])[:8]}"
            )
            validate_round_id(round_id)
            primary_specs: list[dict[str, Any]] = []
            paired_specs: list[dict[str, Any]] = []
            pair_records: list[dict[str, Any]] = []
            pair_candidates: list[tuple[dict[str, Any], dict[str, Any], str]] = []
            for index, entry in enumerate(selected, 1):
                primary_mode_selection = mode_selections[entry["research_id"]]
                primary_mode = primary_mode_selection["selected_mode"]
                primary_assignment_id = (
                    f"a{index:02d}-{entry['research_id']}-{primary_mode}"
                )
                validate_assignment_id(primary_assignment_id)
                primary_spec = {
                    "entry": entry,
                    "mode_selection": primary_mode_selection,
                    "work_mode": primary_mode,
                    "assignment_id": primary_assignment_id,
                    "assignment_role": "primary",
                    "pair_binding": None,
                }
                primary_specs.append(primary_spec)
                if (
                    not (
                        research_cycle is not None
                        and research_cycle["subround"] == "production"
                    )
                    and independent_adverse_pair_is_required(
                        entry,
                        primary_work_mode=primary_mode,
                    )
                ):
                    pair_candidates.append(
                        (entry, primary_spec, primary_assignment_id)
                    )
            if len(primary_specs) + len(pair_candidates) > 99:
                raise ValueError(
                    "V5 primary plus paired adverse assignments exceed the two-digit "
                    "assignment-id capacity"
                )
            for pair_index, (
                entry,
                primary_spec,
                primary_assignment_id,
            ) in enumerate(pair_candidates, len(primary_specs) + 1):
                adverse_assignment_id = (
                    f"a{pair_index:02d}-{entry['research_id']}-refute"
                )
                validate_assignment_id(adverse_assignment_id)
                handoff = build_paired_proof_philosophy_attack_handoff(
                    research_id=entry["research_id"],
                    round_id=round_id,
                    primary_assignment_id=primary_assignment_id,
                    adverse_assignment_id=adverse_assignment_id,
                )
                validate_independent_adverse_pair(
                    handoff["pair"],
                    primary_binding=handoff["primary_binding"],
                    adverse_binding=handoff["adverse_binding"],
                )
                primary_spec["pair_binding"] = handoff["primary_binding"]
                pair_records.append(handoff["pair"])
                paired_specs.append(
                    {
                        "entry": entry,
                        "mode_selection": self._mode_selection(
                            entry,
                            requested_mode="refute",
                            index=pair_index - 1,
                            research_cycle=research_cycle,
                        ),
                        "work_mode": "refute",
                        "assignment_id": adverse_assignment_id,
                        "assignment_role": "paired_adverse",
                        "pair_binding": handoff["adverse_binding"],
                    }
                )
            work_specs = [*primary_specs, *paired_specs]
            campaign_scope: dict[str, Any] | None = None
            campaign_snapshot_relpath: str | None = None
            if campaign_snapshot is not None and campaign_snapshot_raw is not None:
                campaign_snapshot_relpath = (
                    f"rounds/{round_id}/context/campaign.snapshot.json"
                )
                campaign_scope = self._campaign_scope_from_snapshot(
                    campaign_snapshot,
                    snapshot_relpath=campaign_snapshot_relpath,
                    snapshot_sha256=sha256_bytes(campaign_snapshot_raw),
                )
            selection_receipt: dict[str, Any] | None = None
            if (
                research_cycle is not None
                and research_cycle["subround"] == "production"
            ):
                selection_receipt = self._plan_round_selection_receipt(
                    selected_research_ids=[
                        item["research_id"] for item in selected
                    ],
                    research_ids_were_explicit=research_ids is not None,
                    campaign_id=campaign_id,
                    requested_mode=mode,
                    frontier_target_id=frontier_target_id,
                )
            final_round_dir = self.store.rounds_dir / round_id
            round_dir = self.store.rounds_dir / (
                f".{round_id}.staging-"
                f"{sha256_json([round_id, time.time_ns(), os.getpid()])[:12]}"
            )
            assignments_dir = round_dir / "assignments"
            task_cards_dir = round_dir / "task-cards"
            returns_dir = round_dir / "returns"
            artifacts_dir = round_dir / "artifacts"
            work_dir = round_dir / "work"
            context_dir = round_dir / "context"
            for directory in (
                assignments_dir,
                task_cards_dir,
                returns_dir,
                artifacts_dir,
                work_dir,
                context_dir,
            ):
                directory.mkdir(parents=True, exist_ok=False)
            if (
                campaign_snapshot_raw is not None
                and campaign_snapshot_relpath is not None
            ):
                self.store._write_bytes_once(
                    context_dir / "campaign.snapshot.json",
                    campaign_snapshot_raw,
                )
            project_background = self._freeze_project_background(
                round_id=round_id,
                raw=background_raw,
                selected_chunk_ids=selected_background_chunks,
                _materialized_round_dir=round_dir,
            )

            mode_status = self.store.reasoning_modes().status()
            reasoning_binding = {
                "reasoning_mode": mode_status["reasoning_mode"],
                "reasoning_mode_event_id": mode_status[
                    "reasoning_mode_event_id"
                ],
                "reasoning_mode_policy_sha256": mode_status[
                    "reasoning_mode_policy_sha256"
                ],
                "fact_admission_contract_sha256": mode_status[
                    "fact_admission_contract_sha256"
                ],
                "effect": "future_research_budget_only",
            }
            explicit_blackboard_writes = any(
                bool(
                    work_spec["entry"]["metadata"].get(
                        "blackboard_write_space_ids", []
                    )
                )
                for work_spec in work_specs
            )
            all_nodes: dict[str, dict[str, Any]] = {}
            snapshot_nodes, _ = self.store.blackboard().snapshot_objects(
                snapshot["snapshot_id"]
            )
            if explicit_blackboard_writes:
                all_nodes = self.store.blackboard().nodes()
            assignments: list[dict[str, Any]] = []
            for work_spec in work_specs:
                entry = work_spec["entry"]
                mode_selection = work_spec["mode_selection"]
                work_mode = work_spec["work_mode"]
                assignment_id = work_spec["assignment_id"]
                assignment_role = work_spec["assignment_role"]
                pair_binding = work_spec["pair_binding"]
                worker_context_id = (
                    pair_binding["worker_context_id"]
                    if pair_binding is not None
                    else "hostctx-"
                    + sha256_json(
                        {
                            "namespace": "chalxius-v5-worker-context-1",
                            "round_id": round_id,
                            "assignment_id": assignment_id,
                        }
                    )
                )
                prompt_relpath = f"rounds/{round_id}/assignments/{assignment_id}.md"
                task_card_relpath = f"rounds/{round_id}/task-cards/{assignment_id}.json"
                # Keep the historical worker return contract stable.  The
                # terminal seal is a separate immutable projection, so a
                # current assignment does not need to change the path that
                # existing worker/orchestrator code writes.
                return_relpath = f"rounds/{round_id}/returns/{assignment_id}.json"
                artifact_dir_relpath = f"rounds/{round_id}/artifacts/{assignment_id}"
                work_dir_relpath = f"rounds/{round_id}/work/{assignment_id}"
                # Materialize assignment-owned writer roots before dispatch.
                # Terminalization can then revoke directory writes and atomic
                # replacement instead of leaving a stale worker able to
                # recreate a path after ingest.
                (artifacts_dir / assignment_id).mkdir(exist_ok=False)
                (work_dir / assignment_id).mkdir(exist_ok=False)
                requested_spaces = entry["metadata"].get(
                    "blackboard_write_space_ids"
                )
                if requested_spaces is None:
                    requested_spaces = []
                write_spaces = _require_string_list(
                    requested_spaces, "research Blackboard write spaces"
                )
                for space_id in write_spaces:
                    if (
                        all_nodes.get(space_id, {}).get("node_type") != "space"
                        or space_id not in snapshot_nodes
                    ):
                        raise ValueError(
                            "research Blackboard write spaces must name spaces in the "
                            "frozen snapshot"
                        )
                obligations = entry["metadata"].get("obligations", [])
                if not isinstance(obligations, list) or any(
                    not isinstance(item, dict) for item in obligations
                ):
                    raise ValueError("research obligations must be objects")
                stop_conditions = _require_string_list(
                    entry["metadata"].get("stop_conditions", []),
                    "research stop conditions",
                )
                convention_ids = _require_string_list(
                    entry["metadata"].get("convention_profile_ids", []),
                    "research convention profile ids",
                )
                for convention_id in convention_ids:
                    self.store.claims().show_convention(convention_id)
                source_claim_id = entry["metadata"].get("source_claim_id")
                if source_claim_id is not None:
                    if not isinstance(source_claim_id, str):
                        raise ValueError("research source claim id must be a string")
                    self.store.claims().show_claim(source_claim_id)
                campaign_id = entry["metadata"].get("campaign_id")
                if campaign_id is not None:
                    if not isinstance(campaign_id, str):
                        raise ValueError("research campaign id must be a string")
                    self.store.campaigns().status(campaign_id)
                requested_relation = entry["metadata"].get(
                    "goal_relation", "proves"
                )
                if requested_relation not in CLAIM_RELATIONS:
                    raise ValueError("research goal relation is invalid")
                predecessor_interfaces = [
                    self.store.statement_interface(
                        fact_id, materialize=False
                    )
                    for fact_id in entry["dependencies"]
                ]
                research_context = []
                related_artifacts: list[dict[str, str]] = []
                related_artifacts.extend(
                    typed_artifacts_by_research[entry["research_id"]]
                )
                context_research_ids = sorted(
                    set(entry["related_research_ids"]).union(
                        literal_reference_ids[entry["research_id"]]
                    )
                )
                for related_id in context_research_ids:
                    related_record = self._inspection_research_record(
                        related_id,
                        inspection,
                    )
                    research_context.append(
                        {
                            key: related_record[key]
                            for key in (
                                "research_id",
                                "record_sha256",
                                "kind",
                                "status",
                                "claim",
                                "content",
                                "rationale",
                                "actor",
                            )
                        }
                    )
                    related_artifacts.extend(
                        self._typed_research_artifacts(
                            related_record,
                            _inspection_context=inspection,
                        )
                    )
                deduplicated_related_artifacts: dict[
                    tuple[str, str], dict[str, str]
                ] = {}
                for artifact in related_artifacts:
                    key = (artifact["source_research_id"], artifact["role"])
                    existing = deduplicated_related_artifacts.get(key)
                    if existing is not None and existing != artifact:
                        raise ValueError(
                            "Research artifact capability role has conflicting bytes"
                        )
                    deduplicated_related_artifacts[key] = artifact
                related_artifacts = sorted(
                    deduplicated_related_artifacts.values(),
                    key=lambda item: (
                        item["source_research_id"],
                        item["role"],
                        item["sha256"],
                    ),
                )
                required_related_roles = _require_string_list(
                    entry["metadata"].get(
                        "required_related_artifact_roles", []
                    ),
                    "research required related artifact roles",
                )
                available_unqualified_roles = {
                    item["role"].split(":", 1)[-1]
                    for item in related_artifacts
                }
                missing_related_roles = sorted(
                    set(required_related_roles).difference(
                        available_unqualified_roles
                    )
                )
                if missing_related_roles:
                    raise ValueError(
                        "Research work requires capability-bound related artifacts: "
                        + ", ".join(missing_related_roles)
                    )
                adverse_routing = self.store.adverse_routes().task_card_binding(
                    entry=entry,
                    work_mode=work_mode,
                    related_artifacts=related_artifacts,
                )
                assurance_contract = build_assurance_contract(
                    entry=entry,
                    obligations=obligations,
                    work_mode=work_mode,
                    related_artifacts=related_artifacts,
                    computation_design_only=self._computation_design_only(
                        entry=entry,
                        work_mode=work_mode,
                        research_cycle=research_cycle,
                    ),
                )
                context_selection = self._context_selection_binding(
                    blackboard_selection=blackboard_selection,
                    project_background=project_background,
                    mode_selection=mode_selection,
                )
                paper_continuation_scope = (
                    self._inspection_paper_continuation_scope(
                        entry,
                        inspection,
                    )
                )
                card_semantic = {
                    "schema_version": 5,
                    "policy_revision": V5_POLICY_REVISION,
                    "task_context_revision": V5_TASK_CONTEXT_REVISION,
                    "runtime_binding": planned_runtime_binding,
                    "context_selection": context_selection,
                    "project_id": self.store.project_id(),
                    "round_id": round_id,
                    "assignment_id": assignment_id,
                    "worker_id": assignment_id,
                    "research_id": entry["research_id"],
                    "work_mode": work_mode,
                    "requested_claim_relation": requested_relation,
                    "source_claim_id": source_claim_id,
                    "convention_profile_ids": convention_ids,
                    "campaign_id": campaign_id,
                    "control_plane": {
                        "plane": "control",
                        "prompt_relpath": prompt_relpath,
                        "allowed_followups": [
                            "continue",
                            "clarify_control",
                            "stop",
                        ],
                        "final_handoff_fields": [
                            "assignment_id",
                            "status",
                        ],
                        "host_task_scope_id": host_task_scope_id,
                        "worker_context_id": worker_context_id,
                        "assignment_role": assignment_role,
                        "independent_adverse_pair": pair_binding,
                    },
                    "mathematical_state": {
                        "plane": "mathematical_state",
                        "blackboard_snapshot_id": snapshot["snapshot_id"],
                        "blackboard_snapshot_sha256": snapshot[
                            "snapshot_sha256"
                        ],
                        "predecessor_interfaces": predecessor_interfaces,
                        "source_research_dossier": source_dossiers[
                            entry["research_id"]
                        ],
                        "research_reference_revision": (
                            V5_EXACT_RESEARCH_REFERENCE_REVISION
                        ),
                        "literal_research_reference_ids": (
                            literal_reference_ids[entry["research_id"]]
                        ),
                        "research_context": research_context,
                        "related_artifacts": related_artifacts,
                        "authority_snapshot": authority_snapshots[
                            entry["research_id"]
                        ],
                        "project_background": project_background,
                        "read_space_ids": sorted(
                            node_id
                            for node_id, node in snapshot_nodes.items()
                            if node.get("node_type") == "space"
                        ),
                        "write_space_ids": write_spaces,
                    },
                    "blackboard_view": {
                        "snapshot_id": snapshot["snapshot_id"],
                        "snapshot_sha256": snapshot["snapshot_sha256"],
                    },
                    "narrative_plane": {
                        "plane": "narrative",
                        "claim": entry["claim"],
                        "rationale": entry["rationale"],
                        "summary_word_cap": 400,
                        "intuition_word_cap": 400,
                        "limitations_word_cap": 400,
                    },
                    "obligations": assurance_contract["obligations"],
                    "stop_conditions": stop_conditions,
                    "artifact_capability": {
                        "artifact_dir_relpath": artifact_dir_relpath,
                        "work_dir_relpath": work_dir_relpath,
                        "max_files": 256,
                        "max_file_bytes": 16 * 1024 * 1024,
                        "max_total_bytes": 64 * 1024 * 1024,
                    },
                    "return_contract": {
                        "return_relpath": return_relpath,
                        "allowed_outcomes": sorted(V5_RETURN_OUTCOMES),
                        "hash_contract": (
                            "sha256_of_exact_return_bytes_derived_by_canonical_ingestion"
                        ),
                    },
                    "reasoning_mode_binding": reasoning_binding,
                    "assurance_contract": assurance_contract,
                }
                if adverse_routing is not None:
                    card_semantic["adverse_routing"] = adverse_routing
                if research_cycle is not None:
                    card_semantic["research_cycle"] = research_cycle
                if campaign_scope is not None:
                    card_semantic["campaign_scope"] = campaign_scope
                if paper_continuation_scope is not None:
                    card_semantic["paper_continuation_scope"] = (
                        paper_continuation_scope
                    )
                card = {
                    **card_semantic,
                    "task_card_semantic_sha256": sha256_json(card_semantic),
                }
                card_path = task_cards_dir / f"{assignment_id}.json"
                self.store._write_json_once(card_path, card)
                self.validate_task_card(
                    card,
                    expected_path=card_path,
                    _runtime_validation_cache=runtime_validation_cache,
                    _materialized_round_dir=round_dir,
                )
                task_card_sha = sha256_bytes(card_path.read_bytes())
                prompt = self._compact_prompt(
                    card=card, task_card_sha256=task_card_sha
                )
                prompt_path = assignments_dir / f"{assignment_id}.md"
                self.store._write_text_atomic(prompt_path, prompt)
                writer_lease_id = self._writer_lease_id(
                    round_id=round_id,
                    assignment_id=assignment_id,
                    task_card_sha256=task_card_sha,
                    worker_context_id=worker_context_id,
                    host_task_scope_id=host_task_scope_id,
                )
                assignment_semantic = {
                    "assignment_id": assignment_id,
                    "research_id": entry["research_id"],
                    "worker_id": assignment_id,
                    "work_mode": work_mode,
                    "prompt_relpath": prompt_relpath,
                    "prompt_sha256": sha256_bytes(prompt_path.read_bytes()),
                    "task_card_relpath": task_card_relpath,
                    "task_card_sha256": task_card_sha,
                    "return_relpath": return_relpath,
                    "artifact_dir_relpath": artifact_dir_relpath,
                    "work_dir_relpath": work_dir_relpath,
                    "blackboard_snapshot_id": snapshot["snapshot_id"],
                    "blackboard_snapshot_sha256": snapshot["snapshot_sha256"],
                    "host_task_scope_id": host_task_scope_id,
                    "worker_context_id": worker_context_id,
                    "assignment_role": assignment_role,
                    "independent_adverse_pair": pair_binding,
                    "terminal_seal_revision": V5_TERMINAL_SEAL_REVISION,
                    "writer_lease_id": writer_lease_id,
                }
                assignment = {
                    **assignment_semantic,
                    "assignment_sha256": sha256_json(assignment_semantic),
                }
                self.store._write_json_once(
                    assignments_dir / f"{assignment_id}.json", assignment
                )
                assignments.append(assignment)
            supervision_components: list[dict[str, Any]] | None = None
            if (
                research_cycle is not None
                and research_cycle["subround"] == "production"
                and research_cycle["revision"] == V5_RESEARCH_CYCLE_REVISION
            ):
                supervision_components = (
                    self._build_logical_supervision_components(
                        assignments=assignments,
                        source_records=source_records,
                    )
                )
            manifest_semantic = {
                "schema_version": 5,
                "policy_revision": V5_POLICY_REVISION,
                "project_id": self.store.project_id(),
                "round_id": round_id,
                "created_at": _utc_now(),
                "blackboard_snapshot_id": snapshot["snapshot_id"],
                "blackboard_snapshot_sha256": snapshot["snapshot_sha256"],
                "reasoning_mode_binding": reasoning_binding,
                "contribution_policy": "independent_ingest_local_quarantine",
                "assignment_contract_revision": (
                    (
                        V5_PRODUCTION_ALLOCATION_REVISION
                        if research_cycle["revision"]
                        == V5_RESEARCH_CYCLE_REVISION
                        else V5_LEGACY_PRODUCTION_ALLOCATION_REVISION
                    )
                    if research_cycle is not None
                    and research_cycle["subround"] == "production"
                    else V5_LEGACY_ADVERSE_ALLOCATION_REVISION
                ),
                "host_task_scope_id": host_task_scope_id,
                "primary_worker_count": workers,
                "independent_adverse_pairs": pair_records,
                "assignments": assignments,
            }
            if campaign_scope is not None:
                manifest_semantic["campaign_scope"] = campaign_scope
            if research_cycle is not None:
                manifest_semantic["research_cycle"] = research_cycle
            if selection_receipt is not None:
                manifest_semantic["selection_receipt"] = selection_receipt
            if supervision_components is not None:
                manifest_semantic["supervision_components"] = (
                    supervision_components
                )
            manifest = {
                **manifest_semantic,
                "manifest_sha256": sha256_json(manifest_semantic),
            }
            self.store._write_json_once(round_dir / "round.json", manifest)
            if final_round_dir.exists() or final_round_dir.is_symlink():
                raise ValueError("V5 round target already exists")
            if frontier_target_id is not None:
                assert campaign_id is not None
                self._advance_campaign_frontier_for_plan(
                    campaign_id=campaign_id,
                    frontier_target_id=frontier_target_id,
                    selected_research_ids=[
                        item["research_id"]
                        for item in assignments
                        if item.get("assignment_role") != "paired_adverse"
                    ],
                    inspection=lock_inspection,
                )
            os.replace(round_dir, final_round_dir)
        # The planning context may already contain a read-only frontier/round
        # projection from selection.  The newly published round is a mutation
        # boundary, so no cached negative completion or round index may cross
        # it into the returned status.
        inspection.research_product_bindings.clear()
        inspection.frontier_group_completions.clear()
        inspection.frontier_group_actions.clear()
        inspection.frontier_cow_terminal_members.clear()
        inspection.frontier_completion_statuses.clear()
        inspection.round_completed.clear()
        inspection.round_statuses.clear()
        inspection.round_manifests.clear()
        inspection.supervision_manifests_by_production_round.clear()
        inspection.completion_obligation_rounds = None
        inspection.supervision_round_ids_by_production_round = None
        return self.round_status(
            round_id,
            _inspection_context=inspection,
        )

    def _round_manifest(
        self,
        round_id: str,
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> tuple[Path, dict[str, Any]]:
        inspection = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert inspection is not None
        round_id = validate_round_id(round_id)
        cached = inspection.round_manifests.get(round_id)
        if cached is not None:
            return cached
        round_dir = self.store.rounds_dir / round_id
        path = round_dir / "round.json"
        if path.is_symlink() or not path.is_file():
            raise KeyError(f"unknown V5 round: {round_id}")
        manifest = self.store._read_json(path)
        required = {
            "schema_version",
            "policy_revision",
            "project_id",
            "round_id",
            "created_at",
            "blackboard_snapshot_id",
            "blackboard_snapshot_sha256",
            "reasoning_mode_binding",
            "contribution_policy",
            "assignments",
            "manifest_sha256",
        }
        if "campaign_scope" in manifest:
            required.add("campaign_scope")
        if "research_cycle" in manifest:
            required.add("research_cycle")
        if "selection_receipt" in manifest:
            required.add("selection_receipt")
        if "supervision_components" in manifest:
            required.add("supervision_components")
        current_allocation_fields = {
            "assignment_contract_revision",
            "host_task_scope_id",
            "primary_worker_count",
            "independent_adverse_pairs",
        }
        if set(manifest).intersection(current_allocation_fields):
            required.update(current_allocation_fields)
        if set(manifest) != required:
            raise ValueError("V5 round manifest fields are not exact")
        if (
            manifest.get("schema_version") != 5
            or manifest.get("policy_revision") != V5_POLICY_REVISION
            or manifest.get("project_id") != self.store.project_id()
            or manifest.get("round_id") != round_id
            or manifest.get("contribution_policy")
            != "independent_ingest_local_quarantine"
        ):
            raise ValueError("V5 round schema/policy/project/id mismatch")
        semantic = {
            key: value
            for key, value in manifest.items()
            if key != "manifest_sha256"
        }
        if manifest.get("manifest_sha256") != sha256_json(semantic):
            raise ValueError("V5 round manifest hash mismatch")
        campaign_scope = manifest.get("campaign_scope")
        if campaign_scope is not None:
            campaign_scope = self._validate_campaign_scope_binding(
                campaign_scope,
                round_id=round_id,
                _inspection_context=inspection,
            )
        research_cycle = manifest.get("research_cycle")
        if research_cycle is not None:
            research_cycle = self._validate_research_cycle_binding(
                research_cycle
            )
        abort = self.store.reasoning_modes().work_unit_abort(round_id)
        assignments = manifest.get("assignments")
        if not isinstance(assignments, list) or not assignments:
            raise ValueError("V5 round assignments must be nonempty")
        selection_receipt = manifest.get("selection_receipt")
        if selection_receipt is not None:
            if (
                research_cycle is None
                or research_cycle["subround"] != "production"
            ):
                raise ValueError(
                    "plan-round selection receipt requires a production round"
                )
            selection_receipt = self._validate_plan_round_selection_receipt(
                selection_receipt,
                assignments=assignments,
                campaign_scope=campaign_scope,
            )
        current_allocation = "assignment_contract_revision" in manifest
        pair_records: list[dict[str, Any]] = []
        if current_allocation:
            if (
                manifest["assignment_contract_revision"]
                not in {
                    V5_LEGACY_ADVERSE_ALLOCATION_REVISION,
                    V5_LEGACY_PRODUCTION_ALLOCATION_REVISION,
                    V5_PRODUCTION_ALLOCATION_REVISION,
                }
                or not isinstance(manifest["host_task_scope_id"], str)
                or HOST_TASK_SCOPE_ID_RE.fullmatch(
                    manifest["host_task_scope_id"]
                )
                is None
                or isinstance(manifest["primary_worker_count"], bool)
                or not isinstance(manifest["primary_worker_count"], int)
                or manifest["primary_worker_count"] < 1
                or manifest["primary_worker_count"] > len(assignments)
                or not isinstance(manifest["independent_adverse_pairs"], list)
            ):
                raise ValueError("V5 round adverse-allocation contract is invalid")
            seen_pair_ids: set[str] = set()
            for pair in manifest["independent_adverse_pairs"]:
                validated_pair = validate_independent_adverse_pair(pair)
                if validated_pair["pair_id"] in seen_pair_ids:
                    raise ValueError("V5 round duplicates an independent adverse pair")
                seen_pair_ids.add(validated_pair["pair_id"])
                pair_records.append(validated_pair)
        seen: set[str] = set()
        frozen_cards: list[tuple[Path, dict[str, Any]]] = []
        for assignment in assignments:
            if not isinstance(assignment, dict):
                raise ValueError("V5 round assignment must be an object")
            assignment_id = validate_assignment_id(
                _require_nonempty_text(
                    assignment.get("assignment_id"), "V5 assignment id"
                )
            )
            if assignment_id in seen:
                raise ValueError("V5 round assignment ids must be unique")
            seen.add(assignment_id)
            if current_allocation:
                assignment_fields = {
                    "assignment_id",
                    "research_id",
                    "worker_id",
                    "work_mode",
                    "prompt_relpath",
                    "prompt_sha256",
                    "task_card_relpath",
                    "task_card_sha256",
                    "return_relpath",
                    "artifact_dir_relpath",
                    "work_dir_relpath",
                    "blackboard_snapshot_id",
                    "blackboard_snapshot_sha256",
                    "host_task_scope_id",
                    "worker_context_id",
                    "assignment_role",
                    "independent_adverse_pair",
                    "assignment_sha256",
                }
                if "terminal_seal_revision" in assignment:
                    assignment_fields.add("terminal_seal_revision")
                if "writer_lease_id" in assignment:
                    assignment_fields.add("writer_lease_id")
                if (
                    ("terminal_seal_revision" in assignment)
                    != ("writer_lease_id" in assignment)
                ):
                    raise ValueError(
                        "current terminal assignments must bind exactly one writer lease"
                    )
                if set(assignment) != assignment_fields:
                    raise ValueError(
                        "current V5 assignment allocation fields are not exact"
                    )
                if (
                    assignment["host_task_scope_id"]
                    != manifest["host_task_scope_id"]
                    or assignment["assignment_role"]
                    not in {"primary", "paired_adverse"}
                    or not isinstance(assignment["worker_context_id"], str)
                    or not assignment["worker_context_id"].strip()
                ):
                    raise ValueError("V5 assignment host/context/role binding is invalid")
                if (
                    "terminal_seal_revision" in assignment
                    and assignment["terminal_seal_revision"]
                    != V5_TERMINAL_SEAL_REVISION
                ):
                    raise ValueError("V5 assignment terminal-seal revision is invalid")
                if "terminal_seal_revision" in assignment:
                    self._validate_writer_lease_id(
                        assignment.get("writer_lease_id"),
                        round_id=round_dir.name,
                        assignment_id=assignment_id,
                        task_card_sha256=assignment["task_card_sha256"],
                        worker_context_id=assignment["worker_context_id"],
                        host_task_scope_id=assignment["host_task_scope_id"],
                    )
            assignment_semantic = {
                key: value
                for key, value in assignment.items()
                if key != "assignment_sha256"
            }
            if assignment.get("assignment_sha256") != sha256_json(
                assignment_semantic
            ):
                raise ValueError("V5 assignment hash mismatch")
            sidecar = round_dir / "assignments" / f"{assignment_id}.json"
            if (
                sidecar.is_symlink()
                or not sidecar.is_file()
                or self.store._read_json(sidecar) != assignment
            ):
                raise ValueError("V5 assignment sidecar is missing or mismatched")
            card_path = contained_path(
                self.store.root,
                assignment["task_card_relpath"],
                "V5 task card path",
            )
            if (
                card_path.is_symlink()
                or not card_path.is_file()
                or sha256_bytes(card_path.read_bytes())
                != assignment["task_card_sha256"]
            ):
                raise ValueError("V5 task card bytes/hash mismatch")
            frozen_card = self.store._read_json(card_path)
            if current_allocation:
                control = frozen_card.get("control_plane", {})
                if (
                    control.get("host_task_scope_id")
                    != assignment["host_task_scope_id"]
                    or control.get("worker_context_id")
                    != assignment["worker_context_id"]
                    or control.get("assignment_role")
                    != assignment["assignment_role"]
                    or control.get("independent_adverse_pair")
                    != assignment["independent_adverse_pair"]
                ):
                    raise ValueError(
                        "V5 assignment/task-card adverse allocation projections disagree"
                    )
            frozen_cards.append((card_path, frozen_card))
            prompt_path = contained_path(
                self.store.root,
                assignment["prompt_relpath"],
                "V5 prompt path",
            )
            if (
                prompt_path.is_symlink()
                or not prompt_path.is_file()
                or sha256_bytes(prompt_path.read_bytes())
                != assignment["prompt_sha256"]
            ):
                raise ValueError("V5 prompt bytes/hash mismatch")
        if current_allocation:
            assignment_by_id = {
                item["assignment_id"]: item for item in assignments
            }
            card_by_assignment = {
                card["assignment_id"]: card for _, card in frozen_cards
            }
            primary_assignments = [
                item for item in assignments if item["assignment_role"] == "primary"
            ]
            paired_assignments = [
                item
                for item in assignments
                if item["assignment_role"] == "paired_adverse"
            ]
            if len(primary_assignments) != manifest["primary_worker_count"]:
                raise ValueError("V5 workers count must count primary assignments only")
            if len(paired_assignments) != len(pair_records):
                raise ValueError("V5 paired adverse assignment count drifted")
            pair_by_id = {item["pair_id"]: item for item in pair_records}
            for pair in pair_records:
                primary_assignment = assignment_by_id.get(
                    pair["primary_assignment_id"]
                )
                adverse_assignment = assignment_by_id.get(
                    pair["adverse_assignment_id"]
                )
                if primary_assignment is None or adverse_assignment is None:
                    raise ValueError("V5 independent adverse pair assignment is missing")
                validate_independent_adverse_pair(
                    pair,
                    primary_binding=primary_assignment[
                        "independent_adverse_pair"
                    ],
                    adverse_binding=adverse_assignment[
                        "independent_adverse_pair"
                    ],
                )
                if (
                    primary_assignment["assignment_role"] != "primary"
                    or adverse_assignment["assignment_role"] != "paired_adverse"
                    or primary_assignment["research_id"] != pair["research_id"]
                    or adverse_assignment["research_id"] != pair["research_id"]
                    or adverse_assignment["work_mode"] != "refute"
                ):
                    raise ValueError("V5 independent adverse pair role/mode drifted")
            for primary_assignment in primary_assignments:
                card = card_by_assignment[primary_assignment["assignment_id"]]
                source = self._inspection_research_record(
                    primary_assignment["research_id"], inspection
                )
                supervision_only_production = (
                    manifest["assignment_contract_revision"]
                    in {
                        V5_LEGACY_PRODUCTION_ALLOCATION_REVISION,
                        V5_PRODUCTION_ALLOCATION_REVISION,
                    }
                )
                if supervision_only_production and (
                    research_cycle is None
                    or research_cycle["subround"] != "production"
                    or primary_assignment["work_mode"] == "refute"
                ):
                    raise ValueError(
                        "V5 supervision-only allocation is not a constructive "
                        "production subround"
                    )
                required_pair = (
                    False
                    if supervision_only_production
                    else independent_adverse_pair_is_required(
                        source,
                        primary_work_mode=primary_assignment["work_mode"],
                    )
                )
                binding = primary_assignment["independent_adverse_pair"]
                if required_pair != (binding is not None):
                    raise ValueError(
                        "V5 required independent adverse dispatch is missing or spurious"
                    )
                if binding is not None and binding["pair_id"] not in pair_by_id:
                    raise ValueError("V5 primary names an unknown adverse pair")
                if card["control_plane"]["independent_adverse_pair"] != binding:
                    raise ValueError("V5 primary pair card binding drifted")
        if (
            research_cycle is not None
            and research_cycle["subround"] == "production"
            and research_cycle["revision"] == V5_RESEARCH_CYCLE_REVISION
        ):
            if (
                manifest.get("assignment_contract_revision")
                != V5_PRODUCTION_ALLOCATION_REVISION
            ):
                raise ValueError(
                    "component-aware production allocation revision drifted"
                )
            self._validate_logical_supervision_components(
                manifest.get("supervision_components"),
                assignments=assignments,
                _inspection_context=inspection,
            )
        elif (
            research_cycle is not None
            and research_cycle["subround"] == "production"
            and research_cycle["revision"]
            == V5_LEGACY_RESEARCH_CYCLE_REVISION
        ):
            if (
                manifest.get("assignment_contract_revision")
                not in {
                    V5_LEGACY_ADVERSE_ALLOCATION_REVISION,
                    V5_LEGACY_PRODUCTION_ALLOCATION_REVISION,
                }
            ):
                raise ValueError(
                    "legacy production allocation revision drifted"
                )
            if "supervision_components" in manifest:
                raise ValueError(
                    "legacy production rounds cannot carry logical components"
                )
        elif (
            research_cycle is not None
            and research_cycle["subround"] == "supervision"
        ):
            if (
                manifest.get("assignment_contract_revision")
                != V5_LEGACY_ADVERSE_ALLOCATION_REVISION
            ):
                raise ValueError(
                    "Research supervision allocation revision drifted"
                )
            if "supervision_components" in manifest:
                raise ValueError(
                    "supervision rounds cannot carry logical components"
                )
        elif "supervision_components" in manifest:
            raise ValueError(
                "historical or supervision rounds cannot carry logical components"
            )
        completed = self._round_is_completed(
            round_dir,
            manifest,
            _inspection_context=inspection,
        )
        for card_path, card in frozen_cards:
            self.validate_task_card(
                card,
                expected_path=card_path,
                historical_runtime=abort is not None or completed,
                _inspection_context=inspection,
            )
            if card.get("campaign_scope") != campaign_scope:
                raise ValueError(
                    "V5 round/task-card Campaign scope projections disagree"
                )
            if card.get("research_cycle") != research_cycle:
                raise ValueError(
                    "V5 round/task-card Research-cycle projections disagree"
                )
        if research_cycle is not None and research_cycle["subround"] == "supervision":
            self._validate_supervision_round_selection(
                research_cycle=research_cycle,
                selected=[
                    self._inspection_research_record(
                        card["research_id"],
                        inspection,
                    )
                    for _, card in frozen_cards
                    if card["control_plane"].get("assignment_role") == "primary"
                ],
                _inspection_context=inspection,
            )
        snapshot_path = (
            self.store.blackboard().snapshots_dir
            / manifest["blackboard_snapshot_id"]
            / "manifest.json"
        )
        if (
            snapshot_path.is_symlink()
            or not snapshot_path.is_file()
            or sha256_bytes(snapshot_path.read_bytes())
            != manifest["blackboard_snapshot_sha256"]
        ):
            raise ValueError("V5 round Blackboard snapshot bytes/hash mismatch")
        inspection.round_completed[round_id] = completed
        inspection.round_aborts[round_id] = abort
        result = (round_dir, manifest)
        inspection.round_manifests[round_id] = result
        return result

    def _validated_ingest_receipt(
        self,
        *,
        round_dir: Path,
        assignment: dict[str, Any],
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any]:
        """Validate one receipt strongly enough to make its task historical."""

        assignment_id = validate_assignment_id(
            _require_nonempty_text(
                assignment.get("assignment_id"), "V5 receipt assignment id"
            )
        )
        receipt_path = round_dir / "returns" / f"{assignment_id}.receipt.json"
        if receipt_path.is_symlink() or not receipt_path.is_file():
            raise ValueError("V5 ingestion receipt is missing or unsafe")
        receipt = self.store._read_json(receipt_path)
        base_fields = {
            "schema_version",
            "policy_revision",
            "project_id",
            "round_id",
            "assignment_id",
            "task_card_sha256",
            "return_sha256",
            "outcome",
            "research_id",
            "effect",
            "receipt_id",
            "created_at",
        }
        attack_fields = {
            "attack_case_id",
            "route_proposal_id",
            "attack_evidence_status",
            "route_activation_policy",
        }
        program_math_fields = {
            "program_math_review_research_id",
            "program_math_review_policy",
        }
        architecture_observation_fields = {
            "architecture_observation_ids",
            "architecture_observation_policy",
        }
        terminal_seal_fields = {
            "terminal_seal_revision",
            "terminal_seal_sha256",
            "writer_lease_id",
        }
        if not isinstance(receipt, dict):
            raise ValueError("V5 ingestion receipt must be one object")
        receipt_fields = set(receipt)
        has_attack = bool(receipt_fields.intersection(attack_fields))
        has_program_math = bool(receipt_fields.intersection(program_math_fields))
        has_architecture_observations = bool(
            receipt_fields.intersection(architecture_observation_fields)
        )
        terminal_seal_required = (
            assignment.get("terminal_seal_revision")
            == V5_TERMINAL_SEAL_REVISION
        )
        expected_fields = set(base_fields)
        if has_attack:
            expected_fields.update(attack_fields)
        if has_program_math:
            expected_fields.update(program_math_fields)
        if has_architecture_observations:
            expected_fields.update(architecture_observation_fields)
        if terminal_seal_required:
            expected_fields.update(terminal_seal_fields)
        if receipt_fields != expected_fields:
            raise ValueError("V5 ingestion receipt fields are not exact")
        if (
            receipt.get("schema_version") != 5
            or receipt.get("policy_revision") != V5_POLICY_REVISION
            or receipt.get("project_id") != self.store.project_id()
            or receipt.get("round_id") != round_dir.name
            or receipt.get("assignment_id") != assignment_id
            or receipt.get("task_card_sha256")
            != assignment.get("task_card_sha256")
            or receipt.get("outcome") not in V5_RETURN_OUTCOMES
        ):
            raise ValueError("V5 ingestion receipt binding is invalid")
        if terminal_seal_required:
            self._validate_writer_lease_id(
                receipt.get("writer_lease_id"),
                round_id=round_dir.name,
                assignment_id=assignment_id,
                task_card_sha256=assignment["task_card_sha256"],
                worker_context_id=assignment["worker_context_id"],
                host_task_scope_id=assignment["host_task_scope_id"],
            )
            if receipt["writer_lease_id"] != assignment.get("writer_lease_id"):
                raise ValueError("V5 ingestion receipt writer lease drifted")
        for field_name in ("task_card_sha256", "return_sha256"):
            value = receipt.get(field_name)
            if not isinstance(value, str) or SHA256_RE.fullmatch(value) is None:
                raise ValueError(f"V5 ingestion receipt {field_name} is invalid")
        _parse_utc_timestamp(
            receipt.get("created_at"), label="V5 ingestion receipt created_at"
        )
        research_id = validate_memory_id(
            _require_nonempty_text(
                receipt.get("research_id"), "V5 ingestion receipt research id"
            )
        )
        self._inspection_research_record(research_id, _inspection_context)
        if terminal_seal_required:
            terminal_seal_sha256 = receipt.get("terminal_seal_sha256")
            if (
                receipt.get("terminal_seal_revision")
                != V5_TERMINAL_SEAL_REVISION
                or not isinstance(terminal_seal_sha256, str)
                or SHA256_RE.fullmatch(terminal_seal_sha256) is None
            ):
                raise ValueError("V5 ingestion receipt terminal seal is invalid")
            seal = self._validate_terminal_seal(
                round_dir=round_dir,
                assignment=assignment,
                required=True,
            )
            assert seal is not None
            if (
                seal["seal_sha256"] != terminal_seal_sha256
                or seal["sealed_return_sha256"] != receipt["return_sha256"]
            ):
                raise ValueError(
                    "V5 ingestion receipt terminal seal is mismatched "
                    "(return bytes/hash mismatch)"
                )
        else:
            return_path = contained_path(
                self.store.root,
                assignment["return_relpath"],
                "V5 ingested return path",
            )
            if (
                return_path.is_symlink()
                or not return_path.is_file()
                or sha256_bytes(return_path.read_bytes())
                != receipt["return_sha256"]
            ):
                raise ValueError("V5 ingested return bytes/hash mismatch")

        expected_effect = "one_cumulative_research_entry"
        if has_attack:
            case_id = receipt.get("attack_case_id")
            proposal_id = receipt.get("route_proposal_id")
            if (
                not isinstance(case_id, str)
                or not case_id.startswith("attack-case-")
                or SHA256_RE.fullmatch(case_id.removeprefix("attack-case-")) is None
                or not isinstance(proposal_id, str)
                or not proposal_id.startswith("route-proposal-")
                or SHA256_RE.fullmatch(
                    proposal_id.removeprefix("route-proposal-")
                )
                is None
                or receipt.get("attack_evidence_status")
                not in {
                    "worker_reported_counterexample_nontruth",
                    "worker_reported_productive_challenge_nontruth",
                }
                or receipt.get("route_activation_policy")
                not in {"user_decision_only", "main_synthesis_only"}
            ):
                raise ValueError("V5 ingestion receipt attack binding is invalid")
            if _inspection_context is None:
                cases = {
                    item["case_id"]: item
                    for item in self.store.adverse_routes().cases()
                }
                proposals = {
                    item["proposal_id"]: item
                    for item in self.store.adverse_routes().proposals()
                }
            else:
                if _inspection_context.adverse_cases is None:
                    _inspection_context.adverse_cases = {
                        item["case_id"]: item
                        for item in self.store.adverse_routes().cases()
                    }
                if _inspection_context.adverse_proposals is None:
                    _inspection_context.adverse_proposals = {
                        item["proposal_id"]: item
                        for item in self.store.adverse_routes().proposals()
                    }
                cases = _inspection_context.adverse_cases
                proposals = _inspection_context.adverse_proposals
            case = cases.get(case_id)
            proposal = proposals.get(proposal_id)
            if (
                case is None
                or proposal is None
                or proposal.get("case_id") != case_id
                or case.get("round_id") != round_dir.name
                or case.get("assignment_id") != assignment_id
                or case.get("attack_research_id") != research_id
                or case.get("task_card_sha256") != receipt["task_card_sha256"]
                or case.get("return_sha256") != receipt["return_sha256"]
                or case.get("evidence_status")
                != receipt["attack_evidence_status"]
                or proposal.get("activation_policy")
                != receipt["route_activation_policy"]
            ):
                raise ValueError("V5 ingestion receipt attack records are mismatched")
            expected_effect += "_plus_nontruth_attack_proposal"
        if has_program_math:
            program_research_id = validate_memory_id(
                _require_nonempty_text(
                    receipt.get("program_math_review_research_id"),
                    "V5 program-math review Research id",
                )
            )
            if (
                receipt.get("program_math_review_policy")
                != "queued_for_future_multidimensional_frontier"
            ):
                raise ValueError("V5 ingestion receipt program-math policy is invalid")
            self._inspection_research_record(
                program_research_id,
                _inspection_context,
            )
            expected_effect += "_plus_nontruth_program_math_adverse_review"
        if has_architecture_observations:
            observation_ids = receipt.get("architecture_observation_ids")
            if (
                not isinstance(observation_ids, list)
                or not observation_ids
                or len(observation_ids) != len(set(observation_ids))
                or any(
                    not isinstance(item, str)
                    or not item.startswith("chx-observation-")
                    or SHA256_RE.fullmatch(
                        item.removeprefix("chx-observation-")
                    )
                    is None
                    for item in observation_ids
                )
                or receipt.get("architecture_observation_policy")
                != "nontruth_chx_inbox_pending_coordination"
            ):
                raise ValueError(
                    "V5 ingestion receipt CHX observation binding is invalid"
                )
            for observation_id in observation_ids:
                path = (
                    self.store.root
                    / "chx-observations"
                    / "by-id"
                    / f"{observation_id}.json"
                )
                if path.is_symlink() or not path.is_file():
                    raise ValueError(
                        "V5 ingestion receipt CHX observation is missing"
                    )
                observation = self.store._read_json(path)
                if (
                    observation.get("observation_id") != observation_id
                    or observation.get("round_id") != round_dir.name
                    or observation.get("assignment_id") != assignment_id
                    or observation.get("task_card_sha256")
                    != receipt["task_card_sha256"]
                    or observation.get("return_sha256")
                    != receipt["return_sha256"]
                    or observation.get("truth_effect") != "none"
                    or observation.get("project_effect") != "none"
                ):
                    raise ValueError(
                        "V5 ingestion receipt CHX observation is mismatched"
                    )
            expected_effect += "_plus_chx_observation_inbox"
        if receipt.get("effect") != expected_effect:
            raise ValueError("V5 ingestion receipt effect is invalid")
        semantic = {
            key: value
            for key, value in receipt.items()
            if key not in {"receipt_id", "created_at"}
        }
        if receipt.get("receipt_id") != "research-ingest-" + sha256_json(semantic):
            raise ValueError("V5 ingestion receipt content id mismatch")
        return receipt

    def _round_is_completed(
        self,
        round_dir: Path,
        manifest: dict[str, Any],
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> bool:
        """Report whether every assignment produced its immutable Research product.

        A worker-ingestion receipt is a workflow marker and optional provenance;
        it is not a second capability authority.  The Research product carries
        the assignment, task-card, worker, stage, and return-hash bindings that
        let later logical components determine whether the work actually
        passed.  Keeping completion product-first also makes a partially
        published receipt recoverable without reopening a valid Research node.

        Independent authority receipts (verifier returns, Certification,
        Gateway, experiment finals, and terminal seals) remain validated by
        their owning paths; this helper only covers ordinary worker ingestion.
        """

        completed = True
        inspection = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert inspection is not None
        for assignment in manifest["assignments"]:
            try:
                self._research_product_for_assignment(
                    round_dir=round_dir,
                    manifest=manifest,
                    assignment=assignment,
                    _inspection_context=inspection,
                )
                if (
                    assignment.get("terminal_seal_revision")
                    == V5_TERMINAL_SEAL_REVISION
                ):
                    self._validate_terminal_seal(
                        round_dir=round_dir,
                        assignment=assignment,
                        required=True,
                    )
            except ValueError as exc:
                if "worker Research product is missing" in str(exc):
                    completed = False
                    continue
                raise
        return completed

    def _assignment(
        self,
        manifest: dict[str, Any],
        assignment_id: str,
    ) -> dict[str, Any]:
        assignment_id = validate_assignment_id(assignment_id)
        matches = [
            item
            for item in manifest["assignments"]
            if item["assignment_id"] == assignment_id
        ]
        if len(matches) != 1:
            raise KeyError(f"unknown V5 assignment: {assignment_id}")
        return matches[0]

    def _quarantine_records(
        self,
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> list[dict[str, Any]]:
        if (
            _inspection_context is not None
            and _inspection_context.quarantine_records is not None
        ):
            return _inspection_context.quarantine_records
        records: list[dict[str, Any]] = []
        if not self.quarantine_dir.exists():
            if _inspection_context is not None:
                _inspection_context.quarantine_records = records
            return records
        for path in sorted(self.quarantine_dir.glob("*.json")):
            if path.is_symlink() or not path.is_file():
                raise ValueError("V5 quarantine contains an unsafe entry")
            payload = self.store._read_json(path)
            if not isinstance(payload, dict) or payload.get("quarantine_id") != path.stem:
                raise ValueError("V5 quarantine path/id mismatch")
            semantic = {
                key: value
                for key, value in payload.items()
                if key not in {"quarantine_id", "created_at", "record_sha256"}
            }
            expected_id = "quarantine-" + sha256_json(semantic)
            if payload.get("quarantine_id") != expected_id:
                raise ValueError("V5 quarantine content id mismatch")
            without_hash = {
                key: value
                for key, value in payload.items()
                if key != "record_sha256"
            }
            if payload.get("record_sha256") != sha256_json(without_hash):
                raise ValueError("V5 quarantine record hash mismatch")
            records.append(payload)
        if _inspection_context is not None:
            _inspection_context.quarantine_records = records
        return records

    def _round_status_with_context(
        self,
        round_id: str,
        inspection: RoundInspectionContext,
    ) -> dict[str, Any]:
        round_id = validate_round_id(round_id)
        cached = inspection.round_statuses.get(round_id)
        if cached is not None:
            return cached
        round_dir, manifest = self._round_manifest(
            round_id,
            _inspection_context=inspection,
        )
        abort = inspection.round_aborts[round_id]
        completed = inspection.round_completed[round_id]
        quarantined = {
            item["assignment_id"]: item
            for item in self._quarantine_records(
                _inspection_context=inspection
            )
            if item.get("round_id") == round_id
        }
        assignments: list[dict[str, Any]] = []
        for assignment in manifest["assignments"]:
            assignment_id = assignment["assignment_id"]
            return_path = self.store.root / assignment["return_relpath"]
            terminal_source_diagnostics: list[str] = []
            terminalized_marker_status: str | None = None
            product: dict[str, Any] | None = None
            try:
                product, _receipt = self._research_product_for_assignment(
                    round_dir=round_dir,
                    manifest=manifest,
                    assignment=assignment,
                    _inspection_context=inspection,
                )
            except ValueError as exc:
                if "worker Research product is missing" not in str(exc):
                    raise
            if product is not None:
                state = "ingested"
                if (
                    assignment.get("terminal_seal_revision")
                    == V5_TERMINAL_SEAL_REVISION
                ):
                    seal = self._validate_terminal_seal(
                        round_dir=round_dir,
                        assignment=assignment,
                        required=True,
                    )
                    assert seal is not None
                    terminal_source_diagnostics = (
                        self._terminal_source_diagnostics(
                            assignment=assignment,
                            seal=seal,
                        )
                    )
                    marker_path = self._terminalized_marker_path(
                        round_dir, assignment_id
                    )
                    if os.path.lexists(marker_path):
                        try:
                            self._validate_terminalized_lease_marker(
                                round_dir=round_dir,
                                assignment=assignment,
                                seal=seal,
                            )
                            terminalized_marker_status = "valid"
                        except (OSError, ValueError):
                            # The marker is a nontruth diagnostic projection;
                            # do not let its corruption reopen or invalidate a
                            # Research product.  Surface it for repair instead.
                            terminalized_marker_status = "invalid"
                            terminal_source_diagnostics.append(
                                "terminalized_lease_marker:invalid"
                            )
                    else:
                        # Missing marker is a retryable nontruth projection
                        # state (including pre-COW historical rounds), not a
                        # Research validity failure.
                        terminalized_marker_status = "missing"
                        terminal_source_diagnostics.append(
                            "terminalized_lease_marker:missing"
                        )
            elif assignment_id in quarantined:
                state = "quarantined"
            elif abort is not None:
                state = "frozen_aborted"
            elif return_path.exists():
                state = "return_present"
            else:
                state = "awaiting_return"
            assignments.append(
                {
                    **assignment,
                    "state": state,
                    "task_card_path": str(
                        self.store.root / assignment["task_card_relpath"]
                    ),
                    "prompt_path": str(
                        self.store.root / assignment["prompt_relpath"]
                    ),
                    "return_path": str(return_path),
                    "research_product_id": (
                        product["research_id"] if product is not None else None
                    ),
                    "terminal_source_diagnostics": terminal_source_diagnostics,
                    "terminalized_lease_marker": terminalized_marker_status,
                }
            )
        status = {
            **manifest,
            "assignments": assignments,
            "ingested_count": sum(
                item["state"] == "ingested" for item in assignments
            ),
            "quarantined_count": sum(
                item["state"] == "quarantined" for item in assignments
            ),
            "awaiting_count": sum(
                item["state"] == "awaiting_return" for item in assignments
            ),
            "frozen_aborted_count": sum(
                item["state"] == "frozen_aborted" for item in assignments
            ),
            "work_unit_state": (
                "aborted"
                if abort is not None
                else "completed"
                if completed
                else "active"
            ),
            "abort_id": abort["abort_id"] if abort is not None else None,
            "work_unit_abort": abort,
            "round_closure_required": False,
        }
        inspection.round_statuses[round_id] = status
        return status

    def round_status(
        self,
        round_id: str,
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any]:
        """Return the public status projection, optionally sharing one read phase."""

        inspection = (
            _inspection_context
            if _inspection_context is not None
            else RoundInspectionContext()
        )
        return self._round_status_with_context(
            round_id,
            inspection,
        )

    def round_statuses(self) -> dict[str, Any]:
        """Validate and project every V5 round in one ephemeral read phase."""

        rounds_root = self.store.rounds_dir
        if rounds_root.is_symlink() or not rounds_root.is_dir():
            raise ValueError("V5 rounds root is missing or unsafe")
        round_ids: list[str] = []
        private_staging_count = 0
        invalid_visible_names: list[str] = []
        for path in sorted(rounds_root.iterdir(), key=lambda item: item.name):
            if path.is_symlink() or not path.is_dir():
                raise ValueError("V5 rounds root contains an unsafe entry")
            if re.fullmatch(
                r"\.round-[^.]+\.staging-[0-9a-f]+", path.name
            ) is not None:
                # Atomic creation publishes only the final ``round-*`` path.
                # A private staging directory may survive a crash, but it is
                # neither a round nor authority to hide all valid statuses.
                private_staging_count += 1
                continue
            try:
                round_ids.append(validate_round_id(path.name))
            except ValueError:
                # Batch status is an inventory surface.  Preserve strict
                # validation for direct round access while reporting a
                # malformed visible directory without discarding every valid
                # round from Main's view.
                invalid_visible_names.append(path.name)
        inspection = RoundInspectionContext()
        round_states = {
            round_id: self.round_status(
                round_id,
                _inspection_context=inspection,
            )["work_unit_state"]
            for round_id in round_ids
        }
        terminal = sum(
            state in {"aborted", "completed"}
            for state in round_states.values()
        )
        result = {
            "schema_version": 1,
            "workflow_evidence_version": V5_WORKFLOW_EVIDENCE_VERSION,
            "project_id": self.store.project_id(),
            "round_count": len(round_states),
            "terminal_round_count": terminal,
            "round_states": dict(sorted(round_states.items())),
            "truth_effect": "none",
        }
        diagnostics: list[dict[str, Any]] = []
        if private_staging_count:
            diagnostics.append(
                {
                    "code": "private_round_staging_ignored",
                    "count": private_staging_count,
                }
            )
        if invalid_visible_names:
            diagnostics.append(
                {
                    "code": "invalid_visible_round_directories_ignored",
                    "count": len(invalid_visible_names),
                    "entry_names": invalid_visible_names[:8],
                    "entry_names_sha256": sha256_json(
                        invalid_visible_names
                    ),
                }
            )
        if diagnostics:
            result["discovery_diagnostics"] = diagnostics
        return result

    @staticmethod
    def _readiness_action(
        *,
        category: str,
        object_id: str,
        reason: str,
        suggested_command: str,
        enforced_at: str,
    ) -> dict[str, str]:
        semantic = {
            "category": category,
            "object_id": object_id,
            "reason": reason,
            "suggested_command": suggested_command,
            "enforced_at": enforced_at,
        }
        return {
            **semantic,
            "action_id": "advice-" + sha256_json(semantic)[:16],
            "authority": "process_advice_only",
        }

    def process_readiness_status(self, round_id: str) -> dict[str, Any]:
        """Describe repairable process gaps without creating admission authority."""

        status = self.round_status(round_id)
        research_ids = {
            assignment["research_id"] for assignment in status["assignments"]
        }
        actions: list[dict[str, str]] = []
        quarantines = [
            item
            for item in self._quarantine_records()
            if item.get("round_id") == round_id
        ]
        latest_quarantine: dict[str, dict[str, Any]] = {}
        for item in quarantines:
            assignment_id = item["assignment_id"]
            previous = latest_quarantine.get(assignment_id)
            if previous is None or item["created_at"] > previous["created_at"]:
                latest_quarantine[assignment_id] = item
        round_dir = self.store.rounds_dir / round_id
        for assignment in status["assignments"]:
            assignment_id = assignment["assignment_id"]
            state = assignment["state"]
            if state == "awaiting_return":
                actions.append(
                    self._readiness_action(
                        category="return_missing",
                        object_id=assignment_id,
                        reason=(
                            "No return exists for this task card. Other valid "
                            "assignments remain usable."
                        ),
                        suggested_command=(
                            f"complete {assignment['return_relpath']}, then run "
                            f"preflight-return {round_id} {assignment_id}"
                        ),
                        enforced_at="ingest-return for this assignment only",
                    )
                )
            elif state == "return_present":
                actions.append(
                    self._readiness_action(
                        category="return_needs_preflight",
                        object_id=assignment_id,
                        reason="Return bytes exist but have no ingestion receipt.",
                        suggested_command=(
                            f"preflight-return {round_id} {assignment_id}; if valid, "
                            "run ingest-return with the reported SHA-256"
                        ),
                        enforced_at="ingest-return for this assignment only",
                    )
                )
            elif state == "quarantined":
                quarantine = latest_quarantine[assignment_id]
                actions.append(
                    self._readiness_action(
                        category="return_quarantined",
                        object_id=assignment_id,
                        reason=(
                            f"Local validation failed: {quarantine['error']}. "
                            "The quarantine has no effect on valid peers."
                        ),
                        suggested_command=(
                            f"repair {assignment['return_relpath']}; run preflight-return "
                            f"{round_id} {assignment_id}; retry ingest-return"
                        ),
                        enforced_at="ingest-return for this assignment only",
                    )
                )
            elif state == "ingested":
                product_id = assignment.get("research_product_id")
                if isinstance(product_id, str):
                    research_ids.add(product_id)

        relevant_releases = [
            release
            for release in self.releases()
            if research_ids.intersection(
                binding["research_id"]
                for binding in release["research_bindings"]
            )
        ]
        decisions_by_release = {
            decision["release_id"]: decision for decision in self.decisions()
        }
        visible_facts = set(self.store.fact_ids())
        if status["ingested_count"] and not relevant_releases:
            actions.append(
                self._readiness_action(
                    category="candidate_release_missing",
                    object_id=round_id,
                    reason=(
                        "At least one cumulative contribution is available, but no "
                        "Candidate Release binds this round's research yet."
                    ),
                    suggested_command=(
                        "prepare an explicit candidate-release input with the requested "
                        "assurance and challenge dispositions"
                    ),
                    enforced_at="candidate-release",
                )
            )
        for release in relevant_releases:
            decision = decisions_by_release.get(release["release_id"])
            if decision is None:
                actions.append(
                    self._readiness_action(
                        category="certification_missing",
                        object_id=release["release_id"],
                        reason="The sealed Candidate Release has no independent decision.",
                        suggested_command=(
                            f"verifier-capsule {release['release_id']}, then obtain a "
                            "fresh certification-record"
                        ),
                        enforced_at="certification-record",
                    )
                )
            elif decision["verdict"] == "reject":
                actions.append(
                    self._readiness_action(
                        category="candidate_rejected",
                        object_id=release["release_id"],
                        reason=(
                            "The immutable decision rejected this release; repair must "
                            "continue as new Research and a new release."
                        ),
                        suggested_command="research-add, then seal a new candidate-release",
                        enforced_at="candidate-release",
                    )
                )
            elif not set(release["fact_ids"]).issubset(visible_facts):
                actions.append(
                    self._readiness_action(
                        category="gateway_admission_missing",
                        object_id=release["release_id"],
                        reason=(
                            "A correct Certification Decision exists, but its Facts are "
                            "not all active in the V5 Fact Graph."
                        ),
                        suggested_command=(
                            f"fact-admit {release['release_id']} "
                            f"{decision['decision_id']}"
                        ),
                        enforced_at="fact-admit",
                    )
                )

        if status["work_unit_state"] == "aborted":
            advisory_state = "work_unit_aborted"
        elif any(item["category"] == "return_quarantined" for item in actions):
            advisory_state = "local_repairs_recommended"
        elif any(
            item["category"] in {"return_missing", "return_needs_preflight"}
            for item in actions
        ):
            advisory_state = "contributions_in_progress"
        elif actions:
            advisory_state = "next_transition_recommended"
        else:
            advisory_state = "no_process_gap_detected"
        return {
            "schema_version": 5,
            "policy_revision": V5_POLICY_REVISION,
            "project_id": self.store.project_id(),
            "round_id": round_id,
            "advisory_state": advisory_state,
            "recommended_actions": sorted(
                actions, key=lambda item: (item["category"], item["object_id"])
            ),
            "assignment_summary": {
                "total": len(status["assignments"]),
                "ingested": status["ingested_count"],
                "quarantined": status["quarantined_count"],
                "awaiting": status["awaiting_count"],
                "frozen_aborted": status["frozen_aborted_count"],
            },
            "admission_authority": False,
            "truth_effect": "none",
            "recording_effect": (
                "profile-closure-record appends guidance to Research only; "
                "it never marks the process complete"
            ),
        }

    def record_process_readiness(
        self,
        round_id: str,
        payload: dict[str, Any],
        *,
        actor: str,
    ) -> dict[str, Any]:
        if not isinstance(payload, dict) or not set(payload).issubset(
            {"note", "acknowledged_action_ids", "deferred_action_ids"}
        ):
            raise ValueError(
                "V5 readiness record accepts only note, "
                "acknowledged_action_ids, and deferred_action_ids"
            )
        note = payload.get("note", "")
        if not isinstance(note, str):
            raise ValueError("V5 readiness note must be a string")
        acknowledged = _require_string_list(
            payload.get("acknowledged_action_ids", []),
            "acknowledged readiness action ids",
        )
        deferred = _require_string_list(
            payload.get("deferred_action_ids", []),
            "deferred readiness action ids",
        )
        if set(acknowledged).intersection(deferred):
            raise ValueError("a readiness action cannot be acknowledged and deferred")
        report = self.process_readiness_status(round_id)
        known = {item["action_id"] for item in report["recommended_actions"]}
        unknown = sorted(set(acknowledged + deferred).difference(known))
        if unknown:
            raise ValueError(
                "readiness record references unknown current actions: "
                + ", ".join(unknown)
            )
        related = sorted(
            {
                assignment["research_id"]
                for assignment in self.round_status(round_id)["assignments"]
            }
        )
        research = self.add_research(
            {
                "kind": "guidance",
                "status": (
                    "open"
                    if report["recommended_actions"]
                    else "resolved_no_obstruction"
                ),
                "claim": f"Process readiness advice for {round_id}",
                "content": json.dumps(
                    report["recommended_actions"],
                    ensure_ascii=False,
                    sort_keys=True,
                ),
                "rationale": note,
                "relation": "advises",
                "related_research_ids": related,
                "round_id": round_id,
                "advisory_report_sha256": sha256_json(report),
                "acknowledged_action_ids": sorted(dict.fromkeys(acknowledged)),
                "deferred_action_ids": sorted(dict.fromkeys(deferred)),
                "admission_authority": False,
                "truth_effect": "none",
            },
            actor=actor,
        )
        return {
            **report,
            "recorded_research_id": research["research_id"],
            "recorded_research_sha256": research["record_sha256"],
        }

    def _validate_research_cycle_return(
        self,
        *,
        card: dict[str, Any],
        payload: dict[str, Any],
    ) -> None:
        cycle = card.get("research_cycle")
        if cycle is None:
            return
        cycle = self._validate_research_cycle_binding(cycle)
        artifacts = payload.get("artifacts", [])
        by_role = {
            item["role"]: item
            for item in artifacts
            if isinstance(item, dict) and isinstance(item.get("role"), str)
        }
        if cycle["subround"] == "supervision":
            if "research_supervision_report" not in by_role:
                raise ValueError(
                    "Research supervision return lacks its exact review report"
                )
            return
        if card["work_mode"] != "compute":
            return
        source_metadata = card["mathematical_state"][
            "source_research_dossier"
        ]["metadata"]
        approved = source_metadata.get("approved_computation_execution")
        if approved is None:
            if set(by_role) != set(V5_COMPUTATION_DESIGN_ARTIFACT_ROLES):
                raise ValueError(
                    "first-subround computer must return exactly core source, "
                    "mathematical design, and dependency manifest before execution"
                )
            if (
                payload.get("computation_manifest") is not None
                or payload.get("research_assurance", {}).get(
                    "program_math_alignments"
                )
                != []
            ):
                raise ValueError(
                    "first-subround computation design cannot contain execution results"
                )
            return
        approved = self._validate_approved_computation_execution_binding(approved)
        required_execution_roles = {
            "computation_dependencies",
            "computation_log",
            "computation_output",
            "computation_source",
        }
        if not required_execution_roles.issubset(by_role):
            raise ValueError(
                "approved computation return lacks exact source, dependencies, log, or output"
            )
        frozen = {
            item["role"]: item["sha256"]
            for item in approved["design_artifacts"]
        }
        for role in ("computation_source", "computation_dependencies"):
            if by_role[role]["sha256"] != frozen[role]:
                raise ValueError(
                    "approved computation changed supervised source or dependencies; "
                    "start a new production and supervision cycle"
                )
        manifest = payload.get("computation_manifest")
        entries = manifest.get("entries", []) if isinstance(manifest, dict) else []
        if not entries or any(
            entry.get("source_artifact_sha256")
            != frozen["computation_source"]
            for entry in entries
        ):
            raise ValueError(
                "approved computation manifest is not bound to the supervised source"
            )

    @staticmethod
    def _task_primary_source_sha256s(card: dict[str, Any]) -> set[str]:
        """Return exact card capabilities whose role declares primary bytes."""

        mathematical_state = card.get("mathematical_state", {})
        related_artifacts = (
            mathematical_state.get("related_artifacts", [])
            if isinstance(mathematical_state, dict)
            else []
        )
        primary_hashes: set[str] = set()
        for artifact in related_artifacts:
            if not isinstance(artifact, dict):
                continue
            role = artifact.get("role")
            digest = artifact.get("sha256")
            if not isinstance(role, str) or not isinstance(digest, str):
                continue
            role_tokens = {
                token
                for token in re.split(r"[^a-z0-9]+", role.casefold())
                if token
            }
            if "primary" in role_tokens and SHA256_RE.fullmatch(digest):
                primary_hashes.add(digest)
        return primary_hashes

    def _validate_return_payload(
        self,
        *,
        round_id: str,
        assignment_id: str,
        payload: Any,
        return_path: Path,
        artifact_snapshots: list[TerminalArtifactSnapshot] | None = None,
        artifact_bytes_override: dict[str, bytes] | None = None,
        retryable_source_visibility: bool = False,
    ) -> dict[str, Any]:
        if not isinstance(payload, dict):
            raise ValueError("V5 worker return must be one object")
        required = {
            "schema_version",
            "project_id",
            "round_id",
            "assignment_id",
            "worker_id",
            "task_card_sha256",
            "blackboard_snapshot_sha256",
            "outcome",
            "claim",
            "content",
            "narrative",
            "artifacts",
        }
        round_dir, manifest = self._round_manifest(round_id)
        assignment = self._assignment(manifest, assignment_id)
        terminal_seal_required = (
            assignment.get("terminal_seal_revision")
            == V5_TERMINAL_SEAL_REVISION
        )
        card = self.store._read_json(
            self.store.root / assignment["task_card_relpath"]
        )
        adverse_enabled = "adverse_routing" in card
        if adverse_enabled:
            required.add("attack_learning")
        assurance_enabled = "assurance_contract" in card
        if assurance_enabled:
            required.update(
                {
                    "obligation_dispositions",
                    "computation_manifest",
                    "research_assurance",
                }
            )
        if set(payload) != required:
            missing = sorted(required.difference(payload))
            unknown = sorted(set(payload).difference(required))
            raise ValueError(
                "V5 worker return fields are not exact; "
                f"missing={missing}; unknown={unknown}; exact schema: "
                "references/v5_worker_return_contract.md"
            )
        if (
            payload.get("schema_version") != 5
            or payload.get("project_id") != self.store.project_id()
            or payload.get("round_id") != round_id
            or payload.get("assignment_id") != assignment_id
            or payload.get("worker_id") != assignment["worker_id"]
            or payload.get("task_card_sha256")
            != assignment["task_card_sha256"]
            or payload.get("blackboard_snapshot_sha256")
            != assignment["blackboard_snapshot_sha256"]
        ):
            raise ValueError("V5 worker return binding mismatch")
        if payload.get("outcome") not in V5_RETURN_OUTCOMES:
            raise ValueError("V5 worker return outcome is invalid")
        if adverse_enabled:
            adverse_schema = card["adverse_routing"].get("schema_version")
            current_adverse = adverse_schema in (
                ADVERSE_STRUCTURED_ATTACK_TASK_CARD_SCHEMAS
            )
            worker_report_only = adverse_schema == 5
            learning = payload.get("attack_learning")
            if current_adverse:
                if payload["outcome"] == "counterexample":
                    validate_attack_learning(
                        learning,
                        require_current=worker_report_only,
                        expected_result_kind="surviving_counterexample",
                    )
                elif payload["outcome"] in PRODUCTIVE_ATTACK_OUTCOMES:
                    if learning is not None:
                        validate_attack_learning(
                            learning,
                            require_current=worker_report_only,
                            expected_result_kind="productive_challenge",
                        )
                elif learning is not None:
                    raise ValueError(
                        "only a surviving counterexample or productive challenge may "
                        "include attack_learning"
                    )
            elif payload["outcome"] == "counterexample":
                validate_attack_learning(learning)
            elif learning is not None:
                raise ValueError(
                    "legacy non-counterexample V5 return requires attack_learning=null"
                )
        _require_nonempty_text(payload.get("claim"), "worker return claim")
        _require_nonempty_text(payload.get("content"), "worker return content")
        narrative = payload.get("narrative")
        if not isinstance(narrative, dict) or set(narrative) != {
            "rationale",
            "summary",
            "intuition",
            "limitations",
        }:
            raise ValueError("V5 worker narrative fields are not exact")
        for name, value in narrative.items():
            if not isinstance(value, str):
                raise ValueError(f"V5 worker narrative {name} must be a string")
            cap = 400
            if len(value.split()) > cap:
                raise ValueError(f"V5 worker narrative {name} exceeds {cap} words")
        artifacts = payload.get("artifacts")
        artifact_fields = (
            {"path", "sha256", "role"}
            if assurance_enabled
            else {"path", "sha256"}
        )
        if not isinstance(artifacts, list) or any(
            not isinstance(item, dict) or set(item) != artifact_fields
            for item in artifacts
        ):
            raise ValueError(
                "V5 worker artifacts must be exact "
                + ("path/hash/role" if assurance_enabled else "path/hash")
                + " objects"
            )
        capability = card["artifact_capability"]
        if len(artifacts) > capability["max_files"]:
            raise ValueError("V5 worker artifact file count exceeds task-card cap")
        total_bytes = 0
        seen_roles: set[str] = set()
        artifact_bytes_by_sha256: dict[str, bytes] = {}
        artifact_bytes_by_path: dict[str, bytes] = {}
        textual_c0_gate_enabled = self._task_card_skill_version_at_least(
            card, (0, 7, 16)
        )
        artifact_root = contained_path(
            self.store.root,
            capability["artifact_dir_relpath"],
            "V5 artifact root",
        )
        for item in artifacts:
            if not isinstance(item["path"], str) or not isinstance(
                item["sha256"], str
            ):
                raise ValueError("V5 worker artifact fields must be strings")
            if SHA256_RE.fullmatch(item["sha256"]) is None:
                raise ValueError("V5 worker artifact hash is invalid")
            role: str | None = None
            if assurance_enabled:
                role = _require_nonempty_text(
                    item["role"], "V5 worker artifact role"
                )
                if role in seen_roles:
                    raise ValueError("V5 worker artifact roles must be unique")
                seen_roles.add(role)
            artifact_path = contained_path(
                self.store.root, item["path"], "V5 worker artifact path"
            )
            try:
                artifact_path.relative_to(artifact_root)
            except ValueError as exc:
                raise ValueError(
                    "V5 worker artifact is outside its task-card directory"
                ) from exc
            raw_artifact = artifact_bytes_by_path.get(item["path"])
            if raw_artifact is None and artifact_bytes_override is not None:
                raw_artifact = artifact_bytes_override.get(item["path"])
            if raw_artifact is None:
                if artifact_path.is_symlink():
                    raise ValueError("V5 worker artifact is missing or unsafe")
                read_path = (
                    self._lexical_contained_path(
                        item["path"], "V5 worker artifact path"
                    )
                    if terminal_seal_required
                    else artifact_path
                )
                raw_artifact = self._read_regular_bytes_once(
                    read_path,
                    label="V5 worker artifact",
                    containment_root=(
                        self.store.root if terminal_seal_required else None
                    ),
                    require_single_link=terminal_seal_required,
                    retryable_visibility=retryable_source_visibility,
                )
                artifact_bytes_by_path[item["path"]] = raw_artifact
            size = len(raw_artifact)
            if size > capability["max_file_bytes"]:
                raise ValueError("V5 worker artifact exceeds per-file cap")
            total_bytes += size
            if sha256_bytes(raw_artifact) != item["sha256"]:
                raise ValueError("V5 worker artifact bytes/hash mismatch")
            existing_bytes = artifact_bytes_by_sha256.get(item["sha256"])
            if existing_bytes is not None and existing_bytes != raw_artifact:
                raise ValueError("V5 worker artifact SHA-256 collision")
            artifact_bytes_by_sha256[item["sha256"]] = raw_artifact
            suffix = artifact_path.suffix.lower()
            if textual_c0_gate_enabled and suffix in V5_TEXTUAL_ARTIFACT_SUFFIXES:
                allowed_controls = (
                    {0x0A, 0x0D}
                    if suffix in V5_MARKDOWN_ARTIFACT_SUFFIXES
                    else {0x09, 0x0A, 0x0D}
                )
                for offset, byte in enumerate(raw_artifact):
                    if byte < 0x20 and byte not in allowed_controls:
                        raise ValueError(
                            "V5 worker textual artifact contains forbidden control "
                            f"byte; role={role or 'untyped'}; path={item['path']}; "
                            f"byte=0x{byte:02x}; offset={offset}"
                        )
            if (
                assurance_enabled
                and role == "candidate_fact"
                and self._task_card_skill_version_at_least(card, (0, 7, 13))
            ):
                self._validate_candidate_fact_artifact_bytes(raw_artifact)
            if artifact_snapshots is not None:
                artifact_snapshots.append(
                    TerminalArtifactSnapshot(
                        source_relpath=item["path"],
                        sha256=item["sha256"],
                        role=role,
                        raw=raw_artifact,
                    )
                )
        if total_bytes > capability["max_total_bytes"]:
            raise ValueError("V5 worker artifacts exceed total-byte cap")
        if assurance_enabled:
            validate_return_assurance(
                payload=payload,
                contract=card["assurance_contract"],
                artifacts=artifacts,
                artifact_bytes_by_sha256=artifact_bytes_by_sha256,
                task_primary_source_sha256s=(
                    self._task_primary_source_sha256s(card)
                ),
            )
            self._validate_research_cycle_return(card=card, payload=payload)
        canonical_return = self.store.root / assignment["return_relpath"]
        if return_path.resolve() != canonical_return.resolve():
            # Preflight may inspect a draft elsewhere, but its declared
            # bindings and artifact capabilities remain those of the card.
            if return_path.is_symlink() or not return_path.is_file():
                raise ValueError("V5 worker draft return is missing or unsafe")
        return payload

    def _snapshot_return(
        self,
        *,
        round_id: str,
        assignment_id: str,
        input_path: Path | None = None,
        expected_sha256: str | None = None,
    ) -> TerminalIngestSnapshot:
        """Read, hash, parse, and validate one return/artifact snapshot once."""

        _, manifest = self._round_manifest(round_id)
        assignment = self._assignment(manifest, assignment_id)
        canonical_return = self._lexical_contained_path(
            assignment["return_relpath"], "V5 canonical worker return path"
        )
        if input_path is None:
            return_path = canonical_return
        else:
            supplied = Path(input_path).expanduser()
            return_path = (
                supplied
                if supplied.is_absolute()
                else (Path.cwd() / supplied).absolute()
            )
        terminal_seal_required = (
            assignment.get("terminal_seal_revision")
            == V5_TERMINAL_SEAL_REVISION
        )
        canonical_input = return_path.absolute() == canonical_return.absolute()
        raw_return = self._read_regular_bytes_once(
            return_path,
            label="V5 worker return",
            containment_root=(
                self.store.root
                if terminal_seal_required and canonical_input
                else None
            ),
            require_single_link=terminal_seal_required and canonical_input,
            retryable_visibility=canonical_input,
        )
        return_sha256 = sha256_bytes(raw_return)
        if expected_sha256 is not None and return_sha256 != expected_sha256:
            raise _WorkerFinalHashMismatch(
                "worker final handoff hash does not match return bytes"
            )
        try:
            payload = json.loads(raw_return.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise ValueError("V5 worker return is not valid UTF-8 JSON") from exc
        artifact_snapshots: list[TerminalArtifactSnapshot] = []
        self._validate_return_payload(
            round_id=round_id,
            assignment_id=assignment_id,
            payload=payload,
            return_path=return_path,
            artifact_snapshots=artifact_snapshots,
            retryable_source_visibility=canonical_input,
        )
        return TerminalIngestSnapshot(
            return_path=return_path,
            return_relpath=assignment["return_relpath"],
            return_sha256=return_sha256,
            return_bytes=raw_return,
            payload=payload,
            artifacts=tuple(artifact_snapshots),
        )

    def _snapshot_from_terminal_seal(
        self,
        *,
        round_dir: Path,
        assignment: dict[str, Any],
        seal: dict[str, Any],
        expected_sha256: str | None = None,
    ) -> TerminalIngestSnapshot:
        """Reconstruct an ingest snapshot from an already-published seal.

        This is the crash-recovery path for a failure between the atomic COW
        detach and its canonical successor/marker.  The terminal bundle is
        already validated independently, so no mutable worker source path is
        consulted and no new mathematical validation gate is introduced.
        """

        bundle_dir = self._terminal_bundle_dir(
            round_dir, assignment["assignment_id"]
        )
        sealed_return = bundle_dir / "return.json"
        raw_return = self._read_regular_bytes_once(
            sealed_return,
            label="terminal recovery return",
            containment_root=bundle_dir,
            require_single_link=True,
        )
        return_sha256 = sha256_bytes(raw_return)
        if expected_sha256 is not None and return_sha256 != expected_sha256:
            raise _WorkerFinalHashMismatch(
                "worker final handoff hash does not match terminal sealed bytes"
            )
        try:
            payload = json.loads(raw_return.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise ValueError("terminal recovery return is not valid UTF-8 JSON") from exc
        artifact_bytes_override: dict[str, bytes] = {}
        for item in seal["artifacts"]:
            sealed_path = self._lexical_contained_path(
                item["sealed_path"],
                "terminal recovery artifact",
            )
            raw = self._read_regular_bytes_once(
                sealed_path,
                label="terminal recovery artifact",
                containment_root=bundle_dir,
                require_single_link=True,
            )
            if sha256_bytes(raw) != item["sha256"]:
                raise ValueError("terminal recovery artifact hash drifted")
            artifact_bytes_override[item["source_path"]] = raw
        snapshots: list[TerminalArtifactSnapshot] = []
        self._validate_return_payload(
            round_id=round_dir.name,
            assignment_id=assignment["assignment_id"],
            payload=payload,
            return_path=sealed_return,
            artifact_snapshots=snapshots,
            artifact_bytes_override=artifact_bytes_override,
        )
        seal_bindings = [
            (
                item["source_path"],
                item["sha256"],
                item.get("role"),
            )
            for item in seal["artifacts"]
        ]
        snapshot_bindings = [
            (item.source_relpath, item.sha256, item.role)
            for item in snapshots
        ]
        if snapshot_bindings != seal_bindings:
            raise ValueError("terminal recovery artifact bindings drifted")
        return TerminalIngestSnapshot(
            return_path=self._lexical_contained_path(
                assignment["return_relpath"],
                "terminal recovery canonical return",
            ),
            return_relpath=assignment["return_relpath"],
            return_sha256=return_sha256,
            return_bytes=raw_return,
            payload=payload,
            artifacts=tuple(snapshots),
        )

    def preflight_return(
        self,
        *,
        round_id: str,
        assignment_id: str,
        input_path: Path | None = None,
    ) -> dict[str, Any]:
        self.store.reasoning_modes().require_work_unit_active(round_id)
        snapshot = self._snapshot_return(
            round_id=round_id,
            assignment_id=assignment_id,
            input_path=input_path,
        )
        return {
            "valid": True,
            "round_id": round_id,
            "assignment_id": assignment_id,
            "return_path": str(snapshot.return_path),
            "return_sha256": snapshot.return_sha256,
            "outcome": snapshot.payload["outcome"],
        }

    def _quarantine(
        self,
        *,
        round_id: str,
        assignment_id: str,
        assignment: dict[str, Any],
        error: str,
    ) -> dict[str, Any]:
        return_path = self.store.root / assignment["return_relpath"]
        return_sha = (
            sha256_bytes(return_path.read_bytes())
            if return_path.is_file() and not return_path.is_symlink()
            else None
        )
        semantic = {
            "schema_version": 5,
            "policy_revision": V5_POLICY_REVISION,
            "project_id": self.store.project_id(),
            "round_id": round_id,
            "assignment_id": assignment_id,
            "task_card_sha256": assignment["task_card_sha256"],
            "return_relpath": assignment["return_relpath"],
            "return_sha256": return_sha,
            "error": error,
            "effect": "local_contribution_only;valid_peers_unchanged",
            "next_safe_command": "repair this return and retry ingest-return",
        }
        quarantine_id = "quarantine-" + sha256_json(semantic)
        created_at = _utc_now()
        without_hash = {
            **semantic,
            "quarantine_id": quarantine_id,
            "created_at": created_at,
        }
        record = {
            **without_hash,
            "record_sha256": sha256_json(without_hash),
        }
        path = self.quarantine_dir / f"{quarantine_id}.json"
        self.store._write_json_once(path, record)
        return record

    def _enqueue_program_math_adverse_review(
        self,
        *,
        card: dict[str, Any],
        assignment: dict[str, Any],
        result_research: dict[str, Any],
        payload: dict[str, Any],
    ) -> dict[str, Any] | None:
        """Create a typed Research-stage challenge for a computed return.

        The review is queued only for future scheduling.  It does not run a
        worker, change routing, reject the source Research, or affect Fact
        truth.  Exact program/output bytes are inherited through the normal
        related-Research capability boundary.
        """

        if not self.store.adverse_routes().enabled():
            return None
        if card.get("work_mode") == "refute" or "assurance_contract" not in card:
            return None
        cycle = card.get("research_cycle")
        source_metadata = card.get("mathematical_state", {}).get(
            "source_research_dossier", {}
        ).get("metadata", {})
        if (
            isinstance(cycle, dict)
            and cycle.get("subround") == "production"
            and isinstance(source_metadata, dict)
            and "approved_computation_execution" in source_metadata
        ):
            # The explicit second subround owns the exact code/log/output
            # review.  Do not create the legacy duplicate future queue entry.
            return None
        stage_count = card["assurance_contract"].get("computation_stage_count", 0)
        if isinstance(stage_count, bool) or not isinstance(stage_count, int):
            raise ValueError("program-math review stage count is invalid")
        if stage_count == 0 or payload.get("outcome") not in {
            "proof",
            "evidence",
            "insight",
        }:
            return None
        artifacts = payload.get("artifacts", [])
        by_role = {
            item["role"]: item
            for item in artifacts
            if isinstance(item, dict) and isinstance(item.get("role"), str)
        }
        required_roles = {"computation_source", "computation_output"}
        if not required_roles.issubset(by_role):
            raise ValueError(
                "computed Research cannot queue an adverse review without canonical "
                "computation_source and computation_output artifacts"
            )
        manifest = payload.get("computation_manifest")
        manifest_entries = (
            manifest.get("entries", []) if isinstance(manifest, dict) else []
        )
        load_bearing = any(
            isinstance(item, dict) and item.get("role") == "load_bearing"
            for item in manifest_entries
        )
        workload = workload_profile_for_entry(
            {
                "kind": "computation",
                "verification_plan": {
                    "mode": "artifact_replay" if load_bearing else "closed_packet"
                },
                "budgets": {"max_wall_seconds": 0},
            }
        )
        workload["computation"]["stage_count"] = stage_count
        workload = validate_workload_profile(workload)
        source_artifacts = [
            {
                "role": role,
                "sha256": by_role[role]["sha256"],
            }
            for role in sorted(required_roles)
        ]
        review = self.add_research(
            {
                "kind": "challenge",
                "status": "open",
                "claim": (
                    "Adversarially verify the program-mathematics semantic projection for: "
                    + result_research["claim"]
                ),
                "content": (
                    "Attack formula-to-code projection, signs and conventions, index/domain "
                    "boundaries, mathematical-object representation, truncation or precision, "
                    "output interpretation, and non-independent replay. Preserve any valid "
                    "mathematical conclusion outside the exact failure boundary."
                ),
                "rationale": (
                    "A computation-bearing Research result needs an adverse semantic review "
                    "before Candidate promotion; this queue entry has no truth effect."
                ),
                "source": f"research:{result_research['research_id']}",
                "relation": "challenges",
                "related_research_ids": [result_research["research_id"]],
                "logic_signals": [
                    "formula_to_code",
                    "program_math_hybrid",
                ],
                "workload_profile": workload,
                "decision_profile": dict(
                    V5_PROGRAM_MATH_REVIEW_DECISION_PROFILE
                ),
                "required_related_artifact_roles": sorted(required_roles),
                "obligations": [
                    {
                        "obligation_id": "obl-program-math-adverse-review",
                        "description": (
                            "Construct an independent or metamorphic attack on the exact "
                            "formula-code-output chain and report the narrow success boundary."
                        ),
                        "required_artifact_roles": [
                            "computation_output",
                            "computation_source",
                        ],
                        "evidence_types": [
                            "deterministic_output",
                            "executable_source",
                            "runtime_receipt",
                        ],
                        "not_applicable_allowed": False,
                    }
                ],
                "program_math_review": {
                    "source_research_id": result_research["research_id"],
                    "source_task_card_sha256": assignment["task_card_sha256"],
                    "source_artifacts": source_artifacts,
                    "activation": "typed_program_and_output_artifacts",
                },
                "truth_effect": "none",
                "route_effect": "future_refute_task_only",
            },
            actor="v5-adverse-router",
            assurance_contract_revision=V5_ASSURANCE_CONTRACT_REVISION,
        )
        return review

    def _capture_worker_chx_observations(
        self,
        *,
        round_id: str,
        assignment: dict[str, Any],
        return_sha256: str,
    ) -> list[str]:
        """Persist card-bound worker CHX findings in one small nontruth inbox.

        The worker ledger remains canonical.  This projection merely prevents a
        reusable architecture finding from disappearing when Main ingests the
        mathematical return.  Pure mathematical challenges and unbound ledgers
        create no inbox entry.
        """

        ledger_root = self.store.root / "chx-ledgers"
        if ledger_root.is_symlink() or not ledger_root.is_dir():
            return []
        expected_binding = {
            "round_id": round_id,
            "assignment_id": assignment["assignment_id"],
            "task_card_sha256": assignment["task_card_sha256"],
        }
        observation_ids: set[str] = set()
        for ledger_path in sorted(ledger_root.glob("run-*.jsonl")):
            if ledger_path.is_symlink() or not ledger_path.is_file():
                continue
            raw = ledger_path.read_bytes()
            try:
                events = [
                    json.loads(line)
                    for line in raw.decode("utf-8").splitlines()
                    if line
                ]
            except (UnicodeDecodeError, json.JSONDecodeError):
                continue
            if not events or events[-1].get("event") != "run_closed":
                continue
            binding = events[0].get("task_card_binding")
            if not isinstance(binding, dict) or any(
                binding.get(key) != value
                for key, value in expected_binding.items()
            ):
                continue
            reconciliations = {
                event.get("finding_id"): event.get("status")
                for event in events
                if event.get("event") == "finding_reconciled"
            }
            for event in events:
                if event.get("event") != "finding_observed":
                    continue
                finding_id = event.get("finding_id")
                if reconciliations.get(finding_id) not in {
                    "promoted_to_issue",
                    "merged_with_reason",
                }:
                    continue
                identity_payload = {
                    "finding_id": finding_id,
                    "classification": event.get("classification"),
                    "mechanism_type": event.get("mechanism_type"),
                    "trigger": event.get("trigger"),
                    "mechanism": event.get("mechanism"),
                    "upgrade_requirement": event.get("upgrade_requirement"),
                }
                mechanism_identity = (
                    finding_id
                    if isinstance(finding_id, str)
                    else "finding-" + sha256_json(identity_payload)
                )
                observation_id = "chx-observation-" + sha256_json(
                    {
                        "mechanism_identity": mechanism_identity,
                        "project_id": self.store.project_id(),
                    }
                )
                semantic = {
                    "schema_version": 1,
                    "observation_id": observation_id,
                    "mechanism_identity": mechanism_identity,
                    "status": "pending_coordination",
                    "project_id": self.store.project_id(),
                    "round_id": round_id,
                    "assignment_id": assignment["assignment_id"],
                    "task_card_sha256": assignment["task_card_sha256"],
                    "return_sha256": return_sha256,
                    "source_ledger_relpath": str(
                        ledger_path.relative_to(self.store.root)
                    ),
                    "source_ledger_sha256": sha256_bytes(raw),
                    "source_event_sha256": event.get("event_sha256"),
                    "finding": {
                        key: event.get(key)
                        for key in (
                            "finding_id",
                            "classification",
                            "mechanism_type",
                            "trigger",
                            "mechanism",
                            "observed_effect",
                            "mathematical_effect",
                            "current_workaround",
                            "upgrade_requirement",
                            "audit_anchors",
                        )
                    },
                    "routing_policy": (
                        "coordinate_with_chx_and_consult_phx_before_reusable_repair"
                    ),
                    "truth_effect": "none",
                    "project_effect": "none",
                }
                destination = (
                    self.store.root
                    / "chx-observations"
                    / "by-id"
                    / f"{observation_id}.json"
                )
                if destination.exists():
                    existing = self.store._read_json(destination)
                    if (
                        existing.get("observation_id") != observation_id
                        or existing.get("mechanism_identity")
                        != mechanism_identity
                    ):
                        raise ValueError(
                            "CHX observation inbox identity collision"
                        )
                    if (
                        existing.get("round_id") != round_id
                        or existing.get("assignment_id")
                        != assignment["assignment_id"]
                        or existing.get("task_card_sha256")
                        != assignment["task_card_sha256"]
                        or existing.get("return_sha256") != return_sha256
                    ):
                        continue
                else:
                    self.store._write_json_once(destination, semantic)
                observation_ids.add(observation_id)
        return sorted(observation_ids)

    def ingest_return(
        self,
        *,
        round_id: str,
        assignment_id: str,
        worker_final_sha256: str | None = None,
    ) -> dict[str, Any]:
        if worker_final_sha256 is not None and SHA256_RE.fullmatch(
            worker_final_sha256
        ) is None:
            raise ValueError("worker final SHA-256 is invalid")
        round_dir, manifest = self._round_manifest(round_id)
        assignment = self._assignment(manifest, assignment_id)
        receipt_path = round_dir / "returns" / f"{assignment_id}.receipt.json"
        with self.store.v5_mutation_lock(command="ingest-return"):
            if receipt_path.exists():
                receipt = self._validated_ingest_receipt(
                    round_dir=round_dir,
                    assignment=assignment,
                )
                if (
                    worker_final_sha256 is not None
                    and receipt["return_sha256"] != worker_final_sha256
                ):
                    raise ValueError(
                        "terminal ingest conflict: assignment already finalized "
                        "with a different return SHA-256"
                    )
                terminalized_status = "sealed"
                terminalized_error: str | None = None
                if (
                    assignment.get("terminal_seal_revision")
                    == V5_TERMINAL_SEAL_REVISION
                ):
                    # Existing receipts remain subject to the terminal seal's
                    # hard authority boundary.  Only the subsequent COW
                    # projection is best-effort; a corrupt seal or sealed
                    # snapshot must still fail loudly rather than becoming a
                    # cosmetic ``pending`` diagnostic.
                    seal = self._validate_terminal_seal(
                        round_dir=round_dir,
                        assignment=assignment,
                        required=True,
                    )
                    assert seal is not None
                    snapshot = self._snapshot_from_terminal_seal(
                        round_dir=round_dir,
                        assignment=assignment,
                        seal=seal,
                        expected_sha256=receipt["return_sha256"],
                    )
                    try:
                        self._terminalize_worker_paths(
                            round_dir=round_dir,
                            assignment=assignment,
                            snapshot=snapshot,
                            seal=seal,
                        )
                    except Exception as exc:
                        terminalized_status = "pending"
                        terminalized_error = str(exc) or type(exc).__name__
                result = {**receipt, "status": "ingested"}
                if terminalized_error is not None:
                    result["terminalized_lease_status"] = terminalized_status
                    result["terminalized_lease_error"] = terminalized_error
                return result
            self.store.reasoning_modes().require_work_unit_active(round_id)
            try:
                terminal_seal: dict[str, Any] | None = None
                terminal_seal_required = (
                    assignment.get("terminal_seal_revision")
                    == V5_TERMINAL_SEAL_REVISION
                )
                if terminal_seal_required:
                    # A prior attempt may have published the immutable bundle
                    # and then failed during COW.  Recover from that bundle,
                    # never from a mutable source path that a stale worker can
                    # have recreated.
                    terminal_seal = self._validate_terminal_seal(
                        round_dir=round_dir,
                        assignment=assignment,
                        required=False,
                    )
                if terminal_seal is not None:
                    snapshot = self._snapshot_from_terminal_seal(
                        round_dir=round_dir,
                        assignment=assignment,
                        seal=terminal_seal,
                        expected_sha256=worker_final_sha256,
                    )
                else:
                    snapshot = self._snapshot_return(
                        round_id=round_id,
                        assignment_id=assignment_id,
                        expected_sha256=worker_final_sha256,
                    )
            except _WorkerFinalHashMismatch:
                raise
            except _CanonicalSourceNotVisible as visibility_error:
                # ``preflight-return`` validates only one read-only snapshot.
                # A worker may complete the canonical copy-on-write handoff
                # between that snapshot and this locked ingest.  Recheck the
                # immutable terminal seal once; otherwise leave no quarantine
                # or workflow marker and let Main retry the same command.
                if not terminal_seal_required:
                    raise
                try:
                    terminal_seal = self._validate_terminal_seal(
                        round_dir=round_dir,
                        assignment=assignment,
                        required=False,
                    )
                    if terminal_seal is None:
                        raise visibility_error
                    snapshot = self._snapshot_from_terminal_seal(
                        round_dir=round_dir,
                        assignment=assignment,
                        seal=terminal_seal,
                        expected_sha256=worker_final_sha256,
                    )
                except (_WorkerFinalHashMismatch, _CanonicalSourceNotVisible):
                    raise
                except Exception as exc:
                    quarantine = self._quarantine(
                        round_id=round_id,
                        assignment_id=assignment_id,
                        assignment=assignment,
                        error=str(exc),
                    )
                    return {
                        "status": "quarantined",
                        "quarantine_id": quarantine["quarantine_id"],
                        "error": quarantine["error"],
                        "effect": quarantine["effect"],
                        "next_safe_command": quarantine["next_safe_command"],
                    }
            except Exception as exc:
                quarantine = self._quarantine(
                    round_id=round_id,
                    assignment_id=assignment_id,
                    assignment=assignment,
                    error=str(exc),
                )
                return {
                    "status": "quarantined",
                    "quarantine_id": quarantine["quarantine_id"],
                    "error": quarantine["error"],
                    "effect": quarantine["effect"],
                    "next_safe_command": quarantine["next_safe_command"],
                }
            payload = snapshot.payload
            kind_by_outcome = {
                "proof": "proof_attempt",
                "counterexample": "counterexample",
                "evidence": "insight",
                "dead_end": "dead_end",
                "insight": "insight",
                "challenge": "challenge",
            }
            card = self.store._read_json(
                self.store.root / assignment["task_card_relpath"]
            )
            if terminal_seal_required and terminal_seal is None:
                terminal_seal = self._prepare_terminal_seal(
                    round_dir=round_dir,
                    assignment=assignment,
                    snapshot=snapshot,
                )
            assurance_revision = (
                card["assurance_contract"]["revision"]
                if "assurance_contract" in card
                else V5_LEGACY_ASSURANCE_CONTRACT_REVISION
            )
            sealed_artifacts = [
                {
                    "path": item["sealed_path"],
                    "sha256": item["sha256"],
                    **({"role": item["role"]} if "role" in item else {}),
                }
                for item in (
                    terminal_seal["artifacts"]
                    if terminal_seal is not None
                    else []
                )
            ]
            assurance_metadata: dict[str, Any] = {}
            if "assurance_contract" in card:
                research_assurance = payload["research_assurance"]
                route_invalidations = list(
                    research_assurance["route_invalidations"]
                )
                for target_id in route_invalidations:
                    self._research_record(target_id)
                assurance_metadata = {
                    "obligation_dispositions": payload[
                        "obligation_dispositions"
                    ],
                    "computation_manifest": payload["computation_manifest"],
                    "research_assurance": research_assurance,
                    "route_invalidations": route_invalidations,
                    "source_uses": research_assurance["source_uses"],
                    "logic_signals": card["assurance_contract"][
                        "risk_signals"
                    ],
                }
            research = self.add_research(
                {
                    "kind": kind_by_outcome[payload["outcome"]],
                    "claim": payload["claim"],
                    "content": payload["content"],
                    "rationale": payload["narrative"]["rationale"],
                    "relation": "responds_to",
                    "related_research_ids": [assignment["research_id"]],
                    "worker_outcome": payload["outcome"],
                    "narrative": payload["narrative"],
                    "artifacts": (
                        sealed_artifacts
                        if terminal_seal is not None
                        else payload["artifacts"]
                    ),
                    **(
                        {"campaign_id": card["campaign_id"]}
                        if card.get("campaign_id") is not None
                        else {}
                    ),
                    **assurance_metadata,
                    "requested_claim_relation": card[
                        "requested_claim_relation"
                    ],
                    "assignment_provenance": {
                        "schema_version": 2 if terminal_seal is not None else 1,
                        "round_id": round_id,
                        "assignment_id": assignment_id,
                        "worker_id": assignment["worker_id"],
                        "task_card_sha256": assignment["task_card_sha256"],
                        "work_mode": card["work_mode"],
                        "adverse_assignment": card["work_mode"] == "refute",
                        **(
                            {"writer_lease_id": assignment["writer_lease_id"]}
                            if terminal_seal is not None
                            else {}
                        ),
                    },
                },
                actor=assignment["worker_id"],
                task_binding={
                    "round_id": round_id,
                    "assignment_id": assignment_id,
                    "task_card_sha256": assignment["task_card_sha256"],
                    "blackboard_snapshot_sha256": assignment[
                        "blackboard_snapshot_sha256"
                    ],
                    "return_sha256": snapshot.return_sha256,
                    **(
                        {"writer_lease_id": assignment["writer_lease_id"]}
                        if terminal_seal is not None
                        else {}
                    ),
                },
                assurance_contract_revision=assurance_revision,
            )
            program_math_review = self._enqueue_program_math_adverse_review(
                card=card,
                assignment=assignment,
                result_research=research,
                payload=payload,
            )
            attack_capture = None
            if "adverse_routing" in card and payload.get("attack_learning") is not None:
                if card["adverse_routing"].get("schema_version") in (
                    ADVERSE_STRUCTURED_ATTACK_TASK_CARD_SCHEMAS
                ):
                    attack_capture = self.store.adverse_routes().capture_attack(
                        card=card,
                        assignment=assignment,
                        payload=payload,
                        attack_research_id=research["research_id"],
                        return_sha256=snapshot.return_sha256,
                    )
                elif payload["outcome"] == "counterexample":
                    attack_capture = self.store.adverse_routes().capture_counterexample(
                        card=card,
                        assignment=assignment,
                        payload=payload,
                        counterexample_research_id=research["research_id"],
                        return_sha256=snapshot.return_sha256,
                    )
            architecture_observation_ids = self._capture_worker_chx_observations(
                round_id=round_id,
                assignment=assignment,
                return_sha256=snapshot.return_sha256,
            )
            receipt_semantic = {
                "schema_version": 5,
                "policy_revision": V5_POLICY_REVISION,
                "project_id": self.store.project_id(),
                "round_id": round_id,
                "assignment_id": assignment_id,
                "task_card_sha256": assignment["task_card_sha256"],
                "return_sha256": snapshot.return_sha256,
                "outcome": payload["outcome"],
                "research_id": research["research_id"],
                "effect": "one_cumulative_research_entry",
            }
            if terminal_seal is not None:
                receipt_semantic.update(
                    {
                        "terminal_seal_revision": V5_TERMINAL_SEAL_REVISION,
                        "terminal_seal_sha256": terminal_seal["seal_sha256"],
                        "writer_lease_id": assignment["writer_lease_id"],
                    }
                )
            if attack_capture is not None:
                receipt_semantic.update(
                    {
                        "attack_case_id": attack_capture["case_id"],
                        "route_proposal_id": attack_capture["proposal_id"],
                        "attack_evidence_status": attack_capture[
                            "evidence_status"
                        ],
                        "route_activation_policy": attack_capture[
                            "activation_policy"
                        ],
                        "effect": (
                            "one_cumulative_research_entry_plus_nontruth_attack_proposal"
                        ),
                    }
                )
            if program_math_review is not None:
                receipt_semantic.update(
                    {
                        "program_math_review_research_id": program_math_review[
                            "research_id"
                        ],
                        "program_math_review_policy": (
                            "queued_for_future_multidimensional_frontier"
                        ),
                        "effect": (
                            receipt_semantic["effect"]
                            + "_plus_nontruth_program_math_adverse_review"
                        ),
                    }
                )
            if architecture_observation_ids:
                receipt_semantic.update(
                    {
                        "architecture_observation_ids": (
                            architecture_observation_ids
                        ),
                        "architecture_observation_policy": (
                            "nontruth_chx_inbox_pending_coordination"
                        ),
                        "effect": (
                            receipt_semantic["effect"]
                            + "_plus_chx_observation_inbox"
                        ),
                    }
                )
            receipt = {
                **receipt_semantic,
                "receipt_id": "research-ingest-" + sha256_json(receipt_semantic),
                "created_at": _utc_now(),
            }
            self.store._write_json_once(receipt_path, receipt)
            terminalization_error: str | None = None
            if terminal_seal is not None:
                # COW is a nontruth lifecycle projection.  Keep the sealed
                # Research/receipt transaction authoritative even if a host
                # filesystem race or transient permission failure prevents the
                # projection from completing; the next ingest replay retries
                # it from the terminal bundle under the same mutation lock.
                try:
                    self._terminalize_worker_paths(
                        round_dir=round_dir,
                        assignment=assignment,
                        snapshot=snapshot,
                        seal=terminal_seal,
                    )
                except Exception as exc:
                    terminalization_error = str(exc) or type(exc).__name__
            result = {**receipt, "status": "ingested"}
            if terminalization_error is not None:
                result["terminalized_lease_status"] = "pending"
                result["terminalized_lease_error"] = terminalization_error
            return result

    def _release_path(self, release_id: str) -> Path:
        if not isinstance(release_id, str) or not release_id.startswith("release-"):
            raise ValueError("invalid V5 Candidate Release id")
        digest = release_id.removeprefix("release-")
        if SHA256_RE.fullmatch(digest) is None:
            raise ValueError("invalid V5 Candidate Release id")
        return self.candidate_releases_dir / f"{release_id}.json"

    def _decision_path(self, decision_id: str) -> Path:
        if not isinstance(decision_id, str) or not decision_id.startswith("decision-"):
            raise ValueError("invalid V5 Certification Decision id")
        digest = decision_id.removeprefix("decision-")
        if SHA256_RE.fullmatch(digest) is None:
            raise ValueError("invalid V5 Certification Decision id")
        return self.certification_decisions_dir / f"{decision_id}.json"

    def _certification_repair_intent_path(self, decision_id: str) -> Path:
        self._decision_path(decision_id)
        return self.certification_repair_outbox_dir / f"{decision_id}.json"

    def _certification_repair_effect_path(self, decision_id: str) -> Path:
        self._decision_path(decision_id)
        return self.certification_repair_effects_dir / f"{decision_id}.json"

    def _normalize_artifacts(
        self,
        artifacts: Any,
        *,
        seal: bool,
    ) -> tuple[list[dict[str, str]], list[dict[str, str]]]:
        if not isinstance(artifacts, list) or any(
            not isinstance(item, dict)
            or set(item) != {"path", "sha256", "role"}
            for item in artifacts
        ):
            raise ValueError(
                "candidate artifacts must be exact path/sha256/role objects"
            )
        normalized: list[dict[str, str]] = []
        validation_view: list[dict[str, str]] = []
        seen: set[tuple[str, str]] = set()
        total_bytes = 0
        for item in artifacts:
            relpath = _require_nonempty_text(item["path"], "candidate artifact path")
            digest = _require_nonempty_text(
                item["sha256"], "candidate artifact SHA-256"
            )
            role = _require_nonempty_text(item["role"], "candidate artifact role")
            if SHA256_RE.fullmatch(digest) is None:
                raise ValueError("candidate artifact SHA-256 is invalid")
            key = (digest, role)
            if key in seen:
                raise ValueError("candidate artifact hash/role binding is duplicated")
            seen.add(key)
            source = contained_path(
                self.store.root, relpath, "candidate artifact source path"
            )
            if source.is_symlink() or not source.is_file():
                raise ValueError("candidate artifact source is missing or unsafe")
            raw = source.read_bytes()
            if sha256_bytes(raw) != digest:
                raise ValueError("candidate artifact source bytes/hash mismatch")
            total_bytes += len(raw)
            if total_bytes > 64 * 1024 * 1024:
                raise ValueError("candidate artifacts exceed the 64 MiB release cap")
            safe_name = source.name
            sealed_relpath = (
                f"candidate_releases/artifacts/by-hash/{digest}/{safe_name}"
            )
            if seal:
                sealed = self.store.root / sealed_relpath
                self.store._write_bytes_once(sealed, raw)
            normalized.append(
                {
                    "artifact_sha256": digest,
                    "role": role,
                    "name": safe_name,
                    "sealed_relpath": sealed_relpath,
                }
            )
            validation_view.append(
                {"path": sealed_relpath, "sha256": digest, "role": role}
            )
        normalized.sort(
            key=lambda item: (
                item["artifact_sha256"],
                item["role"],
                item["name"],
            )
        )
        validation_view.sort(
            key=lambda item: (item["sha256"], item["role"], item["path"])
        )
        return normalized, validation_view

    def _validate_paper_evidence_refs(
        self,
        refs: Any,
        *,
        validation_subject: dict[str, Any],
        require_current: bool = True,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> list[dict[str, Any]]:
        if not isinstance(refs, list) or any(not isinstance(item, dict) for item in refs):
            raise ValueError("paper_evidence_refs must be a list of objects")
        if validation_subject["kind"] != "paper":
            if refs:
                raise ValueError(
                    "paper_evidence_refs are only valid for a paper validation subject"
                )
            return []
        if not refs:
            raise ValueError("paper validation requires Logic and Audit EvidenceRefs")
        paper = self._inspection_paper_logic(_inspection_context)
        current = set(paper.status()["current_snapshot_ids"])
        normalized: list[dict[str, Any]] = []
        graph_kinds: set[str] = set()
        bound_target_ids: set[str] = set()
        ref_bindings: set[tuple[str, str]] = set()
        for index, ref in enumerate(refs, 1):
            required = {
                "paper_id",
                "snapshot_id",
                "snapshot_sha256",
                "graph_kind",
                "target_artifact_sha256",
                "target_node_ids",
            }
            if set(ref) != required:
                raise ValueError(
                    f"paper EvidenceRef {index} fields are not exact"
                )
            snapshot_id = _require_nonempty_text(
                ref["snapshot_id"], "paper snapshot id"
            )
            if require_current and snapshot_id not in current:
                raise ValueError(
                    "paper EvidenceRef must bind a current, nonsuperseded snapshot"
                )
            manifest = paper.snapshot_manifest(snapshot_id)
            manifest_path = paper.snapshots_dir / snapshot_id / "manifest.json"
            if ref["snapshot_sha256"] != sha256_bytes(manifest_path.read_bytes()):
                raise ValueError("paper EvidenceRef snapshot bytes/hash mismatch")
            if (
                ref["paper_id"] != validation_subject["subject_id"]
                or manifest["paper_id"] != ref["paper_id"]
                or manifest["graph_kind"] != ref["graph_kind"]
            ):
                raise ValueError("paper EvidenceRef target/snapshot mismatch")
            artifact_sha = validation_subject["artifact_sha256"]
            if (
                ref["target_artifact_sha256"] != artifact_sha
                or artifact_sha
                not in {
                    item.get("artifact_sha256")
                    for item in manifest["source_artifacts"]
                    if isinstance(item, dict)
                }
            ):
                raise ValueError(
                    "paper EvidenceRef does not bind the requested source artifact"
                )
            target_ids = _require_string_list(
                ref["target_node_ids"], "paper EvidenceRef target node ids"
            )
            if len(target_ids) != len(set(target_ids)):
                raise ValueError("paper EvidenceRef target node ids are duplicated")
            nodes, _ = paper.snapshot_objects(snapshot_id)
            missing = sorted(set(target_ids).difference(nodes))
            if missing:
                raise ValueError(
                    "paper EvidenceRef target nodes are absent: "
                    + ", ".join(missing)
                )
            bound_target_ids.update(target_ids)
            graph_kinds.add(ref["graph_kind"])
            binding = (ref["graph_kind"], snapshot_id)
            if binding in ref_bindings:
                raise ValueError("paper EvidenceRef snapshot binding is duplicated")
            ref_bindings.add(binding)
            normalized.append(
                {
                    "paper_id": ref["paper_id"],
                    "snapshot_id": snapshot_id,
                    "snapshot_sha256": ref["snapshot_sha256"],
                    "graph_kind": ref["graph_kind"],
                    "target_artifact_sha256": artifact_sha,
                    "target_node_ids": sorted(dict.fromkeys(target_ids)),
                }
            )
        if not {"logic", "audit"}.issubset(graph_kinds):
            raise ValueError(
                "paper validation requires both current Logic and Audit snapshots"
            )
        load_bearing = set(validation_subject["load_bearing_node_ids"])
        unbound = sorted(load_bearing.difference(bound_target_ids))
        if unbound:
            raise ValueError(
                "paper load-bearing nodes are not bound by any EvidenceRef: "
                + ", ".join(unbound)
            )
        normalized.sort(key=lambda item: (item["graph_kind"], item["snapshot_id"]))
        return normalized

    def _validate_evidence_bridge_refs(
        self,
        refs: Any,
        *,
        artifacts: list[dict[str, Any]],
        sealed_record: bool,
        require_current: bool,
    ) -> list[dict[str, Any]]:
        if not isinstance(refs, list) or any(not isinstance(item, dict) for item in refs):
            raise ValueError("evidence_bridge_refs must be a list of objects")
        expected_fields = (
            {
                "bridge_id",
                "bridge_record_sha256",
                "bridge_artifact_sha256",
                "library_id",
                "evidence_ids",
            }
            if sealed_record
            else {"bridge_id", "bridge_artifact_sha256"}
        )
        artifact_bindings: dict[str, Path] = {}
        bridge_artifact_hashes: set[str] = set()
        for artifact in artifacts:
            if sealed_record:
                digest = artifact.get("artifact_sha256")
                role = artifact.get("role")
                relpath = artifact.get("sealed_relpath")
            else:
                digest = artifact.get("sha256")
                role = artifact.get("role")
                relpath = artifact.get("path")
            if role != "evidence_bridge_capsule":
                continue
            if not isinstance(digest, str) or not isinstance(relpath, str):
                raise ValueError("Evidence bridge artifact binding is malformed")
            if digest in artifact_bindings:
                raise ValueError("Evidence bridge artifact hash is duplicated")
            artifact_bindings[digest] = contained_path(
                self.store.root,
                relpath,
                "Evidence bridge capsule artifact",
            )
            bridge_artifact_hashes.add(digest)
        normalized: list[dict[str, Any]] = []
        seen_bridge_ids: set[str] = set()
        seen_evidence_ids: set[str] = set()
        for index, ref in enumerate(refs, 1):
            if set(ref) != expected_fields:
                raise ValueError(
                    f"Evidence bridge ref {index} fields are not exact"
                )
            bridge_id = _require_nonempty_text(ref["bridge_id"], "Evidence bridge id")
            digest = _require_nonempty_text(
                ref["bridge_artifact_sha256"], "Evidence bridge artifact SHA-256"
            )
            if SHA256_RE.fullmatch(digest) is None or digest not in artifact_bindings:
                raise ValueError(
                    "Evidence bridge ref must bind a declared bridge capsule artifact"
                )
            if bridge_id in seen_bridge_ids:
                raise ValueError("Evidence bridge ref is duplicated")
            seen_bridge_ids.add(bridge_id)
            artifact_record = self.store._read_json(artifact_bindings[digest])
            expected_record_sha = artifact_record.get("record_sha256")
            if not isinstance(expected_record_sha, str):
                raise ValueError("Evidence bridge artifact lacks its record hash")
            validated = self.store.evidence().validate_bridge_artifact(
                path=artifact_bindings[digest],
                expected_sha256=digest,
                expected_bridge_id=bridge_id,
                expected_record_sha256=expected_record_sha,
                require_current=require_current,
            )
            if sealed_record and validated != ref:
                raise ValueError("sealed Evidence bridge ref drifted from its capsule")
            overlap = seen_evidence_ids.intersection(validated["evidence_ids"])
            if overlap:
                raise ValueError(
                    "Evidence item is selected by multiple bridge refs: "
                    + ", ".join(sorted(overlap))
                )
            seen_evidence_ids.update(validated["evidence_ids"])
            normalized.append(validated)
        if set(item["bridge_artifact_sha256"] for item in normalized) != bridge_artifact_hashes:
            raise ValueError(
                "every evidence_bridge_capsule artifact must have exactly one Evidence bridge ref"
            )
        normalized.sort(key=lambda item: item["bridge_id"])
        return normalized

    def _validate_requested_assurance(
        self,
        assurance: Any,
        *,
        candidate_ids: set[str],
        internal_edges: list[list[str]],
        candidate_facts: dict[str, Fact] | None = None,
    ) -> dict[str, Any]:
        if (
            isinstance(assurance, dict)
            and _is_research_draft_assurance_revision(
                assurance.get("contract_revision")
            )
        ):
            if candidate_facts is None or set(candidate_facts) != candidate_ids:
                raise ValueError(
                    "research-draft assurance requires the exact Candidate Fact set"
                )
            return validate_research_draft_assurance(
                assurance,
                candidate_facts=candidate_facts,
                internal_edges=internal_edges,
            )
        if not isinstance(assurance, dict) or set(assurance) != {
            "validation_subject",
            "validation_granularity",
            "coverage",
        }:
            raise ValueError("requested_assurance fields are not exact")
        subject = assurance["validation_subject"]
        if not isinstance(subject, dict) or set(subject) != {
            "kind",
            "subject_id",
            "artifact_sha256",
            "load_bearing_node_ids",
        }:
            raise ValueError("validation_subject fields are not exact")
        if subject.get("kind") not in {"theorem", "paper"}:
            raise ValueError("validation_subject kind must be theorem or paper")
        subject_id = _require_nonempty_text(
            subject.get("subject_id"), "validation subject id"
        )
        load_bearing = _require_string_list(
            subject.get("load_bearing_node_ids"),
            "validation subject load-bearing node ids",
        )
        if len(set(load_bearing)) != len(load_bearing):
            raise ValueError("load-bearing node ids must be unique")
        artifact_sha = subject.get("artifact_sha256")
        if subject["kind"] == "paper":
            if not isinstance(artifact_sha, str) or SHA256_RE.fullmatch(
                artifact_sha
            ) is None:
                raise ValueError("paper validation subject requires an artifact SHA-256")
        elif artifact_sha is not None:
            raise ValueError("theorem validation subject artifact_sha256 must be null")
        granularity = assurance.get("validation_granularity")
        if granularity not in V5_VALIDATION_GRANULARITIES:
            raise ValueError("validation_granularity is invalid")
        coverage = assurance.get("coverage")
        if not isinstance(coverage, list) or any(
            not isinstance(item, dict) for item in coverage
        ):
            raise ValueError("validation coverage must be a list of objects")
        normalized_coverage: list[dict[str, Any]] = []
        covered: set[str] = set()
        for item in coverage:
            if set(item) != {"paper_node_id", "disposition", "fact_id", "reason"}:
                raise ValueError("validation coverage entry fields are not exact")
            node_id = _require_nonempty_text(
                item["paper_node_id"], "coverage paper node id"
            )
            if node_id in covered:
                raise ValueError("validation coverage contains a duplicate node")
            covered.add(node_id)
            disposition = item["disposition"]
            if disposition not in V5_COVERAGE_DISPOSITIONS:
                raise ValueError("validation coverage disposition is invalid")
            fact_id = item["fact_id"]
            reason = item["reason"]
            if not isinstance(reason, str):
                raise ValueError("validation coverage reason must be a string")
            if disposition == "fact_bundle_member":
                if not isinstance(fact_id, str) or fact_id not in candidate_ids:
                    raise ValueError(
                        "fact_bundle_member coverage must name a release candidate"
                    )
            elif fact_id is not None:
                raise ValueError(
                    "non-Fact coverage dispositions must use fact_id=null"
                )
            if disposition != "fact_bundle_member" and not reason.strip():
                raise ValueError(
                    "non-Fact coverage disposition requires an explicit reason"
                )
            normalized_coverage.append(
                {
                    "paper_node_id": node_id,
                    "disposition": disposition,
                    "fact_id": fact_id,
                    "reason": reason.strip(),
                }
            )
        if set(load_bearing) != covered:
            missing = sorted(set(load_bearing).difference(covered))
            extra = sorted(covered.difference(load_bearing))
            raise ValueError(
                "validation coverage does not exactly cover load-bearing nodes; "
                f"missing={missing} extra={extra}"
            )
        if granularity == "monolithic_theorem":
            if len(candidate_ids) != 1:
                raise ValueError(
                    "monolithic_theorem requires exactly one candidate Fact"
                )
            if load_bearing or coverage:
                raise ValueError(
                    "monolithic_theorem cannot claim nodewise paper coverage"
                )
        elif granularity == "atomic_fact_dag":
            if len(candidate_ids) < 2 or not internal_edges:
                raise ValueError(
                    "atomic_fact_dag requires multiple candidates and an internal edge"
                )
            if subject["kind"] != "theorem" or load_bearing or coverage:
                raise ValueError(
                    "atomic_fact_dag without a paper target cannot claim paper coverage"
                )
        elif granularity == "nodewise_proof_dag":
            if len(candidate_ids) < 2 or not internal_edges:
                raise ValueError(
                    "nodewise_proof_dag requires multiple candidates and an internal edge"
                )
            if subject["kind"] != "paper" or not load_bearing:
                raise ValueError(
                    "nodewise_proof_dag requires a paper target and load-bearing nodes"
                )
        else:
            if not candidate_ids:
                raise ValueError(
                    "paper_target_closure requires at least one Candidate Fact"
                )
            if subject["kind"] != "paper" or not load_bearing:
                raise ValueError(
                    "paper_target_closure requires a paper subject and exact closure nodes"
                )
        return {
            "validation_subject": {
                "kind": subject["kind"],
                "subject_id": subject_id,
                "artifact_sha256": artifact_sha,
                "load_bearing_node_ids": sorted(load_bearing),
            },
            "validation_granularity": granularity,
            "coverage": sorted(
                normalized_coverage, key=lambda item: item["paper_node_id"]
            ),
        }

    def _candidate_interface(
        self,
        fact: Fact,
        rendered: bytes,
        *,
        assurance_contract_revision: str,
    ) -> dict[str, Any]:
        placeholder = sha256_json(["v5-candidate-interface", fact.fact_id])
        return build_statement_interface(
            fact=fact,
            stored_fact_sha256=sha256_bytes(rendered),
            acceptance_event_sha256=placeholder,
            admission_review_id=placeholder,
            workflow_evidence_version=5,
            assurance_contract_revision=assurance_contract_revision,
        )

    def _validate_sealed_research_draft_release(
        self,
        record: dict[str, Any],
        *,
        candidate_facts: dict[str, Fact],
        deep_dependencies: bool,
    ) -> dict[str, Any]:
        """Validate the prospective Paper-admission seam without reopening it N times."""

        evidence = record.get("research_draft_evidence")
        if not isinstance(evidence, dict) or set(evidence) != {
            "plan",
            "batch",
            "adequacy_receipt",
            "research_records",
        }:
            raise ValueError("sealed research-draft evidence fields are not exact")
        plan = evidence["plan"]
        batch = evidence["batch"]
        adequacy = evidence["adequacy_receipt"]
        if not all(isinstance(item, dict) for item in (plan, batch, adequacy)):
            raise ValueError("sealed research-draft evidence records are malformed")
        if plan.get("record_sha256") != sha256_json(
            {key: value for key, value in plan.items() if key != "record_sha256"}
        ):
            raise ValueError("sealed research-draft plan hash mismatch")
        if batch.get("record_sha256") != sha256_json(
            {key: value for key, value in batch.items() if key != "record_sha256"}
        ):
            raise ValueError("sealed research-draft batch hash mismatch")
        if adequacy.get("adequacy_receipt_sha256") != sha256_json(
            {
                key: value
                for key, value in adequacy.items()
                if key != "adequacy_receipt_sha256"
            }
        ):
            raise ValueError("sealed research-draft adequacy receipt hash mismatch")
        validate_research_draft_ref(
            record.get("research_draft_ref"),
            plan=plan,
            batch=batch,
            adequacy_receipt=adequacy,
        )
        research_records = evidence["research_records"]
        if not isinstance(research_records, list) or any(
            not isinstance(item, dict) for item in research_records
        ):
            raise ValueError("sealed research-draft Research records are malformed")
        embedded_research: dict[str, dict[str, Any]] = {}
        for item in research_records:
            research_id = item.get("research_id")
            if not isinstance(research_id, str) or research_id in embedded_research:
                raise ValueError("sealed research-draft Research id is invalid or duplicated")
            if item.get("record_sha256") != sha256_json(
                {key: value for key, value in item.items() if key != "record_sha256"}
            ):
                raise ValueError("sealed research-draft Research record hash mismatch")
            embedded_research[research_id] = item
        expected_research = {
            binding["research_id"]: binding["record_sha256"]
            for binding in record.get("research_bindings", [])
        }
        if set(embedded_research) != set(expected_research) or any(
            embedded_research[research_id]["record_sha256"] != digest
            for research_id, digest in expected_research.items()
        ):
            raise ValueError("sealed research-draft Research closure drifted")
        assurance = validate_research_draft_assurance(
            record.get("requested_assurance"),
            candidate_facts=candidate_facts,
            internal_edges=record.get("internal_edges", []),
        )
        if assurance != record.get("requested_assurance"):
            raise ValueError("sealed research-draft assurance normalization drifted")
        preflight = record.get("research_draft_admission_preflight")
        if not isinstance(preflight, dict):
            raise ValueError("sealed research-draft preflight is missing")
        preflight_semantic = {
            key: value
            for key, value in preflight.items()
            if key not in {"preflight_id", "preflight_sha256"}
        }
        preflight_sha = sha256_json(preflight_semantic)
        if (
            preflight.get("contract_revision")
            != RESEARCH_DRAFT_PREFLIGHT_REVISION
            or preflight.get("preflight_id") != "rdpf-" + preflight_sha
            or preflight.get("preflight_sha256") != preflight_sha
            or preflight.get("structural_status") != "PASS"
            or preflight.get("truth_effect") != "none"
            or set(preflight.get("candidate_fact_ids", [])) != set(candidate_facts)
            or preflight.get("plan_id") != plan.get("plan_id")
            or preflight.get("batch_id") != batch.get("batch_id")
        ):
            raise ValueError("sealed research-draft preflight binding is invalid")
        closure = record.get("paper_evidence_transport_closure")
        if not isinstance(closure, dict):
            raise ValueError("sealed Paper EvidenceRef transport closure is missing")
        closure_semantic = {
            key: value for key, value in closure.items() if key != "closure_sha256"
        }
        if (
            closure.get("contract_revision") != PAPER_TRANSPORT_REVISION
            or closure.get("closure_sha256") != sha256_json(closure_semantic)
            or closure.get("off_project_reconstructable") is not True
            or preflight.get("paper_transport_closure_sha256")
            != closure.get("closure_sha256")
        ):
            raise ValueError("sealed Paper EvidenceRef transport closure drifted")
        members = closure.get("members")
        if not isinstance(members, list) or any(
            not isinstance(item, dict) for item in members
        ):
            raise ValueError("sealed Paper transport members are malformed")
        artifact_bindings = {
            (item.get("artifact_sha256"), item.get("role"))
            for item in record.get("artifacts", [])
        }
        required_members = {
            (item.get("artifact_sha256"), item.get("role")) for item in members
        }
        if not required_members.issubset(artifact_bindings):
            raise ValueError("sealed release omits a Paper transport member")
        ref_snapshot_ids = {
            item.get("snapshot_id") for item in record.get("paper_evidence_refs", [])
        }
        if not ref_snapshot_ids.issubset(set(closure.get("snapshot_ids", []))):
            raise ValueError("sealed Paper EvidenceRef/transport snapshot set drifted")
        receipt = record.get("validated_dependency_receipt")
        receipt_result = self._validate_research_draft_dependency_cache(
            record,
            force_deep=deep_dependencies,
        )
        if receipt.get("validation_subject_sha256") != preflight_sha:
            raise ValueError("validated dependency receipt binds the wrong preflight")
        return receipt_result

    def _validate_research_draft_dependency_cache(
        self,
        record: dict[str, Any],
        *,
        force_deep: bool,
    ) -> dict[str, Any]:
        """Hash only dependency files whose stable local fingerprint changed."""

        receipt = record["validated_dependency_receipt"]
        validate_dependency_receipt(
            receipt,
            project_root=self.store.root,
            changed_dependency_ids=set(),
        )
        fingerprints: dict[str, dict[str, int]] = {}
        for item in receipt["dependencies"]:
            relpath = item["relpath_or_null"]
            if relpath is None:
                continue
            path = contained_path(
                self.store.root,
                relpath,
                "research-draft cached dependency",
            )
            if path.is_symlink() or not path.is_file():
                raise ValueError("research-draft dependency is missing or unsafe")
            stat = path.stat()
            fingerprints[item["dependency_id"]] = {
                "device": stat.st_dev,
                "inode": stat.st_ino,
                "size": stat.st_size,
                "mtime_ns": stat.st_mtime_ns,
                "ctime_ns": stat.st_ctime_ns,
            }
        cache_dir = self.candidate_releases_dir / "_dependency_cache"
        cache_path = cache_dir / f"{record['release_id']}.json"
        previous: dict[str, Any] | None = None
        if cache_path.exists():
            if cache_path.is_symlink() or not cache_path.is_file():
                raise ValueError("research-draft dependency cache is unsafe")
            value = self.store._read_json(cache_path)
            if (
                isinstance(value, dict)
                and value.get("release_id") == record["release_id"]
                and value.get("receipt_id") == receipt["receipt_id"]
                and value.get("truth_effect") == "none"
            ):
                previous = value
        previous_fingerprints = (
            previous.get("file_fingerprints", {}) if previous is not None else {}
        )
        changed = (
            set(fingerprints)
            if force_deep or previous is None
            else {
                dependency_id
                for dependency_id, fingerprint in fingerprints.items()
                if previous_fingerprints.get(dependency_id) != fingerprint
            }
        )
        removed = set(previous_fingerprints).difference(fingerprints)
        if removed:
            raise ValueError("research-draft dependency cache inventory drifted")
        if not changed and previous is not None:
            return {
                "receipt_id": receipt["receipt_id"],
                "checked_dependency_ids": [],
                "reuse_mode": "sealed_record_only",
                "truth_effect": "none",
                "cache_status": "reused",
                "changed_dependency_ids": [],
            }
        validation = validate_dependency_receipt(
            receipt,
            project_root=self.store.root,
            changed_dependency_ids=changed,
        )
        cache = {
            "schema_version": 1,
            "release_id": record["release_id"],
            "release_sha256": record["release_sha256"],
            "receipt_id": receipt["receipt_id"],
            "file_fingerprints": fingerprints,
            "last_checked_dependency_ids": validation["checked_dependency_ids"],
            "cache_effect": "performance_only",
            "truth_effect": "none",
        }
        if previous != cache:
            self.store._write_json_atomic(cache_path, cache)
        return {
            **validation,
            "cache_status": "refreshed" if changed else "reused",
            "changed_dependency_ids": sorted(changed),
        }

    def _research_assurance_evidence(
        self,
        *,
        research_records: list[dict[str, Any]],
        authorized_artifact_hashes: set[str],
        assurance_contract_revision: str,
    ) -> list[dict[str, Any]]:
        if assurance_contract_revision != V5_ASSURANCE_CONTRACT_REVISION:
            return []
        evidence: list[dict[str, Any]] = []
        for record in research_records:
            if self._research_assurance_revision(record) != V5_ASSURANCE_CONTRACT_REVISION:
                continue
            metadata = record["metadata"]
            if "task_binding" not in metadata:
                continue
            required = {
                "obligation_dispositions",
                "computation_manifest",
                "research_assurance",
                "artifacts",
            }
            missing = sorted(required.difference(metadata))
            if missing:
                raise ValueError(
                    "task-bound current Research is missing assurance evidence: "
                    + ", ".join(missing)
                )
            artifact_bindings = [
                {
                    "artifact_sha256": item["sha256"],
                    "role": item["role"],
                }
                for item in metadata["artifacts"]
            ]
            missing_hashes = sorted(
                {
                    item["artifact_sha256"] for item in artifact_bindings
                }.difference(authorized_artifact_hashes)
            )
            if missing_hashes:
                raise ValueError(
                    "Candidate Release does not seal and authorize every bound Research "
                    "artifact needed by the verifier: "
                    + ", ".join(missing_hashes)
                )
            evidence.append(
                {
                    "research_id": record["research_id"],
                    "record_sha256": record["record_sha256"],
                    "task_binding": metadata["task_binding"],
                    "obligation_dispositions": metadata[
                        "obligation_dispositions"
                    ],
                    "computation_manifest": metadata["computation_manifest"],
                    "research_assurance": metadata["research_assurance"],
                    "artifact_bindings": sorted(
                        artifact_bindings,
                        key=lambda item: (
                            item["role"],
                            item["artifact_sha256"],
                        ),
                    ),
                }
            )
        if not evidence:
            raise ValueError(
                "current Candidate Release requires at least one task-bound Research "
                "assurance-evidence record"
            )
        return sorted(evidence, key=lambda item: item["research_id"])

    def _applicable_assurance_checks(
        self,
        *,
        facts: dict[str, Fact],
        research_records: list[dict[str, Any]],
        assurance_contract_revision: str,
    ) -> list[str]:
        """Derive only the 0.4.3 checks triggered by this exact release."""

        if assurance_contract_revision != V5_ASSURANCE_CONTRACT_REVISION:
            return []
        checks = {"research_obligation_evidence"}
        risk_signals = {
            signal
            for record in research_records
            for signal in record.get("metadata", {}).get("logic_signals", [])
            if isinstance(signal, str)
        }
        if "topology_extremal_invariants" in risk_signals:
            checks.add("extremal_edge_cases")
        if "parametric_contour_substitution" in risk_signals:
            checks.add("contour_substitution")
        if "claimed_combinatorial_structure" in risk_signals:
            checks.add("structural_computation")
        if "geometric_stage_typing" in risk_signals:
            checks.add("geometric_stage_typing")
        if "program_math_semantic_alignment" in risk_signals or any(
            record.get("metadata", {}).get("computation_manifest") is not None
            for record in research_records
        ):
            checks.add("program_math_semantic_alignment")
        if "source_formula" in risk_signals or "fixed_to_family_transport" in risk_signals:
            checks.add("research_source_use")

        for fact in facts.values():
            for ref in fact.external_refs:
                if ref.get("source_evidence_version") != 4:
                    continue
                checks.update(
                    {
                        "source_transcription_coverage",
                        "source_conclusion_transport",
                        "source_status_evidence",
                    }
                )
                audit = ref.get("critical_audit")
                if isinstance(audit, dict) and any(
                    isinstance(item, dict) and item.get("status") != "pass"
                    for item in audit.get("sanity_checks", [])
                ):
                    checks.add("source_nonpass_reconciliation")
                applicability = ref.get("applicability")
                if isinstance(applicability, dict) and any(
                    isinstance(item, dict) and "contour_substitution" in item
                    for item in applicability.get("transport_obligations", [])
                ):
                    checks.add("contour_substitution")
            if any(
                isinstance(entry, dict) and "claimed_structure" in entry
                for entry in fact.computational_evidence
            ):
                checks.add("structural_computation")
        return sorted(checks)

    def _prepare_candidate_facts(
        self,
        fact_payloads: Any,
        *,
        artifacts: list[dict[str, str]],
        authorized_artifact_hashes: set[str],
        verification_plan: dict[str, Any],
        assurance_contract_revision: str,
        require_geometric_stage_typing: bool = False,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> tuple[
        dict[str, Fact],
        dict[str, bytes],
        list[str],
        list[list[str]],
        list[str],
    ]:
        if not isinstance(fact_payloads, list) or not fact_payloads or any(
            not isinstance(item, dict) for item in fact_payloads
        ):
            raise ValueError("Candidate Release facts must be a nonempty object list")
        facts: dict[str, Fact] = {}
        rendered: dict[str, bytes] = {}
        for payload in fact_payloads:
            fact = Fact.from_dict(payload)
            errors = fact.validate()
            if errors:
                raise ValueError("; ".join(errors))
            if fact.problem_id != self.store.project_id():
                raise ValueError("Candidate Fact belongs to another project")
            raw = validate_fact_round_trip(fact).encode("utf-8")
            if fact.fact_id in facts:
                raise ValueError("Candidate Release has a duplicate Fact id")
            validate_external_refs_for_submission(
                fact.external_refs,
                fact.proof,
                require_formula_fidelity=True,
                require_critical_audit=True,
                required_source_evidence_version=(
                    4
                    if assurance_contract_revision
                    == V5_ASSURANCE_CONTRACT_REVISION
                    else 3
                ),
                artifact_hashes=authorized_artifact_hashes,
            )
            validate_elementary_uses_for_submission(
                fact.elementary_uses,
                fact.proof,
            )
            clauses = extract_statement_clauses(fact.statement, require_v4=True)
            validate_quantifier_ledger(
                fact.quantifier_ledger,
                statement=fact.statement,
                proof=fact.proof,
                clause_ids={item["clause_id"] for item in clauses},
            )
            for convention_id in fact.convention_profile_ids:
                self.store.claims().show_convention(convention_id)
            validate_computational_evidence(
                fact.computational_evidence,
                proof=fact.proof,
                artifacts=artifacts,
                verification_plan=verification_plan,
                workflow_evidence_version=V5_WORKFLOW_EVIDENCE_VERSION,
                assurance_contract_revision=assurance_contract_revision,
            )
            validate_terminology(fact.terminology, proof=fact.proof)
            typed_objects = extract_geometric_objects(fact.statement)
            if (
                assurance_contract_revision == V5_ASSURANCE_CONTRACT_REVISION
                and require_geometric_stage_typing
                and any(
                    clause_is_stage_sensitive(clause["text"])
                    for clause in clauses
                )
                and not typed_objects
            ):
                raise ValueError(
                    "stage-sensitive Candidate Fact requires explicit [GEO:*] "
                    "stage/ambient/space/genus ownership anchors"
                )
            facts[fact.fact_id] = fact
            rendered[fact.fact_id] = raw
        active = self.store.facts(
            _inspection_context=_inspection_context,
        )
        collisions = sorted(set(facts).intersection(active))
        if collisions:
            raise ValueError(
                "Candidate Release collides with active V5 Facts: "
                + ", ".join(collisions)
            )
        combined = {**active, **facts}
        graph = DependencyGraph(combined)
        missing = graph.missing_predecessors()
        if missing:
            raise ValueError(
                "Candidate Release has unavailable predecessors: "
                + ", ".join(
                    f"{fact_id}->{predecessor}"
                    for fact_id, predecessor in missing
                )
            )
        graph.topological_order()
        candidate_interfaces = {
            fact_id: self._candidate_interface(
                fact,
                rendered[fact_id],
                assurance_contract_revision=assurance_contract_revision,
            )
            for fact_id, fact in facts.items()
        }

        def interface_lookup(fact_id: str) -> dict[str, Any]:
            if fact_id in candidate_interfaces:
                return candidate_interfaces[fact_id]
            return self.store.statement_interface(
                fact_id,
                materialize=False,
                _inspection_context=_inspection_context,
            )

        def legacy_premise_resolver(
            source_fact_id: str,
            source_clause: dict[str, Any],
        ) -> list[dict[str, str]]:
            tokens = referenced_premise_clause_tokens(source_clause["text"])
            if not tokens:
                return []
            source_fact = combined[source_fact_id]
            matches: list[dict[str, str]] = []
            for premise_fact_id in source_fact.predecessors:
                interface = validate_statement_interface(
                    interface_lookup(premise_fact_id)
                )
                for clause in interface["clauses"]:
                    if clause["clause_id"].upper() not in tokens:
                        continue
                    statement_sha = sha256_bytes(
                        clause["text"].encode("utf-8")
                    )
                    matches.append(
                        {
                            "fact_id": premise_fact_id,
                            "clause_id": clause["clause_id"],
                            "statement_sha256": statement_sha,
                            "witness_id": (
                                "LEGACY-PREMISE:"
                                f"{premise_fact_id}:{clause['clause_id']}:{statement_sha}"
                            ),
                        }
                    )
            if not matches:
                raise ValueError(
                    "legacy conditional predecessor names a premise clause that "
                    "is not exported by an exact declared predecessor"
                )
            if len(matches) != 1:
                raise ValueError(
                    "legacy conditional predecessor premise reference is ambiguous"
                )
            return sorted(
                matches,
                key=lambda item: (item["fact_id"], item["clause_id"]),
            )

        for fact in facts.values():
            validate_predecessor_uses(
                fact.predecessor_uses,
                predecessors=fact.predecessors,
                proof=fact.proof,
                interface_lookup=interface_lookup,
                convention_profile_ids=fact.convention_profile_ids,
                assurance_contract_revision=assurance_contract_revision,
                target_typed_objects=extract_geometric_objects(fact.statement),
                target_statement_interface=candidate_interfaces[fact.fact_id],
                legacy_premise_resolver=legacy_premise_resolver,
            )
        internal_edges = sorted(
            [
                [predecessor, fact_id]
                for fact_id, fact in facts.items()
                for predecessor in fact.predecessors
                if predecessor in facts
            ]
        )
        external_predecessors = sorted(
            {
                predecessor
                for fact in facts.values()
                for predecessor in fact.predecessors
                if predecessor not in facts
            }
        )
        order = [
            fact_id
            for fact_id in graph.topological_order(set(facts))
            if fact_id in facts
        ]
        return facts, rendered, order, internal_edges, external_predecessors

    def _lightweight_research_records(self) -> dict[str, dict[str, Any]]:
        """Read immutable Research identity/lineage without opening its artifacts.

        Candidate Release uses this projection only for the pre-release adverse
        gate.  It deliberately runs before source hashing, assurance replay, and
        artifact sealing, so a missing fresh attack fails at the cheap boundary.
        The normal full Research validator still runs later and remains the
        authority for release construction.
        """

        required = {
            "schema_version",
            "policy_revision",
            "project_id",
            "research_id",
            "kind",
            "status",
            "claim",
            "content",
            "rationale",
            "dependencies",
            "source",
            "relation",
            "related_research_ids",
            "metadata",
            "actor",
            "created_at",
            "semantic_sha256",
            "record_sha256",
        }
        records: dict[str, dict[str, Any]] = {}
        for path in sorted(self.research_entries_dir.glob("*.json")):
            if path.is_symlink() or not path.is_file():
                raise ValueError("fresh adverse Research inventory is unsafe")
            record = self.store._read_json(path)
            if not isinstance(record, dict) or set(record) != required:
                raise ValueError(
                    "fresh adverse Research header fields are not exact"
                )
            research_id = validate_memory_id(
                _require_nonempty_text(
                    record.get("research_id"), "fresh adverse Research id"
                )
            )
            if (
                path.stem != research_id
                or record.get("schema_version") != 5
                or record.get("policy_revision") != V5_POLICY_REVISION
                or record.get("project_id") != self.store.project_id()
                or record.get("kind") not in V5_RESEARCH_KINDS
                or record.get("status") not in MEMORY_STATUSES
            ):
                raise ValueError("fresh adverse Research identity is invalid")
            if research_id in records:
                raise ValueError("fresh adverse Research ids are duplicated")
            related = _require_string_list(
                record.get("related_research_ids"),
                "fresh adverse Research related ids",
            )
            for related_id in related:
                validate_memory_id(related_id)
            if not isinstance(record.get("metadata"), dict):
                raise ValueError("fresh adverse Research metadata must be an object")
            _require_nonempty_text(record.get("actor"), "fresh adverse Research actor")
            _parse_utc_timestamp(
                record.get("created_at"),
                label="fresh adverse Research created_at",
            )
            independent_adverse_required(record)
            self._research_is_adverse_assignment(record)
            semantic = {
                key: record[key]
                for key in required.difference(
                    {
                        "research_id",
                        "created_at",
                        "semantic_sha256",
                        "record_sha256",
                    }
                )
            }
            if (
                record.get("semantic_sha256") != sha256_json(semantic)
                or research_id != record["semantic_sha256"][:12]
            ):
                raise ValueError("fresh adverse Research semantic hash mismatch")
            without_hash = {
                key: value
                for key, value in record.items()
                if key != "record_sha256"
            }
            if record.get("record_sha256") != sha256_json(without_hash):
                raise ValueError("fresh adverse Research record hash mismatch")
            records[research_id] = record
        return records

    def _candidate_fact_fingerprints_for_adverse(
        self,
        fact_payloads: Any,
    ) -> list[dict[str, str]]:
        """Canonicalize only Candidate Fact bytes for the cheap adverse gate."""

        if (
            not isinstance(fact_payloads, list)
            or not fact_payloads
            or any(not isinstance(item, dict) for item in fact_payloads)
        ):
            raise ValueError("Candidate Release facts must be a nonempty object list")
        bindings: list[dict[str, str]] = []
        seen: set[str] = set()
        for payload in fact_payloads:
            fact = Fact.from_dict(payload)
            raw = self._canonical_atomic_candidate_fact_bytes(fact)
            if fact.fact_id in seen:
                raise ValueError("Candidate Release has a duplicate Fact id")
            seen.add(fact.fact_id)
            bindings.append(
                {
                    "fact_id": fact.fact_id,
                    "fact_sha256": sha256_bytes(raw),
                }
            )
        return sorted(bindings, key=lambda item: item["fact_id"])

    def _canonical_atomic_candidate_fact_bytes(self, fact: Fact) -> bytes:
        """Validate the cheap prospective Fact-byte and atomicity boundary."""

        errors = fact.validate()
        if errors:
            raise ValueError("; ".join(errors))
        if fact.problem_id != self.store.project_id():
            raise ValueError("Candidate Fact belongs to another project")
        clauses = extract_statement_clauses(fact.statement, require_v4=True)
        if fact.semantic_interface:
            placeholder = sha256_json(
                ["v5-candidate-atomicity-interface", fact.fact_id]
            )
            semantic_interface = build_statement_interface(
                fact=fact,
                stored_fact_sha256=sha256_bytes(
                    validate_fact_round_trip(fact).encode("utf-8")
                ),
                acceptance_event_sha256=placeholder,
                admission_review_id=placeholder,
                workflow_evidence_version=5,
                assurance_contract_revision=V5_ASSURANCE_CONTRACT_REVISION,
            )
            semantic_components = [
                item["semantic_contract"]
                for item in semantic_interface["clauses"]
                if item.get("semantic_contract", {}).get("component_kind")
                in {"conclusion", "mathematical_claim", "empirical_hypothesis"}
            ]
            semantic_atoms = len(semantic_components)
            atomicity_source = "semantic conclusion components"
        else:
            semantic_atoms = len(clauses)
            atomicity_source = "[CLAIM:*] statement clauses"
        if semantic_atoms != 1:
            raise ValueError(
                "Candidate Fact must expose exactly one semantic conclusion "
                f"atom through {atomicity_source}; split separable conclusions "
                "into separate Facts and bind their predecessor edges"
            )
        return validate_fact_round_trip(fact).encode("utf-8")

    def _validate_candidate_fact_artifact_bytes(self, raw: bytes) -> Fact:
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError("candidate_fact artifact must be UTF-8") from exc
        try:
            fact = parse_fact_markdown(text)
            canonical = self._canonical_atomic_candidate_fact_bytes(fact)
        except ValueError as exc:
            raise ValueError(f"candidate_fact artifact is invalid: {exc}") from exc
        if raw != canonical:
            raise ValueError(
                "candidate_fact artifact bytes are not the exact canonical Fact "
                "Markdown serialization"
            )
        return fact

    def _precheck_candidate_assurance_shape(
        self,
        *,
        fact_payloads: Any,
        assurance: Any,
    ) -> list[dict[str, str]]:
        """Reject local Candidate/assurance shape errors before global replay.

        This projection is deliberately nonauthoritative.  It validates the
        exact Candidate Fact identities needed by the already-cheap adverse
        gate and checks only cardinality and internal-edge predicates that are
        decidable from the submitted bytes.  The complete assurance validator
        still runs after Research, source, artifact, and predecessor closure.
        """

        bindings = self._candidate_fact_fingerprints_for_adverse(fact_payloads)
        if not isinstance(assurance, dict):
            return bindings
        granularity = assurance.get("validation_granularity")
        if granularity not in V5_VALIDATION_GRANULARITIES:
            return bindings
        candidate_ids = {item["fact_id"] for item in bindings}
        facts = [Fact.from_dict(item) for item in fact_payloads]
        has_internal_edge = any(
            predecessor in candidate_ids
            for fact in facts
            for predecessor in fact.predecessors
        )
        if granularity == "monolithic_theorem" and len(candidate_ids) != 1:
            raise ValueError(
                "monolithic_theorem requires exactly one candidate Fact"
            )
        if granularity == "atomic_fact_dag" and (
            len(candidate_ids) < 2 or not has_internal_edge
        ):
            raise ValueError(
                "atomic_fact_dag requires multiple candidates and an internal edge"
            )
        if granularity == "nodewise_proof_dag" and (
            len(candidate_ids) < 2 or not has_internal_edge
        ):
            raise ValueError(
                "nodewise_proof_dag requires multiple candidates and an internal edge"
            )
        return bindings

    def _precheck_candidate_statement_interfaces(
        self,
        *,
        fact_payloads: Any,
        explicit_research_envelopes: list[dict[str, Any]],
    ) -> None:
        """Reject local current-assurance interface errors before global replay.

        This is a rejection-only projection.  Immutable Research envelopes are
        sufficient to prove that an explicitly selected branch uses the
        current assurance contract, and the submitted Fact bytes are sufficient
        to construct its statement interface.  Every surviving input is still
        reconstructed after the complete Research and artifact closure.
        """

        if not any(
            self._research_assurance_revision(record)
            == V5_ASSURANCE_CONTRACT_REVISION
            for record in explicit_research_envelopes
        ):
            return
        if not isinstance(fact_payloads, list):
            return
        for payload in fact_payloads:
            if not isinstance(payload, dict):
                continue
            fact = Fact.from_dict(payload)
            errors = fact.validate()
            if errors:
                raise ValueError("; ".join(errors))
            rendered = validate_fact_round_trip(fact).encode("utf-8")
            self._candidate_interface(
                fact,
                rendered,
                assurance_contract_revision=V5_ASSURANCE_CONTRACT_REVISION,
            )

    def _lightweight_adverse_assignment_binding(
        self,
        *,
        target: dict[str, Any],
        adverse: dict[str, Any],
        producer: str,
        candidate_fact_sha256s: set[str],
    ) -> dict[str, Any]:
        """Validate one ingested refute lineage without running release audit."""

        if adverse["actor"] in {producer, target["actor"]}:
            raise ValueError("adverse worker is not independent of the producer")
        metadata = adverse["metadata"]
        provenance = metadata.get("assignment_provenance")
        task_binding = metadata.get("task_binding")
        if (
            not self._research_is_adverse_assignment(adverse)
            or not isinstance(provenance, dict)
            or provenance.get("work_mode") != "refute"
            or not isinstance(task_binding, dict)
        ):
            raise ValueError("Research is not an ingested refute assignment")
        if (
            adverse.get("relation") != "responds_to"
            or adverse.get("related_research_ids") != [target["research_id"]]
        ):
            raise ValueError("adverse Research does not directly target this branch head")
        if _parse_utc_timestamp(
            adverse["created_at"], label="fresh adverse created_at"
        ) < _parse_utc_timestamp(
            target["created_at"], label="fresh adverse target created_at"
        ):
            raise ValueError("adverse Research predates its target")

        round_id = validate_round_id(provenance["round_id"])
        assignment_id = validate_assignment_id(provenance["assignment_id"])
        round_dir = self.store.rounds_dir / round_id
        manifest_path = round_dir / "round.json"
        assignment_path = round_dir / "assignments" / f"{assignment_id}.json"
        card_path = self._task_card_path(round_id, assignment_id)
        for label, path in (
            ("round manifest", manifest_path),
            ("assignment", assignment_path),
            ("task card", card_path),
        ):
            if path.is_symlink() or not path.is_file():
                raise ValueError(f"fresh adverse {label} is missing or unsafe")

        manifest = self.store._read_json(manifest_path)
        if (
            not isinstance(manifest, dict)
            or manifest.get("schema_version") != 5
            or manifest.get("policy_revision") != V5_POLICY_REVISION
            or manifest.get("project_id") != self.store.project_id()
            or manifest.get("round_id") != round_id
        ):
            raise ValueError("fresh adverse round identity is invalid")
        manifest_semantic = {
            key: value for key, value in manifest.items() if key != "manifest_sha256"
        }
        if manifest.get("manifest_sha256") != sha256_json(manifest_semantic):
            raise ValueError("fresh adverse round hash mismatch")
        if self.store.reasoning_modes().work_unit_abort(round_id) is not None:
            raise ValueError("fresh adverse round was aborted")

        assignment = self.store._read_json(assignment_path)
        if (
            not isinstance(assignment, dict)
            or assignment.get("assignment_id") != assignment_id
            or assignment.get("research_id") != target["research_id"]
            or assignment.get("worker_id") != adverse["actor"]
            or assignment.get("work_mode") != "refute"
            or assignment.get("task_card_sha256")
            != provenance["task_card_sha256"]
            or assignment.get("assignment_role")
            not in {"primary", "paired_adverse"}
            or assignment.get("task_card_relpath")
            != card_path.relative_to(self.store.root).as_posix()
        ):
            raise ValueError("fresh adverse assignment binding is invalid")
        pair_binding = assignment.get("independent_adverse_pair")
        if assignment["assignment_role"] == "primary":
            if pair_binding is not None:
                raise ValueError(
                    "primary refute cannot reuse a paired-primary allocation"
                )
        elif (
            not isinstance(pair_binding, dict)
            or pair_binding.get("role") != "paired_adverse"
            or pair_binding.get("research_id") != target["research_id"]
            or pair_binding.get("worker_id") != adverse["actor"]
            or pair_binding.get("shared_context_forbidden") is not True
        ):
            raise ValueError("paired adverse isolation binding is invalid")
        assignment_semantic = {
            key: value
            for key, value in assignment.items()
            if key != "assignment_sha256"
        }
        if assignment.get("assignment_sha256") != sha256_json(
            assignment_semantic
        ):
            raise ValueError("fresh adverse assignment hash mismatch")
        manifest_assignments = manifest.get("assignments")
        if (
            not isinstance(manifest_assignments, list)
            or sum(
                item == assignment
                for item in manifest_assignments
                if isinstance(item, dict)
            )
            != 1
        ):
            raise ValueError("fresh adverse assignment is not frozen by its round")
        if (
            manifest.get("host_task_scope_id") is not None
            and manifest.get("host_task_scope_id")
            != assignment.get("host_task_scope_id")
        ):
            raise ValueError("fresh adverse round/task scope drifted")
        if assignment["assignment_role"] == "paired_adverse":
            pairs = manifest.get("independent_adverse_pairs")
            if not isinstance(pairs, list):
                raise ValueError("fresh adverse pair is absent from its round")
            matched_pairs = [
                validate_independent_adverse_pair(item)
                for item in pairs
                if isinstance(item, dict)
                and item.get("adverse_assignment_id") == assignment_id
            ]
            if (
                len(matched_pairs) != 1
                or matched_pairs[0]["research_id"] != target["research_id"]
                or matched_pairs[0]["adverse_worker_id"] != adverse["actor"]
            ):
                raise ValueError("fresh adverse pair lineage is invalid")

        raw_card = card_path.read_bytes()
        if sha256_bytes(raw_card) != provenance["task_card_sha256"]:
            raise ValueError("fresh adverse task-card byte hash mismatch")
        card = self.store._read_json(card_path)
        control = card.get("control_plane") if isinstance(card, dict) else None
        if (
            not isinstance(card, dict)
            or card.get("project_id") != self.store.project_id()
            or card.get("round_id") != round_id
            or card.get("assignment_id") != assignment_id
            or card.get("research_id") != target["research_id"]
            or card.get("worker_id") != adverse["actor"]
            or card.get("work_mode") != "refute"
            or not isinstance(control, dict)
            or control.get("assignment_role") != assignment["assignment_role"]
            or control.get("host_task_scope_id")
            != assignment.get("host_task_scope_id")
            or control.get("worker_context_id")
            != assignment.get("worker_context_id")
        ):
            raise ValueError("fresh adverse task-card scope is invalid")
        host_task_scope_id = control.get("host_task_scope_id")
        worker_context_id = control.get("worker_context_id")
        if (
            not isinstance(host_task_scope_id, str)
            or HOST_TASK_SCOPE_ID_RE.fullmatch(host_task_scope_id) is None
            or not isinstance(worker_context_id, str)
            or not worker_context_id.strip()
        ):
            raise ValueError("fresh adverse host scope/context is missing")
        card_semantic = {
            key: value
            for key, value in card.items()
            if key != "task_card_semantic_sha256"
        }
        if card.get("task_card_semantic_sha256") != sha256_json(card_semantic):
            raise ValueError("fresh adverse task-card semantic hash mismatch")
        related_artifacts = card.get("mathematical_state", {}).get(
            "related_artifacts"
        )
        if not isinstance(related_artifacts, list):
            raise ValueError("fresh adverse task card lacks frozen candidate artifacts")
        frozen_hashes = {
            item.get("sha256")
            for item in related_artifacts
            if isinstance(item, dict)
            and isinstance(item.get("sha256"), str)
            and SHA256_RE.fullmatch(item["sha256"]) is not None
        }
        missing_candidate_hashes = sorted(
            candidate_fact_sha256s.difference(frozen_hashes)
        )
        if missing_candidate_hashes:
            raise ValueError(
                "fresh adverse task card does not bind the exact Candidate Fact bytes"
            )

        product, receipt = self._research_product_for_assignment(
            round_dir=round_dir,
            manifest=manifest,
            assignment=assignment,
        )
        product_metadata = product.get("metadata", {})
        product_task_binding = (
            product_metadata.get("task_binding")
            if isinstance(product_metadata, dict)
            else None
        )
        return_sha256 = (
            product_task_binding.get("return_sha256")
            if isinstance(product_task_binding, dict)
            else None
        )
        if (
            product.get("research_id") != adverse["research_id"]
            or not isinstance(return_sha256, str)
            or SHA256_RE.fullmatch(return_sha256) is None
            or return_sha256 != task_binding.get("return_sha256")
        ):
            raise ValueError("fresh adverse Research product binding is invalid")

        return {
            "target_research_id": target["research_id"],
            "adverse_research_id": adverse["research_id"],
            "adverse_worker_id": adverse["actor"],
            "round_id": round_id,
            "assignment_id": assignment_id,
            "task_card_sha256": provenance["task_card_sha256"],
            "return_sha256": return_sha256,
            "receipt_id": receipt["receipt_id"] if receipt is not None else None,
            "host_task_scope_id": host_task_scope_id,
            "worker_context_id": worker_context_id,
        }

    def _fresh_adverse_readiness(
        self,
        *,
        research_ids: list[str],
        candidate_fact_bindings: list[dict[str, str]],
        challenge_dispositions: Any,
        adverse_actor_ids: Any,
        producer: str,
    ) -> dict[str, Any]:
        """Fail before expensive Candidate work when a fresh attack is missing."""

        records = self._lightweight_research_records()
        missing = sorted(set(research_ids).difference(records))
        if missing:
            raise ValueError(
                "fresh_adverse_missing: selected Research is absent: "
                + ", ".join(missing)
            )
        adverse_kinds = {"challenge", "counterexample", "obstacle", "dead_end"}
        required_targets = {
            research_id
            for research_id in research_ids
            if independent_adverse_required(records[research_id])
            and records[research_id]["kind"] not in adverse_kinds
            and not self._research_is_adverse_assignment(records[research_id])
        }

        ancestor_cache: dict[str, set[str]] = {}

        def ancestors(research_id: str) -> set[str]:
            cached = ancestor_cache.get(research_id)
            if cached is not None:
                return cached
            result: set[str] = set()
            stack = list(records[research_id]["related_research_ids"])
            while stack:
                related_id = stack.pop()
                if related_id == research_id:
                    raise ValueError("fresh adverse Research lineage is cyclic")
                if related_id not in records:
                    raise ValueError(
                        "fresh adverse Research lineage names an unknown ancestor"
                    )
                if related_id in result:
                    continue
                result.add(related_id)
                stack.extend(records[related_id]["related_research_ids"])
            ancestor_cache[research_id] = result
            return result

        maximal_targets = sorted(
            research_id
            for research_id in required_targets
            if not any(
                research_id in ancestors(other_id)
                for other_id in required_targets
                if other_id != research_id
            )
        )

        if not isinstance(challenge_dispositions, list) or any(
            not isinstance(item, dict)
            or set(item) != {"research_id", "disposition", "rationale"}
            for item in challenge_dispositions
        ):
            raise ValueError(
                "fresh_adverse_missing: challenge dispositions are not ready"
            )
        disposition_ids = {
            item["research_id"]
            for item in challenge_dispositions
            if isinstance(item.get("research_id"), str)
            and item.get("disposition") in V5_CHALLENGE_DISPOSITIONS
            and isinstance(item.get("rationale"), str)
            and item["rationale"].strip()
        }
        actors = _require_string_list(adverse_actor_ids, "adverse actor ids")
        actor_set = set(actors)
        candidate_hashes = {
            item["fact_sha256"] for item in candidate_fact_bindings
        }
        bindings: list[dict[str, str]] = []
        for target_id in maximal_targets:
            target = records[target_id]
            respondents = sorted(
                (
                    record
                    for record in records.values()
                    if record.get("relation") == "responds_to"
                    and record.get("related_research_ids") == [target_id]
                    and self._research_is_adverse_assignment(record)
                ),
                key=lambda item: (item["created_at"], item["research_id"]),
                reverse=True,
            )
            accepted: dict[str, str] | None = None
            rejected: list[str] = []
            for adverse in respondents:
                try:
                    candidate = self._lightweight_adverse_assignment_binding(
                        target=target,
                        adverse=adverse,
                        producer=producer,
                        candidate_fact_sha256s=candidate_hashes,
                    )
                except (KeyError, TypeError, ValueError) as exc:
                    rejected.append(f"{adverse['research_id']}={exc}")
                    continue
                if adverse["research_id"] not in disposition_ids:
                    rejected.append(
                        f"{adverse['research_id']}=missing Candidate disposition"
                    )
                    continue
                if adverse["actor"] not in actor_set:
                    rejected.append(
                        f"{adverse['research_id']}=missing adverse_actor_ids binding"
                    )
                    continue
                accepted = candidate
                break
            if accepted is None:
                detail = "; ".join(rejected[:3]) if rejected else "no direct refute return"
                raise ValueError(
                    "fresh_adverse_missing: run and ingest one independent refute "
                    f"against branch head {target_id}, binding the exact Candidate "
                    f"Fact bytes, then disposition it before Candidate Release ({detail})"
                )
            bindings.append(accepted)

        semantic = {
            "contract_revision": V5_FRESH_ADVERSE_READINESS_REVISION,
            "required": bool(maximal_targets),
            "status": "ready" if maximal_targets else "not_required",
            "required_target_research_ids": maximal_targets,
            "candidate_fact_bindings": candidate_fact_bindings,
            "adverse_bindings": sorted(
                bindings, key=lambda item: item["target_research_id"]
            ),
            "gate_position": (
                "before_artifact_normalization_and_candidate_release_validation"
            ),
            "verifier_instruction": (
                "independently_adjudicate_every_bound_adverse_disposition"
            ),
            "truth_effect": "none",
        }
        return {**semantic, "readiness_sha256": sha256_json(semantic)}

    def _validate_fresh_adverse_readiness(
        self,
        value: Any,
        *,
        candidate_records: list[dict[str, Any]],
        research_bindings: list[dict[str, Any]],
        challenge_dispositions: list[dict[str, Any]],
        excluded_verifier_ids: list[str],
    ) -> dict[str, Any]:
        fields = {
            "contract_revision",
            "required",
            "status",
            "required_target_research_ids",
            "candidate_fact_bindings",
            "adverse_bindings",
            "gate_position",
            "verifier_instruction",
            "truth_effect",
            "readiness_sha256",
        }
        if not isinstance(value, dict) or set(value) != fields:
            raise ValueError("Candidate Release fresh-adverse readiness fields are not exact")
        semantic = {
            key: item for key, item in value.items() if key != "readiness_sha256"
        }
        if (
            value["contract_revision"] not in V5_FRESH_ADVERSE_READINESS_REVISIONS
            or not isinstance(value["required"], bool)
            or value["status"]
            != ("ready" if value["required"] else "not_required")
            or value["gate_position"]
            != "before_artifact_normalization_and_candidate_release_validation"
            or value["verifier_instruction"]
            != "independently_adjudicate_every_bound_adverse_disposition"
            or value["truth_effect"] != "none"
            or value["readiness_sha256"] != sha256_json(semantic)
        ):
            raise ValueError("Candidate Release fresh-adverse readiness is invalid")
        expected_candidate_bindings = sorted(
            (
                {
                    "fact_id": item["fact_id"],
                    "fact_sha256": item["fact_sha256"],
                }
                for item in candidate_records
            ),
            key=lambda item: item["fact_id"],
        )
        if value["candidate_fact_bindings"] != expected_candidate_bindings:
            raise ValueError("Candidate Release fresh-adverse Candidate bytes drifted")
        targets = _require_string_list(
            value["required_target_research_ids"],
            "fresh-adverse required target ids",
        )
        for research_id in targets:
            validate_memory_id(research_id)
        bindings = value["adverse_bindings"]
        binding_fields = {
            "target_research_id",
            "adverse_research_id",
            "adverse_worker_id",
            "round_id",
            "assignment_id",
            "task_card_sha256",
            "return_sha256",
            "receipt_id",
            "host_task_scope_id",
            "worker_context_id",
        }
        if (
            not isinstance(bindings, list)
            or any(not isinstance(item, dict) or set(item) != binding_fields for item in bindings)
            or [item["target_research_id"] for item in bindings] != targets
            or value["required"] != bool(targets)
        ):
            raise ValueError("Candidate Release fresh-adverse bindings are invalid")
        bound_research_ids = {
            item["research_id"] for item in research_bindings
        }
        disposition_ids = {
            item["research_id"] for item in challenge_dispositions
        }
        for binding in bindings:
            validate_memory_id(binding["target_research_id"])
            validate_memory_id(binding["adverse_research_id"])
            validate_round_id(binding["round_id"])
            validate_assignment_id(binding["assignment_id"])
            for field_name in ("task_card_sha256", "return_sha256"):
                if SHA256_RE.fullmatch(binding[field_name]) is None:
                    raise ValueError("Candidate Release fresh-adverse hash is invalid")
            if (
                binding["target_research_id"] not in bound_research_ids
                or binding["adverse_research_id"] not in bound_research_ids
                or binding["adverse_research_id"] not in disposition_ids
                or not isinstance(binding["adverse_worker_id"], str)
                or not binding["adverse_worker_id"].strip()
                or binding["adverse_worker_id"] not in excluded_verifier_ids
                or (
                    binding["receipt_id"] is not None
                    and (
                        not isinstance(binding["receipt_id"], str)
                        or not binding["receipt_id"].startswith("research-ingest-")
                        or SHA256_RE.fullmatch(
                            binding["receipt_id"].removeprefix("research-ingest-")
                        )
                        is None
                    )
                )
                or not isinstance(binding["host_task_scope_id"], str)
                or HOST_TASK_SCOPE_ID_RE.fullmatch(
                    binding["host_task_scope_id"]
                )
                is None
                or not isinstance(binding["worker_context_id"], str)
                or not binding["worker_context_id"].strip()
            ):
                raise ValueError(
                    "Candidate Release fresh-adverse release closure drifted"
                )
        return value

    def candidate_release(
        self,
        payload: dict[str, Any],
        *,
        producer: str,
        preflight_only: bool = False,
    ) -> dict[str, Any]:
        if not isinstance(payload, dict):
            raise ValueError("Candidate Release input must be one object")
        required = {
            "schema_version",
            "bundle_claim",
            "candidates",
            "research_entry_ids",
            "claim_relation",
            "artifacts",
            "verification_plan",
            "requested_assurance",
            "challenge_dispositions",
            "paper_evidence_refs",
            "adverse_actor_ids",
        }
        allowed = {
            *required,
            "successor_contracts",
            "evidence_bridge_refs",
            "paper_continuation_ref",
            "philosophy_atomicity",
            "research_draft_ref",
        }
        missing_fields = sorted(required.difference(payload))
        unknown_fields = sorted(set(payload).difference(allowed))
        if missing_fields or unknown_fields:
            raise ValueError(
                "Candidate Release input fields are not exact; "
                f"missing={missing_fields} unknown={unknown_fields} "
                "schema=references/paper_input_contracts.md"
            )
        if payload.get("schema_version") != 5:
            raise ValueError("Candidate Release schema_version must be 5")
        producer = _require_nonempty_text(producer, "Candidate Release producer")
        bundle_claim = _require_nonempty_text(
            payload.get("bundle_claim"), "Candidate Release bundle claim"
        )
        claim_relation = payload.get("claim_relation")
        if claim_relation not in CLAIM_RELATIONS:
            raise ValueError("Candidate Release claim_relation is invalid")
        research_ids = _require_string_list(
            payload.get("research_entry_ids"), "Candidate Release research ids"
        )
        research_ids = [validate_memory_id(item) for item in research_ids]
        if not research_ids or len(set(research_ids)) != len(research_ids):
            raise ValueError(
                "Candidate Release research ids must be nonempty and unique"
            )
        candidate_fact_bindings = self._precheck_candidate_assurance_shape(
            fact_payloads=payload.get("candidates"),
            assurance=payload.get("requested_assurance"),
        )
        explicit_research_envelopes = [
            self._research_record_envelope(item) for item in research_ids
        ]
        self._precheck_candidate_statement_interfaces(
            fact_payloads=payload.get("candidates"),
            explicit_research_envelopes=explicit_research_envelopes,
        )
        inspection = self._bind_inspection_context(
            RoundInspectionContext(),
            create=True,
        )
        assert inspection is not None
        explicit_research_records = [
            self._inspection_research_record(item, inspection)
            for item in research_ids
        ]
        supervision_review_only_ids = sorted(
            item["research_id"]
            for item in explicit_research_records
            if (
                isinstance(
                    item.get("metadata", {}).get("research_supervision"),
                    dict,
                )
                or self._research_is_adverse_assignment(item)
            )
        )
        if supervision_review_only_ids:
            raise ValueError(
                "Candidate Release selects review-only Research-supervision task "
                "or return records; select the constructive branch and let bound "
                "review evidence attach automatically: "
                + ", ".join(supervision_review_only_ids)
            )
        required_supervision_result_ids = (
            self._required_supervision_results_for_candidate(
                explicit_research_records,
                _inspection_context=inspection,
            )
        )
        route_projections = self._explicit_research_projections(
            research_ids,
            campaign_id=None,
            _inspection_context=inspection,
        )
        stale_selected = {
            item["research_id"]: route_projections[item["research_id"]][
                "route_invalidated_by"
            ]
            for item in explicit_research_records
            if route_projections[item["research_id"]]["route_status"]
            != "current"
        }
        if stale_selected:
            details = ", ".join(
                f"{research_id} invalidated_by={invalidators}"
                for research_id, invalidators in sorted(stale_selected.items())
            )
            raise ValueError(
                "Candidate Release selects stale Research; create a copy-on-write "
                f"repair branch first: {details}"
            )
        research_records = self._release_research_records(
            explicit_research_records,
            _inspection_context=inspection,
        )
        bound_research_ids = {
            record["research_id"] for record in research_records
        }
        missing_supervision_results = sorted(
            required_supervision_result_ids.difference(bound_research_ids)
        )
        if missing_supervision_results:
            raise ValueError(
                "Candidate Release closure omitted required completed Research "
                "supervision results: "
                + ", ".join(missing_supervision_results)
            )
        fresh_adverse_readiness = self._fresh_adverse_readiness(
            research_ids=research_ids,
            candidate_fact_bindings=candidate_fact_bindings,
            challenge_dispositions=payload.get("challenge_dispositions"),
            adverse_actor_ids=payload.get("adverse_actor_ids"),
            producer=producer,
        )
        assurance_contract_revision = (
            V5_ASSURANCE_CONTRACT_REVISION
            if any(
                self._research_assurance_revision(record)
                == V5_ASSURANCE_CONTRACT_REVISION
                for record in research_records
            )
            else V5_LEGACY_ASSURANCE_CONTRACT_REVISION
        )
        research_logic_signals = {
            signal
            for record in research_records
            for signal in record.get("metadata", {}).get("logic_signals", [])
            if isinstance(signal, str)
        }
        research_bindings = [
            {
                "research_id": record["research_id"],
                "record_sha256": record["record_sha256"],
                "kind": record["kind"],
                "actor": record["actor"],
            }
            for record in research_records
        ]
        verification_plan = payload.get("verification_plan")
        if not isinstance(verification_plan, dict) or set(verification_plan) != {
            "mode",
            "authorized_artifact_roles",
            "required_checks",
        }:
            raise ValueError("Candidate Release verification_plan fields are not exact")
        if verification_plan.get("mode") != "closed_capsule":
            raise ValueError("Candidate Release verification mode must be closed_capsule")
        authorized_roles = _require_string_list(
            verification_plan.get("authorized_artifact_roles"),
            "verification authorized artifact roles",
        )
        required_checks = _require_string_list(
            verification_plan.get("required_checks"),
            "verification required checks",
        )
        if len(authorized_roles) != len(set(authorized_roles)):
            raise ValueError("verification authorized artifact roles are duplicated")
        if len(required_checks) != len(set(required_checks)):
            raise ValueError("verification required checks are duplicated")
        minimum_checks = {
            "mathematical",
            "typing",
            "scope",
            "source_and_applicability",
            "predecessor_interfaces",
            "computation_replay",
            "challenge_dispositions",
            "assurance_scope",
        }
        if not minimum_checks.issubset(required_checks):
            raise ValueError(
                "Candidate Release verification_plan omits invariant checks: "
                + ", ".join(sorted(minimum_checks.difference(required_checks)))
            )
        normalized_artifacts, validation_artifacts = self._normalize_artifacts(
            payload.get("artifacts"), seal=False
        )
        artifact_roles = {item["role"] for item in normalized_artifacts}
        if not set(authorized_roles).issubset(artifact_roles):
            raise ValueError(
                "verification plan authorizes an undeclared artifact role"
            )
        normalized_plan = {
            "mode": "closed_capsule",
            "authorized_artifact_roles": sorted(dict.fromkeys(authorized_roles)),
            "required_checks": sorted(dict.fromkeys(required_checks)),
        }
        authorized_artifact_hashes = {
            item["sha256"]
            for item in validation_artifacts
            if item["role"] in set(authorized_roles)
        }
        bridge_refs = self._validate_evidence_bridge_refs(
            payload.get("evidence_bridge_refs", []),
            artifacts=payload.get("artifacts"),
            sealed_record=False,
            require_current=True,
        )
        if bridge_refs and (
            "evidence_bridge_capsule" not in authorized_roles
            or "evidence_bridge_current" not in required_checks
        ):
            raise ValueError(
                "Evidence bridge use requires an authorized evidence_bridge_capsule "
                "artifact and the evidence_bridge_current certification check"
            )
        (
            facts,
            rendered,
            order,
            internal_edges,
            external_predecessors,
        ) = self._prepare_candidate_facts(
            payload.get("candidates"),
            artifacts=validation_artifacts,
            authorized_artifact_hashes=authorized_artifact_hashes,
            verification_plan=normalized_plan,
            assurance_contract_revision=assurance_contract_revision,
            require_geometric_stage_typing=(
                "geometric_stage_typing" in research_logic_signals
            ),
            _inspection_context=inspection,
        )
        if candidate_fact_bindings != sorted(
            (
                {
                    "fact_id": fact_id,
                    "fact_sha256": sha256_bytes(rendered[fact_id]),
                }
                for fact_id in facts
            ),
            key=lambda item: item["fact_id"],
        ):
            raise ValueError(
                "Candidate Fact bytes drifted after the fresh-adverse gate"
            )
        candidate_interfaces = [
            self._candidate_interface(
                facts[fact_id],
                rendered[fact_id],
                assurance_contract_revision=assurance_contract_revision,
            )
            for fact_id in order
        ]
        successor_input = payload.get("successor_contracts", [])
        if (
            successor_input
            and assurance_contract_revision
            != V5_ASSURANCE_CONTRACT_REVISION
        ):
            raise ValueError(
                "copy-on-write successor contracts are prospective current-assurance only"
            )
        successor_contracts = (
            validate_successor_contracts(
                successor_input,
                candidates=facts,
                active_facts=self.store.facts(
                    _inspection_context=inspection,
                ),
                active_fact_sha256=lambda fact_id: sha256_bytes(
                    self.store.active_fact_path(
                        fact_id,
                        _inspection_context=inspection,
                    ).read_bytes()
                ),
            )
            if assurance_contract_revision == V5_ASSURANCE_CONTRACT_REVISION
            else []
        )
        research_assurance_evidence = self._research_assurance_evidence(
            research_records=research_records,
            authorized_artifact_hashes=authorized_artifact_hashes,
            assurance_contract_revision=assurance_contract_revision,
        )
        applicable_assurance_checks = self._applicable_assurance_checks(
            facts=facts,
            research_records=research_records,
            assurance_contract_revision=assurance_contract_revision,
        )
        if successor_contracts:
            applicable_assurance_checks = sorted(
                {
                    *applicable_assurance_checks,
                    "proof_lineage_conservation",
                }
            )
        missing_assurance_checks = sorted(
            set(applicable_assurance_checks).difference(
                normalized_plan["required_checks"]
            )
        )
        if missing_assurance_checks:
            raise ValueError(
                "Candidate Release omits assurance checks applicable to its exact evidence: "
                + ", ".join(missing_assurance_checks)
            )
        if any(
            entry.get("role") == "load_bearing"
            for fact in facts.values()
            for entry in fact.computational_evidence
        ) and "program_math_truncation" not in normalized_plan["required_checks"]:
            raise ValueError(
                "load-bearing V5 computation requires the "
                "program_math_truncation certification check"
            )
        assurance = self._validate_requested_assurance(
            payload.get("requested_assurance"),
            candidate_ids=set(facts),
            internal_edges=internal_edges,
            candidate_facts=facts,
        )
        strict_research_draft = _is_research_draft_assurance_revision(
            assurance.get("contract_revision")
        )
        if (
            strict_research_draft
            and assurance_contract_revision != V5_ASSURANCE_CONTRACT_REVISION
        ):
            raise ValueError(
                "research-draft admission requires current Research assurance"
            )
        if strict_research_draft and (
            "paper_continuation_ref" in payload
            or "philosophy_atomicity" in payload
        ):
            raise ValueError(
                "research_draft_ref cannot be mixed with the legacy Paper continuation path"
            )
        if not strict_research_draft and "research_draft_ref" in payload:
            raise ValueError(
                "research_draft_ref requires the prospective research-draft assurance"
            )
        if (
            not _is_research_draft_assurance_revision(
                assurance.get("contract_revision")
            )
            and assurance["validation_granularity"] in {
            "nodewise_proof_dag",
            "paper_target_closure",
            }
        ):
            mapped_fact_ids = {
                item["fact_id"]
                for item in assurance["coverage"]
                if item["disposition"] == "fact_bundle_member"
            }
            if mapped_fact_ids != set(facts):
                raise ValueError(
                    "nodewise paper coverage must map every Candidate Release "
                    "Fact exactly through one or more load-bearing nodes; "
                    f"mapped={sorted(mapped_fact_ids)} candidates={sorted(facts)}"
                )
        continuation = self.paper_continuation(
            _inspection_context=inspection,
        )
        continuation_plan_ids = continuation.plan_ids_for_research(
            research_records
        )
        if strict_research_draft and continuation_plan_ids:
            raise ValueError(
                "prospective research-draft admission cannot inherit a legacy continuation plan"
            )
        if len(continuation_plan_ids) > 1:
            raise ValueError(
                "one Candidate Release cannot mix Paper continuation plans"
            )
        continuation_binding: dict[str, Any] | None = None
        continuation_evidence: dict[str, Any] | None = None
        continuation_release_capsule: dict[str, Any] | None = None
        continuation_release_operation: dict[str, Any] | None = None
        continuation_release_proof: dict[str, Any] | None = None
        continuation_proof_timings: dict[str, int] | None = None
        continuation_fallback_exception_count = 0
        if continuation_plan_ids:
            plan_id = continuation_plan_ids[0]
            release_proof, proof_timings, fallback_exception_count = (
                continuation.prepare_release_proof(
                    plan_id=plan_id,
                    ref=payload.get("paper_continuation_ref"),
                    paper_evidence_refs=payload.get("paper_evidence_refs", []),
                    candidate_interfaces=candidate_interfaces,
                )
            )
            continuation_release_proof = release_proof
            continuation_proof_timings = proof_timings
            continuation_fallback_exception_count = fallback_exception_count
            continuation_binding = continuation.validate_release_binding(
                plan_id=plan_id,
                ref=payload.get("paper_continuation_ref"),
                philosophy_atomicity=payload.get("philosophy_atomicity"),
                facts=facts,
                release_proof=release_proof,
            )
            plan = continuation_binding["plan"]
            expected_nodes = {
                *plan["selected_reconstruction_node_ids"],
                *plan["selected_source_node_ids"],
            }
            subject = assurance["validation_subject"]
            if (
                assurance["validation_granularity"]
                != "paper_target_closure"
                or subject["kind"] != "paper"
                or subject["subject_id"] != plan["paper_id"]
                or subject["artifact_sha256"]
                != plan["source_artifact_sha256"]
                or set(subject["load_bearing_node_ids"]) != expected_nodes
            ):
                raise ValueError(
                    "Paper continuation release must use paper_target_closure over "
                    "the exact selected source and reconstruction nodes"
                )
            continuation_checks = {"paper_continuation_adequacy"}
            if plan["domain_profile"] in {"philosophy", "mixed"}:
                continuation_checks.update(
                    {
                        "philosophy_semantic_atomicity",
                        "philosophy_plain_language_clarity",
                    }
                )
            missing_continuation_checks = sorted(
                continuation_checks.difference(
                    normalized_plan["required_checks"]
                )
            )
            if missing_continuation_checks:
                raise ValueError(
                    "Paper continuation release omits required certification checks: "
                    + ", ".join(missing_continuation_checks)
                )
        elif (
            "paper_continuation_ref" in payload
            or "philosophy_atomicity" in payload
        ):
            raise ValueError(
                "Paper continuation release fields require bound continuation Research"
            )
        research_draft_context: dict[str, Any] | None = None
        if strict_research_draft:
            release_ref = payload.get("research_draft_ref")
            if not isinstance(release_ref, dict):
                raise ValueError(
                    "prospective research-draft release requires research_draft_ref"
                )
            plan_id = _require_nonempty_text(
                release_ref.get("plan_id"), "research-draft release plan id"
            )
            manager = self.research_draft()
            plan = manager.plan(plan_id, deep=True)
            current_batch = manager.current_batch(plan_id)
            if current_batch is None:
                raise ValueError(
                    "research-draft plan has no complete current disposition batch"
                )
            batch_id = _require_nonempty_text(
                release_ref.get("batch_id"), "research-draft release batch id"
            )
            if current_batch["batch_id"] != batch_id:
                raise ValueError(
                    "research_draft_ref must bind the exact current disposition batch"
                )
            batch = manager.batch(batch_id, deep=True)
            adequacy_receipt = current_batch["cached_summary"][
                "adequacy_receipt"
            ]
            research_draft_context = {
                "release_ref": release_ref,
                "plan": plan,
                "batch": batch,
                "adequacy_receipt": adequacy_receipt,
            }
        paper_refs = self._validate_paper_evidence_refs(
            payload.get("paper_evidence_refs"),
            validation_subject=assurance["validation_subject"],
            _inspection_context=inspection,
        )
        if continuation_binding is not None:
            if (
                continuation_release_proof is None
                or continuation_proof_timings is None
            ):
                raise ValueError(
                    "Paper continuation release proof was not prepared"
                )
            prepared_continuation = prepare_candidate_continuation_release_capsule(
                continuation,
                plan=continuation_binding["plan"],
                ref=continuation_binding["paper_continuation_ref"],
                release_proof=continuation_release_proof,
                selected_dispositions=continuation_binding[
                    "selected_dispositions"
                ],
                paper_evidence_refs=paper_refs,
                candidate_interfaces=candidate_interfaces,
                proof_phase_timings_ms=continuation_proof_timings,
                fallback_exception_count=(
                    continuation_fallback_exception_count
                ),
            )
            continuation_release_capsule = prepared_continuation["capsule"]
            continuation_release_operation = prepared_continuation["operation"]
            continuation_evidence = continuation_release_capsule["evidence"]
            required_writing_hashes = {
                item["artifact_sha256"]
                for item in continuation_evidence[
                    "writing_artifact_bindings"
                ]
            }
            authorized_writing_hashes = {
                item["sha256"]
                for item in validation_artifacts
                if item["role"] == "paper_revised_writing"
                and item["role"] in set(authorized_roles)
            }
            missing_writing = sorted(
                required_writing_hashes.difference(authorized_writing_hashes)
            )
            if missing_writing:
                raise ValueError(
                    "Paper continuation release must seal and authorize every revised "
                    "writing artifact as paper_revised_writing: "
                    + ", ".join(missing_writing)
                )
        if assurance["validation_subject"]["kind"] == "paper":
            subject_sha = assurance["validation_subject"]["artifact_sha256"]
            if subject_sha not in authorized_artifact_hashes:
                raise ValueError(
                    "paper Candidate Release must authorize its exact source artifact "
                    "for the fresh verifier"
                )
            paper_checks = {
                "paper_source_fidelity",
                "paper_graph_structure",
                "paper_audit",
                "paper_target_coverage",
            }
            missing_paper_checks = sorted(
                paper_checks.difference(normalized_plan["required_checks"])
            )
            if missing_paper_checks:
                raise ValueError(
                    "paper Candidate Release omits required certification checks: "
                    + ", ".join(missing_paper_checks)
                )
        if strict_research_draft:
            if "stance_preservation" in assurance:
                domain_continuity_check = "stance_preservation"
            elif "mathematical_target_preservation" in assurance:
                domain_continuity_check = (
                    "mathematical_target_and_refinement_continuity"
                )
            else:
                domain_continuity_check = "domain_target_continuity"
            research_draft_checks = {
                "composable_parallel_verification",
                "research_draft_admission_preflight",
                "paper_evidence_transport_closure",
                "validated_dependency_receipt",
                "language_neutral_statement_interfaces",
                "semantic_component_atomicity",
                domain_continuity_check,
            }
            missing_research_draft_checks = sorted(
                research_draft_checks.difference(normalized_plan["required_checks"])
            )
            if missing_research_draft_checks:
                raise ValueError(
                    "research-draft release omits required certification checks: "
                    + ", ".join(missing_research_draft_checks)
                )
        if continuation_binding is not None:
            plan = continuation_binding["plan"]
            expected_nodes = {
                *plan["selected_reconstruction_node_ids"],
                *plan["selected_source_node_ids"],
            }
            matching_logic_refs = [
                item
                for item in paper_refs
                if item["graph_kind"] == "logic"
                and item["snapshot_id"] == plan["snapshot_id"]
            ]
            if (
                len(matching_logic_refs) != 1
                or set(matching_logic_refs[0]["target_node_ids"])
                != expected_nodes
            ):
                raise ValueError(
                    "Paper continuation release must bind its exact Logic snapshot "
                    "and complete selected closure in one EvidenceRef"
                )
        subject_artifact = assurance["validation_subject"]["artifact_sha256"]
        if (
            subject_artifact is not None
            and subject_artifact
            not in {item["artifact_sha256"] for item in normalized_artifacts}
        ):
            raise ValueError(
                "paper validation subject artifact is not sealed by the release"
            )
        challenge_dispositions = payload.get("challenge_dispositions")
        if not isinstance(challenge_dispositions, list) or any(
            not isinstance(item, dict) for item in challenge_dispositions
        ):
            raise ValueError("challenge_dispositions must be a list of objects")
        normalized_dispositions: list[dict[str, str]] = []
        disposed_ids: set[str] = set()
        for item in challenge_dispositions:
            if set(item) != {"research_id", "disposition", "rationale"}:
                raise ValueError("challenge disposition fields are not exact")
            research_id = validate_memory_id(
                _require_nonempty_text(
                    item["research_id"], "challenge research id"
                )
            )
            if research_id in disposed_ids:
                raise ValueError("challenge disposition is duplicated")
            disposed_ids.add(research_id)
            challenge = self._inspection_research_record(
                research_id,
                inspection,
            )
            if (
                challenge["kind"]
                not in {"challenge", "counterexample", "obstacle"}
                and not self._research_is_adverse_assignment(challenge)
            ):
                raise ValueError(
                    "challenge disposition must reference adverse research"
                )
            if item["disposition"] not in V5_CHALLENGE_DISPOSITIONS:
                raise ValueError("challenge disposition is invalid")
            rationale = _require_nonempty_text(
                item["rationale"], "challenge disposition rationale"
            )
            normalized_dispositions.append(
                {
                    "research_id": research_id,
                    "disposition": item["disposition"],
                    "rationale": rationale,
                }
            )
        bound_challenges = {
            record["research_id"]
            for record in research_records
            if record["kind"] in {"challenge", "counterexample", "obstacle"}
            or self._research_is_adverse_assignment(record)
        }
        missing_dispositions = sorted(bound_challenges.difference(disposed_ids))
        if missing_dispositions:
            raise ValueError(
                "Candidate Release has undisposed bound challenges: "
                + ", ".join(missing_dispositions)
            )
        adverse_actor_ids = _require_string_list(
            payload.get("adverse_actor_ids"), "adverse actor ids"
        )
        if any(not item.strip() for item in adverse_actor_ids):
            raise ValueError("adverse actor ids must be nonempty strings")
        if len(adverse_actor_ids) != len(set(adverse_actor_ids)):
            raise ValueError("adverse actor ids are duplicated")
        actual_adverse_actor_ids = sorted(
            {
                record["actor"]
                for record in research_records
                if record["kind"] in {"challenge", "counterexample", "obstacle"}
                or self._research_is_adverse_assignment(record)
            }
        )
        if set(adverse_actor_ids) != set(actual_adverse_actor_ids):
            raise ValueError(
                "adverse actor ids must exactly match bound adverse Research actors: "
                + ", ".join(actual_adverse_actor_ids)
            )
        excluded_verifier_ids = sorted(
            {
                producer,
                *adverse_actor_ids,
                *(fact.author for fact in facts.values()),
                *(record["actor"] for record in research_records),
            }
        )
        child_ids = {edge[0] for edge in internal_edges}
        root_fact_ids = sorted(set(facts).difference(child_ids))
        intermediate_fact_ids = sorted(set(facts).difference(root_fact_ids))
        candidate_records = [
            {
                "fact_id": fact_id,
                "fact_sha256": sha256_bytes(rendered[fact_id]),
                "fact_markdown": rendered[fact_id].decode("utf-8"),
            }
            for fact_id in order
        ]
        research_draft_preflight: dict[str, Any] | None = None
        if research_draft_context is not None:
            research_draft_preflight = research_draft_admission_preflight(
                store=self.store,
                plan=research_draft_context["plan"],
                batch=research_draft_context["batch"],
                adequacy_receipt=research_draft_context["adequacy_receipt"],
                release_ref=research_draft_context["release_ref"],
                assurance=assurance,
                candidate_facts=facts,
                candidate_fact_file_sha256={
                    fact_id: sha256_bytes(rendered[fact_id])
                    for fact_id in facts
                },
                candidate_interfaces=candidate_interfaces,
                internal_edges=internal_edges,
                external_predecessor_ids=external_predecessors,
                research_bindings=research_bindings,
                paper_evidence_refs=paper_refs,
                artifacts=validation_artifacts,
                authorized_artifact_roles=authorized_roles,
                active_fact_file_sha256=lambda fact_id: sha256_bytes(
                    self.store.active_fact_path(
                        fact_id,
                        _inspection_context=inspection,
                    ).read_bytes()
                ),
                revoked_fact_ids=self.revoked_fact_ids(
                    _inspection_context=inspection,
                ),
            )
            if research_draft_preflight["normalized_assurance"] != assurance:
                raise ValueError(
                    "research-draft assurance normalization drifted across preflight"
                )
        semantic = {
            "schema_version": 5,
            "policy_revision": V5_POLICY_REVISION,
            "project_id": self.store.project_id(),
            "bundle_claim": bundle_claim,
            "producer": producer,
            "claim_relation": claim_relation,
            "research_bindings": research_bindings,
            "candidates": candidate_records,
            "fact_ids": order,
            "root_fact_ids": root_fact_ids,
            "intermediate_fact_ids": intermediate_fact_ids,
            "internal_edges": internal_edges,
            "external_predecessors": external_predecessors,
            "artifacts": normalized_artifacts,
            "verification_plan": normalized_plan,
            "requested_assurance": assurance,
            "challenge_dispositions": sorted(
                normalized_dispositions, key=lambda item: item["research_id"]
            ),
            "paper_evidence_refs": paper_refs,
            "fresh_adverse_readiness": fresh_adverse_readiness,
            **(
                {
                    "research_draft_ref": research_draft_context[
                        "release_ref"
                    ],
                    "research_draft_evidence": {
                        "plan": research_draft_context["plan"],
                        "batch": research_draft_context["batch"],
                        "adequacy_receipt": research_draft_context[
                            "adequacy_receipt"
                        ],
                        "research_records": research_records,
                    },
                    "research_draft_admission_preflight": (
                        research_draft_preflight["preflight"]
                    ),
                    "paper_evidence_transport_closure": (
                        research_draft_preflight["paper_transport_closure"]
                    ),
                    "validated_dependency_receipt": (
                        research_draft_preflight[
                            "validated_dependency_receipt"
                        ]
                    ),
                }
                if research_draft_context is not None
                and research_draft_preflight is not None
                else {}
            ),
            **(
                {
                    "paper_continuation_ref": continuation_binding[
                        "paper_continuation_ref"
                    ],
                    "paper_continuation_release_capsule": (
                        continuation_release_capsule
                    ),
                    **(
                        {
                            "philosophy_atomicity": continuation_binding[
                                "philosophy_atomicity"
                            ]
                        }
                        if continuation_binding["philosophy_atomicity"]
                        is not None
                        else {}
                    ),
                }
                if continuation_binding is not None
                else {}
            ),
            **(
                {"evidence_bridge_refs": bridge_refs}
                if "evidence_bridge_refs" in payload
                else {}
            ),
            "excluded_verifier_ids": excluded_verifier_ids,
            "fact_admission_contract_sha256": FACT_ADMISSION_CONTRACT_SHA256,
            "neutral_review_submission_revision": (
                NEUTRAL_REVIEW_SUBMISSION_REVISION
            ),
            "assurance_contract_revision": assurance_contract_revision,
            **(
                {
                    "applicable_assurance_checks": applicable_assurance_checks,
                    "candidate_interfaces": candidate_interfaces,
                    "research_assurance_evidence": research_assurance_evidence,
                    "successor_contracts": successor_contracts,
                }
                if assurance_contract_revision
                == V5_ASSURANCE_CONTRACT_REVISION
                else {}
            ),
            "truth_effect": "none",
        }
        release_sha = sha256_json(semantic)
        release_id = "release-" + release_sha
        created_at = _utc_now()
        without_record_hash = {
            **semantic,
            "release_id": release_id,
            "release_sha256": release_sha,
            "created_at": created_at,
        }
        record = {
            **without_record_hash,
            "record_sha256": sha256_json(without_record_hash),
        }
        if preflight_only:
            return {
                "valid": True,
                "release_id": release_id,
                "release_sha256": release_sha,
                "assurance_contract_revision": assurance_contract_revision,
                "applicable_assurance_checks": applicable_assurance_checks,
                "successor_contract_count": len(successor_contracts),
                "fresh_adverse_readiness": fresh_adverse_readiness,
                **(
                    {
                        "paper_continuation_release_validation": (
                            continuation_release_operation
                        )
                    }
                    if continuation_release_operation is not None
                    else {}
                ),
                "project_effect": "none",
                "truth_effect": "none",
            }
        path = self._release_path(release_id)
        with self.store.v5_mutation_lock(command="candidate-release"):
            sealed_inspection = self._bind_inspection_context(
                RoundInspectionContext(),
                create=True,
            )
            assert sealed_inspection is not None
            if path.exists():
                existing = self.release(
                    release_id,
                    _inspection_context=sealed_inspection,
                )
                if existing["release_sha256"] != release_sha:
                    raise ValueError(f"Candidate Release id collision at {path}")
                return existing
            try:
                sealed_supervision_result_ids = (
                    self._required_supervision_results_for_candidate(
                        explicit_research_records,
                        _inspection_context=sealed_inspection,
                    )
                )
            except ValueError as exc:
                raise ValueError(
                    "Candidate Research supervision liveness changed between "
                    "preflight and seal"
                ) from exc
            if (
                sealed_supervision_result_ids
                != required_supervision_result_ids
            ):
                raise ValueError(
                    "Candidate Research supervision result set changed between "
                    "preflight and seal"
                )
            sealed, _ = self._normalize_artifacts(
                payload.get("artifacts"), seal=True
            )
            if sealed != normalized_artifacts:
                raise ValueError(
                    "candidate artifact binding changed between preflight and seal"
                )
            if strict_research_draft:
                self._validate_research_draft_dependency_cache(
                    record,
                    force_deep=True,
                )
            self.store._write_json_once(path, record)
        return record

    def release(
        self,
        release_id: str,
        *,
        _lineage_facts: dict[str, Fact] | None = None,
        _lineage_paths: dict[str, Path] | None = None,
        _skip_successor_validation: bool = False,
        _deep_dependencies: bool = False,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any]:
        _inspection_context = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert _inspection_context is not None
        cache_key = (
            release_id,
            _skip_successor_validation,
            _deep_dependencies,
        )
        cacheable = _lineage_facts is None and _lineage_paths is None
        if (
            cacheable
            and _inspection_context is not None
            and cache_key in _inspection_context.release_records
        ):
            return _inspection_context.release_records[cache_key]
        path = self._release_path(release_id)
        if path.is_symlink() or not path.is_file():
            raise KeyError(f"unknown V5 Candidate Release: {release_id}")
        record = self.store._read_json(path)
        if not isinstance(record, dict):
            raise ValueError("Candidate Release record must be one object")
        record_only = {"release_id", "release_sha256", "created_at", "record_sha256"}
        semantic = {
            key: value for key, value in record.items() if key not in record_only
        }
        release_sha = sha256_json(semantic)
        if (
            record.get("schema_version") != 5
            or record.get("policy_revision") != V5_POLICY_REVISION
            or record.get("project_id") != self.store.project_id()
            or record.get("truth_effect") != "none"
            or record.get("release_id") != "release-" + release_sha
            or record.get("release_sha256") != release_sha
            or path.stem != record.get("release_id")
        ):
            raise ValueError("Candidate Release schema/project/id/hash mismatch")
        without_hash = {
            key: value for key, value in record.items() if key != "record_sha256"
        }
        if record.get("record_sha256") != sha256_json(without_hash):
            raise ValueError("Candidate Release record hash mismatch")
        created_at = _parse_utc_timestamp(
            record.get("created_at"), label="Candidate Release created_at"
        )
        if record.get("fact_admission_contract_sha256") != FACT_ADMISSION_CONTRACT_SHA256:
            raise ValueError("Candidate Release Fact contract mismatch")
        neutral_review_revision = record.get("neutral_review_submission_revision")
        if (
            neutral_review_revision is not None
            and neutral_review_revision != NEUTRAL_REVIEW_SUBMISSION_REVISION
        ):
            raise ValueError(
                "Candidate Release neutral review submission revision is unsupported"
            )
        strict_research_draft = _is_research_draft_assurance_revision(
            record.get("requested_assurance", {}).get("contract_revision")
        )
        candidates = record.get("candidates")
        if not isinstance(candidates, list) or not candidates:
            raise ValueError("Candidate Release candidates are invalid")
        seen: list[str] = []
        for candidate in candidates:
            if not isinstance(candidate, dict) or set(candidate) != {
                "fact_id",
                "fact_sha256",
                "fact_markdown",
            }:
                raise ValueError("Candidate Release candidate fields are not exact")
            raw = candidate["fact_markdown"].encode("utf-8")
            if sha256_bytes(raw) != candidate["fact_sha256"]:
                raise ValueError("Candidate Release Fact bytes/hash mismatch")
            fact = parse_fact_markdown(candidate["fact_markdown"])
            if fact.fact_id != candidate["fact_id"]:
                raise ValueError("Candidate Release Fact id mismatch")
            seen.append(fact.fact_id)
        if seen != record.get("fact_ids"):
            raise ValueError("Candidate Release Fact order is inconsistent")
        if "fresh_adverse_readiness" in record:
            self._validate_fresh_adverse_readiness(
                record["fresh_adverse_readiness"],
                candidate_records=candidates,
                research_bindings=record.get("research_bindings", []),
                challenge_dispositions=record.get(
                    "challenge_dispositions", []
                ),
                excluded_verifier_ids=record.get(
                    "excluded_verifier_ids", []
                ),
            )
        if not strict_research_draft:
            for artifact in record.get("artifacts", []):
                sealed = contained_path(
                    self.store.root,
                    artifact["sealed_relpath"],
                    "sealed Candidate Release artifact",
                )
                if (
                    sealed.is_symlink()
                    or not sealed.is_file()
                    or sha256_bytes(sealed.read_bytes())
                    != artifact["artifact_sha256"]
                ):
                    raise ValueError("sealed Candidate Release artifact drifted")
            for binding in record.get("research_bindings", []):
                research = self._inspection_research_record(
                    binding["research_id"], _inspection_context
                )
                if research["record_sha256"] != binding["record_sha256"]:
                    raise ValueError("Candidate Release research binding drifted")
        assurance_revision = record.get(
            "assurance_contract_revision",
            V5_LEGACY_ASSURANCE_CONTRACT_REVISION,
        )
        if assurance_revision not in {
            V5_ASSURANCE_CONTRACT_REVISION,
            V5_LEGACY_ASSURANCE_CONTRACT_REVISION,
        }:
            raise ValueError("Candidate Release assurance revision is unsupported")
        if assurance_revision == V5_ASSURANCE_CONTRACT_REVISION:
            for field in (
                "applicable_assurance_checks",
                "candidate_interfaces",
                "research_assurance_evidence",
                "successor_contracts",
            ):
                if not isinstance(record.get(field), list):
                    raise ValueError(
                        f"current Candidate Release {field} must be a list"
                    )
            candidate_facts = {
                candidate["fact_id"]: parse_fact_markdown(
                    candidate["fact_markdown"]
                )
                for candidate in candidates
            }
            successor_input_fields = {
                "mode",
                "predecessor_fact_id",
                "successor_fact_id",
                "predecessor_fact_sha256",
                "predecessor_proof_sha256",
                "successor_proof_sha256",
                "statement_projection",
                "proof_unit_conservation",
            }
            reconstructed_successor_input = [
                {key: item[key] for key in successor_input_fields}
                for item in record["successor_contracts"]
            ]
            if _skip_successor_validation:
                # Admission discovery is deliberately two phase.  The first
                # phase validates immutable release/admission bytes without
                # asking the active-Fact projection to validate itself.  The
                # second phase supplies a complete, read-only lineage snapshot
                # and replays this contract normally.
                expected_successors = record["successor_contracts"]
            else:
                if (_lineage_facts is None) != (_lineage_paths is None):
                    raise ValueError(
                        "Candidate Release lineage snapshot is incomplete"
                    )
                if _lineage_facts is None or _lineage_paths is None:
                    _lineage_facts, _lineage_paths = self._lineage_snapshot(
                        admitted_before=created_at,
                        exclude_release_ids={release_id},
                        _inspection_context=_inspection_context,
                    )
                expected_successors = validate_successor_contracts(
                    reconstructed_successor_input,
                    candidates=candidate_facts,
                    active_facts=_lineage_facts,
                    active_fact_sha256=lambda fact_id: sha256_bytes(
                        _lineage_paths[fact_id].read_bytes()
                    ),
                )
            if expected_successors != record["successor_contracts"]:
                raise ValueError("Candidate Release successor contract drifted")
            authorized_roles = set(
                record["verification_plan"]["authorized_artifact_roles"]
            )
            authorized_hashes = {
                item["artifact_sha256"]
                for item in record["artifacts"]
                if item["role"] in authorized_roles
            }
            bound_research = (
                record["research_draft_evidence"]["research_records"]
                if strict_research_draft
                else [
                    self._inspection_research_record(
                        binding["research_id"], _inspection_context
                    )
                    for binding in record["research_bindings"]
                ]
            )
            expected_evidence = self._research_assurance_evidence(
                research_records=bound_research,
                authorized_artifact_hashes=authorized_hashes,
                assurance_contract_revision=assurance_revision,
            )
            if expected_evidence != record["research_assurance_evidence"]:
                raise ValueError("Candidate Release Research assurance evidence drifted")
            expected_interfaces = [
                self._candidate_interface(
                    candidate_facts[fact_id],
                    next(
                        item["fact_markdown"].encode("utf-8")
                        for item in candidates
                        if item["fact_id"] == fact_id
                    ),
                    assurance_contract_revision=assurance_revision,
                )
                for fact_id in record["fact_ids"]
            ]
            if expected_interfaces != record["candidate_interfaces"]:
                raise ValueError("Candidate Release statement interfaces drifted")
            expected_checks = self._applicable_assurance_checks(
                facts=candidate_facts,
                research_records=bound_research,
                assurance_contract_revision=assurance_revision,
            )
            if expected_successors:
                expected_checks = sorted(
                    {*expected_checks, "proof_lineage_conservation"}
                )
            if expected_checks != record["applicable_assurance_checks"]:
                raise ValueError("Candidate Release applicable assurance checks drifted")
        sealed_candidate_facts = {
            candidate["fact_id"]: parse_fact_markdown(
                candidate["fact_markdown"]
            )
            for candidate in candidates
        }
        if strict_research_draft:
            self._validate_sealed_research_draft_release(
                record,
                candidate_facts=sealed_candidate_facts,
                deep_dependencies=_deep_dependencies,
            )
            bound_research = record["research_draft_evidence"][
                "research_records"
            ]
        else:
            bound_research = [
                self._inspection_research_record(
                    binding["research_id"], _inspection_context
                )
                for binding in record["research_bindings"]
            ]
        continuation = self.paper_continuation(
            _inspection_context=_inspection_context
        )
        continuation_plan_ids = continuation.plan_ids_for_research(
            bound_research
        )
        continuation_binding: dict[str, Any] | None = None
        if len(continuation_plan_ids) > 1:
            raise ValueError("Candidate Release mixes Paper continuation plans")
        if continuation_plan_ids:
            continuation_binding = continuation.validate_release_binding(
                plan_id=continuation_plan_ids[0],
                ref=record.get("paper_continuation_ref"),
                philosophy_atomicity=record.get("philosophy_atomicity"),
                facts=sealed_candidate_facts,
                require_current=False,
            )
            expected_nodes = {
                *continuation_binding["plan"][
                    "selected_reconstruction_node_ids"
                ],
                *continuation_binding["plan"]["selected_source_node_ids"],
            }
            subject = record["requested_assurance"]["validation_subject"]
            if (
                record["requested_assurance"]["validation_granularity"]
                != "paper_target_closure"
                or set(subject["load_bearing_node_ids"]) != expected_nodes
            ):
                raise ValueError("Candidate Release Paper continuation scope drifted")
            if "paper_continuation_release_capsule" in record:
                continuation.validate_release_capsule(
                    record["paper_continuation_release_capsule"],
                    require_current=False,
                    expected_ref=record["paper_continuation_ref"],
                    expected_paper_evidence_refs=record["paper_evidence_refs"],
                    expected_candidate_interfaces=record.get(
                        "candidate_interfaces", []
                    ),
                )
                if "paper_continuation_evidence" in record:
                    raise ValueError(
                        "Candidate Release duplicates continuation capsule evidence"
                    )
            else:
                expected_continuation_evidence = continuation.release_evidence(
                    plan_id=continuation_plan_ids[0],
                    disposition_ids=record["paper_continuation_ref"][
                        "disposition_ids"
                    ],
                    require_current=False,
                )
                if record.get("paper_continuation_evidence") != (
                    expected_continuation_evidence
                ):
                    raise ValueError(
                        "Candidate Release Paper continuation verifier evidence drifted"
                    )
        elif (
            "paper_continuation_ref" in record
            or "philosophy_atomicity" in record
            or "paper_continuation_evidence" in record
            or "paper_continuation_release_capsule" in record
        ):
            raise ValueError(
                "Candidate Release has unbound Paper continuation fields"
            )
        validated_paper_refs = (
            record.get("paper_evidence_refs", [])
            if strict_research_draft
            else self._validate_paper_evidence_refs(
                record.get("paper_evidence_refs"),
                validation_subject=record["requested_assurance"][
                    "validation_subject"
                ],
                require_current=False,
                _inspection_context=_inspection_context,
            )
        )
        if continuation_binding is not None:
            plan = continuation_binding["plan"]
            expected_nodes = {
                *plan["selected_reconstruction_node_ids"],
                *plan["selected_source_node_ids"],
            }
            matching_logic_refs = [
                item
                for item in validated_paper_refs
                if item["graph_kind"] == "logic"
                and item["snapshot_id"] == plan["snapshot_id"]
            ]
            if (
                len(matching_logic_refs) != 1
                or set(matching_logic_refs[0]["target_node_ids"])
                != expected_nodes
            ):
                raise ValueError(
                    "Candidate Release Paper continuation Logic binding drifted"
                )
        if "evidence_bridge_refs" in record:
            self._validate_evidence_bridge_refs(
                record["evidence_bridge_refs"],
                artifacts=record.get("artifacts", []),
                sealed_record=True,
                require_current=False,
            )
        if cacheable and _inspection_context is not None:
            _inspection_context.release_records[cache_key] = record
        return record

    def releases(
        self,
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> list[dict[str, Any]]:
        _inspection_context = self._bind_inspection_context(
            _inspection_context
        )
        if not self.candidate_releases_dir.exists():
            return []
        return [
            self.release(
                path.stem,
                _inspection_context=_inspection_context,
            )
            for path in sorted(self.candidate_releases_dir.glob("release-*.json"))
        ]

    def _require_current_paper_continuation_release(
        self,
        release: dict[str, Any],
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any] | None:
        bound_research = [
            self._inspection_research_record(
                binding["research_id"], _inspection_context
            )
            for binding in release["research_bindings"]
        ]
        continuation = self.paper_continuation(
            _inspection_context=_inspection_context
        )
        plan_ids = continuation.plan_ids_for_research(bound_research)
        if not plan_ids:
            return None
        if len(plan_ids) != 1:
            raise ValueError("Candidate Release mixes Paper continuation plans")
        current_proof: dict[str, Any] | None = None
        if "paper_continuation_release_capsule" in release:
            capsule = validate_candidate_continuation_release_capsule(
                continuation,
                release["paper_continuation_release_capsule"],
                require_current=False,
                expected_ref=release.get("paper_continuation_ref"),
                expected_paper_evidence_refs=release["paper_evidence_refs"],
                expected_candidate_interfaces=release.get(
                    "candidate_interfaces", []
                ),
            )
            current_proof = continuation.require_current_release_capsule(capsule)
            plan = continuation.plan(plan_ids[0])
        else:
            facts = {
                item["fact_id"]: parse_fact_markdown(item["fact_markdown"])
                for item in release["candidates"]
            }
            binding = continuation.validate_release_binding(
                plan_id=plan_ids[0],
                ref=release.get("paper_continuation_ref"),
                philosophy_atomicity=release.get("philosophy_atomicity"),
                facts=facts,
                require_current=True,
            )
            plan = binding["plan"]
        paper_refs = self._validate_paper_evidence_refs(
            release["paper_evidence_refs"],
            validation_subject=release["requested_assurance"][
                "validation_subject"
            ],
            require_current=True,
            _inspection_context=_inspection_context,
        )
        expected_nodes = {
            *plan["selected_reconstruction_node_ids"],
            *plan["selected_source_node_ids"],
        }
        matching_logic_refs = [
            item
            for item in paper_refs
            if item["graph_kind"] == "logic"
            and item["snapshot_id"] == plan["snapshot_id"]
        ]
        if (
            len(matching_logic_refs) != 1
            or set(matching_logic_refs[0]["target_node_ids"])
            != expected_nodes
        ):
            raise ValueError("Candidate Release Paper continuation is stale")
        return current_proof

    def release_for_fact(self, fact_id: str) -> dict[str, Any]:
        fact_id = validate_fact_id(fact_id)
        matches = [
            release for release in self.releases() if fact_id in release["fact_ids"]
        ]
        if len(matches) != 1:
            raise ValueError(
                f"V5 Fact candidate {fact_id} does not belong to one unique release"
            )
        return matches[0]

    def _source_nonpass_checks(
        self,
        release: dict[str, Any],
    ) -> list[dict[str, str]]:
        result: list[dict[str, str]] = []
        for candidate in release["candidates"]:
            fact = parse_fact_markdown(candidate["fact_markdown"])
            for ref in fact.external_refs:
                if ref.get("source_evidence_version") != 4:
                    continue
                audit = ref.get("critical_audit")
                if not isinstance(audit, dict):
                    continue
                for check in audit.get("sanity_checks", []):
                    if not isinstance(check, dict) or check.get("status") == "pass":
                        continue
                    result.append(
                        {
                            "fact_id": fact.fact_id,
                            "source_key": str(ref.get("key", "")),
                            "check_kind": str(check.get("kind", "")),
                            "status": str(check.get("status", "")),
                            "finding": str(check.get("finding", "")),
                        }
                    )
        return sorted(
            result,
            key=lambda item: (
                item["fact_id"],
                item["source_key"],
                item["check_kind"],
            ),
        )

    def _source_query_capabilities(
        self,
        release: dict[str, Any],
    ) -> list[dict[str, Any]]:
        capabilities: list[dict[str, Any]] = []
        for candidate in release["candidates"]:
            fact = parse_fact_markdown(candidate["fact_markdown"])
            for ref in fact.external_refs:
                if ref.get("source_evidence_version") != 4:
                    continue
                audit = ref.get("critical_audit")
                if not isinstance(audit, dict):
                    continue
                source_audit = audit.get("source_audit")
                if not isinstance(source_audit, dict):
                    continue
                for search in source_audit.get("issue_searches", []):
                    if (
                        isinstance(search, dict)
                        and search.get("evidence_mode") == "narrow_live_query"
                        and isinstance(search.get("live_query_capability"), dict)
                    ):
                        capabilities.append(
                            {
                                "fact_id": fact.fact_id,
                                "source_key": str(ref.get("key", "")),
                                "search_kind": str(search.get("kind", "")),
                                **search["live_query_capability"],
                            }
                        )
        capabilities.sort(
            key=lambda item: (
                item["fact_id"],
                item["source_key"],
                item["search_kind"],
            )
        )
        return capabilities

    def _certification_decision_template(
        self,
        release: dict[str, Any],
    ) -> dict[str, Any]:
        source_nonpass = self._source_nonpass_checks(release)
        template: dict[str, Any] = {
            "schema_version": 5,
            "release_id": release["release_id"],
            "release_sha256": release["release_sha256"],
            "capsule_sha256": "COPY_EXACT_CAPSULE_SHA256_FROM_CAPSULE_JSON",
            "verdict": "correct",
            "findings": [],
            "check_results": [
                {"check_id": check_id, "status": "pass", "findings": []}
                for check_id in release["verification_plan"]["required_checks"]
            ],
            "candidate_checks": [
                {"fact_id": fact_id, "verdict": "correct", "findings": []}
                for fact_id in release["fact_ids"]
            ],
            "edge_checks": [
                {
                    "predecessor_fact_id": predecessor,
                    "fact_id": fact_id,
                    "verdict": "correct",
                    "findings": [],
                }
                for predecessor, fact_id in release["internal_edges"]
            ],
            "assurance_matrix": self._expected_assurance_matrix(release),
            "reviewer": "REPLACE_WITH_FRESH_VERIFIER_ID",
            "host_attestation": {
                "host": "REPLACE_WITH_HOST_ID",
                "agent_id": "REPLACE_WITH_FRESH_VERIFIER_ID",
                "isolation": "fresh_context",
                "fork_turns": "none",
                "allowed_capsule_sha256": "COPY_EXACT_CAPSULE_SHA256_FROM_CAPSULE_JSON",
            },
        }
        if source_nonpass:
            template["source_check_reconciliation"] = [
                {
                    **{
                        key: item[key]
                        for key in ("fact_id", "source_key", "check_kind", "status")
                    },
                    "disposition": "bound_correction",
                    "rationale": "REPLACE_WITH_EXACT_RECONCILIATION_OR_REJECT",
                }
                for item in source_nonpass
            ]
        if _is_research_draft_assurance_revision(
            release["requested_assurance"].get("contract_revision")
        ):
            template["parallel_verification_aggregate_id"] = (
                "COPY_EXACT_ELIGIBLE_AGGREGATE_ID_FROM_PROJECT"
            )
        return template

    def verifier_capsule(
        self,
        release_id: str,
        *,
        _release: dict[str, Any] | None = None,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any]:
        _inspection_context = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert _inspection_context is not None
        if (
            release_id in _inspection_context.verifier_capsules
        ):
            return _inspection_context.verifier_capsules[release_id]
        release = (
            _release
            if _release is not None
            else self.release(
                release_id,
                _inspection_context=_inspection_context,
            )
        )
        if release.get("release_id") != release_id:
            raise ValueError("verifier capsule supplied Release id mismatch")
        self._require_current_paper_continuation_release(
            release,
            _inspection_context=_inspection_context,
        )
        predecessor_packets = []
        for fact_id in release["external_predecessors"]:
            fact_path = self.store.active_fact_path(
                fact_id,
                _inspection_context=_inspection_context,
            )
            predecessor_packets.append(
                {
                    "fact_id": fact_id,
                    "fact_sha256": sha256_bytes(fact_path.read_bytes()),
                    "statement": self.store.get_fact(
                        fact_id,
                        _inspection_context=_inspection_context,
                    ).statement,
                    "statement_interface": self.store.statement_interface(
                        fact_id,
                        materialize=False,
                        _inspection_context=_inspection_context,
                    ),
                }
            )
        authorized_roles = set(
            release["verification_plan"]["authorized_artifact_roles"]
        )
        authorized_artifacts = [
            artifact
            for artifact in release["artifacts"]
            if artifact["role"] in authorized_roles
        ]
        semantic: dict[str, Any] = {
            "schema_version": 5,
            "policy_revision": V5_POLICY_REVISION,
            "project_id": self.store.project_id(),
            "release_id": release_id,
            "release_sha256": release["release_sha256"],
            "fact_admission_contract_sha256": FACT_ADMISSION_CONTRACT_SHA256,
            "candidates": release["candidates"],
            "fact_ids": release["fact_ids"],
            "root_fact_ids": release["root_fact_ids"],
            "intermediate_fact_ids": release["intermediate_fact_ids"],
            "internal_edges": release["internal_edges"],
            "predecessor_packets": predecessor_packets,
            "authorized_artifacts": authorized_artifacts,
            "required_checks": release["verification_plan"]["required_checks"],
            "requested_assurance": release["requested_assurance"],
            "paper_evidence_refs": release["paper_evidence_refs"],
            "challenge_dispositions": release["challenge_dispositions"],
            "excluded_verifier_ids": release["excluded_verifier_ids"],
            "instructions": {
                "workspace_access": "forbidden",
                "allowed_input": "this_exact_capsule_only",
                "review_scope": (
                    "check every candidate, internal edge, predecessor use, source, "
                    "computation, challenge disposition, and requested assurance"
                ),
                "truth_effect": "none_until_gateway_admission",
            },
        }
        host_controlled_review = (
            release.get("neutral_review_submission_revision")
            == NEUTRAL_REVIEW_SUBMISSION_REVISION
        )
        if host_controlled_review:
            semantic["neutral_review_submission_revision"] = (
                NEUTRAL_REVIEW_SUBMISSION_REVISION
            )
        if "paper_continuation_ref" in release:
            semantic["paper_continuation_ref"] = release[
                "paper_continuation_ref"
            ]
            if "philosophy_atomicity" in release:
                semantic["philosophy_atomicity"] = release[
                    "philosophy_atomicity"
                ]
            if "paper_continuation_release_capsule" in release:
                semantic["paper_continuation_release_capsule"] = release[
                    "paper_continuation_release_capsule"
                ]
            else:
                semantic["paper_continuation_evidence"] = release[
                    "paper_continuation_evidence"
                ]
            semantic["instructions"]["paper_continuation_boundary"] = (
                "verify exact target-closure adequacy separately from Fact truth; "
                "for philosophy, independently reconstruct the conjunct inventory and "
                "reject any Fact that hides more than one independently falsifiable "
                "component behind its single declared conjunct; compare every ordinary-"
                "language paraphrase with the formal claim and reject undefined or "
                "unnecessary jargon that conceals a premise, burden, or inferential step"
            )
        if _is_research_draft_assurance_revision(
            release["requested_assurance"].get("contract_revision")
        ):
            semantic.update(
                {
                    "research_draft_ref": release["research_draft_ref"],
                    "research_draft_evidence": release[
                        "research_draft_evidence"
                    ],
                    "research_draft_admission_preflight": release[
                        "research_draft_admission_preflight"
                    ],
                    "paper_evidence_transport_closure": release[
                        "paper_evidence_transport_closure"
                    ],
                    "validated_dependency_receipt": release[
                        "validated_dependency_receipt"
                    ],
                }
            )
            if "stance_preservation" in release["requested_assurance"]:
                domain_boundary = (
                    "preserve the declared philosophical stance unless an exact "
                    "Operator authorization is sealed"
                )
            elif "mathematical_target_preservation" in release["requested_assurance"]:
                domain_boundary = (
                    "keep the original mathematical target, hypotheses, domains, and "
                    "quantifiers explicit; a typed weaker result is intermediate progress "
                    "and cannot close or replace the exact target"
                )
            else:
                domain_boundary = (
                    "preserve the declared empirical or mixed target through its exact "
                    "domain adapter"
                )
            semantic["instructions"]["research_draft_boundary"] = (
                "reconstruct the complete Paper target closure from the sealed transport; "
                "check node dispositions separately from many-to-many Paper-Fact mappings; "
                "check every source-derived atomic component and qualified failure surface; "
                + domain_boundary
            )
        if "evidence_bridge_refs" in release:
            current_bridge_refs = self._validate_evidence_bridge_refs(
                release["evidence_bridge_refs"],
                artifacts=release["artifacts"],
                sealed_record=True,
                require_current=True,
            )
            semantic["evidence_bridge_refs"] = current_bridge_refs
            semantic["instructions"]["evidence_boundary"] = (
                "bridge capsules are nontruth source inputs; independently verify every "
                "selected claim before recommending Fact admission"
            )
        if (
            release.get("assurance_contract_revision")
            == V5_ASSURANCE_CONTRACT_REVISION
        ):
            source_nonpass = self._source_nonpass_checks(release)
            template = self._certification_decision_template(release)
            successor_predecessor_packets = []
            for contract in release.get("successor_contracts", []):
                predecessor_id = contract["predecessor_fact_id"]
                predecessor_path = self.store.active_fact_path(
                    predecessor_id,
                    _inspection_context=_inspection_context,
                )
                predecessor_raw = predecessor_path.read_bytes()
                predecessor = self.store.get_fact(
                    predecessor_id,
                    _inspection_context=_inspection_context,
                )
                successor_predecessor_packets.append(
                    {
                        "fact_id": predecessor_id,
                        "fact_sha256": sha256_bytes(predecessor_raw),
                        "fact_markdown": predecessor_raw.decode("utf-8"),
                        "statement": predecessor.statement,
                        "proof": predecessor.proof,
                    }
                )
            semantic.update(
                {
                    "assurance_contract_revision": V5_ASSURANCE_CONTRACT_REVISION,
                    "applicable_assurance_checks": release.get(
                        "applicable_assurance_checks", []
                    ),
                    "candidate_interfaces": release.get(
                        "candidate_interfaces", []
                    ),
                    "research_assurance_evidence": release.get(
                        "research_assurance_evidence", []
                    ),
                    "successor_contracts": release.get(
                        "successor_contracts", []
                    ),
                    "successor_predecessor_packets": sorted(
                        successor_predecessor_packets,
                        key=lambda item: item["fact_id"],
                    ),
                    "proof_diff_policy": {
                        "display": "statement_and_proof_diffs_separately",
                        "interface_only": "predecessor_proof_bytes_must_match_exactly",
                        "rewritten_proof": (
                            "every_predecessor_proof_unit_mapped_or_explicitly_pruned"
                        ),
                    },
                    "source_nonpass_checks": source_nonpass,
                    "source_query_capabilities": self._source_query_capabilities(
                        release
                    ),
                    "decision_return": {
                        "template": template,
                        "allowed_nested_keys": {
                            "finding": [
                                "id",
                                "severity",
                                "class",
                                "description",
                                "repair_hint",
                            ],
                            "check_result": ["check_id", "status", "findings"],
                            "candidate_check": ["fact_id", "verdict", "findings"],
                            "edge_check": [
                                "predecessor_fact_id",
                                "fact_id",
                                "verdict",
                                "findings",
                            ],
                            "source_check_reconciliation": [
                                "fact_id",
                                "source_key",
                                "check_kind",
                                "status",
                                "disposition",
                                "rationale",
                            ],
                        },
                        "verifier_action": (
                            "write output/review-draft.json only; do not write the "
                            "canonical review or record into the project"
                            if host_controlled_review
                            else (
                                "write and locally preflight output/review.json only; "
                                "do not record into the project"
                            )
                        ),
                        **(
                            {
                                "host_action": (
                                    "run host/submit_review.py so a strict preflight "
                                    "either quarantines the draft or atomically "
                                    "publishes immutable output/review.json plus a "
                                    "formal-return receipt"
                                )
                            }
                            if host_controlled_review
                            else {}
                        ),
                        "gateway_action": (
                            (
                                "only after the formally_returned receipt and exact "
                                "review bytes validate, run certification-record and "
                                "fact-admit"
                            )
                            if host_controlled_review
                            else (
                                "after byte-preserving handoff, the gateway runs "
                                "certification-record and fact-admit"
                            )
                        ),
                        "local_validator": "host/validate_decision.py",
                        **(
                            {"host_submission_program": "host/submit_review.py"}
                            if host_controlled_review
                            else {}
                        ),
                    },
                }
            )
        capsule_sha = sha256_json(semantic)
        capsule = {
            **semantic,
            "capsule_id": "capsule-" + capsule_sha,
            "capsule_sha256": capsule_sha,
        }
        if _inspection_context is not None:
            _inspection_context.verifier_capsules[release_id] = capsule
        return capsule

    def _validate_finding(self, finding: Any, *, label: str) -> dict[str, str]:
        finding = _require_exact_object_fields(
            finding,
            {"id", "severity", "class", "description", "repair_hint"},
            label=label,
            pointer=f"/{label.replace('[', '/').replace(']', '')}",
        )
        normalized = {
            key: _require_nonempty_text(finding[key], f"{label} {key}")
            for key in ("id", "severity", "class", "description")
        }
        if finding["severity"] not in {"critical_error", "gap"}:
            raise ValueError(f"{label} severity is invalid")
        if finding["class"] not in V5_FINDING_CLASSES:
            raise ValueError(f"{label} class is invalid")
        repair_hint = finding["repair_hint"]
        if not isinstance(repair_hint, str):
            raise ValueError(f"{label} repair_hint must be a string")
        return {**normalized, "repair_hint": repair_hint}

    def _certification_repair_payload(
        self,
        decision: dict[str, Any],
    ) -> dict[str, Any]:
        if decision.get("verdict") != "reject":
            raise ValueError(
                "Certification repair effects are allowed only for rejection decisions"
            )
        findings = decision.get("findings")
        if not isinstance(findings, list) or not findings:
            raise ValueError("rejecting Certification Decision lacks repair findings")
        return {
            "kind": "repair",
            "claim": (
                "Repair rejected Candidate Release " + decision["release_id"]
            ),
            "content": "; ".join(item["description"] for item in findings),
            "release_id": decision["release_id"],
            "decision_id": decision["decision_id"],
            "finding_ids": [item["id"] for item in findings],
        }

    def _certification_repair_intent(
        self,
        decision: dict[str, Any],
    ) -> dict[str, Any]:
        semantic = {
            "schema_version": 1,
            "contract_revision": V5_CERTIFICATION_REPAIR_OUTBOX_REVISION,
            "project_id": self.store.project_id(),
            "decision_id": decision["decision_id"],
            "decision_sha256": decision["decision_sha256"],
            "release_id": decision["release_id"],
            "release_sha256": decision["release_sha256"],
            "repair_actor": V5_CERTIFICATION_REPAIR_ACTOR,
            "repair_payload": self._certification_repair_payload(decision),
            "assurance_contract_revision": (
                V5_LEGACY_ASSURANCE_CONTRACT_REVISION
            ),
            "effect": "materialize_nontruth_repair_research",
            "truth_effect": "none",
            "premise_eligible": False,
        }
        return {
            **semantic,
            "intent_id": "cert-repair-intent-" + sha256_json(semantic),
        }

    def _validate_certification_repair_intent_record(
        self,
        intent: Any,
    ) -> dict[str, Any]:
        intent = _require_exact_object_fields(
            intent,
            {
                "schema_version",
                "contract_revision",
                "project_id",
                "decision_id",
                "decision_sha256",
                "release_id",
                "release_sha256",
                "repair_actor",
                "repair_payload",
                "assurance_contract_revision",
                "effect",
                "truth_effect",
                "premise_eligible",
                "intent_id",
            },
            label="Certification repair intent",
            pointer="/",
        )
        self._decision_path(intent["decision_id"])
        self._release_path(intent["release_id"])
        for key in ("decision_sha256", "release_sha256"):
            if (
                not isinstance(intent[key], str)
                or SHA256_RE.fullmatch(intent[key]) is None
            ):
                raise ValueError(f"Certification repair intent {key} is invalid")
        payload = _require_exact_object_fields(
            intent["repair_payload"],
            {
                "kind",
                "claim",
                "content",
                "release_id",
                "decision_id",
                "finding_ids",
            },
            label="Certification repair payload",
            pointer="/repair_payload",
        )
        if (
            intent["schema_version"] != 1
            or intent["contract_revision"]
            != V5_CERTIFICATION_REPAIR_OUTBOX_REVISION
            or intent["project_id"] != self.store.project_id()
            or intent["decision_id"]
            != "decision-" + intent["decision_sha256"]
            or intent["repair_actor"] != V5_CERTIFICATION_REPAIR_ACTOR
            or intent["assurance_contract_revision"]
            != V5_LEGACY_ASSURANCE_CONTRACT_REVISION
            or intent["effect"] != "materialize_nontruth_repair_research"
            or intent["truth_effect"] != "none"
            or intent["premise_eligible"] is not False
            or payload["kind"] != "repair"
            or payload["release_id"] != intent["release_id"]
            or payload["decision_id"] != intent["decision_id"]
        ):
            raise ValueError("Certification repair intent semantics are invalid")
        _require_nonempty_text(payload["claim"], "Certification repair claim")
        if not isinstance(payload["content"], str):
            raise ValueError("Certification repair content must be a string")
        finding_ids = _require_string_list(
            payload["finding_ids"],
            "Certification repair finding ids",
        )
        if (
            not finding_ids
            or any(not item for item in finding_ids)
            or len(finding_ids) != len(set(finding_ids))
        ):
            raise ValueError("Certification repair finding ids are invalid")
        semantic = {
            key: value for key, value in intent.items() if key != "intent_id"
        }
        if intent["intent_id"] != "cert-repair-intent-" + sha256_json(semantic):
            raise ValueError("Certification repair intent id/hash mismatch")
        return intent

    def _load_certification_repair_intent(
        self,
        decision: dict[str, Any],
    ) -> dict[str, Any]:
        path = self._certification_repair_intent_path(decision["decision_id"])
        if path.is_symlink() or not path.is_file():
            raise KeyError(
                "missing Certification rejection repair intent: "
                + decision["decision_id"]
            )
        intent = self._validate_certification_repair_intent_record(
            self.store._read_json(path)
        )
        expected = self._certification_repair_intent(decision)
        if intent != expected:
            raise ValueError("Certification rejection repair intent drifted")
        return intent

    def _certification_repair_effect_receipt(
        self,
        *,
        decision: dict[str, Any],
        intent: dict[str, Any],
        research: dict[str, Any],
    ) -> dict[str, Any]:
        semantic = {
            "schema_version": 1,
            "contract_revision": V5_CERTIFICATION_REPAIR_OUTBOX_REVISION,
            "project_id": self.store.project_id(),
            "intent_id": intent["intent_id"],
            "decision_id": decision["decision_id"],
            "decision_record_sha256": decision["record_sha256"],
            "release_id": decision["release_id"],
            "repair_research_id": research["research_id"],
            "repair_research_semantic_sha256": research["semantic_sha256"],
            "repair_research_record_sha256": research["record_sha256"],
            "effect": "nontruth_repair_research_materialized",
            "truth_effect": "none",
            "premise_eligible": False,
        }
        return {
            **semantic,
            "receipt_id": "cert-repair-effect-" + sha256_json(semantic),
        }

    def _load_certification_repair_effect(
        self,
        *,
        decision: dict[str, Any],
        intent: dict[str, Any],
    ) -> dict[str, Any]:
        path = self._certification_repair_effect_path(decision["decision_id"])
        if path.is_symlink() or not path.is_file():
            raise KeyError(
                "missing Certification rejection repair effect: "
                + decision["decision_id"]
            )
        receipt = self.store._read_json(path)
        research_id = receipt.get("repair_research_id")
        if not isinstance(research_id, str):
            raise ValueError(
                "Certification rejection repair effect lacks a Research id"
            )
        research = self._research_record(research_id)
        expected = self._certification_repair_effect_receipt(
            decision=decision,
            intent=intent,
            research=research,
        )
        if receipt != expected:
            raise ValueError("Certification rejection repair effect drifted")
        return receipt

    def _write_certification_repair_effect(
        self,
        receipt: dict[str, Any],
    ) -> None:
        self.store._write_json_once(
            self._certification_repair_effect_path(receipt["decision_id"]),
            receipt,
        )

    def _ensure_certification_repair_effect(
        self,
        decision: dict[str, Any],
    ) -> dict[str, Any]:
        """Finish the durable rejection side effect on an explicit write retry."""

        intent = self._certification_repair_intent(decision)
        self.store._write_json_once(
            self._certification_repair_intent_path(decision["decision_id"]),
            intent,
        )
        effect_path = self._certification_repair_effect_path(
            decision["decision_id"]
        )
        if effect_path.exists():
            receipt = self._load_certification_repair_effect(
                decision=decision,
                intent=intent,
            )
            research = self._research_record(receipt["repair_research_id"])
            self.paper_continuation()._status_index.reconcile_research(research)
            return receipt
        research = self.add_research(
            intent["repair_payload"],
            actor=intent["repair_actor"],
            assurance_contract_revision=intent[
                "assurance_contract_revision"
            ],
        )
        receipt = self._certification_repair_effect_receipt(
            decision=decision,
            intent=intent,
            research=research,
        )
        self._write_certification_repair_effect(receipt)
        return receipt

    def _expected_assurance_matrix(
        self,
        release: dict[str, Any],
    ) -> dict[str, Any]:
        paper_requested = (
            release["requested_assurance"]["validation_subject"]["kind"]
            == "paper"
        )
        return {
            "paper_source_fidelity": (
                "complete" if paper_requested else "not_requested"
            ),
            "paper_graph_structure": (
                "complete" if paper_requested else "not_requested"
            ),
            "paper_audit": "complete" if paper_requested else "not_requested",
            "root_fact_admission": "candidate",
            "intermediate_fact_coverage": {
                "admitted_count": 0,
                "required_count": len(release["intermediate_fact_ids"]),
            },
            "validation_granularity": release["requested_assurance"][
                "validation_granularity"
            ],
        }

    def certification_record(
        self,
        payload: dict[str, Any],
        *,
        preflight_only: bool = False,
    ) -> dict[str, Any]:
        if not isinstance(payload, dict):
            raise ValueError("Certification Decision input must be one object")
        required = {
            "schema_version",
            "release_id",
            "release_sha256",
            "capsule_sha256",
            "verdict",
            "findings",
            "check_results",
            "candidate_checks",
            "edge_checks",
            "assurance_matrix",
            "reviewer",
            "host_attestation",
        }
        release_id = payload.get("release_id")
        if not isinstance(release_id, str):
            raise ValueError(
                "Certification Decision fields are not exact: missing=/release_id"
            )
        inspection = self._bind_inspection_context(
            RoundInspectionContext(),
            create=True,
        )
        assert inspection is not None
        release = self.release(
            release_id,
            _inspection_context=inspection,
        )
        strict_research_draft = _is_research_draft_assurance_revision(
            release["requested_assurance"].get("contract_revision")
        )
        if strict_research_draft:
            required.add("parallel_verification_aggregate_id")
        source_nonpass = self._source_nonpass_checks(release)
        if source_nonpass:
            required.add("source_check_reconciliation")
        _require_exact_object_fields(
            payload,
            required,
            label="Certification Decision input",
            pointer="",
        )
        if payload.get("schema_version") != 5:
            raise ValueError("Certification Decision schema_version must be 5")
        capsule = self.verifier_capsule(
            release["release_id"],
            _release=release,
            _inspection_context=inspection,
        )
        if (
            payload.get("release_sha256") != release["release_sha256"]
            or payload.get("capsule_sha256") != capsule["capsule_sha256"]
        ):
            raise ValueError("Certification Decision release/capsule binding mismatch")
        parallel_aggregate: dict[str, Any] | None = None
        if strict_research_draft:
            aggregate_id = _require_nonempty_text(
                payload.get("parallel_verification_aggregate_id"),
                "parallel verification aggregate id",
            )
            parallel_aggregate = self.parallel_verification().require_eligible_for_release(
                release["release_id"], aggregate_id
            )
        verdict = payload.get("verdict")
        if verdict not in {"correct", "reject"}:
            raise ValueError("Certification Decision verdict must be correct or reject")
        findings_value = payload.get("findings")
        if not isinstance(findings_value, list):
            raise ValueError("Certification Decision findings must be a list")
        findings = [
            self._validate_finding(item, label=f"finding[{index}]")
            for index, item in enumerate(findings_value, 1)
        ]
        if len({item["id"] for item in findings}) != len(findings):
            raise ValueError("Certification Decision finding ids must be unique")
        check_results = payload.get("check_results")
        if not isinstance(check_results, list):
            raise ValueError("Certification /check_results must be a list")
        normalized_check_results: list[dict[str, Any]] = []
        for index, raw_item in enumerate(check_results):
            item = _require_exact_object_fields(
                raw_item,
                {"check_id", "status", "findings"},
                label="Certification check_result",
                pointer=f"/check_results/{index}",
            )
            check_id = _require_nonempty_text(
                item["check_id"], "Certification check id"
            )
            if item["status"] not in {"pass", "fail"}:
                raise ValueError("Certification check status is invalid")
            check_findings = _require_string_list(
                item["findings"], "Certification check finding ids"
            )
            if any(finding_id not in {f["id"] for f in findings} for finding_id in check_findings):
                raise ValueError("Certification check references an unknown finding")
            normalized_check_results.append(
                {
                    "check_id": check_id,
                    "status": item["status"],
                    "findings": sorted(dict.fromkeys(check_findings)),
                }
            )
        if {item["check_id"] for item in normalized_check_results} != set(
            capsule["required_checks"]
        ):
            raise ValueError(
                "Certification check_results do not exactly cover required checks"
            )
        if len(normalized_check_results) != len(
            {item["check_id"] for item in normalized_check_results}
        ):
            raise ValueError("Certification check_results contain duplicate checks")
        candidate_checks = payload.get("candidate_checks")
        if not isinstance(candidate_checks, list):
            raise ValueError("Certification /candidate_checks must be a list")
        normalized_candidate_checks: list[dict[str, Any]] = []
        for index, raw_item in enumerate(candidate_checks):
            item = _require_exact_object_fields(
                raw_item,
                {"fact_id", "verdict", "findings"},
                label="Certification candidate_check",
                pointer=f"/candidate_checks/{index}",
            )
            fact_id = validate_fact_id(item["fact_id"])
            if item["verdict"] not in {"correct", "reject"}:
                raise ValueError("Certification candidate verdict is invalid")
            check_findings = _require_string_list(
                item["findings"], "candidate check finding ids"
            )
            if any(finding_id not in {f["id"] for f in findings} for finding_id in check_findings):
                raise ValueError("candidate check references an unknown finding")
            normalized_candidate_checks.append(
                {
                    "fact_id": fact_id,
                    "verdict": item["verdict"],
                    "findings": sorted(dict.fromkeys(check_findings)),
                }
            )
        if {item["fact_id"] for item in normalized_candidate_checks} != set(
            release["fact_ids"]
        ):
            raise ValueError(
                "Certification candidate_checks do not exactly cover release Facts"
            )
        if len(normalized_candidate_checks) != len(
            {item["fact_id"] for item in normalized_candidate_checks}
        ):
            raise ValueError("Certification candidate_checks contain duplicate Facts")
        edge_checks = payload.get("edge_checks")
        if not isinstance(edge_checks, list):
            raise ValueError("Certification /edge_checks must be a list")
        normalized_edge_checks: list[dict[str, Any]] = []
        for index, raw_item in enumerate(edge_checks):
            item = _require_exact_object_fields(
                raw_item,
                {"predecessor_fact_id", "fact_id", "verdict", "findings"},
                label="Certification edge_check",
                pointer=f"/edge_checks/{index}",
            )
            predecessor = validate_fact_id(item["predecessor_fact_id"])
            fact_id = validate_fact_id(item["fact_id"])
            if item["verdict"] not in {"correct", "reject"}:
                raise ValueError("Certification edge verdict is invalid")
            check_findings = _require_string_list(
                item["findings"], "edge check finding ids"
            )
            if any(finding_id not in {f["id"] for f in findings} for finding_id in check_findings):
                raise ValueError("edge check references an unknown finding")
            normalized_edge_checks.append(
                {
                    "predecessor_fact_id": predecessor,
                    "fact_id": fact_id,
                    "verdict": item["verdict"],
                    "findings": sorted(dict.fromkeys(check_findings)),
                }
            )
        expected_edges = {tuple(edge) for edge in release["internal_edges"]}
        actual_edges = {
            (item["predecessor_fact_id"], item["fact_id"])
            for item in normalized_edge_checks
        }
        if actual_edges != expected_edges:
            raise ValueError(
                "Certification edge_checks do not exactly cover internal edges"
            )
        if len(normalized_edge_checks) != len(actual_edges):
            raise ValueError("Certification edge_checks contain duplicate edges")
        normalized_reconciliation: list[dict[str, str]] = []
        if source_nonpass:
            reconciliation = payload.get("source_check_reconciliation")
            if not isinstance(reconciliation, list):
                raise ValueError(
                    "Certification /source_check_reconciliation must be a list"
                )
            expected_nonpass = {
                (
                    item["fact_id"],
                    item["source_key"],
                    item["check_kind"],
                    item["status"],
                )
                for item in source_nonpass
            }
            seen_nonpass: set[tuple[str, str, str, str]] = set()
            for index, raw_item in enumerate(reconciliation):
                item = _require_exact_object_fields(
                    raw_item,
                    {
                        "fact_id",
                        "source_key",
                        "check_kind",
                        "status",
                        "disposition",
                        "rationale",
                    },
                    label="Certification source_check_reconciliation",
                    pointer=f"/source_check_reconciliation/{index}",
                )
                identity = tuple(
                    _require_nonempty_text(
                        item[key],
                        f"source reconciliation {key}",
                    )
                    for key in ("fact_id", "source_key", "check_kind", "status")
                )
                if identity not in expected_nonpass or identity in seen_nonpass:
                    raise ValueError(
                        "Certification source reconciliation is unknown or duplicated: "
                        + ":".join(identity)
                    )
                seen_nonpass.add(identity)
                disposition = item.get("disposition")
                if disposition not in {
                    "bound_correction",
                    "scope_restriction",
                    "reject",
                }:
                    raise ValueError(
                        "Certification source reconciliation disposition is invalid"
                    )
                rationale = _require_nonempty_text(
                    item.get("rationale"),
                    "source reconciliation rationale",
                )
                normalized_reconciliation.append(
                    {
                        "fact_id": identity[0],
                        "source_key": identity[1],
                        "check_kind": identity[2],
                        "status": identity[3],
                        "disposition": disposition,
                        "rationale": rationale,
                    }
                )
            if seen_nonpass != expected_nonpass:
                raise ValueError(
                    "Certification source reconciliation does not exactly cover every non-pass check"
                )
        expected_matrix = self._expected_assurance_matrix(release)
        if payload.get("assurance_matrix") != expected_matrix:
            raise ValueError("Certification assurance matrix is incorrect")
        reviewer = _require_nonempty_text(payload.get("reviewer"), "reviewer")
        if reviewer.casefold() in {
            item.casefold() for item in release["excluded_verifier_ids"]
        }:
            raise ValueError(
                "Certification reviewer participated in candidate/adverse research"
            )
        attestation = payload.get("host_attestation")
        attestation = _require_exact_object_fields(
            attestation,
            {
                "host",
                "agent_id",
                "isolation",
                "fork_turns",
                "allowed_capsule_sha256",
            },
            label="Certification host_attestation",
            pointer="/host_attestation",
        )
        for key in ("host", "agent_id", "isolation", "fork_turns"):
            _require_nonempty_text(attestation[key], f"host attestation {key}")
        if (
            attestation["agent_id"] != reviewer
            or attestation["isolation"] != "fresh_context"
            or attestation["fork_turns"] != "none"
            or attestation["allowed_capsule_sha256"] != capsule["capsule_sha256"]
        ):
            raise ValueError("Certification fresh-context attestation is invalid")
        clean = (
            not findings
            and all(item["status"] == "pass" for item in normalized_check_results)
            and all(item["verdict"] == "correct" for item in normalized_candidate_checks)
            and all(item["verdict"] == "correct" for item in normalized_edge_checks)
            and all(
                item["disposition"] != "reject"
                for item in normalized_reconciliation
            )
        )
        if verdict == "correct" and not clean:
            raise ValueError("correct Certification Decision must be completely clean")
        if verdict == "reject" and clean:
            raise ValueError("rejecting Certification Decision requires a failed check")
        # Execute the byte-identical validator transported to the neutral capsule
        # before storage.  Gateway-specific diagnostics above remain stable, while
        # no locally preflighted shape or finding class can diverge at admission.
        validate_decision_against_capsule(payload, capsule)
        semantic = {
            "schema_version": 5,
            "policy_revision": V5_POLICY_REVISION,
            "project_id": self.store.project_id(),
            "release_id": release["release_id"],
            "release_sha256": release["release_sha256"],
            "capsule_sha256": capsule["capsule_sha256"],
            "verdict": verdict,
            "findings": findings,
            "check_results": sorted(
                normalized_check_results, key=lambda item: item["check_id"]
            ),
            "candidate_checks": sorted(
                normalized_candidate_checks, key=lambda item: item["fact_id"]
            ),
            "edge_checks": sorted(
                normalized_edge_checks,
                key=lambda item: (item["predecessor_fact_id"], item["fact_id"]),
            ),
            "assurance_matrix": expected_matrix,
            "reviewer": reviewer,
            "host_attestation": attestation,
            **(
                {
                    "parallel_verification_aggregate_id": parallel_aggregate[
                        "aggregate"
                    ]["aggregate_id"],
                    "parallel_verification_aggregate_record_sha256": (
                        parallel_aggregate["record_sha256"]
                    ),
                }
                if parallel_aggregate is not None
                else {}
            ),
            **(
                {
                    "source_check_reconciliation": sorted(
                        normalized_reconciliation,
                        key=lambda item: (
                            item["fact_id"],
                            item["source_key"],
                            item["check_kind"],
                        ),
                    )
                }
                if source_nonpass
                else {}
            ),
            "truth_effect": "none",
        }
        decision_sha = sha256_json(semantic)
        decision_id = "decision-" + decision_sha
        if preflight_only:
            return {
                "valid": True,
                "decision_id": decision_id,
                "decision_sha256": decision_sha,
                "release_id": release["release_id"],
                "capsule_sha256": capsule["capsule_sha256"],
                "project_effect": "none",
                "truth_effect": "none",
            }
        reviewed_at = _utc_now()
        without_hash = {
            **semantic,
            "decision_id": decision_id,
            "decision_sha256": decision_sha,
            "reviewed_at": reviewed_at,
        }
        record = {**without_hash, "record_sha256": sha256_json(without_hash)}
        with self.store.v5_mutation_lock(command="certification-record"):
            # Recheck under the publication lock.  Besides making concurrent
            # submissions single-writer, this is the explicit retry boundary
            # that may finish a previously interrupted repair side effect.
            locked_inspection = self._bind_inspection_context(
                RoundInspectionContext(),
                create=True,
            )
            assert locked_inspection is not None
            locked_release = self.release(
                release_id,
                _inspection_context=locked_inspection,
            )
            locked_capsule = self.verifier_capsule(
                release_id,
                _release=locked_release,
                _inspection_context=locked_inspection,
            )
            if (
                locked_release["release_sha256"] != release["release_sha256"]
                or locked_capsule["capsule_sha256"] != capsule["capsule_sha256"]
            ):
                raise ValueError(
                    "Certification Release or capsule changed before publication"
                )
            existing_for_release: list[dict[str, Any]] = []
            for path in sorted(
                self.certification_decisions_dir.glob("decision-*.json")
            ):
                if path.is_symlink() or not path.is_file():
                    raise ValueError(
                        "Certification Decision store contains an unsafe entry"
                    )
                existing = self.decision(
                    path.stem,
                    validate_bindings=False,
                    _inspection_context=locked_inspection,
                )
                if existing["release_id"] == release["release_id"]:
                    existing_for_release.append(existing)
            if existing_for_release:
                if len(existing_for_release) != 1:
                    raise ValueError(
                        "Candidate Release has multiple Certification Decisions"
                    )
                existing = existing_for_release[0]
                if existing["decision_id"] != decision_id:
                    raise ValueError(
                        "Candidate Release already has a Certification Decision; "
                        "repair Research and seal a new release"
                    )
                if existing["verdict"] == "reject":
                    self._ensure_certification_repair_effect(existing)
                return existing
            if verdict == "reject":
                # The durable intent is published before the Decision so there
                # is no visible new rejection without an exact recoverable
                # description of its required nontruth side effect.
                intent = self._certification_repair_intent(record)
                self.store._write_json_once(
                    self._certification_repair_intent_path(decision_id),
                    intent,
                )
            self.store._write_json_once(self._decision_path(decision_id), record)
            if verdict == "reject":
                self._ensure_certification_repair_effect(record)
        return record

    def decision(
        self,
        decision_id: str,
        *,
        validate_bindings: bool = True,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any]:
        _inspection_context = self._bind_inspection_context(
            _inspection_context
        )
        cache_key = (decision_id, validate_bindings)
        if (
            _inspection_context is not None
            and cache_key in _inspection_context.decision_records
        ):
            return _inspection_context.decision_records[cache_key]
        path = self._decision_path(decision_id)
        if path.is_symlink() or not path.is_file():
            raise KeyError(f"unknown V5 Certification Decision: {decision_id}")
        record = self.store._read_json(path)
        if not isinstance(record, dict):
            raise ValueError("Certification Decision record must be one object")
        record_only = {
            "decision_id",
            "decision_sha256",
            "reviewed_at",
            "record_sha256",
        }
        semantic = {
            key: value for key, value in record.items() if key not in record_only
        }
        decision_sha = sha256_json(semantic)
        if (
            record.get("schema_version") != 5
            or record.get("policy_revision") != V5_POLICY_REVISION
            or record.get("project_id") != self.store.project_id()
            or record.get("truth_effect") != "none"
            or record.get("decision_id") != "decision-" + decision_sha
            or record.get("decision_sha256") != decision_sha
            or path.stem != record.get("decision_id")
        ):
            raise ValueError("Certification Decision schema/project/id/hash mismatch")
        without_hash = {
            key: value for key, value in record.items() if key != "record_sha256"
        }
        if record.get("record_sha256") != sha256_json(without_hash):
            raise ValueError("Certification Decision record hash mismatch")
        if validate_bindings:
            release = (
                self.release(record["release_id"])
                if _inspection_context is None
                else self.release(
                    record["release_id"],
                    _inspection_context=_inspection_context,
                )
            )
            capsule = self.verifier_capsule(
                release["release_id"],
                _release=release,
                _inspection_context=_inspection_context,
            )
            if (
                record["release_sha256"] != release["release_sha256"]
                or record["capsule_sha256"] != capsule["capsule_sha256"]
            ):
                raise ValueError("Certification Decision binding drifted")
            strict_research_draft = _is_research_draft_assurance_revision(
                release["requested_assurance"].get("contract_revision")
            )
            if strict_research_draft:
                aggregate_id = record.get("parallel_verification_aggregate_id")
                if not isinstance(aggregate_id, str):
                    raise ValueError(
                        "research-draft Certification Decision lacks parallel verification"
                    )
                aggregate = self.parallel_verification().require_eligible_for_release(
                    release["release_id"], aggregate_id
                )
                if (
                    record.get("parallel_verification_aggregate_record_sha256")
                    != aggregate["record_sha256"]
                ):
                    raise ValueError(
                        "Certification Decision parallel aggregate binding drifted"
                    )
            elif any(
                key in record
                for key in (
                    "parallel_verification_aggregate_id",
                    "parallel_verification_aggregate_record_sha256",
                )
            ):
                raise ValueError(
                    "non-research-draft Certification Decision has parallel aggregate fields"
                )
        if _inspection_context is not None:
            _inspection_context.decision_records[cache_key] = record
        return record

    def decisions(
        self,
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> list[dict[str, Any]]:
        _inspection_context = self._bind_inspection_context(
            _inspection_context
        )
        if not self.certification_decisions_dir.exists():
            return []
        return [
            self.decision(
                path.stem,
                _inspection_context=_inspection_context,
            )
            for path in sorted(self.certification_decisions_dir.glob("decision-*.json"))
        ]

    def _admission_dir(self, release_id: str) -> Path:
        self._release_path(release_id)
        return self.admissions_dir / release_id

    def _validated_admission(
        self,
        release_id: str,
        *,
        _lineage_facts: dict[str, Fact] | None = None,
        _lineage_paths: dict[str, Path] | None = None,
        _skip_successor_validation: bool = False,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> tuple[dict[str, Any], dict[str, Path]]:
        _inspection_context = self._bind_inspection_context(
            _inspection_context
        )
        cache_key = (release_id, _skip_successor_validation)
        cacheable = _lineage_facts is None and _lineage_paths is None
        if (
            cacheable
            and _inspection_context is not None
            and cache_key in _inspection_context.admission_records
        ):
            return _inspection_context.admission_records[cache_key]
        directory = self._admission_dir(release_id)
        marker_path = directory / "ACCEPTED.json"
        if marker_path.is_symlink() or not marker_path.is_file():
            raise ValueError("V5 admission marker is missing or unsafe")
        marker = self.store._read_json(marker_path)
        release = self.release(
            release_id,
            _lineage_facts=_lineage_facts,
            _lineage_paths=_lineage_paths,
            _skip_successor_validation=_skip_successor_validation,
            _inspection_context=_inspection_context,
        )
        strict_research_draft = _is_research_draft_assurance_revision(
            release["requested_assurance"].get("contract_revision")
        )
        required = {
            "schema_version",
            "policy_revision",
            "project_id",
            "release_id",
            "release_sha256",
            "decision_id",
            "decision_sha256",
            "capsule_sha256",
            "fact_ids",
            "fact_sha256",
            "gateway",
            "reviewer",
            "accepted_at",
            "acceptance_id",
        }
        if strict_research_draft:
            required.update(
                {
                    "parallel_verification_aggregate_id",
                    "parallel_verification_aggregate_record_sha256",
                }
            )
        if not isinstance(marker, dict) or set(marker) != required:
            raise ValueError("V5 admission marker fields are not exact")
        semantic = {
            key: value for key, value in marker.items() if key != "acceptance_id"
        }
        if (
            marker.get("schema_version") != 5
            or marker.get("policy_revision") != V5_POLICY_REVISION
            or marker.get("project_id") != self.store.project_id()
            or marker.get("release_id") != release_id
            or marker.get("acceptance_id")
            != "acceptance-" + sha256_json(semantic)
        ):
            raise ValueError("V5 admission marker schema/project/id/hash mismatch")
        _parse_utc_timestamp(
            marker.get("accepted_at"), label="V5 admission accepted_at"
        )
        decision = self.decision(
            marker["decision_id"],
            validate_bindings=False,
            _inspection_context=_inspection_context,
        )
        if (
            decision["verdict"] != "correct"
            or marker["release_sha256"] != release["release_sha256"]
            or marker["decision_sha256"] != decision["decision_sha256"]
            or marker["capsule_sha256"] != decision["capsule_sha256"]
            or marker["reviewer"] != decision["reviewer"]
            or marker["fact_ids"] != release["fact_ids"]
        ):
            raise ValueError("V5 admission release/decision/capsule binding mismatch")
        if strict_research_draft:
            aggregate_id = marker["parallel_verification_aggregate_id"]
            aggregate = self.parallel_verification().require_eligible_for_release(
                release_id, aggregate_id
            )
            if (
                marker["parallel_verification_aggregate_record_sha256"]
                != aggregate["record_sha256"]
                or decision.get("parallel_verification_aggregate_id")
                != aggregate_id
                or decision.get("parallel_verification_aggregate_record_sha256")
                != aggregate["record_sha256"]
            ):
                raise ValueError(
                    "V5 admission parallel-verification binding drifted"
                )
        candidate_by_id = {
            item["fact_id"]: item for item in release["candidates"]
        }
        paths: dict[str, Path] = {}
        expected_sha: dict[str, str] = {}
        for fact_id in release["fact_ids"]:
            path = directory / "facts" / f"{fact_id}.md"
            candidate = candidate_by_id[fact_id]
            if (
                path.is_symlink()
                or not path.is_file()
                or path.read_text(encoding="utf-8")
                != candidate["fact_markdown"]
            ):
                raise ValueError("V5 admitted Fact bytes differ from Candidate Release")
            digest = sha256_bytes(path.read_bytes())
            if digest != candidate["fact_sha256"]:
                raise ValueError("V5 admitted Fact hash mismatch")
            paths[fact_id] = path
            expected_sha[fact_id] = digest
        if marker["fact_sha256"] != expected_sha:
            raise ValueError("V5 admission marker Fact hash map mismatch")
        result = (marker, paths)
        if cacheable and _inspection_context is not None:
            _inspection_context.admission_records[cache_key] = result
        return result

    def _lineage_snapshot(
        self,
        *,
        admitted_before: datetime | str | None = None,
        exclude_release_ids: set[str] | None = None,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> tuple[dict[str, Fact], dict[str, Path]]:
        """Build an immutable active-Fact snapshot without recursive lineage reads.

        Release/admission bytes are validated in a first pass with successor
        replay deferred.  Callers then replay successor contracts against this
        explicit snapshot.  Facts from an excluded release are never eligible
        to serve as their own historical active predecessors.
        """

        _inspection_context = self._bind_inspection_context(
            _inspection_context
        )
        cutoff = (
            _parse_utc_timestamp(admitted_before, label="lineage admission cutoff")
            if isinstance(admitted_before, str)
            else admitted_before
        )
        if cutoff is not None:
            if not isinstance(cutoff, datetime) or cutoff.tzinfo is None:
                raise ValueError("lineage admission cutoff must be timezone-aware")
            cutoff = cutoff.astimezone(timezone.utc)
        excluded = exclude_release_ids or set()
        cache_key = (
            cutoff.isoformat() if cutoff is not None else "",
            tuple(sorted(excluded)),
        )
        if (
            _inspection_context is not None
            and cache_key in _inspection_context.lineage_snapshots
        ):
            return _inspection_context.lineage_snapshots[cache_key]
        revoked = self.revoked_fact_ids(
            _inspection_context=_inspection_context
        )
        paths: dict[str, Path] = {}
        if not self.admissions_dir.exists():
            return {}, paths
        for directory in sorted(self.admissions_dir.glob("release-*")):
            if directory.is_symlink() or not directory.is_dir():
                raise ValueError("V5 admission store contains an unsafe entry")
            marker_path = directory / "ACCEPTED.json"
            if not marker_path.exists():
                continue
            if directory.name in excluded:
                continue
            marker, admitted_paths = self._validated_admission(
                directory.name,
                _skip_successor_validation=True,
                _inspection_context=_inspection_context,
            )
            if cutoff is not None and _parse_utc_timestamp(
                marker["accepted_at"], label="V5 admission accepted_at"
            ) >= cutoff:
                continue
            for fact_id, path in admitted_paths.items():
                if fact_id in revoked:
                    continue
                if fact_id in paths:
                    raise ValueError(
                        f"V5 Fact {fact_id} has multiple active admissions"
                    )
                paths[fact_id] = path
        facts: dict[str, Fact] = {}
        for fact_id, path in paths.items():
            fact = parse_fact_markdown(path.read_text(encoding="utf-8"))
            errors = fact.validate()
            if errors:
                raise ValueError(
                    f"invalid admitted V5 Fact {fact_id}: " + "; ".join(errors)
                )
            if fact.fact_id != fact_id or fact.problem_id != self.store.project_id():
                raise ValueError("admitted V5 Fact id/project binding mismatch")
            facts[fact_id] = fact
        result = (facts, paths)
        if _inspection_context is not None:
            _inspection_context.lineage_snapshots[cache_key] = result
        return result

    def _validate_lineage_snapshot(
        self,
        facts: dict[str, Fact],
        paths: dict[str, Path],
        *,
        exclude_release_ids: set[str] | None = None,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> None:
        excluded = exclude_release_ids or set()
        if not self.admissions_dir.exists():
            return
        for directory in sorted(self.admissions_dir.glob("release-*")):
            marker_path = directory / "ACCEPTED.json"
            if directory.name in excluded or not marker_path.exists():
                continue
            release = self.release(
                directory.name,
                _skip_successor_validation=True,
                _inspection_context=_inspection_context,
            )
            _, own_paths = self._validated_admission(
                directory.name,
                _skip_successor_validation=True,
                _inspection_context=_inspection_context,
            )
            own_fact_ids = set(own_paths)
            historical_facts, historical_paths = self._lineage_snapshot(
                admitted_before=release["created_at"],
                exclude_release_ids={directory.name},
                _inspection_context=_inspection_context,
            )
            _, admitted_paths = self._validated_admission(
                directory.name,
                _lineage_facts=historical_facts,
                _lineage_paths=historical_paths,
                _inspection_context=_inspection_context,
            )
            if set(admitted_paths) != own_fact_ids:
                raise ValueError("V5 admission Fact set drifted between validation phases")

    def _provisional_active_fact_snapshot(
        self,
        *,
        release_ids: set[str] | None = None,
        _inspection_context: RoundInspectionContext,
    ) -> tuple[dict[str, Fact], dict[str, Path]]:
        """Build a command-local admission projection at a re-entry boundary.

        The projection validates only immutable local Release, marker, and Fact
        bytes.  It is never persisted and never completes active-Fact
        validation.  Its sole purpose is to let descendant frozen task cards
        compare their exact Fact authority while the outer frame remains
        responsible for full Release, Research, Decision, successor, and
        lineage replay.
        """

        revoked = self.revoked_fact_ids(
            _inspection_context=_inspection_context
        )
        facts: dict[str, Fact] = {}
        paths: dict[str, Path] = {}
        if not self.admissions_dir.exists():
            return facts, paths
        directories = (
            [self._admission_dir(release_id) for release_id in sorted(release_ids)]
            if release_ids is not None
            else sorted(self.admissions_dir.glob("release-*"))
        )
        for directory in directories:
            if directory.is_symlink() or not directory.is_dir():
                raise ValueError("V5 admission store contains an unsafe entry")
            marker_path = directory / "ACCEPTED.json"
            if not marker_path.exists():
                continue
            if marker_path.is_symlink() or not marker_path.is_file():
                raise ValueError("V5 admission marker is missing or unsafe")
            release_path = self._release_path(directory.name)
            if release_path.is_symlink() or not release_path.is_file():
                raise ValueError("V5 admission names a missing Candidate Release")
            release = self.store._read_json(release_path)
            if not isinstance(release, dict):
                raise ValueError("Candidate Release record must be one object")
            release_record_only = {
                "release_id",
                "release_sha256",
                "created_at",
                "record_sha256",
            }
            release_semantic = {
                key: value
                for key, value in release.items()
                if key not in release_record_only
            }
            release_sha = sha256_json(release_semantic)
            if (
                release.get("schema_version") != 5
                or release.get("policy_revision") != V5_POLICY_REVISION
                or release.get("project_id") != self.store.project_id()
                or release.get("truth_effect") != "none"
                or release.get("release_id") != directory.name
                or release.get("release_id") != "release-" + release_sha
                or release.get("release_sha256") != release_sha
            ):
                raise ValueError("Candidate Release local identity is invalid")
            release_without_hash = {
                key: value
                for key, value in release.items()
                if key != "record_sha256"
            }
            if release.get("record_sha256") != sha256_json(
                release_without_hash
            ):
                raise ValueError("Candidate Release local record hash mismatch")
            candidates = release.get("candidates")
            if not isinstance(candidates, list) or not candidates:
                raise ValueError("Candidate Release candidates are invalid")
            candidate_by_id: dict[str, dict[str, Any]] = {}
            candidate_order: list[str] = []
            for candidate in candidates:
                if not isinstance(candidate, dict) or set(candidate) != {
                    "fact_id",
                    "fact_sha256",
                    "fact_markdown",
                }:
                    raise ValueError(
                        "Candidate Release candidate fields are not exact"
                    )
                raw = candidate["fact_markdown"].encode("utf-8")
                if sha256_bytes(raw) != candidate["fact_sha256"]:
                    raise ValueError("Candidate Release Fact bytes/hash mismatch")
                fact = parse_fact_markdown(candidate["fact_markdown"])
                if fact.fact_id != candidate["fact_id"]:
                    raise ValueError("Candidate Release Fact id mismatch")
                if fact.fact_id in candidate_by_id:
                    raise ValueError("Candidate Release Fact ids are duplicated")
                candidate_order.append(fact.fact_id)
                candidate_by_id[fact.fact_id] = candidate
            if candidate_order != release.get("fact_ids"):
                raise ValueError("Candidate Release Fact order is inconsistent")

            marker = self.store._read_json(marker_path)
            marker_required = {
                "schema_version",
                "policy_revision",
                "project_id",
                "release_id",
                "release_sha256",
                "decision_id",
                "decision_sha256",
                "capsule_sha256",
                "fact_ids",
                "fact_sha256",
                "gateway",
                "reviewer",
                "accepted_at",
                "acceptance_id",
            }
            if _is_research_draft_assurance_revision(
                release.get("requested_assurance", {}).get(
                    "contract_revision"
                )
            ):
                marker_required.update(
                    {
                        "parallel_verification_aggregate_id",
                        "parallel_verification_aggregate_record_sha256",
                    }
                )
            if not isinstance(marker, dict) or set(marker) != marker_required:
                raise ValueError("V5 admission marker fields are not exact")
            marker_semantic = {
                key: value
                for key, value in marker.items()
                if key != "acceptance_id"
            }
            if (
                marker.get("schema_version") != 5
                or marker.get("policy_revision") != V5_POLICY_REVISION
                or marker.get("project_id") != self.store.project_id()
                or marker.get("release_id") != directory.name
                or marker.get("release_sha256") != release_sha
                or marker.get("fact_ids") != candidate_order
                or marker.get("acceptance_id")
                != "acceptance-" + sha256_json(marker_semantic)
            ):
                raise ValueError("V5 admission local identity is invalid")
            _parse_utc_timestamp(
                marker.get("accepted_at"), label="V5 admission accepted_at"
            )
            expected_sha = {
                fact_id: candidate_by_id[fact_id]["fact_sha256"]
                for fact_id in candidate_order
            }
            if marker.get("fact_sha256") != expected_sha:
                raise ValueError("V5 admission local Fact hash map mismatch")
            for fact_id in candidate_order:
                path = directory / "facts" / f"{fact_id}.md"
                candidate = candidate_by_id[fact_id]
                if (
                    path.is_symlink()
                    or not path.is_file()
                    or path.read_text(encoding="utf-8")
                    != candidate["fact_markdown"]
                    or sha256_bytes(path.read_bytes())
                    != candidate["fact_sha256"]
                ):
                    raise ValueError(
                        "V5 admitted Fact bytes differ from Candidate Release"
                    )
                fact = parse_fact_markdown(candidate["fact_markdown"])
                errors = fact.validate()
                if errors:
                    raise ValueError(
                        f"invalid provisionally visible V5 Fact {fact_id}: "
                        + "; ".join(errors)
                    )
                if (
                    fact.fact_id != fact_id
                    or fact.problem_id != self.store.project_id()
                ):
                    raise ValueError(
                        "provisionally visible V5 Fact id/project mismatch"
                    )
                if fact_id in revoked:
                    continue
                if fact_id in paths:
                    raise ValueError(
                        f"V5 Fact {fact_id} has multiple active admissions"
                    )
                paths[fact_id] = path
                facts[fact_id] = fact
        return facts, paths

    def active_fact_paths(
        self,
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Path]:
        _inspection_context = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert _inspection_context is not None
        if (
            _inspection_context.active_fact_paths is not None
        ):
            return _inspection_context.active_fact_paths
        if _inspection_context.active_fact_validation_in_progress:
            facts, paths = self._provisional_active_fact_snapshot(
                _inspection_context=_inspection_context
            )
            _inspection_context.active_fact_paths = paths
            _inspection_context.active_facts = facts
            return paths
        _inspection_context.active_fact_validation_in_progress = True
        try:
            facts, paths = self._lineage_snapshot(
                _inspection_context=_inspection_context
            )
            self._validate_lineage_snapshot(
                facts,
                paths,
                _inspection_context=_inspection_context,
            )
            provisional_paths = _inspection_context.active_fact_paths
            provisional_facts = _inspection_context.active_facts
            if provisional_paths is not None and provisional_paths != paths:
                raise ValueError(
                    "provisional active-Fact paths drifted from full validation"
                )
            if provisional_facts is not None and provisional_facts != facts:
                raise ValueError(
                    "provisional active-Fact content drifted from full validation"
                )
            _inspection_context.active_fact_paths = paths
            _inspection_context.active_facts = facts
            return paths
        except Exception:
            _inspection_context.active_fact_paths = None
            _inspection_context.active_facts = None
            raise
        finally:
            _inspection_context.active_fact_validation_in_progress = False

    def _preflight_post_admission_history(
        self,
        *,
        release: dict[str, Any],
        accepted_at: str,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> None:
        """Prove that a prospective admission cannot rewrite sealed history.

        Existing releases are replayed against their own seal-time snapshots.  The
        prospective marker is necessarily later than its release and therefore is
        absent from every already-sealed release snapshot.
        """

        _inspection_context = self._bind_inspection_context(
            _inspection_context,
            create=True,
        )
        assert _inspection_context is not None
        accepted = _parse_utc_timestamp(
            accepted_at, label="prospective V5 admission accepted_at"
        )
        release_created = _parse_utc_timestamp(
            release.get("created_at"), label="Candidate Release created_at"
        )
        if accepted <= release_created:
            raise ValueError("V5 admission timestamp must follow Candidate Release sealing")
        for path in sorted(self.candidate_releases_dir.glob("release-*.json")):
            if path.is_symlink() or not path.is_file():
                raise ValueError("V5 Candidate Release store contains an unsafe entry")
            historical = self.release(
                path.stem,
                _inspection_context=_inspection_context,
            )
            historical_created = _parse_utc_timestamp(
                historical.get("created_at"), label="Candidate Release created_at"
            )
            if accepted <= historical_created:
                raise ValueError(
                    "prospective V5 admission does not postdate sealed release history"
                )
        facts, paths = self._lineage_snapshot(
            _inspection_context=_inspection_context,
        )
        self._validate_lineage_snapshot(
            facts,
            paths,
            _inspection_context=_inspection_context,
        )

    def fact_admit(
        self,
        *,
        release_id: str,
        decision_id: str,
        gateway: str,
    ) -> dict[str, Any]:
        gateway = _require_nonempty_text(gateway, "V5 admission gateway")
        inspection = self._bind_inspection_context(
            RoundInspectionContext(),
            create=True,
        )
        assert inspection is not None
        directory = self._admission_dir(release_id)
        marker_path = directory / "ACCEPTED.json"
        if marker_path.exists():
            marker, _ = self._validated_admission(
                release_id,
                _inspection_context=inspection,
            )
            if marker["decision_id"] != decision_id or marker["gateway"] != gateway:
                raise ValueError(
                    "Candidate Release was already admitted with different evidence"
                )
            admitted_release = self.release(
                release_id,
                _inspection_context=inspection,
            )
            self._materialize_admission_projections(
                marker,
                release=admitted_release,
            )
            return marker
        release = self.release(
            release_id,
            _deep_dependencies=True,
            _inspection_context=inspection,
        )
        decision = self.decision(
            decision_id,
            validate_bindings=False,
            _inspection_context=inspection,
        )
        capsule = self.verifier_capsule(
            release_id,
            _release=release,
            _inspection_context=inspection,
        )
        if (
            decision["release_id"] != release_id
            or decision["verdict"] != "correct"
            or decision["release_sha256"] != release["release_sha256"]
            or decision["capsule_sha256"] != capsule["capsule_sha256"]
        ):
            raise ValueError(
                "V5 admission requires the clean exact Certification Decision"
            )
        strict_research_draft = _is_research_draft_assurance_revision(
            release["requested_assurance"].get("contract_revision")
        )
        parallel_aggregate: dict[str, Any] | None = None
        if strict_research_draft:
            aggregate_id = decision.get("parallel_verification_aggregate_id")
            if not isinstance(aggregate_id, str):
                raise ValueError(
                    "research-draft admission lacks parallel verification aggregate"
                )
            parallel_aggregate = self.parallel_verification().require_eligible_for_release(
                release_id, aggregate_id
            )
            if (
                decision.get("parallel_verification_aggregate_record_sha256")
                != parallel_aggregate["record_sha256"]
            ):
                raise ValueError(
                    "research-draft admission aggregate binding differs from the decision"
                )
        if gateway.casefold() == decision["reviewer"].casefold():
            raise ValueError("V5 admission gateway must differ from the verifier")
        candidate_payloads = [
            parse_fact_markdown(item["fact_markdown"]).as_submission_dict()
            for item in release["candidates"]
        ]
        validation_artifacts = [
            {
                "path": item["sealed_relpath"],
                "sha256": item["artifact_sha256"],
                "role": item["role"],
            }
            for item in release["artifacts"]
        ]
        (
            _,
            rendered,
            order,
            internal_edges,
            external_predecessors,
        ) = self._prepare_candidate_facts(
            candidate_payloads,
            artifacts=validation_artifacts,
            authorized_artifact_hashes={
                item["sha256"]
                for item in validation_artifacts
                if item["role"]
                in set(release["verification_plan"]["authorized_artifact_roles"])
            },
            verification_plan=release["verification_plan"],
            assurance_contract_revision=release.get(
                "assurance_contract_revision",
                V5_LEGACY_ASSURANCE_CONTRACT_REVISION,
            ),
            require_geometric_stage_typing=(
                "geometric_stage_typing"
                in release.get("applicable_assurance_checks", [])
            ),
            _inspection_context=inspection,
        )
        if (
            order != release["fact_ids"]
            or internal_edges != release["internal_edges"]
            or external_predecessors != release["external_predecessors"]
        ):
            raise ValueError("Candidate Release mathematical graph binding drifted")
        if not _is_research_draft_assurance_revision(
            release["requested_assurance"].get("contract_revision")
        ):
            self._validate_paper_evidence_refs(
                release["paper_evidence_refs"],
                validation_subject=release["requested_assurance"][
                    "validation_subject"
                ],
            )
        fact_sha = {
            fact_id: sha256_bytes(rendered[fact_id])
            for fact_id in release["fact_ids"]
        }
        accepted_at = _utc_now()
        marker_semantic = {
            "schema_version": 5,
            "policy_revision": V5_POLICY_REVISION,
            "project_id": self.store.project_id(),
            "release_id": release_id,
            "release_sha256": release["release_sha256"],
            "decision_id": decision_id,
            "decision_sha256": decision["decision_sha256"],
            "capsule_sha256": capsule["capsule_sha256"],
            "fact_ids": release["fact_ids"],
            "fact_sha256": fact_sha,
            "gateway": gateway,
            "reviewer": decision["reviewer"],
            **(
                {
                    "parallel_verification_aggregate_id": parallel_aggregate[
                        "aggregate"
                    ]["aggregate_id"],
                    "parallel_verification_aggregate_record_sha256": (
                        parallel_aggregate["record_sha256"]
                    ),
                }
                if parallel_aggregate is not None
                else {}
            ),
            "accepted_at": accepted_at,
        }
        marker = {
            **marker_semantic,
            "acceptance_id": "acceptance-" + sha256_json(marker_semantic),
        }
        projection_plan = self._admission_projection_plan(
            marker,
            release=release,
        )
        self._preflight_admission_projections(projection_plan)
        with self.store.v5_mutation_lock(command="fact-admit"):
            # The publication phase gets a fresh snapshot under the mutation
            # lock.  Consumers inside that phase share it, but no pre-lock
            # authority cache is promoted across the liveness boundary.
            locked_inspection = self._bind_inspection_context(
                RoundInspectionContext(),
                create=True,
            )
            assert locked_inspection is not None
            if marker_path.exists():
                existing, _ = self._validated_admission(
                    release_id,
                    _inspection_context=locked_inspection,
                )
                if (
                    existing["decision_id"] != decision_id
                    or existing["gateway"] != gateway
                ):
                    raise ValueError(
                        "Candidate Release was already admitted with different evidence"
                    )
                admitted_release = self.release(
                    release_id,
                    _inspection_context=locked_inspection,
                )
                self._materialize_admission_projections(
                    existing,
                    release=admitted_release,
                )
                return existing
            self._preflight_post_admission_history(
                release=release,
                accepted_at=accepted_at,
                _inspection_context=locked_inspection,
            )
            facts_dir = directory / "facts"
            facts_dir.mkdir(parents=True, exist_ok=True)
            if directory.is_symlink() or facts_dir.is_symlink():
                raise ValueError("V5 admission staging directory is unsafe")
            expected_files = {
                facts_dir / f"{fact_id}.md" for fact_id in release["fact_ids"]
            }
            unexpected = {
                path
                for path in directory.rglob("*")
                if (path.is_file() or path.is_symlink())
                and path not in expected_files
                and path != marker_path
            }
            if unexpected:
                raise ValueError(
                    "V5 admission staging contains unexpected files: "
                    + ", ".join(
                        sorted(
                            path.relative_to(directory).as_posix()
                            for path in unexpected
                        )
                    )
                )
            for fact_id in release["fact_ids"]:
                path = facts_dir / f"{fact_id}.md"
                self.store._write_bytes_once(path, rendered[fact_id], mode=0o644)
            # This write is the sole all-or-none visibility switch.
            self.store._write_json_once(marker_path, marker)
            self._materialize_admission_projections(
                marker,
                release=release,
                projection_plan=projection_plan,
            )
        return marker

    def _admission_projection_plan(
        self,
        marker: dict[str, Any],
        *,
        release: dict[str, Any],
    ) -> list[dict[str, Any]]:
        candidate_by_id = {
            item["fact_id"]: item for item in release["candidates"]
        }
        plan: list[dict[str, Any]] = []
        for fact_id in release["fact_ids"]:
            event_id = sha256_json(
                [
                    "accepted-v5",
                    fact_id,
                    marker["release_id"],
                    marker["decision_id"],
                    marker["acceptance_id"],
                ]
            )
            event = {
                "evidence_version": 5,
                "event": "accepted",
                "event_id": event_id,
                "fact_id": fact_id,
                "release_id": marker["release_id"],
                "release_sha256": marker["release_sha256"],
                "decision_id": marker["decision_id"],
                "decision_sha256": marker["decision_sha256"],
                "capsule_sha256": marker["capsule_sha256"],
                "acceptance_id": marker["acceptance_id"],
                "gateway": marker["gateway"],
                "reviewer": marker["reviewer"],
                "fact_sha256": marker["fact_sha256"][fact_id],
                "claim_relation": release["claim_relation"],
                "timestamp": marker["accepted_at"],
            }
            fact = parse_fact_markdown(
                candidate_by_id[fact_id]["fact_markdown"]
            )
            interface = build_statement_interface(
                fact=fact,
                stored_fact_sha256=marker["fact_sha256"][fact_id],
                acceptance_event_sha256=event_id,
                admission_review_id=marker["decision_sha256"],
                workflow_evidence_version=5,
                assurance_contract_revision=release.get(
                    "assurance_contract_revision",
                    V5_LEGACY_ASSURANCE_CONTRACT_REVISION,
                ),
            )
            validate_statement_interface(interface)
            plan.append(
                {
                    "event": event,
                    "interface": interface,
                    "interface_path": self.store.interfaces_dir / f"{fact_id}.json",
                }
            )
        return plan

    def _preflight_admission_projections(
        self,
        projection_plan: list[dict[str, Any]],
    ) -> None:
        existing_events = self.store._read_jsonl(self.store.verification_log)
        for item in projection_plan:
            event = item["event"]
            matches = [
                existing
                for existing in existing_events
                if existing.get("event_id") == event["event_id"]
            ]
            if len(matches) > 1:
                raise ValueError(
                    "duplicate admission projection event: " + event["event_id"]
                )
            if matches:
                existing_semantic = {
                    key: value
                    for key, value in matches[0].items()
                    if key != "timestamp"
                }
                expected_semantic = {
                    key: value for key, value in event.items() if key != "timestamp"
                }
                if existing_semantic != expected_semantic:
                    raise ValueError(
                        "divergent admission projection event: " + event["event_id"]
                    )
            interface_path = item["interface_path"]
            if interface_path.is_symlink():
                raise ValueError(
                    f"immutable statement interface is unsafe: {interface_path}"
                )
            rendered = (
                json.dumps(
                    item["interface"],
                    ensure_ascii=False,
                    indent=2,
                    sort_keys=True,
                )
                + "\n"
            ).encode("utf-8")
            if interface_path.exists() and (
                not interface_path.is_file()
                or interface_path.read_bytes() != rendered
            ):
                raise ValueError(
                    f"immutable statement interface collision at {interface_path}"
                )

    def _materialize_admission_projections(
        self,
        marker: dict[str, Any],
        *,
        release: dict[str, Any] | None = None,
        projection_plan: list[dict[str, Any]] | None = None,
    ) -> None:
        if release is None:
            release = self.release(marker["release_id"])
        if projection_plan is None:
            projection_plan = self._admission_projection_plan(
                marker,
                release=release,
            )
        self._preflight_admission_projections(projection_plan)
        for item in projection_plan:
            event = item["event"]
            self.store._append_jsonl_once(
                self.store.verification_log,
                event,
                event_id=event["event_id"],
            )
            write_interface_once(
                item["interface_path"],
                item["interface"],
            )

    def revoked_fact_ids(
        self,
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> set[str]:
        _inspection_context = self._bind_inspection_context(
            _inspection_context
        )
        if (
            _inspection_context is not None
            and _inspection_context.revoked_fact_ids is not None
        ):
            return _inspection_context.revoked_fact_ids
        if not self.revocations_dir.exists():
            if _inspection_context is not None:
                _inspection_context.revoked_fact_ids = set()
                return _inspection_context.revoked_fact_ids
            return set()
        result: set[str] = set()
        for path in sorted(self.revocations_dir.glob("*.json")):
            if path.is_symlink() or not path.is_file():
                raise ValueError("V5 revocation store contains an unsafe entry")
            record = self.store._read_json(path)
            fact_id = validate_fact_id(record.get("fact_id"))
            if path.stem != fact_id:
                raise ValueError("V5 revocation path/id mismatch")
            semantic = {
                key: value for key, value in record.items() if key != "record_sha256"
            }
            if record.get("record_sha256") != sha256_json(semantic):
                raise ValueError("V5 revocation record hash mismatch")
            result.add(fact_id)
        if _inspection_context is not None:
            _inspection_context.revoked_fact_ids = result
        return result

    def revoke(
        self,
        fact_id: str,
        *,
        reason: str,
        actor: str,
    ) -> list[str]:
        fact_id = validate_fact_id(fact_id)
        reason = _require_nonempty_text(reason, "V5 revocation reason")
        actor = _require_nonempty_text(actor, "V5 revocation actor")
        facts = self.store.facts()
        if fact_id not in facts:
            raise KeyError(f"unknown active V5 Fact: {fact_id}")
        graph = DependencyGraph(facts)
        revoked = [fact_id, *sorted(graph.descendants([fact_id]))]
        with self.store.v5_mutation_lock(command="v5-revoke"):
            for current in revoked:
                semantic = {
                    "schema_version": 5,
                    "policy_revision": V5_POLICY_REVISION,
                    "project_id": self.store.project_id(),
                    "fact_id": current,
                    "root_fact_id": fact_id,
                    "reason": reason,
                    "actor": actor,
                    "revoked_at": _utc_now(),
                }
                record = {
                    **semantic,
                    "record_sha256": sha256_json(semantic),
                }
                self.store._write_json_once(
                    self.revocations_dir / f"{current}.json", record
                )
                event_id = sha256_json(["revoked", current, fact_id, reason])
                self.store._append_jsonl_once(
                    self.store.revocation_log,
                    {
                        "evidence_version": 5,
                        "event_id": event_id,
                        "fact_id": current,
                        "root_fact_id": fact_id,
                        "reason": reason,
                        "actor": actor,
                        "timestamp": semantic["revoked_at"],
                    },
                    event_id=event_id,
                )
        return revoked

    def _json_count(self, directory: Path) -> int:
        if not directory.exists():
            return 0
        return sum(
            1
            for path in directory.glob("*.json")
            if path.is_file() and not path.is_symlink()
        )

    def status(
        self,
        *,
        _inspection_context: RoundInspectionContext | None = None,
    ) -> dict[str, Any]:
        _inspection_context = self._bind_inspection_context(
            _inspection_context
        )
        research_entries = self._json_count(self.research_entries_dir)
        quarantined = self._json_count(self.quarantine_dir)
        releases = self._json_count(self.candidate_releases_dir)
        decisions = self._json_count(self.certification_decisions_dir)
        facts = len(
            self.store.fact_ids(
                _inspection_context=_inspection_context
            )
        )
        decision_records = (
            self.decisions(_inspection_context=_inspection_context)
            if decisions
            else []
        )
        latest_decision = (
            max(decision_records, key=lambda item: item["reviewed_at"])
            if decision_records
            else None
        )
        pending_repair_effect = (
            latest_decision is not None
            and latest_decision["verdict"] == "reject"
            and (
                self._certification_repair_effect_path(
                    latest_decision["decision_id"]
                ).is_symlink()
                or not self._certification_repair_effect_path(
                    latest_decision["decision_id"]
                ).is_file()
            )
        )
        if facts:
            current_state = "Fact"
            blocking_issue = None
            next_safe_command = "status"
        elif latest_decision is not None and latest_decision["verdict"] == "correct":
            current_state = "Certification Decision"
            blocking_issue = "accepted decision has not been gateway-admitted"
            next_safe_command = "fact-admit"
        elif pending_repair_effect:
            current_state = "Certification Decision"
            blocking_issue = (
                "rejecting decision has a pending nontruth repair effect; "
                "retry the exact certification-record input"
            )
            next_safe_command = "certification-record"
        elif decisions:
            current_state = "Research"
            blocking_issue = "latest Candidate Release was rejected"
            next_safe_command = "research-add"
        elif releases:
            current_state = "Candidate Release"
            blocking_issue = "candidate release has no certification decision"
            next_safe_command = "verifier-capsule"
        else:
            current_state = "Research"
            blocking_issue = None
            next_safe_command = "research-add"
        paper_continuation = self.paper_continuation(
            _inspection_context=_inspection_context
        ).status_all_summary()
        return {
            "schema_version": 1,
            "workflow_evidence_version": V5_WORKFLOW_EVIDENCE_VERSION,
            "policy_revision": V5_POLICY_REVISION,
            "lifecycle_contract_sha256": V5_LIFECYCLE_CONTRACT_SHA256,
            "current_state": current_state,
            "blocking_issue": blocking_issue,
            "next_safe_command": next_safe_command,
            "counts": {
                "research_entries": research_entries,
                "quarantined_contributions": quarantined,
                "candidate_releases": releases,
                "certification_decisions": decisions,
                "facts": facts,
            },
            "paper_continuation": paper_continuation,
        }

    def fact_evidence_audit(self) -> dict[str, Any]:
        with self.store.snapshot_lock():
            return self._fact_evidence_audit_snapshot_bound()

    def _fact_evidence_audit_snapshot_bound(self) -> dict[str, Any]:
        """Audit only the V5 authority bytes required for Fact Evidence.

        External Evidence capture must remain readable across Chalxius runtime
        upgrades.  Frozen rounds, task cards, modes, Blackboard, Paper, and
        other nontruth workflow surfaces are therefore deliberately outside
        this audit.  The active Fact projection and every authority object that
        makes it visible remain fully validated.
        """

        inspection = self._bind_inspection_context(None, create=True)
        assert inspection is not None
        authority_errors: list[str] = []
        graph_errors: list[str] = []
        warnings: list[str] = []
        trust_debt: list[str] = []
        facts: dict[str, Fact] = {}
        active_paths: dict[str, Path] = {}
        admitted_fact_markers: dict[str, dict[str, Any]] = {}

        def authority_error(message: str) -> None:
            authority_errors.append(message)

        def graph_error(message: str) -> None:
            graph_errors.append(message)

        try:
            project = self.store.project()
            project_id = self.store.project_id()
        except Exception as exc:
            authority_error(f"invalid project.json: {exc}")
            project = {}
            project_id = ""
        if project:
            if (
                project.get("workflow_evidence_version")
                != V5_WORKFLOW_EVIDENCE_VERSION
            ):
                authority_error("Fact Evidence audit requires a V5 source project")
            if project.get("policy_revision") != V5_POLICY_REVISION:
                authority_error("V5 source project policy_revision is mismatched")
            if project.get("truth_policy") != "verifier-gated":
                authority_error("V5 source project truth policy is not verifier-gated")

        if self.contract_path.is_symlink() or not self.contract_path.is_file():
            authority_error("V5 lifecycle contract is missing or unsafe")
        else:
            try:
                contract = self.store._read_json(self.contract_path)
                semantic = {key: contract[key] for key in V5_LIFECYCLE_CONTRACT}
                if semantic != V5_LIFECYCLE_CONTRACT:
                    raise ValueError(
                        "semantic contract differs from the release contract"
                    )
                if contract.get("contract_sha256") != sha256_json(semantic):
                    raise ValueError("contract hash mismatch")
            except Exception as exc:
                authority_error(f"invalid V5 lifecycle contract: {exc}")

        for label, directory in (
            ("research entries", self.research_entries_dir),
            ("candidate releases", self.candidate_releases_dir),
            ("candidate artifacts", self.candidate_artifacts_dir),
            ("certification decisions", self.certification_decisions_dir),
            ("Fact admissions", self.admissions_dir),
            ("Fact revocations", self.revocations_dir),
        ):
            if directory.is_symlink() or not directory.is_dir():
                authority_error(f"V5 {label} directory is missing or unsafe")

        try:
            active_paths = self.active_fact_paths(
                _inspection_context=inspection
            )
        except Exception as exc:
            authority_error(f"active V5 Fact lineage failed: {exc}")

        for directory in sorted(self.admissions_dir.glob("release-*")):
            if directory.is_symlink() or not directory.is_dir():
                authority_error("V5 admission store contains an unsafe entry")
                continue
            marker_path = directory / "ACCEPTED.json"
            if not marker_path.exists():
                warnings.append(
                    f"V5 admission staging {directory.name} has no visibility marker"
                )
                continue
            try:
                marker, paths = self._validated_admission(
                    directory.name,
                    _inspection_context=inspection,
                )
                for fact_id in paths:
                    if fact_id in admitted_fact_markers:
                        raise ValueError(
                            f"Fact {fact_id} has more than one admission marker"
                        )
                    admitted_fact_markers[fact_id] = marker
            except Exception as exc:
                authority_error(f"V5 admission {directory.name}: {exc}")

        try:
            revoked_ids = self.revoked_fact_ids(
                _inspection_context=inspection
            )
        except Exception as exc:
            authority_error(f"invalid V5 revocation store: {exc}")
            revoked_ids = set()
        unknown_revocations = sorted(
            revoked_ids.difference(admitted_fact_markers)
        )
        if unknown_revocations:
            authority_error(
                "V5 revocations have no admitted Fact: "
                + ", ".join(unknown_revocations)
            )
        visible_expected = set(admitted_fact_markers).difference(revoked_ids)
        if set(active_paths) != visible_expected:
            authority_error(
                "active V5 Fact visibility differs from admission/revocation provenance"
            )

        for fact_id, path in sorted(active_paths.items()):
            try:
                fact = parse_fact_markdown(path.read_text(encoding="utf-8"))
                validation_errors = fact.validate()
                if validation_errors:
                    raise ValueError("; ".join(validation_errors))
                if fact.fact_id != fact_id or fact.problem_id != project_id:
                    raise ValueError("Fact id/project binding mismatch")
                facts[fact_id] = fact
            except Exception as exc:
                graph_error(f"invalid active V5 Fact {fact_id}: {exc}")

        if not facts:
            authority_error("external Fact Evidence requires at least one active Fact")
        graph = DependencyGraph(facts)
        for fact_id, predecessor in graph.missing_predecessors():
            graph_error(f"{fact_id}: missing active V5 predecessor {predecessor}")
        try:
            graph.topological_order()
            depths = graph.depths()
            max_depth = max(depths.values(), default=0)
        except ValueError as exc:
            graph_error(str(exc))
            max_depth = 0

        try:
            verification_events = self.store._read_jsonl(
                self.store.verification_log
            )
        except Exception as exc:
            authority_error(f"invalid V5 verification log: {exc}")
            verification_events = []
        events_by_fact: dict[str, list[dict[str, Any]]] = {}
        for event in verification_events:
            if event.get("evidence_version") != V5_WORKFLOW_EVIDENCE_VERSION:
                authority_error(
                    "V5 verification log contains non-V5 admission authority"
                )
                continue
            fact_id = str(event.get("fact_id", ""))
            events_by_fact.setdefault(fact_id, []).append(event)
        for fact_id, marker in admitted_fact_markers.items():
            events = events_by_fact.get(fact_id, [])
            if len(events) != 1:
                authority_error(
                    f"V5 Fact {fact_id} must have exactly one acceptance event"
                )
                continue
            event = events[0]
            expected_id = sha256_json(
                [
                    "accepted-v5",
                    fact_id,
                    marker["release_id"],
                    marker["decision_id"],
                    marker["acceptance_id"],
                ]
            )
            for key, expected in (
                ("event", "accepted"),
                ("event_id", expected_id),
                ("release_id", marker["release_id"]),
                ("decision_id", marker["decision_id"]),
                ("capsule_sha256", marker["capsule_sha256"]),
                ("acceptance_id", marker["acceptance_id"]),
                ("fact_sha256", marker["fact_sha256"][fact_id]),
            ):
                if event.get(key) != expected:
                    authority_error(
                        f"V5 Fact {fact_id} acceptance event {key} mismatch"
                    )
                    break
        unknown_event_facts = sorted(
            set(events_by_fact).difference(admitted_fact_markers)
        )
        if unknown_event_facts:
            authority_error(
                "V5 acceptance events have no admission marker: "
                + ", ".join(unknown_event_facts)
            )

        for fact_id in sorted(facts):
            try:
                self.store.statement_interface(fact_id, materialize=False)
            except Exception as exc:
                authority_error(f"V5 statement interface {fact_id}: {exc}")

        errors = [
            *graph_errors,
            *(f"authority: {message}" for message in authority_errors),
        ]
        return {
            "schema_version": 1,
            "contract_revision": V5_FACT_EVIDENCE_AUDIT_REVISION,
            "scope": "active_v5_fact_authority_only",
            "source_runtime_policy": "independent_of_frozen_nontruth_workflow_runtime",
            "workflow_evidence_version": V5_WORKFLOW_EVIDENCE_VERSION,
            "fact_admission_contract_sha256": FACT_ADMISSION_CONTRACT_SHA256,
            "current_ok": not errors,
            "history_clean": not trust_debt,
            "facts": len(facts),
            "edges": sum(len(fact.predecessors) for fact in facts.values()),
            "max_depth": max_depth,
            "active_fact_ids": sorted(facts),
            "graph_errors": graph_errors,
            "authority_errors": authority_errors,
            "errors": errors,
            "warnings": warnings,
            "trust_debt": trust_debt,
            "ignored_nontruth_surfaces": [
                "rounds_and_task_cards",
                "reasoning_modes",
                "blackboard",
                "paper_logic_and_audit",
                "campaigns",
                "pulses",
                "experiments",
            ],
            "truth_effect": "none",
            "project_effect": "none",
        }

    def audit(self) -> V5AuditReport:
        with self.store.snapshot_lock():
            return self._audit_snapshot_bound()

    def _audit_snapshot_bound(self) -> V5AuditReport:
        report = V5AuditReport()
        inspection = self._bind_inspection_context(None, create=True)
        assert inspection is not None

        def workflow_error(message: str) -> None:
            report.workflow_errors.append(message)
            report.errors.append(f"workflow: {message}")

        def graph_error(message: str) -> None:
            report.graph_errors.append(message)
            report.errors.append(message)

        try:
            project = self.store.project()
        except Exception as exc:
            graph_error(f"invalid project.json: {exc}")
            return report
        if project.get("workflow_evidence_version") != V5_WORKFLOW_EVIDENCE_VERSION:
            workflow_error("V5 audit received a non-V5 project")
            return report
        if project.get("policy_revision") != V5_POLICY_REVISION:
            workflow_error("V5 project policy_revision is missing or mismatched")

        if self.contract_path.is_symlink() or not self.contract_path.is_file():
            workflow_error("V5 lifecycle contract is missing or unsafe")
        else:
            try:
                contract = self.store._read_json(self.contract_path)
                semantic = {
                    key: contract[key]
                    for key in V5_LIFECYCLE_CONTRACT
                }
                if semantic != V5_LIFECYCLE_CONTRACT:
                    raise ValueError("semantic contract differs from the release contract")
                if contract.get("contract_sha256") != sha256_json(semantic):
                    raise ValueError("contract hash mismatch")
            except Exception as exc:
                workflow_error(f"invalid V5 lifecycle contract: {exc}")

        for label, directory in (
            ("research entries", self.research_entries_dir),
            ("research quarantine", self.quarantine_dir),
            ("candidate releases", self.candidate_releases_dir),
            ("candidate artifacts", self.candidate_artifacts_dir),
            ("certification decisions", self.certification_decisions_dir),
            ("Fact admissions", self.admissions_dir),
            ("Fact revocations", self.revocations_dir),
        ):
            if directory.is_symlink() or not directory.is_dir():
                workflow_error(f"V5 {label} directory is missing or unsafe")

        try:
            report.research_entries = len(
                self.research_records(_inspection_context=inspection)
            )
        except Exception as exc:
            workflow_error(f"invalid V5 Research Ledger: {exc}")
        try:
            novelty_events = self.store._read_jsonl(self.store.novelty_log)
            report.novelty_entries = len(novelty_events)
            for message in self._audit_novelty(
                _inspection_context=inspection
            ):
                workflow_error(f"novelty: {message}")
        except Exception as exc:
            workflow_error(f"invalid V5 novelty ledger: {exc}")
        try:
            report.quarantined_contributions = len(
                self._quarantine_records(
                    _inspection_context=inspection
                )
            )
        except Exception as exc:
            workflow_error(f"invalid V5 research quarantine: {exc}")
        releases: list[dict[str, Any]] = []
        try:
            releases = self.releases(_inspection_context=inspection)
            report.candidate_releases = len(releases)
            report.candidates = sum(len(item["fact_ids"]) for item in releases)
        except Exception as exc:
            workflow_error(f"invalid V5 Candidate Release store: {exc}")
        decisions: list[dict[str, Any]] = []
        try:
            decisions = self.decisions(_inspection_context=inspection)
            report.certification_decisions = len(decisions)
        except Exception as exc:
            workflow_error(f"invalid V5 Certification Ledger: {exc}")
        decision_release_ids = [item["release_id"] for item in decisions]
        if len(decision_release_ids) != len(set(decision_release_ids)):
            workflow_error("a Candidate Release has multiple Certification Decisions")

        decisions_by_id = {
            item["decision_id"]: item for item in decisions
        }
        for label, directory in (
            (
                "Certification repair outbox",
                self.certification_repair_outbox_dir,
            ),
            (
                "Certification repair effects",
                self.certification_repair_effects_dir,
            ),
        ):
            # These stores are prospective.  Their absence is compatible with
            # projects initialized before the recovery protocol existed.
            if directory.exists() and (
                directory.is_symlink() or not directory.is_dir()
            ):
                workflow_error(f"V5 {label} directory is unsafe")
        if (
            self.certification_repair_outbox_dir.is_dir()
            and not self.certification_repair_outbox_dir.is_symlink()
        ):
            for path in sorted(
                self.certification_repair_outbox_dir.glob("decision-*.json")
            ):
                if path.is_symlink() or not path.is_file():
                    workflow_error(
                        "Certification repair outbox contains an unsafe entry: "
                        + path.name
                    )
                    continue
                decision = decisions_by_id.get(path.stem)
                if decision is None:
                    try:
                        intent = self._validate_certification_repair_intent_record(
                            self.store._read_json(path)
                        )
                        if intent.get("decision_id") != path.stem:
                            raise ValueError("path/decision binding mismatch")
                    except Exception as exc:
                        workflow_error(
                            f"Certification repair intent {path.stem}: {exc}"
                        )
                    else:
                        report.warnings.append(
                            "Certification repair intent has no visible Decision; "
                            "retry the exact certification-record input: "
                            + path.stem
                        )
                    continue
                if decision["verdict"] != "reject":
                    workflow_error(
                        "correct Certification Decision has a repair intent: "
                        + path.stem
                    )
                    continue
                try:
                    self._load_certification_repair_intent(decision)
                except Exception as exc:
                    workflow_error(
                        f"Certification repair intent {path.stem}: {exc}"
                    )
        if (
            self.certification_repair_effects_dir.is_dir()
            and not self.certification_repair_effects_dir.is_symlink()
        ):
            for path in sorted(
                self.certification_repair_effects_dir.glob("decision-*.json")
            ):
                if path.is_symlink() or not path.is_file():
                    workflow_error(
                        "Certification repair effects contain an unsafe entry: "
                        + path.name
                    )
                    continue
                decision = decisions_by_id.get(path.stem)
                if decision is None or decision["verdict"] != "reject":
                    workflow_error(
                        "Certification repair effect has no rejecting Decision: "
                        + path.stem
                    )
                    continue
                try:
                    intent = self._load_certification_repair_intent(decision)
                    self._load_certification_repair_effect(
                        decision=decision,
                        intent=intent,
                    )
                except Exception as exc:
                    workflow_error(
                        f"Certification repair effect {path.stem}: {exc}"
                    )
        for decision in decisions:
            if decision["verdict"] != "reject":
                continue
            intent_path = self._certification_repair_intent_path(
                decision["decision_id"]
            )
            effect_path = self._certification_repair_effect_path(
                decision["decision_id"]
            )
            if not intent_path.is_file() or intent_path.is_symlink():
                report.warnings.append(
                    "rejecting Certification Decision has no durable repair intent; "
                    "retry the exact certification-record input: "
                    + decision["decision_id"]
                )
            elif not effect_path.is_file() or effect_path.is_symlink():
                report.warnings.append(
                    "rejecting Certification Decision has a pending repair effect; "
                    "retry the exact certification-record input: "
                    + decision["decision_id"]
                )

        for manifest_path in sorted(self.store.rounds_dir.glob("*/round.json")):
            try:
                manifest = self.store._read_json(manifest_path)
                if manifest.get("schema_version") != 5:
                    raise ValueError(
                        "V5 root contains a non-V5 mutable round"
                    )
                status = self.round_status(
                    manifest_path.parent.name,
                    _inspection_context=inspection,
                )
                report.round_states[manifest_path.parent.name] = status[
                    "work_unit_state"
                ]
            except Exception as exc:
                workflow_error(
                    f"V5 round {manifest_path.parent.name}: {exc}"
                )

        try:
            facts = self.store.facts(_inspection_context=inspection)
        except Exception as exc:
            graph_error(f"active Fact visibility failed: {exc}")
            facts = {}
        report.facts = len(facts)
        report.edges = sum(len(fact.predecessors) for fact in facts.values())
        graph = DependencyGraph(facts)
        for fact_id, predecessor in graph.missing_predecessors():
            graph_error(f"{fact_id}: missing active V5 predecessor {predecessor}")
        try:
            graph.topological_order()
            depths = graph.depths()
            report.max_depth = max(depths.values(), default=0)
        except ValueError as exc:
            graph_error(str(exc))

        admission_markers: dict[str, dict[str, Any]] = {}
        admitted_fact_markers: dict[str, dict[str, Any]] = {}
        for directory in sorted(self.admissions_dir.glob("release-*")):
            if directory.is_symlink() or not directory.is_dir():
                workflow_error("V5 admission store contains an unsafe entry")
                continue
            marker_path = directory / "ACCEPTED.json"
            if not marker_path.exists():
                report.warnings.append(
                    f"V5 admission staging {directory.name} has no visibility marker; "
                    "retry fact-admit with the same evidence"
                )
                continue
            try:
                marker, paths = self._validated_admission(
                    directory.name,
                    _inspection_context=inspection,
                )
                admission_markers[directory.name] = marker
                for fact_id in paths:
                    if fact_id in admitted_fact_markers:
                        raise ValueError(
                            f"Fact {fact_id} has more than one admission marker"
                        )
                    admitted_fact_markers[fact_id] = marker
            except Exception as exc:
                workflow_error(f"V5 admission {directory.name}: {exc}")

        try:
            revoked_ids = self.revoked_fact_ids(
                _inspection_context=inspection
            )
        except Exception as exc:
            workflow_error(f"invalid V5 revocation store: {exc}")
            revoked_ids = set()
        visible_expected = set(admitted_fact_markers).difference(revoked_ids)
        if set(facts) != visible_expected:
            workflow_error(
                "active V5 Fact visibility differs from admission/revocation provenance"
            )

        verification_events = self.store._read_jsonl(self.store.verification_log)
        events_by_fact: dict[str, list[dict[str, Any]]] = {}
        for event in verification_events:
            if event.get("evidence_version") != V5_WORKFLOW_EVIDENCE_VERSION:
                workflow_error(
                    "V5 verification log contains non-V5 admission authority"
                )
                continue
            fact_id = str(event.get("fact_id", ""))
            events_by_fact.setdefault(fact_id, []).append(event)
        for fact_id, marker in admitted_fact_markers.items():
            events = events_by_fact.get(fact_id, [])
            if len(events) != 1:
                workflow_error(
                    f"V5 Fact {fact_id} must have exactly one acceptance event"
                )
                continue
            event = events[0]
            expected_id = sha256_json(
                [
                    "accepted-v5",
                    fact_id,
                    marker["release_id"],
                    marker["decision_id"],
                    marker["acceptance_id"],
                ]
            )
            for key, expected in (
                ("event", "accepted"),
                ("event_id", expected_id),
                ("release_id", marker["release_id"]),
                ("decision_id", marker["decision_id"]),
                ("capsule_sha256", marker["capsule_sha256"]),
                ("acceptance_id", marker["acceptance_id"]),
                ("fact_sha256", marker["fact_sha256"][fact_id]),
            ):
                if event.get(key) != expected:
                    workflow_error(
                        f"V5 Fact {fact_id} acceptance event {key} mismatch"
                    )
                    break
        unknown_event_facts = sorted(set(events_by_fact).difference(admitted_fact_markers))
        if unknown_event_facts:
            workflow_error(
                "V5 acceptance events have no admission marker: "
                + ", ".join(unknown_event_facts)
            )

        for fact_id in sorted(facts):
            try:
                self.store.statement_interface(
                    fact_id,
                    materialize=False,
                    _inspection_context=inspection,
                )
            except Exception as exc:
                workflow_error(f"V5 statement interface {fact_id}: {exc}")

        targets = self.store.targets()
        report.targets = len(targets)
        unknown_targets = sorted(set(targets).difference(facts))
        if unknown_targets:
            graph_error(
                "V5 targets are not active Facts: " + ", ".join(unknown_targets)
            )
        elif targets:
            try:
                report.target_closure = len(graph.closure(targets))
            except Exception as exc:
                graph_error(f"V5 target closure failed: {exc}")

        try:
            blackboard_report = self.store.blackboard().audit()
        except Exception as exc:
            workflow_error(f"blackboard audit failed: {exc}")
        else:
            report.blackboard_graph_errors.extend(blackboard_report["errors"])
            report.blackboard_graph_warnings.extend(blackboard_report["warnings"])
            for message in blackboard_report["errors"]:
                workflow_error(f"blackboard: {message}")
            report.warnings.extend(
                f"blackboard: {message}" for message in blackboard_report["warnings"]
            )

        try:
            paper_report = self._inspection_paper_logic(inspection).audit(
                blackboard=self.store.blackboard()
            )
        except Exception as exc:
            workflow_error(f"Paper Logic/Audit audit failed: {exc}")
        else:
            report.paper_logic_errors.extend(paper_report["errors"])
            report.paper_logic_warnings.extend(paper_report["warnings"])
            report.paper_source_nodes = paper_report["source_nodes"]
            report.paper_reconstruction_nodes = paper_report[
                "reconstruction_nodes"
            ]
            report.paper_audit_nodes = paper_report["audit_nodes"]
            for message in paper_report["errors"]:
                workflow_error(f"paper_logic: {message}")
            report.warnings.extend(
                f"paper_logic: {message}" for message in paper_report["warnings"]
            )

        try:
            continuation_report = self.paper_continuation(
                _inspection_context=inspection
            ).audit()
        except Exception as exc:
            workflow_error(f"Paper continuation audit failed: {exc}")
        else:
            for message in continuation_report["errors"]:
                workflow_error(f"paper_continuation: {message}")
            continuation_counts = continuation_report["counts"]
            report.paper_continuation_plans = continuation_counts["plans"]
            report.paper_continuation_complete_plans = continuation_counts[
                "complete_plans"
            ]
            report.paper_continuation_targets = continuation_counts["targets"]
            report.paper_continuation_researched = continuation_counts[
                "researched"
            ]
            report.paper_continuation_dispositioned = continuation_counts[
                "dispositioned"
            ]
            report.paper_continuation_unresolved = continuation_counts[
                "unresolved"
            ]
            report.paper_continuation_successor_mapped = continuation_counts[
                "successor_mapped"
            ]
            report.paper_continuation_revised_manuscript_covered = (
                continuation_counts["revised_manuscript_covered"]
            )
            report.paper_continuation_adequacy_complete = (
                continuation_report["adequacy_complete"]
            )

        try:
            research_draft_report = self.research_draft().audit()
        except Exception as exc:
            workflow_error(f"research-draft lifecycle audit failed: {exc}")
        else:
            for message in research_draft_report["errors"]:
                workflow_error(f"research_draft: {message}")

        try:
            parallel_verification_report = self.parallel_verification().audit()
        except Exception as exc:
            workflow_error(f"parallel-verification lifecycle audit failed: {exc}")
        else:
            for message in parallel_verification_report["errors"]:
                workflow_error(f"parallel_verification: {message}")

        try:
            claims_report = self.store.claims().audit()
        except Exception as exc:
            workflow_error(f"claim/convention registry audit failed: {exc}")
        else:
            for message in claims_report["errors"]:
                workflow_error(f"claim/convention registry: {message}")

        def source_claim_exists(claim_id: str) -> bool:
            try:
                self.store.claims().show_claim(claim_id)
            except (KeyError, ValueError, OSError):
                return False
            return True

        try:
            campaign_report = self.store.campaigns().audit(
                fact_exists=lambda fact_id: fact_id in facts,
                source_claim_exists=source_claim_exists,
            )
        except Exception as exc:
            workflow_error(f"campaign audit failed: {exc}")
        else:
            for message in campaign_report["errors"]:
                workflow_error(f"campaign: {message}")

        try:
            pulse_report = self.store.collaboration().audit()
        except Exception as exc:
            workflow_error(f"V5 pulse audit failed: {exc}")
        else:
            for message in pulse_report["errors"]:
                workflow_error(f"V5 pulse: {message}")

        try:
            experiment_report = self.store.experiments().audit_all(
                _inspection_context=inspection
            )
        except Exception as exc:
            workflow_error(f"V5 experiment audit failed: {exc}")
        else:
            for message in experiment_report["errors"]:
                workflow_error(f"V5 experiment: {message}")

        try:
            mode_report = self.store.reasoning_modes().audit()
        except Exception as exc:
            workflow_error(f"reasoning mode audit failed: {exc}")
        else:
            for message in mode_report["errors"]:
                workflow_error(f"reasoning mode: {message}")
            report.warnings.extend(
                f"reasoning mode: {message}"
                for message in mode_report["warnings"]
            )

        try:
            abort_records = self.store.reasoning_modes().work_unit_aborts()
        except Exception as exc:
            workflow_error(f"work-unit abort projection audit failed: {exc}")
        else:
            for abort in abort_records:
                round_id = abort["round_id"]
                try:
                    status = self.round_status(
                        round_id,
                        _inspection_context=inspection,
                    )
                except Exception as exc:
                    workflow_error(
                        f"work-unit abort/status projection failed for {round_id}: {exc}"
                    )
                    continue
                if (
                    status.get("work_unit_state") != "aborted"
                    or status.get("abort_id") != abort["abort_id"]
                    or status.get("awaiting_count") != 0
                    or any(
                        assignment.get("state")
                        in {"awaiting_return", "return_present"}
                        for assignment in status.get("assignments", [])
                    )
                ):
                    workflow_error(
                        "work-unit abort/status projection mismatch for "
                        f"{round_id}"
                    )

        return report


def v5_contract_file_sha256(path: Path) -> str:
    """Expose a small test/diagnostic helper without granting write authority."""

    return sha256_bytes(path.read_bytes())
